(window.GIM_TP=window.GIM_TP||{})["Z.AddendaIII.0"]={"from":0,"a":[[["רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הֲווּ אַזְלֵי בְּאָרְחָא, עַד דַהֲווּ אַזְלֵי פָּגְעוּ בְּהַהוּא יְנוֹקָא דְהָוָה אָזִיל וְהָוָה לָאֵי. אָמַר לוֹן, לָאִינָא דְּלָא אֲכִילְנָא יוֹמָא דֵין. אֲפִיקוּ נַהֲמָא וְיָהֲבוּ לֵיהּ, אִתְרָחִישׁ לוֹן נִיסָא וְאַשְׁכָּחוּ חַד נְבִיעוּ דָקִיק דְמַיָּא (ס\"א תחות אילנא) תְחוֹתְהוֹן וְשָׁתוּ מִנֵּיהּ וְיַתְבוּ.","פָּתַח הַהוּא יְנוֹקָא וְאָמַר, (ויקרא א׳:א׳) ויִּקְרָא אֶל מֹשֶׁה, הָכָא אַלֶף זְעִירָא, אֲמַאי. בְּגִין דְּהַאי קְרִיאָה לָא הֲוָה בִּשְׁלִימוּ, מַאי טַעְמָא דְּלָא הֲוָה אֶלָּא בְּמַשְׁכְּנָא וּבְאַרְעָא אַחֲרָא. בְּגִין דִּשְׁלִימוּ לָא אִשְׁתְּכַּח אֶלָּא בְּאַרְעָא קַדִּישָׁא.","תּוּ, הָכָא שְׁכִינְתָּא, הֲתָם שְׁלִימוּ דְּדְּכָר ונוּקְבָּא (דברי הימים א א׳:א׳) אָדָם שֵׁת אֱנוֹשׁ, אָדָם שְׁלִימוּ דִּדְכָר וְנוּקְבָּא, הָכָא נוּקְבָּא. תּוּ סֵיפָא דִקְרָא וַיְדַבֵּר יְיָ אֵלָיו מְאֹהֶל מוֹעֵד לֵאמֹר, בְּגִין כָּךְ א' זְעִירָא.","וְתּוּ א' זְעִירָא מְתַל לְמַלְכָּא דְהָוָה יָתִיב בְּכוּרְסַיָּיא וְכִּתְרָא דְּמָלְכוּתָא עָלֵיהּ וְאִיקְרֵי מֶלֶךְ עִילָאָה, כַּד נָחִית וְאָזִיל לְבֵּי עַבְדֵּיהּ, מֶלֶךְ זוּטָא אִקְרֵי. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, כָּל זִמְנָא דְּאִיהוּ לְעֵילָּא עַל כֹּלָּא, מֶלֶךְ עִילָאָה אִיקְרֵי. כֵּיוָן דְּנָחִית מְדוֹרֵיהּ לְתַתָּא, מֶלֶךְ אִיהוּ, אֲבָל לָאו עִילָאָה כְּדְּקַדְמִיתָא. בְּגִין כָּךְ אַלֶף זְעִירָא.","ויִּקְרָא, הָכִי תָנֵינָן, זָמִין לֵיהּ לְהֵיכָלֵיהּ מֶאֹהֶל מוֹעֵד. מַאן הוּא אֹהֶל מוֹעֵד, אֹהֶל דְּבֵּיהּ תָלֵינָן מוֹעֲדָא וְחָגָא וְשַׁבְּתָא לְמִמְנֵי. כְּמָה דְאַתְּ אָמֵר (בראשית א׳:י״ד) וְהָיוּ לְאֹתוֹת וּלְמוֹעֲדִים וּבֵיהּ שַׁרְיָיא חוּשְׁבָּנָא לְמִמְנֵי, וּמָאן אִיהוּ סִיהֲרָא. כְּמָה דְאַתְּ אָמֵר (ישעיהו ל״ג:כ׳) אֹהֶל בַּל יִצְעַן בַּל יִסַע יְתְדוֹתָיו לַנֵצַח.","לֵאמֹר, מָאי לֵאמֹר, בְּגִין לְגַלָּאָה. אֲבָל כֹּלָא חַד וְשַׁפִּיר הוּא, בְּגִין דִּשְׁלִימוּ הוּא אֲתָר לְגַלָּאָה מָה דְהָוָה סָתִים לְגוֹ. וּבְכָל אֲתָר, לֵאמֹר, כְּמָה דְאַתְּ אָמֵר, ויְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר, וַיְדַבֵּר יְיָ אֵלָיו מְאֹהֶל מוֹעֵד לֵאמֹר. דְאִתְיְיהִיב רֵשׁוּ לְגַלָּאָה, דְּהָא אִתְמָנֵי לְּסִיהֲרָא הַהוּא מִלָּה מֵאֲתָר דְּמֹשֶׁה קַיָימָא. ויְדַבֵּר יְיָ לְעֵילָּא. אֶל מֹשֶׁה בְּאֶמְצָעִיתָא. לֵאמֹר בָּבְּרַיְיתָא (ס\"א בבתרייא) אֲתָר דְּאִית רֵשׁוּ לְגַלָּאָה.","תּוּ וַיִּקְרָא אֶל מֹשֶׁה, מָה כְּתִיב לְעֵילָּא (שמות ט\"ל) וַיָבִיאוּ אֵת הַמִּשְׁכָּן אֶל מֹשֶׁה וְגוֹ'. אַמָּאי אֶל מֹשֶׁה, הָכִי אָמְרוּ, בְּגִין דְּמֹשֶׁה חָמָא לֵיהּ בְּטוּרָא וְקוּדְשָׁא בְּרִיךְ הוּא אֲחְמֵי לֵיהּ בְּחֵיזוּ דְּעֵינָא כְּמָה דְאַתְּ אָמֵר (שמות כ״ז:ח׳) כַּאֲשֶׁר הֶרְאָה אוֹתְךָ בָּהָר. (במדבר ח׳:ד׳) כַּמַּרְאֶה אֲשֶׁר הֶרְאָה יְיָ אֵת מֹשֶׁה וגוֹ'. וּכְתִיב (שמות כ״ה:מ׳) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מֹרְאֵה בָּהָר. הַשְׁתָּא דְּאַיְתִיאוּ לֵיהּ, בְּגִין דְּיִחְמֵי אִי אִיהוּ כְּהַהוּא מַשְׁכְּנָא דְּחָמָא (ס\"א בגין דיחמי איהו ההוא משכנא דחמא).","אֲבָל אֲמַאי וַיָבִיאוּ אֵת הַמִּשְׁכָּן אֶל מֹשֶׁה. אֶלָּא לְמַלְכָּא דְּבָעָא לְמִבְנֵי פַּלְטְרִין לְמַטְרוֹנִיתָא, פַּקִיד לְאוּמָנִין, הֵיכָלָא דָא, בְּדוּךְ פְּלַן. וְהֵיכָלָא דָא בְּדוּךְ פְּלַן. הָכָא אֲתָר לְעֲרְסֵיה. הָכָא אֲתָר לְנַיְיחָא. כֵּיוָן דְּעַבִידוּ לוֹן אוּמָנִין אַחֲמִיוּ לְמַלְכָּא. כָּךְ, ויָבִיאוּ אֵת הַמִּשְׁכָּן אֶל מֹשֶׁה מָארִיהּ דְּבֵיתָא, אִישׁ הָאֱלֹהִים. כֵּיוָן דְּאִשְׁתַכְלַל הֵיכָלָא לְמַטְרוֹנִיתָא, זְמִינַת לְמַלְכָּא לְמֵיכַלָא. זְמִינַת לְבַעְלָה עִמָּהּ, בְּגִין כָּךְ ויִּקְּרָא אֶל מֹשֶׁה.","וּבְגִין דְּמֹשֶׁה מָארֵי דְּבֵיתָא אִיהוּ, מָה כְּתִיב (שמות ל״ג:ז׳) וְמֹשֶׁה יִקַּח אֵת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה. מֹשֶׁה דְּאִיהוּ מָארֵיהּ דְּבֵיתָא עֲבָד הָכִי (מה) דְּלֵית רֵשׁוּ לְבַּר נָשׁ אַחֲרָא לְמֶעְבַּד הָכִי.","ויְדַבֵּר יְיָ אֵלָיו דַּרְגָּא אַחֲרָא עִילָאָה, וּכְדֵין בְּשַׁעֲתָא דְּאִזְדַמָן מֹשֶׁה לְמֵיעָאל כְּדֵין פָּתַח וְאָמַר אָדָם כִּי יַקְרִיב מִכֶּם. מַאי אָדָם הָכָא, אֶלָּא כַּד אִתְחַבְּרָן שִׁמְשָׁא וסִיהֲרָא כַּחֲדָא. פָּתַח וְאָמַר אָדָם, כְּדִכְתִיב (חבקוק ג׳:י״א) שֶׁמֶשׁ יָרֵחַ עָמַד זְבוּלָה. עָמַד וְלֹא עָמְדוּ.","כִּי יַקְרִיב מִכֶּם, הָכָא אִתְרְמִיז מַאן דְּיַעֲבִיד פּוּלְחָנָא דְּקָרְבְּנָא שְׁלִים דְּיִשְׁתְּכַח דְּכָר ונוּקְבָּא, מַשְׁמַע מִכֶּם דְּיִשְׁתְּכַח כְּחִיזוּ דִּילְכוֹן. קָרְבָּן לַיְיָ, דְּיַקְרִיב כֹּלָּא לְאִתְאַחֲדָא כַּחֲדָא עֵילָא ותַתָּא.","מִן הַבְּהֵמָה, לְאַחֲזָאָה אָדָם וּבְהֵמָה וְכֹלָּא כַּחֲדָא. מִן הַבָּקָר וּמִן הַצֹּאן, אִלֵּין רְתִיכִין דְּאִינוּן דַּכְיָין. כֵּיוָן דְּאָמַר מִן הַבְּהֵמָה, יָכוֹל מִכֹּלָּא בֵּין דַּכְיָין בֵּין מְסָאֲבָן, הֲדַר וְאָמַר מִן הַבָּקָר וּמִן הַצֹּאן וְגוֹ'.","קָרְבָּנְכֶם, קָרְבָּנִי מִּבָּעֵי לֵיהּ. מַאי קָרֵבָּנְכֶם אֶלָּא בְּקַדְמִיתָא קָרְבָּן לַיְיָ, הַשְׁתָּא קָרְבָּנְכֶם קָרְבָּן לַיְיָ אָדָם קָרְבָּנְכֶם מִן הַבָּקָר וּמִן הַצֹּאן לְאַחֲזָאָה יִחוּדָא מֵעֵילָּא לְתַתָּא. וּמִתַּתָּא לְעֵילָּא הַיְינוּ קָרְבָּן לַיְיָ, מֵעֵילָּא לְתַתָּא הַיְינוּ קָרְבָּנְכֶם."],[],[[0,"","רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶרֶךְ. בְּעוֹד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְּאוֹתוֹ תִינוֹק שֶׁהָיָה הוֹלֵךְ וְהָיָה עָיֵף. אָמַר לוֹ, אֲנִי עָיֵף שֶׁלֹּא אָכַלְתִּי הַיּוֹם הַזֶּה. הוֹצִיאוּ לֶחֶם וְנָתְנוּ לוֹ. הִתְרַחֵשׁ לָהֶם נֵס, וּמָצְאוּ מַעְיָן דַּק שֶׁל מַיִם (תחת האילן) תַּחְתֵּיהֶם, וְשָׁתוּ מִמֶּנּוּ וְיָשְׁבוּ."],[1,"","פָּתַח אוֹתוֹ תִינוֹק וְאָמַר, וַיִּקְרָא אֶל מֹשֶׁה, לָמָּה כָּאן א' זְעִירָה? מִשּׁוּם שֶׁהַקְּרִיאָה הַזּוֹ לֹא הָיְתָה בִּשְׁלֵמוּת. מָה הַטַּעַם? שֶׁלֹּא הָיָה אֶלָּא בַּמִּשְׁכָּן וּבְאֶרֶץ אַחֶרֶת, מִשּׁוּם שֶׁאֵין שְׁלֵמוּת נִמְצֵאת אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה."],[2,"","עוֹד כָּאן שְׁכִינָה, שָׁם שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה, (דברי הימים א א) אָדָם, שֵׁת, אֱנוֹשׁ. אָדָם שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה. כָּאן נְקֵבָה. עוֹד, סוֹף הַכָּתוּב, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, מִשּׁוּם כָּךְ א' זְעִירָה,"],[3,"","וְעוֹד א' זְעִירָה. מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּכִסֵּא, וְכֶתֶר מַלְכוּת עָלָיו, וְנִקְרָא מֶלֶךְ עֶלְיוֹן. כְּשֶׁיּוֹרֵד וְהוֹלֵךְ לְבֵית עַבְדּוֹ, נִקְרָא מֶלֶךְ קָטָן. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל זְמַן שֶׁהוּא לְמַעְלָה עַל הַכֹּל, נִקְרָא מֶלֶךְ עֶלְיוֹן. כֵּיוָן שֶׁהוֹרִיד אֶת מְדוֹרוֹ לְמַטָּה, הוּא מֶלֶךְ, אֲבָל לֹא עֶלְיוֹן כְּמוֹ בַּתְּחִלָּה, מִשּׁוּם כָּךְ א' זְעִירָה."],[4,"","וַיִּקְרָא, כָּךְ שָׁנִינוּ, הִזְמִין אוֹתוֹ לְהֵיכָלוֹ. מֵאֹהֶל מוֹעֵד, מִיהוּ אֹהֶל מוֹעֵד? אֹהֶל שֶׁבּוֹ תְּלוּיִים מוֹעֵד וְחַג וְשַׁבָּת לִמְנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וְהָיוּ לְאתת וּלְמועֲדִים, וּבו מַתְחִילִים לִמְנות אֶת הַחֶשְׁבּוֹן, וּמִיהוּ? הַלְּבָנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח."],[5,"","לֵאמֹר, מַה זֶּה לֵאמֹר? כְּדֵי לְגַלּוֹת, אֲבָל הַכֹּל אֶחָד וְיָפֶה הוּא, מִשּׁוּם שֶׁשְּׁלֵמוּת הוּא מָקוֹם לְגַלּוֹת מַה שֶּׁהָיָה נִסְתָּר בִּפְנִים, וּבְכָל מָקוֹם לֵאמֹר, כְּמוֹ שֶׁנֶּאֱמַר וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. שֶׁנִּתְּנָה רְשׁוּת לְגַלּוֹת, שֶׁהֲרֵי הָיָה צִוּוּי לַלְּבָנָה אוֹתוֹ הַדָּבָר מֵהַמָּקוֹם שֶׁעָמַד מֹשֶׁה. וַיְדַבֵּר ה' - לְמַעְלָה, אֶל מֹשֶׁה - בָּאֶמְצַע, לֵאמֹר - בַּחוּץ (בסוף), הַמָּקוֹם שֶׁיֵּשׁ רְשׁוּת לְגַלּוֹת."],[6,"","עוֹד וַיִּקְרָא אֶל מֹשֶׁה, מַה כָּתוּב לְמַעְלָה? (שמות לט) וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה וְגוֹ'. לָמָּה אֶל מֹשֶׁה? כָּךְ אָמְרוּ, מִשּׁוּם שֶׁמֹּשֶׁה רָאָה אוֹתוֹ בָּהָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ בְּמַרְאֵה הָעַיִן, כְּמוֹ שֶׁנֶּאֱמַר (שם כז) כַּאֲשֶׁר הֶרְאָה אֹתְךְ בָּהָר. כַּמַּרְאֶה אֲשֶׁר הֶרְאָה ה' אֶת מֹשֶׁה וְגוֹ'. וְכָתוּב וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר. עַכְשָׁו שֶׁהֵבִיאוּ לוֹ כְּדֵי שֶׁיִּרְאֶה אִם הוּא כְּמוֹ אוֹתוֹ הַמִּשְׁכָּן שֶׁרָאָה (כדי שיראה הוא אותו משכן שראה)."],[7,"","אֲבָל לָמָּה וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה? אֶלָּא, לְמֶלֶךְ שֶׁרָצָה לִבְנוֹת פַּלְטֵרִין לַגְּבִירָה, צִוָּה לָאֻמָּנִים: הַהֵיכָל הַזֶּה בְּמָקוֹם פְּלוֹנִי, וְהַהֵיכָל הַזֶּה בְּמָקוֹם פְּלוֹנִי, כָּאן הַמָּקוֹם לְמִטָּתָהּ, וְכָאן הַמָּקוֹם לִמְנוּחָה. כֵּיוָן שֶׁעָשׂוּ אוֹתָם הָאֻמָּנִים, הֶרְאוּ לַמֶּלֶךְ. כָּךְ וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה, בַּעַל הַבַּיִת אִישׁ הָאֱלֹהִים. כֵּיוָן שֶׁנִּתְקַן הַהֵיכָל לַגְּבִירָה, הִזְמִינָה אֶת הַמֶּלֶךְ לֶאֱכֹל, הִזְמִינָה אֶת בַּעְלָהּ עִמָּהּ. מִשּׁוּם כָּךְ וַיִּקְרָא אֶל מֹשֶׁה,"],[8,"","וּמִשּׁוּם שֶׁמֹּשֶׁה הוּא בַּעַל הַבַּיִת, מַה כָּתוּב? (שם לג) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה. מֹשֶׁה שֶׁהוּא בַּעַל הַבַּיִת עָשָׂה כָּךְ, (מה) שֶׁאֵין רְשׁוּת לְאָדָם אַחֵר לַעֲשׂוֹת כָּךְ."],[9,"","וַיְדַבֵּר ה' אֵלָיו, דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה. וְאָז, בְּשָׁעָה שֶׁהִזְדַּמֵּן מֹשֶׁה לְהִכָּנֵס, אָז פָּתַח וְאָמַר, אָדָם כִּי יַקְרִיב מִכֶּם. מָה אָדָם כָּאן? אֶלָּא כְּשֶׁמִּתְחַבְּרִים הַשֶּׁמֶשׁ וְהַלְּבָנָה כְּאֶחָד, פָּתַח וְאָמַר אָדָם, כְּמוֹ שֶׁכָּתוּב שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה. עָמַד וְלֹא עָמְדוּ."],[10,"","כִּי יַקְרִיב מִכֶּם, כָּאן נִרְמָז, מִי שֶׁיַּעֲשֶׂה אֶת הַקָּרְבָּן שָׁלֵם, שֶׁיִּמָּצְאוּ זָכָר וּנְקֵבָה, מַשְׁמָע מִכֶּם, שֶׁנִּמְצָא כְּמוֹ הַמַּרְאֶה שֶׁלָּכֶם. קָרְבָּן לַה', שֶׁיַּקְרִיב הַכֹּל לְהִתְאַחֵד כְּאֶחָד מַעְלָה וּמַטָּה. מִן הַבְּהֵמָה, לְהַרְאוֹת אָדָם וּבְהֵמָה, וְהַכֹּל כְּאֶחָד."],[11,"","מִן הַבָּקָר וּמִן הַצֹּאן, אֵלּוּ הַמֶּרְכָּבוֹת שֶׁהֵן טְהוֹרוֹת. כֵּיוָן שֶׁאָמַר מִן הַבְּהֵמָה, יָכוֹל מֵהַכֹּל, בֵּין טְהוֹרִים בֵּין טְמֵאִים? חָזַר וְאָמַר, מִן הַבָּקָר וּמִן הַצֹּאן וְגוֹ'."],[12,"","קָרְבַּנְכֶם?! קָרְבָּנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה קָרְבַּנְכֶם? אֶלָּא בָּרִאשׁוֹנָה קָרְבָּן לַה', וְעַכְשָׁו קָרְבַּנְכֶם, קָרְבָּן לַה' אָדָם, קָרְבַּנְכֶם מִן הַבָּקָר וּמִן הַצֹאן, לְהַרְאוֹת יִחוּד מִמַּעְלָה לְמַטָּה. מִמַּטָּה לְמַעְלָה הַיְנוּ קָרְבָּן לַה'. מִמַּעְלָה לְמַטָּה הַיְנוּ קָרְבַּנְכֶם."]]],[["מְתַל לְמַלְכָּא דְּאִיהוּ יָתִיב בְּטוּרְסֶקָא עִילָאָה לְעֵילָּא וְכָרְסַיָּיא דִּילֵיהּ אִתְתַּקָּן עַל הַהוּא טוּרְסֶקָא וּמַלְכָּא עִילָאָה עַל כֹּלָּא. בַּר נָשׁ דְקָרִיב קָרְבְּנָא (ס\"א דורונא) לְמַלְכָּא, בָּעָא לְסַלְקָא מִדַרְגָּא לְדָרְגָּא עַד דְּסָלִיק מִתַּתָּא לְעֵילָּא לְאֲתָר דְּמַלְכָּא יָתִיב, עִילָאָה עַל כָּל כֹּלָּא. וּכְדֵין יָדְעִין דְּהָא סָלְקִין דוֹרוֹנָא לְמַלְכָּא והַהוּא דוֹרוֹנָא (ס\"א דמלכא) מִן מַלְכָּא אִיהוּ. נָחִית דוֹרוֹנָא מֵעֵילָּא לְתַתָּא, הַא יְדִיעָן דְּהַהוּא דוֹרוֹנָא (ס\"א דמלכא) נָחִית מֵעֵילָּא לִרְחִימָא דְּמַלְכָּא דְּאִיהוּ לְתַתָּא.","כָּךְ בְּקַדְמִיתָא אָדָם סָלִיק בְּדַרְגּוֹי מִתַּתָּא לְעֵילָּא, וּכְדֵין קָרְבָּן לַיְיָ מִן הַבְּהֵמָה מִן הַבָּקָר, נָחִית בְּדַרְגּוֹי מֵעֵילָא לְתַתָּא וּכְדֵין קָרֵבָּנְכֶם. בְּגִין כָּךְ (שיר השירים ה׳:א׳) אֲכַלְתִי יַעְרִי עִם דִבְשִׁי וגוֹ' הַיְינוּ אָדָם קָרְבָּן לַיְיָ. אִכְלוּ רֵעִים הַיְינוּ מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹּאן. וּכְדֵין תַּקְרִיבוּ אֵת קָרְבָּנְכֶם.","אָתוּ רִבִּי יְהוּדָה וְר' יִצְחָק וּנְשָׁקוּהוּ. אָמְרוּ בְּרִיךְ רַחֲמָנָא, דְּזָכֵינָא לְמִשְׁמָע דָא. אָמַר רַבִּי יְהוּדָה יֵאוֹת הֲוָה לְהַהוּא יְנוֹקָא דְּלָא יִנְדָע כּוּלֵי הַאי, ואֲנָא מִסְתַּפֵּינָא עָלֵיהּ אִי יִתְקַיַּים בְּעָלְמָא בְּגִינֵי הַאי, אָמַר רַבִּי יִצְחָק וְלָמָּה. אָמַר לֵיהּ, דְּהָא יָכִיל לְאִסְתַּכְּלָא בְּאֲתָר דְּלֵית רֵשׁוּ לְּבַּר נָשׁ לְאִסְתַּכְּלָא בֵּיהּ וּמִסְתָּפֵינָא עָלּוֹי דְּעַד לָא יִמְטֵי לְפִרְקוֹי יִסְתָּכַּל וְיִשְׁגָּח וְיֵעֲנְשׁוּן לֵיהּ,","שָׁמַע הַהוּא יְנוֹקָא. אָמַר, לָא מִסְתַּפֵּינָא מֵעוֹנָשָׁא לְּעָלְמִין דְּהָא בְּשַׁעֲתָא דְאִסְתַּלַּק אַבָּא מֵעָלְמָא, בָּרִיךְ לִי וְצַלִּי עֲלַי וְיַדָּעְנָא דִּזְכוּתָא דְּאַבָּא יָגִין עֲלַי. אָמַר לֵיהּ מַאן הוּא אֲבוּךְ. אָמַר בְּרֵיהּ דְרַב הַמְנוּנָא סָבָא. נָטְלוּ לֵיהּ וְאַרְכְּבוּ לֵיהּ עַל כִּתְפַיְיהוּ תְלַת מִילִין. אַזְלוּ וסַדָּרוּ מִילִין קָמֵיהּ דְּרַבִּי שִׁמְעוֹן. אָמַר לוֹן, וַדַּאי יְרוּתָא אוֹרַיְיתָא אַחְסִין, וְאִלְמָלֵא זְכוּתָא דְּאָבוֹי אִתְעֲנַשׁ מִלְּעֵילָּא, אֲבָל קוּדְשָׁא בְּרִיךְ הוּא, לְאִינוּן דְּאָזִילוּ בַּתְרָא דְּאוֹרַיְיתָא אַחְסִינוּ לָהּ אִינוּן וּבַנָיְיהוּ לְעָלְמִין.","שָׁמוֹר אֶת יוֹם הַשַׁבָּת, הַהוּא בְּמִדָּה שְׁבִיעִית נֶאֱמַר דִּכְתִיב, אֶת שַׁבְּתוֹתַי תִּשְׁמוֹרוּ וּמִקְדָשִׁי תִּירָאוּ, מַאי נִיהוּ מִדָּה שְׁבִיעִית הֱוִי אוֹמֵר זֶה מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַאי טַעְמָא אָמַר שַׁבְּתוֹתַי וְלֹא אָמַר שַׁבְּתַי. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיָה לוֹ אִשָּׁה נָאָה, וְכָל שָׁבוּעַ וְשָׁבוּעַ מַזְמִינָה יוֹם אֶחָד לִהְיוֹת עִמּוֹ. וְהַמֶּלֶךְ יֵשׁ לוֹ בָּנִים נָאִים וְאוֹהַבָם, וְאָמַר לָהֶם הוֹאִיל וְכֵן הוּא, שִׂמְחוּ גַּם אַתֶּם בְּיוֹם שִׂמְחָתִי, כִּי אֲנִי בְּשֶׁלָכֶם אֲנִי מִשְׁתַּדֵּל, וְגַם אַתֶּם הֲדְרוּ אוֹתִי. וּמַאי טַעְמָא זָכוֹר וְשָׁמוֹר. זָכוֹר לַזָּכָר וְשָׁמוֹר לַכַלָּה. וּמַאי טַעְמָא וּמִקְדָשִׁי תִּירָאוּ, שִׁמְרוּ עַצְמְכֶם מִן הַהִרְהוּר, כִּי מִקְדָשִׁי קָדוֹשׁ הוּא. לָמָה, כִּי אֲנִי יְיָ בְּכָל צָד.","אָמַר רַבִּי רְחוּמָאי מָהוּ דִכְתִיב וַיִשָׂא אַהֲרֹן אֵת יָדָיו אֶל הָעָם וַיְבַרְכֵם וַיֵּרֶד, וְהָא כְּבָר יָרַד. אֶלָּא וַיֵּרֶד מֵעֲשׂוֹת הַחַטָּאת וְהַעוֹלָה וְאַחַר כַּךְ וַיִשָׂא אַהֲרֹן אֵת יָדָיו אֶל הָעָם. נְשִׂיאוּת זוֹ לָמָּה, לְפִי שֶׁהִקְרִיב קָרְבָּן וְנִתְרָצָה לִפְנֵי אֲבִיהֶם שֶׂבַּשָׁמַיִם. כְּדְּאָמַר צָרִיךְ אוֹתוֹ שֶׁמְקַרְבָן לַעֶלְיוֹנִים וּמְיַיחֲדָן לְיַיחֵד בִּכְלַלָן אֵלּוּ. וּמָה אֶל הָעָם, בַּעֲבוּר הָעָם. וּמָאי טַעְמָא בִּנְשִׂיאוּת לְבַרֵךְ לְהוֹן בִּבְרָכָה, אֶלָּא מִשׁוּם דְּיֵשׁ בַּאָדָם עֶשֶׂר אֶצְבָּעוֹת רֶמֶז לְי' סְפִירוֹת שֶׁנֶחְתְמוּ בְּהוֹן שָּׁמַיִם וָאָרֶץ.","פָּתַח רַבִּי נְהוֹרָאי בְּפָרָשַׁת צִיצִית וְדָרַשׁ, (במדבר ט״ו:ל״ח) וְעָשׂוּ לָהֶם צִיצִית עַל כַּנְפֵי בִגְדֵיהֶם לְדוֹרוֹתָם. מַאי שְׁנָא דְהָכָא וּבְשַׁבָּת לְדֹרֹתָם חָסֵר, דִּכְתִיב, (שמות ל״א:ט״ז) לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדֹרֹתָם, חָסֵר. דְּתָנִינָן. תִּקְנוּ פָּרָשַׁת צִיצִית בִּקְרִיאַת שְׁמַע. וּבְדִירָתוֹ שֶׁל אָדָם, נִמְצָא פָּרָשַׁת קְרִיאַת שְׁמַע, חוּץ מִפָּרָשַׁת צִיצִית, שֶׁחָסֵר מִשָּׁם. בַּמֶּה נִשְׁלַם. אֶלָּא כְּשֶׁאָדָם מִתְעַטֵּף בְּבֵיתוֹ בַּצִּיצִית, וְיוֹצֵא בוֹ לְפִתְחוֹ, הֲרֵי נִשְׁלַם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בּוֹ, וּמַלְאַךְ הַמָּוְת זָז מִשָּׁם וְהַיְינוּ לְדֹרֹתָם, שֶׁיִּהְיֶה שָׁלֵם. וְיֵצֵא מִפֶּתַח בֵּיתוֹ בְּמִצְוָה זוֹ, וּמַלְאָךְ הַמַּשְׁחִית זָז מִשָּׁם ונִיצוֹל הָאָדָם מִכָּל נֶזֶק. מְנָלָן. מִמַּאי דִכְתִיב מְזוּזֹת, מֵאוֹתִיּוֹתָיו מַשְׁמַע, זָ\"ז מָוְ\"ת. שֶׁלֹּא נִיתַּן לוֹ רְשׁוּת לְחַבֵּל, וְזָז מִפִּתְחוֹ."],[],[[0,"","מָשָׁל לְמֶלֶךְ שֶׁהוּא יוֹשֵׁב בְּגַג עֶלְיוֹן לְמַעְלָה, וְכִסְאוֹ מְתֻקָּן עַל אוֹתוֹ הַגַּג, וְהַמֶּלֶךְ הָעֶלְיוֹן עַל הַכֹּל. אָדָם שֶׁמַּקְרִיב קָרְבָּן (דורון) לַמֶּלֶךְ, צָרִיךְ לַעֲלוֹת מִדַּרְגָּה לְדַרְגָּה, עַד שֶׁעוֹלֶה מִמַּטָּה לְמַעְלָה, לְמָקוֹם שֶׁהַמֶּלֶךְ יוֹשֵׁב עֶלְיוֹן עַל הַכֹּל, וְאָז יוֹדְעִים שֶׁהֲרֵי מַעֲלִים דּוֹרוֹן לַמֶּלֶךְ, וְאוֹתוֹ דוֹרוֹן (של המלך) מִן הַמֶּלֶךְ הוּא. יוֹרֵד דּוֹרוֹן מִמַּעְלָה לְמַטָּה, הֲרֵי יוֹדְעִים שֶׁאוֹתוֹ דוֹרוֹן יוֹרֵד מִלְמַעְלָה לַאֲהוּב הַמֶּלֶךְ שֶׁהוּא לְמַטָּה."],[1,"","כָּךְ בַּתְּחִלָּה אָדָם, עוֹלֶה בְדַרְגוֹתָיו מִמַּטָּה לְמַעְלָה, וְזֶה קָרְבָּן לַה' מִן הַבְּהֵמָה מִן הַבָּקָר. יוֹרֵד בְּדַרְגוֹתָיו מִמַּעְלָה לְמַטָּה, וְאָז קָרְבַּנְכֶם. מִשּׁוּם כָּךְ, (שיר השירים ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי וְגוֹ'. הַיְנוּ אָדָם קָרְבָּן לַה', אִכְלוּ רֵעִים, הַיְנוּ מִן הַבְּהֵמָה וּמִן הַצּאן, וְאָז תַּקְרִיבוּ אֶת קָרְבַּנְכֶם."],[2,"","בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וּנְשָׁקוּהוּ. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁזָּכִינוּ לִשְׁמֹעַ אֶת זֶה. אָמַר רַבִּי יְהוּדָה, נָאֶה הוּא לְאוֹתוֹ תִינוֹק שֶׁלֹּא יָדַע אֶת כָּל זֶה, וַאֲנִי פּוֹחֵד עָלָיו אִם יִתְקַיֵּם בָּעוֹלָם בִּגְלַל זֶה. אָמַר רַבִּי יִצְחָק, וְלָמָּה? אָמַר לוֹ, שֶׁהֲרֵי יָכוֹל לְהִסְתַּכֵּל בְּמָקוֹם שֶׁאֵין רְשׁוּת לְאָדָם לְהִסְתַּכֵּל בּוֹ, וַאֲנִי פּוֹחֵד עָלָיו, שֶׁטֶּרֶם יַגִּיעַ לְפִרְקוֹ יִתְבּוֹנֵן וְיַשְׁגִּיחַ וְיַעֲנִישׁוּ אוֹתוֹ."],[3,"","שָׁמַע אוֹתוֹ הַתִּינוֹק, אָמַר, אֵינִי פּוֹחֵד מֵעֹנֶשׁ לְעוֹלָמִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁהִסְתַּלֵּק אָבִי מִן הָעוֹלָם, בֵּרַךְ אוֹתִי וְהִתְפַּלֵּל עָלַי, וְיוֹדֵעַ אֲנִי שֶׁזְּכוּת אָבִי תָּגֵן עָלַי. אָמְרוּ לוֹ, מִי הוּא אָבִיךְ? אָמַר, בְּנוֹ שֶׁל רַב הַמְנוּנָא סָבָא. לָקְחוּ אוֹתוֹ וְהִרְכִּיבוּ אוֹתוֹ עַל כִּתְפֵיהֶם שְׁלֹשָׁה מִילִין. הָלְכוּ וְסִדְּרוּ אֶת הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי יְרֻשַּׁת הַתּוֹרָה הוּא יָרַשׁ, וְאִלְמָלֵא זְכוּת אָבִיו, הָיָה נֶעֱנָשׁ מִלְּמַעְלָה, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְאוֹתָם שֶׁהוֹלְכִים אַחַר הַתּוֹרָה, מוֹרִישׁ אוֹתָהּ לָהֶם וְלִבְנֵיהֶם לְעוֹלָמִים. (ע\"כ מההשמטות)."],[4,"","שָׁמוֹר אֶת יוֹם הַשַּׁבָּת, הַהוּא בְּמִדָּה שְׁבִיעִית נֶאֱמַר, שֶׁכָּתוּב אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִירָאוּ. מַה זּוֹ מִדָּה שְׁבִיעִית? הֱוֵה אוֹמֵר, זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה הַטַּעַם אָמַר שַׁבְּתֹתַי וְלֹא אָמַר שַׁבַּתִּי? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיְתָה לוֹ אִשָּׁה נָאָה, וְכָל שָׁבוּעַ וְשָׁבוּעַ מַזְמִינָהּ יוֹם אֶחָד לִהְיוֹת עִמּוֹ, וְהַמֶּלֶךְ יֵשׁ לוֹ בָּנִים נָאִים וְאוֹהֲבָם, וְאָמַר לָהֶם: הוֹאִיל וְכֵן הוּא, שִׂמְחוּ גַּם אַתֶּם בְּיוֹם שִׂמְחָתִי, כִּי אֲנִי בְּשֶׁלָּכֶם אֲנִי מִשְׁתַּדֵּל, וְגַם אַתֶּם הַדְּרוּ אוֹתִי. וּמָה הַטַּעַם זָכוֹר וְשָׁמוֹר? זָכוֹר לַזָּכָר, וְשָׁמוֹר לַכַּלָּה. וּמָה הַטַּעַם וּמִקְדָּשִׁי תִירָאוּ? שִׁמְרוּ עַצְמְכֶם מִן הַהִרְהוּר, כִּי מִקְדָּשִׁי קָדוֹשׁ הוּא, לָמָּה? כִּי אֲנִי ה' בְּכָל צַד: (ע\"כ מההשמטות)."],[5,"","אָמַר רַבִּי רְחוּמַאי, מַהוּ שֶׁכָּתוּב וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרֲכֵם וַיֵּרֶד, וַהֲרֵיִ כְּבָר יָרַד? אֶלָּא וַיֵּרֶד מֵעֲשֹׂת הַחַטָּאת וְהָעֹלָה, וְאַחַר כָּךְ וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם! נְשִׂיאוּת זוֹ לָמָּה? לְפִי שֶׁהִקְרִיב קָרְבָּן וְנִתְרַצָּה לִפְנֵי אֲבִיהֶם שֶׁבַּשָּׁמַיִם. כְּמוֹ שֶׁאָמַר, צָרִיךְ אוֹתוֹ שֶׁמְּקָרְבָם לָעֶלְיוֹנִים וּמְיַחֲדָם, לְיַחֵד בִּכְלָלָם אֵלּוּ. וּמַהוּ אֶל הָעָם? בַּעֲבוּר הָעָם. וּמָה הַטַּעַם בִּנְשִׂיאוּת לְבָרֵךְ אוֹתָם בִּבְרָכָה? אֶלָּא מִשּׁוּם שֶׁיֵּשׁ בָּאָדָם עֶשֶׂר אֶצְבָּעוֹת, רֶמֶז לְעֶשֶׂר סְפִירוֹת שֶׁנֶּחְתְּמוּ בָהֶן שָׁמַיִם וָאָרֶץ: (ע\"כ מההשמטות)."],[6,"","פָּתַח רַבִּי נְהוֹרַאי בְּפָרָשַׁת צִיצִית וְדָרַשׁ, וְעָשׂוּ לָהֶם צִיצִת וְגוֹ'. כָּאן כָּתוּב לְדרֹתָם, וְגַבֵּי שַׁבָּת לְדרֹתָם, שֶׁכָּתוּב לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדרֹתָם, (חסר). שֶׁשָּׁנִינוּ, תִּקְּנוּ פָּרָשַׁת צִיצִית בִּקְרִיַּת שְׁמַע, וּבְדִירָתוֹ שֶׁל אָדָם נִמְצָא קְרִיַּת שְׁמַע, חוּץ מִפָּרָשַׁת צִיצִית שֶׁחֲסֵרָה מִשָּׁם. בַּמֶּה נִשְׁלָם? אֶלָּא כְּשֶׁהָאָדָם מִתְעַטֵּף בְּצִיצִית וְיוֹצֵא בּוֹ לְפֶתַח דִּירָתוֹ שָׁלֶם. וְהַקָּדוֹשׁ בָּרוּךָ הוּא שָׂמֵחַ, וּמַלְאָךְ הַמַּוֶת זָז מִשָּׁם, וְנִצּוֹל הָאָדָם מִכָּל נֵזֶק וּמִכָּל מַשְׁחִית. וְהַיְנוּ לְדרֹתָם, בִּשְׁבִיל דִּירָתָם. שֶׁהָיָה שָׁם שָׁלֵם וְיָצָא מִפֶּתַח בֵּיתוֹ בְּמִצְות, מַלְאָךְ הַמַּשְׁחִית זָז מִשָּׁם, וְנִצּוֹל הָאָדָם מִכָּל נֵזֶק וּמִכָּל מַשְׁחִית. מִנַּיִן לָנוּ? מִמַּה שֶּׁכָּתוּב מְזֻזוֹת. מֵהָאוֹתִיּוֹת מַשְׁמָע - זָ\"ז מָוֶ\"ת, שֶׁלֹּא נִתָּן רְשׁוּת לַמַּשְׁחִית לְחַבֵּל וְזָז מִפִּתְח וֹ."]]],[["בְּשַׁבָּת דִּכְתִיב לְדֹרֹתָם, מַאי טַעְמָא. מִפְּנֵי שֶׁכֵּיוָן שֶׁקִּידַּשׁ הַיּוֹם, דִּירָתָם שֶׁל יִשְׂרָאֵל צְרִיכָה לִהְיוֹת בְּנֵר דָּלוּק, וְשֻׁלְחָן עָרוּךְ, וּמִטָּה מְמוּצַּעַת וְדִירָתָן מְתוּקֶּנֶת כְּדִירַת חָתָן לְקַבֵּל בּוֹ הַכַּלָּה. וּמַאי נִיהוּ. שַׁבָּת הִיא כַּלָּה. וּלְעוֹלָם אֵין מַכְנִיסִין אוֹתָהּ אֶלָּא בְּדִירָה מְתוּקֶּנֶת לִכְבוֹדָהּ, כְּפִי הָרָאוּי לָהּ. וְעַל דָּא כְּתִיב, לַעֲשׂוֹת אֶת הַשַּׁבָּת. וּכְתִיב, לְדֹרֹתָם, לְהַכְנִיס בָּהּ כַּלָּה קְדוֹשָׁה לְדִירָתָהּ וְלִהְיוֹת בְּתוֹכָהּ. בְּשָׁעָה שֶׁקִּידַּשׁ הַיּוֹם, וְכַלָּה זוֹ בָּאָה, ואֵינָהּ מוֹצְאָה דִירָה מְתוּקֶּנֶת, וְשׁוּלְחָן עָרוּךְ, ונֵר דָּלוּק. כַּלָּה זוֹ אוֹמֶרֶת, אֵין דִּירָה זוֹ מִיִּשְׂרָאֵל. בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל כְּתִיב, אֵין זֶה מִיִּשְׂרָאֵל, אֵין דִּירָתוֹ לִקְדוּשָּׁה. עַל כֵּן צָרִיךְ הֶיכֵּר קְדוּשָּׁה בַּבַּיִת. וְעַל דָּא כְּתִיב לְדֹרֹתָם, בְּשַׁבָּת וּבְצִיצִית.","אָמַר רִבִּי נְהוֹרָאי, אַסְהַדְּנָא, עַל מַאן דְּנָפַק מִתְּרַע בֵּיתֵיהּ בְּעִיטּוּפָא דְמִצְוָה, וּתְפִילִּין בְּרֹאשׁוֹ, בְּשָׁעָה דְּנָפֵיק בֵּין תְּרֵין תַּרְעִין, אִזְדַּמְּנָא שְׁכִינָה עֲלֵיהּ. וּתְרֵין מַלְאָכִין דְּקָיְימִין עֲלֵיהּ, חַד מִיָּמִינָא, וְחַד מִשְּׂמָאלָא, וְכוּלְּהוֹן מְלַוִּין לֵיהּ עַד בֵּי כְּנִישְׁתָּא, וּמְבָרְכִין לֵיהּ. וְחַד מְקַטְרְגָא דְּאִיהוּ קָיְימָא קַמֵּי פִּתְחֵי דְבַר נָשׁ אָזֵיל מִבַּתְרַיְיהוּ, וְעַל כָּרְחֵיהּ אָתֵיב וַאֲמַר אָמֵן.","\u0003ספר הבהיר\u0004 מַאי טַעְמָא אָנוּ מֵטִילִין תְּכֵלֶת בַּצִּיצִית, וּמַאי טַעְמָא שְׁלֹשִׁים וּשְׁתַּיִם. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ שֶׁהָיָה לוֹ גַּן נָאֵה וְלוֹ שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת וְשָׂם שׁוֹמֵר עֲלֵיהֶן, וְהוֹדִיעוֹ לְבַדּוֹ אוֹתָן הַנְתִיבוֹת. אָמַר לוֹ, שׁוֹמְרֵם וְלֵךְ בָּהֶם בְּכָל יוֹם וְכָל זְמָן שֶׁתַדְרִיכֵם שָׁלוֹם לָךְ.","מָה עָשָׂה הַשׁוֹמֵר, אָמַר, אִם אֲנִי אֶהְיֶה לְבַדִּי בְּאֵלֶּה הַנְתִיבוֹת, אִי אֶפְשָׁר לְשׁוֹמֵר אֶחָד לְקַיֵּים אֵלּוּ הַנְתִיבוֹת. וְעוֹד כִּי יֹאמְרוּ הַעוֹלָם, כִּילַי הוּא מֶלֶךְ זֶה וְשׁוֹמֵר זֶה. לְכָךְ שָׂם שׁוֹמֵר זֶה, שׁוֹמְרִים אֲחֵרִים עַל הַנְתִיבוֹת אֵלֶה שֶׁהֵן שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת.","וּמַאי טַעְמָא דֶּתְכֶלֶת אָמַר הַשׁוֹמֵר שֶׁמָּא יֹאמְרוּ הַשׁוֹמְרִים, הַגַּן שֶׁלִי הוּא. נָתַן לָהֶם סִימָן, רְאוּ הַסִימָן לַמֶּלֶךְ שֶׁהוּא שֶׁלּוֹ, שֶׁהַגָּן הַזֶּה וְאֵלֶּה הַנְתִיבוֹת הוּא תִקְנָם, ואֵינָם שֶׁלִי וְהִנֵּה חוֹתָמוֹ.","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ וּבִּתוֹ שֶׁהָיוּ לָהֶם עֲבָדִים, בִּקְשׁוּ לֵילֵךְ מֵרָחוֹק, פַּחֲדוּ מִן אֵימַת הַמֶּלֶךְ. נָתַן לָהֶם הַמֶּלֶךְ סִימָנוֹ. פַּחֲדוּ מִן הַבַּת ונָתְּנָה לָהֶם סִימָן. אָמְרוּ, מֵעֲתָּה בִּשְׁנֵי סִימָנִין אֵלּוּ (תהילים קכ״א:ז׳) יְיָ יִשְׁמָרְךָ מִכָּל רָע, יִשְׁמֹר אֵת נַפְשֶׁךָ.","(עוד שם) וּמַאי נִיהִי, אֶרֶץ דְּנֵחְצָבָה מִמֶּנָּה שָּׁמַיִם וְהִיא כִּסְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהִיא אֶבֶן יְקָרָה, וְהִיא יַם הַחָכְמָה. וּכְנֵגְדָּה תְּכֵלֶת בְּטַלִית צִיצִית. דְּאָמַר רַבִּי מֵאִיר, מָה נִשְׁתָנָה (דאמר) תְּכֵלֶת מִכָּל מִינֵי צִבְעוֹנִין, מִפְּנֵי שֶׁתְּכֵלֶת דּוֹמֶה לַיָּם. וְהַיָּם דּוֹמֶה לָרָקִיעַ וְהַרָקִיעַ דּוֹמֶה לְכִּסֵא הַכָּבוֹד. שֶׁנֶּאֱמַר (שמות כ״ד:י׳) ויִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר וּכְתִיב כְּמַרְאֶה אֶבֶן סַפִּיר דְמוּת כִּסֵּא. (ע\"כ):","דִּכְתִיב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, דְּהַהוּא חַיָּה עִילָאָה. וּבְגִין דְּהַאי נֶפֶשׁ חַיָּה אִיהִי קַדִּישָׁא עִילָאָה, כַּד אַרְעָא קַדִּישָׁא מָשְׁכָא לָהּ בְּגַוָוהּ ואִתְכְּלִילַת בָּהּ, כְּדֵין קָרֵינַן לָהּ נְשָׁמָה. וְתָּא חֲזֵי, בְּכָל זִמְנָא דְּבַּר נָשׁ אָזִיל בְּאוֹרַח קְשׁוֹט, וּפוּמֵיה וְלִישָׁנֵיה מְמַלְלָן מִילִין קַדִּישִׁין בִּצְלוֹתָא, בְּאוֹרַיְיתָא. הַאי נִשְׁמָתָא אִתְדַבְּקַת בֵּיהּ, רְחִימָא הוּא דְּמָארֵיהּ. כַּמָה נְטוּרִין נַטְרִין לֵיהּ מִכָּל סִטְרִין. רְשִׁימָא הוּא לְטָב לְעֵילָּא וְתַתָּא וּשְׁכִינְתָּא קַדִּישָׁא שַׁרְיָיא עֲלוֹי. וְדָא הִיא דְּסַלְקָא לְעֵילָּא וּמְמַלְלָא קַמֵי מַלְכָּא קַדִּישָׁא וְעֲיְילָא בְּכָל תַרְעִין וְלֵית דְּיִמְחֵי בִּידָהָא. וְעַל דָא אִתְּקְרֵי רוּחַ מְמַלְלָא. דְּהָא כָּל שְׁאָר נָפְשָׁתַא (נפשתאן) לֵית לוֹן רֵשׁוּ לְמַלְּלָא קַמֵי מַלְכָּא בָּר הַאי."],[],[[0,"","בְּשַׁבָּת שֶׁכָּתוּב לְדרֹתָם, מָה הַטַּעַם? כֵּיוָן שֶׁקָּדַשׁ הַיּוֹם, דִּירָתָם שֶׁל יִשְׂרָאֵל צְרִיכָה לִהְיוֹת בְּנֵר דּוֹלֵק וְשֻׁלְחָן עָרוּךְ וּמִטָּה מֻצַּעַת, וְדִירָתוֹ מְתֻקֶּנֶת כְּדִירַת חָתָן לְקַבֵּל בּוֹ הַכַּלָּה. וּמִי הִיא? הַשַּׁבָּת הִיא כַּלָּה, וּלְעוֹלָם אֵין מַכְנִיסִין אוֹתָהּ אֶלָּא בְּדִירָה מְתֻקֶּנֶת לִכְבוֹדָהּ כְּפִי הָרָאוּי לָהּ, וְעַל זֶה כָּתוּב לַעֲשׂוֹת אֶת הַשַּׁבָּת. וְכָתוּב לְדרֹתָם? לְהַכְנִיס בָּהּ כַּלָּה קְדוֹשָׁה לְדִירָתָהּ וְלִהְיוֹת בְּתוֹכָהּ. בְּשָׁעָה שֶׁקָּדַשׁ הַיּוֹם, וְאִם כַּלָּה זוֹ בָּאָה וְאֵינָהּ מוֹצְאָה דִירָה מְתֻקֶּנֶת וְשֻׁלְחָן עָרוּךְ וְנֵר דּוֹלֵק - כַּלָּה זוֹ אוֹמֶרֶת: אֵין דִּירָה זוֹ מִיִּשְׂרָאֵל. כָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. אֵין זֶה מִיִּשְׂרָאֵל, אֵין דִּירָתוֹ לִקְדֻשָּׁה. וְעַל כֵּן צָרִיךְ כָּאן קְדֻשָּׁה לְדִירַת יִשְׂרָאֵל, וְעַל זֶה כָּתוּב לְדרֹתָם - בְּשַׁבָּת וּבְצִיצִית."],[1,"","אָמַר רַבִּי נְהוֹרַאי, מֵעִיד אֲנִי עָלַי, מִי שֶׁיּוֹצֵא מִשַּׁעַר בֵּיתוֹ בְּעִטּוּף שֶׁל מִצְוָה וּתְפִלִּין בְּרֹאשׁוֹ, בְּשָׁעָה שֶׁיּוֹצֵא מִבֵּין שְׁנֵי שְׁעָרִים מִזְדַּמֶּנֶת עָלָיו הַשְּׁכִינָה, וּשְׁנֵי מַלְאָכִים שֶׁעוֹמְדִים עָלָיו, אֶחָד מִימִינוֹ וְאֶחָד מִשְּׂמֹאלוֹ, כֻּלָּם מְלַוִּים אוֹתוֹ עַד בֵּית הַכְּנֶסֶת וּמְבָרְכִים אוֹתוֹ. מְקַטְרֵג אֶחָד שֶׁעוֹמֵד לִפְנֵי הַפֶּתַח שֶׁל הָאָדָם הוֹלֵךְ אַחֲרֵיהֶם, וְעַל כָּרְחוֹ מֵשִׁיב וְאוֹמֵר אָמֵן: ע\"כ מההשמטות."],[2,"","מָה הַטַּעַם אָנוּ מַטִּילִים תְּכֵלֶת בַּצִּיצִית, וּמָה הַטַּעַם שְׁלֹשׁים וּשְׁנַיִם? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיָה לוֹ גַּן נָאֶה וְלוֹ שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת, וְשָׂם שׁוֹמֵר עֲלֵיהֶן, וְהוֹדִיעוֹ לְבַדּוֹ אוֹתָן הַנְּתִיבוֹת. אָמַר לוֹ: שָׁמְרֵם וְלֵךְ בָּהֶם בְּכָל יוֹם, וּבְכָל זְמַן שֶׁתַּדְרִיכֵם שָׁלוֹם לָךְ."],[3,"","מֶה עָשָׂה הַשּׁוֹמֵר? אָמַר: אִם אֲנִי אֶהְיֶה לְבַדִּי בְּאֵלֶּה הַנְּתִיבוֹת, אֵי אֶפְשָׁר לְשׁוֹמֵר אֶחָד לְקַיֵּם אֵלּוּ הַנְּתִיבוֹת, וְעוֹד, כִּי יֹאמְרוּ הָעוֹלָם, כִּילַי הוּא מֶלֶךְ זֶה וְשׁוֹמֵר זֶה. לְכָךְ שָׂם שׁוֹמֵר זֶה שׁוֹמְרִים אֲחֵרִים עַל הַנְּתִיבוֹת, אֵלֶּה הֵן שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת."],[4,"","וּמָה הַטַּעַם שֶׁל הַתְּכֵלֶת? אָמַר הַשּׁוֹמֵר: שֶׁמָּא יֹאמְרוּ הַשּׁוֹמְרִים הַגָּן שֶׁלִּי הוּא. נָתַן לָהֶם סִימָן וְאָמַר: רְאוּ הַסִּימָן לַמֶּלֶךְ שֶׁהוּא שֶׁלּוֹ, שֶׁהַגָּן הַזֶּה וְאֵלֶּה הַנְּתִיבוֹת הוּא תִּקְּנָם, וְאֵינָם שֶׁלִּי, וְהִנֵּה חוֹתָמוֹ."],[5,"","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ וּבִתּוֹ שֶׁהָיוּ לָהֶם עֲבָדִים, בִּקְשׁוּ לֵילֵךְ מֵרָחוֹק - פָּחֲדוּ מִן אֵימַת הַמֶּלֶךְ, נָתַן לָהֶם הַמֶּלֶךְ סִימָנוֹ. פָּחֲדוּ מִן הַבַּת, וְנָתְנָה לָהֶם סִימָן. אָמְרוּ: מֵעַתָּה בִּשְׁנֵי סִימָנִים אֵלּוּ - (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע, יִשְׁמֹר אֶת נַפְשֶׁךְ."],[6,"","וּמַה הִיא? אֶרֶץ שֶׁנֶּחְצְבָה מִמֶּנָּה שָׁמַיִם, וְהִיא כִּסְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא אֶבֶן יְקָרָה, וְהִיא יָם הַחָכְמָה, וּכְנֶגְדָּהּ תְּכֵלֶת בְּטַלִּית צִיצִית. שֶׁאָמַר רַבִּי מֵאִיר, מַה נִּשְׁתַּנָּה (שאמר) תְּכֵלֶת מִכָּל מִינֵי צִבְעוֹנִין? מִפְּנֵי שֶׁתְּכֵלֶת דּוֹמֶה לַיָּם, וְהַיָּם דּוֹמֶה לָרָקִיעַ, וְהָרָקִיעַ דּוֹמֶה לְכִסֵּא הַכָּבוֹד, שֶׁנֶּאֱמַר (שמות כד) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. וְכָתוּב (יחזקאל א) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא: ע\"כ מההשמטות."],[7,"","שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, נֶפֶשׁ שֶׁל אוֹתָהּ חַיָּה עֶלְיוֹנָה, וּמִשּׁוּם שֶׁהַנֶּפֶשׁ חַיָּה הַזּוֹ הִיא קְדוֹשָׁה עֶלְיוֹנָה, כְּשֶׁהָאָרֶץ הַקְּדוֹשָׁה מוֹשֶׁכֶת אוֹתָהּ לְתוֹכָהּ וְנִכְלֶלֶת בָּהּ, אֲזַי קוֹרְאִים לָהּ נְשָׁמָה. וּבֹא רְאֵה, בְּכָל זְמַן שֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, וּפִיו וּלְשׁוֹנוֹ מְדַבְּרִים דְּבָרִים קְדוֹשִׁים, בִּתְפִלָּה וּבְתוֹרָה, הַנְּשָׁמָה הַזּוֹ נִדְבֶּקֶת בּוֹ, הוּא אָהוּב שֶׁל רִבּוֹנוֹ, כַּמָּה שׁוֹמְרִים שּׁוֹמְרִים עָלָיו מִכָּל הַצְּדָדִים, רָשׁוּם הוּא לְטוֹב לְמַעְלָה וּלְמַטָּה, וְהַשְּׁכִינָה הַקְּדוֹשָׁה שׁוֹרָה עָלָיו. וְזוֹהִי שֶׁעוֹלָה לְמַעְלָה וּמְדַבֶּרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנֶסֶת לְכָל הַשְּׁעָרִים, וְאֵין מִי שֶׁיִּמְחֶה בְיָדָהּ. וְעַל זֶה נִקְרֵאת רוּחַ מְדַבֶּרֶת, שֶׁהֲרֵי לְכָל שְׁאָר הַנְּפָשׁוֹת (נפשותינו) אֵין רְשׁוּת לְדַבֵּר לִפְנֵי הַמֶּלֶךְ פְּרָט לָזוֹ."]]],[["וּבְזִמְנָא דְּאִיהוּ אַסְטֵי אוֹרְחוֹי וְשִׂפְוָּותֵיהּ וְלִישָׁנֵיה מְמַלְלָן מִילִין בִּישִׁין, שְׁכִינְתָּא אִסְתַּלְקַת מִנֵּיהּ וְנִשְׁמָתָא קַדִּישָׁא אִתְעַבְּרַת מִנֵּיהּ וְלָא אִתְדַבְּקַת בֵּיהּ. וּמִסִטְרָא דְחִוְיָיא בִּישָׁא תַקִּיפָא אִתְעָר רוּחָא חֲדָא דְשָׁט וְאַכִיל בְּעָלְמָא, דְּלָא שַׁרְיָיא אֶלָּא בְּאֲתָר דִּקְדוּשָׁה עִילָאָה אִסְתְּלַק מִתַּמָּן.","ואִינוּן מִילִין סָלְקִין לְאֲתָר דְחִוְיָיא בִּישָׁא, דְּכֹלָּא לְאַתְרֵיהּ אִתְהַדָר. וּבְשַׁעֲתָא דְּסָלְקִין, כֹּלָּא מַכְרִיזִין וְאַמְרִין אִסְתָּלָקוּ סוּחְרָנֵיהּ דְמִלָה בִּישָׁא דִּפְלַנְיָא. פְּנוּן אֲתָר לְאָרְחֵיהּ דְחִוְיָיא תַקִּיפָא. וְהַהִיא נְשָׁמָה סַלְקָא בְּכִסּוּפָא, בְּעָאקוּ דְּכֹלָּא. וְלָא יַהֲבִין לָהּ אֲתָר לְמַלְּלָא כְּמִלְקַדְמִין. וּכְדֵין חִוְיָּיא אִזְדָּמַן.","וְכַד הַהִיא מִלָּה בִּישָׁא סַלְקָא בְּאוֹרְחִין יְדִיעָאן וְשָׁארֵי קַמֵי דְחִוְיָיא תַקִּיפָא כַּמָה רוּחִין מִתְעָרִין בְּעָלְמָא וְרוּחָא נַחְתָא מֵהַהוּא סִטְרָא, וְאַשְׁכַּח דְּהַהוּא בַּר נָשׁ אִתְעָר לֵיהּ בְּמִלָּה בִּישָׁא. וְהָא רוּחָא מְמַלְלָא קַדִּישָׁא אִתְעַבְּרַת מִנֵּיהּ, כְּדֵין שַׁרְיָיא עֲלוֹי וְסָאִיב לֵיהּ, וּכְדֵין הוּא סָגִיר ואִתְפְּגִים בִּבְשָׂרֵיהּ בְּחִיזוּ דְּאַנְפּוֹי בְּכֹלָּא.","וְעַל דָא כְּתִיב (משלי כ״א:כ״ג) שׁוֹמֵר פִּיו וּלְשׁוֹנוֹ שׁוֹמֵר מִצָרוֹת נַפְשׁוֹ. נַפְשׁוֹ וַדַּאי, הַהִיא דְהָוָה מְמַלְלָא אִתְעֲבִידַת מַשְׁתוּקָא בְּגִין מִלוּלָא בִּישָׁא וּכְמָּה דְּעוֹנְשָׁא דְּבַּר נָשׁ בְּהַאי, בְּגִין מִלָּה בִּישָׁא, כָּךְ עוֹנְשֵׁיהּ בְּגִין מִלָּה טָבָא (דאתי לידיה דיכיל למללא ולא מליל):","וְכִי בְּכָל עֵת יָכִיל בַּר נָשׁ לְמֶעְבַּד צְדָקָה, אִי הָכִי תְרֵיסָר שַׁעְתֵּי בְּיוֹמָא מַאן יָכִיל. אֶלָּא הָכִי אוֹלִיפְנָא, מַאן דְּעָבִיד צְדָקָה בְּכָל עֵת. מַאי בְּכָל עֵת, כְּמָה דְאַתְּ אָמֵר (ויקרא ט״ז:ב׳) וְאַל יָבֹא בְּכָל עֵת אֶל הַקּוֹדֶשׁ, ואוּקְמוּהָ.","וְלָא תֵימָא בִּכְנֶסֶת יִשְׂרָאֵל בִּלְחוֹדוֹי, דְּאִיהִי עֵת רַעֲוָא קַדִּישָׁא בְּצַדִיק. אֶלָּא אֲפִילּוּ בְּכָל עֵת דִּלְתַתָּא אַסְגֵּי צְדָקָה עֲלַיְיהוּ ואִתְעַר צְדָקָה בְּכֻלְּהוּ, בְּעִלָּאֵי וְתַתָּאֵי. בְּגִין כָּךְ יְשַׁוִּי לִבֵּיהּ וּרְעוּתֵיהּ בַּר נָשׁ וְיִדְבַּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.","כֵּיוָן דְּמָטוּ קַמֵי דְּרַבִּי שִׁמְעוֹן סָחוּ לֵיהּ עוֹבָדָא. אָמַר, וּמָה דָא בִּלְחוֹדוֹי, אֲפִילּוּ כָּל מַאן דְאֲחִיד לְּאִילָנָא (באילנא) דְחַיֵי אִשְׁתֵּזִיב בְּהַאי עַלְמָא ואֲפִילּוּ מִן מוֹתָא דְּעָלְמָא, מִשְׁאָר בְּנֵי נָשָׁא. כָּל שֶׁכֵּן מְאַחֲרָא.","אָמַר רַבִּי שִׁמְעוֹן בְּכֻלְּהוּ אִתְעָר צְדָקָה אִילָנָא דְחַיֵי, וְהַאי אֲתָר אִיהוּ דִּמְזוֹנָא לְכֹלָא לְתַלְמִידֵי חֲכָמִים. מַאי עֲבִידְתַיְיהוּ דְּהָא כָּל בְּנֵי עַלְמָא לָא יַכְלֵי לְאִתְעָרָא צְדָקָה עֲלַיְיהוּ, דְּהָא אִינוּן בִּצְדָקָה אֲחִידָן וְכָל בְּנֵי עַלְמָא בִּזְכוּתַיְיהוּ נִזוֹנִין, בְּהוּ מַמָּשׁ. ואִינוּן לָא יַכְלִין לְאִתְזָנָא בְּהוּ מַמָּשׁ, בְּגִין דְּכָל מַאן דְּאִשָׁתַדָל בְּאוֹרַיְיתָא, אִשְׁתַּדַּל בְּאִילָנָא דְחַיֵי דְּכָל בְּנֵי עַלְמָא נִזוֹנִין מִנֵּיהּ. אִשְׁתְּכַּח דְּתַלְמִידֵי חֲכָמִים מִתְעָרֵי מְזוֹנָא לְעַלְמָא וּשְׁלָמָא.","אִי לְכָל בְּנֵי עַלְמָא מִתְעָרֵי מְזוֹנָא, לוֹן אֲמַאי לָא מִתְעָרֵי. אֶלָּא תַּלְמִיד חָכָם הוּא אִילָנָא דְחַיֵי מַמָּשׁ. וְאִילָנָא דְחַיֵי לָא מִתְּזָן אֶלָּא מִן הָעוֹלָם הַבָּא. וְהָעוֹלָם הַבָּא לָא אִשְׁתְּכַּח בְּהַאי עַלְמָא אֶלָּא לְבָתַר דְּעָאל לְהַהוּא עַלְמָא, כְּדֵין אִתְּזָן בֵּיהּ וְאִתְנֵטָעוּ שָׁרְשׁוֹי עָלֵיהּ.","הַשְׁתָּא אַכְלֵי מֵאִיבָּא דְּאִילָנָא דְחַיֵי. וּמָאן אִיהוּ, הַהוּא אֲתָר דְּאִשְׁתַּכַּח לְגַבֵּי מִסְכְּנָא וְאִיהוּ אִקְרֵי (בראשית ג׳:ג׳) פְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגַּן. וְעַל דָּא אַכְלֵי מֵהַהוּא פְּרִי בְּהַאי עַלְמָא.","וְעַל דָּא תָנֵינָן, הֵם נִזוֹנִין בִּזְרוֹעַ. מַאי בִּזְרוֹעַ, דָא גְּבוּרָה. וְאִינוּן זְמִינִין לְעוֹלָם הַבָּא. דִּמְזוֹנָא דְּעוֹלָם הַבָּא, לָאו אִיהִי בְּהָאי עַלְמָא, אֶלָּא צִמְצוּמָא זְעִירָא דְּחֵילָא דִּילֵיהּ, דְאִשְׁתַּכַּח בִּמְתִיקוּ דְּאוֹרַיְיתָא. וְדָא טַעֲמֵי עַל הַהוּא אִיבָּא דְּאִילָנָא תַּתָּאָה וְדָא חֵידוּ דְּתַלְמִידֵי חֲכָמִים וּמְזוֹנָא עִילָאָה דִּילְהוֹן.","כֵּיוָן דְּיַעֲבְרוּן מֵהַאי עַלְמָא, כַּמָה נְחָלִין עִלָּאִין דְּעוֹלָם הַבָּא סָחֲרָן לְדוּכְתַיְיהוּ, וְיִשְׁתַרְשׁוּן בֵּיהּ וְיִסְתָלְקוּן לְעֵילָּא לְעֵילָּא. כְּמָה דְאַתְּ אָמֵר (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאֲתָה אֱלֹהִים זוּלָתֶךָ יָעֲשֶׂה לִמְחַכֵּה לוֹ. מַאי יָעֲשֶׂה, דָא יוֹבְלָא. הַהוּא דְּאִקְּרֵי הָעוֹלָם הַבָּא. לִמְחַכֵּה לוֹ ודַּאי, דְּלָא בַּעְיָין מְזוֹנָא לְעַלְמָא דָא, עַד דְּאָתַאן (ס\"א דאתקן) לִמְזוֹנָא דִּילְהוֹן. וּמַאי מְזוֹנָא דִּילְהוֹן, הָעוֹלָם הַבָּא. וְעַל דָא זַכָּאָן בְּכֹלָּא. דְּעָלַיְיהוּ כְּתִיב עַיִן לֹא רָאֲתָה אֱלֹהִים וְגוֹ':","שִׁבְעָה יוֹמִין עִלָּאִין, בָּרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא. וַעֲלַיְיהוּ שָׁתֵיל וּבָנֵי עָלְמִין. הֲדָא הוּא דִכְתִיב (שמות כ׳:י״א) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה', וְלֹא כְתִיב בְּשֵׁשֶׁת. וְלָקֳבֵיל אִינוּן שִׁבְעָה יוֹמִין עִילָּאִין, בָּרָא בְּאַרְעָא שִׁבְעָה זַכָּאֵי קְשׁוֹט, לְקָיְימָא לוֹן, וּלְאַנְהָרָא לוֹן, כָּל חַד וְחַד לָקֳבֵיל יוֹמֵיהּ. וְשָׁתֵיל לְהוֹ, כָּל חַד וְחַד בְּדָרָא דְּאִתְחֲזֵי לֵיהּ. ואִינוּן אֲבָהָן דְּעָלְמָא, אַבְרָהָם יִצְחָק ויַעֲקֹב וְיוֹסֵף וּמשֶׁה וְאַהֲרֹן וְדָוִד."],[],[[0,"","וּבִזְמַן שֶׁהוּא מַסְטֶה אֶת דְּרָכָיו, וְשִׂפְתוֹתָיו וּלְשׁוֹנוֹ מְדַבְּרִים דִּבּוּרִים רָעִים, הַשְּׁכִינָה מִסְתַּלֶּקֶת מִמֶּנּוּ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה עוֹבֶרֶת מִמֶּנּוּ וְלֹא נִדְבֶּקֶת בּוֹ. וּמִצַּד שֶׁל הַנָּחָשׁ הָרָע הַקָּשֶׁה מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁמְּשׁוֹטֶטֶת וְאוֹכֶלֶת בָּעוֹלָם, שֶׁאֵין שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁקְּדֻשָּׁה עֶלְיוֹנָה הִסְתַּלְּקָה מִשָּׁם."],[1,"","וְאוֹתָם דִּבּוּרִים עוֹלִים לִמְקוֹם הַנָּחָשׁ הָרָע, שֶׁהַכֹּל חוֹזֵר לִמְקוֹמוֹ. וּבְשָׁעָה שֶׁמַּעֲלִים, הַכֹּל מַכְרִיזִים וְאוֹמְרִים: הִסְתַּלְּקוּ מִסְּבִיבוֹ שֶׁל הַדִּבּוּר הָרָע שֶׁל פְּלוֹנִי! פַּנּוּ מָקוֹם לְדַרְכּוֹ שֶׁל הַנָּחָשׁ הַקָּשֶׁה! וְאוֹתָהּ נְשָׁמָה עוֹלָה בְּבוּשָׁה וּבְצָרַת הַכֹּל, וְלֹא נוֹתְנִים לָהּ מָקוֹם לְדַבֵּר כְּמִקֹּדֶם, וְאָז מִזְדַּמֵּן הַנָּחָשׁ."],[2,"","וּכְשֶׁאוֹתוֹ הַדִּבּוּר הָרָע עוֹלֶה בִּדְרָכִים יְדוּעוֹת וְשׁוֹרֶה לִפְנֵי הַנָּחָשׁ הַקָּשֶׁה, כַּמָּה רוּחוֹת מִתְעוֹרְרוֹת בָּעוֹלָם, וְרוּחַ יוֹרֶדֶת מֵאוֹתוֹ הַצַּד, וּמוֹצֵאת שֶׁאוֹתוֹ אָדָם עוֹרֵר אוֹתָהּ בְּדִבּוּר רָע, וַהֲרֵי הָרוּחַ הַמְדַבֶּרֶת הַקְּדוֹשָׁה עָבְרָה מִמֶּנּוּ, אָז שׁוֹרָה עָלָיו וּמְטַמֵּאת אוֹתוֹ, וְאָז הוּא סָגוּר, וְנִפְגָּם בְּשָׂרוֹ בְּמַרְאֵה פָנָיו בַּכֹּל,"],[3,"","וְעַל זֶה כָּתוּב שֹׁמֵר פִּיו וּלְשׁוֹנוֹ שֹׁמֵר מִצָּרוֹת נַפְשׁוֹ, נַפְשׁוֹ וַדַּאי. אוֹתָהּ שֶׁהָיְתָה מְדַבֶּרֶת, נֶעֶשְׂתָה מְשֻׁתֶּקֶת מִשּׁוּם דִּבּוּר רָע. וּכְמוֹ שֶׁעָנְשׁוֹ שֶׁל אָדָם בָּזֶה מִשּׁוּם אוֹתוֹ דִבּוּר רָע, כָּךְ עָנְשׁוֹ בִּגְלַל דִּבּוּר טוֹב (שבא לידו שיכל לדבר ולא דבר). ע\"כ מההשמטות."],[4,"","וְכִי בְכָל עֵת יָכוֹל אָדָם לַעֲשׂוֹת צְדָקָה? אִם כֵּן, שְׁתֵּים עֶשְׂרֵה שָׁעוֹת בְּיוֹם מִי יָכוֹל?! אֶלָּא כָּךְ לָמַדְנוּ, מִי שֶׁעוֹשֶׂה צְדָקָה בְּכָל עֵת. מַהוּ בְּכָל עֵת? כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טז) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ, וּבֵאֲרוּהָ."],[5,"","וְלֹא תֹאמַר בִּכְנֶסֶת יִשְׂרָאֵל לְבַדָּהּ, שֶׁהִיא עֵת רָצוֹן קָדוֹשׁ בְּצַדִּיק, אֶלָּא אֲפִלּוּ בְכָל עֵת שֶׁלְּמַטָּה מַרְבֶּה צְדָקָה עֲלֵיהֶם, וּמִתְעוֹרֶרֶת צְדָקָה בְּכֻלָּם, בְּעֶלְיוֹנִים וְתַחְתּוֹנִים. מִפְּנֵי כֵן יָשִׂים אָדָם לִבּוֹ וּרְצוֹנוֹ וְיִדְבַּק בּוֹ בַּקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","כֵּיוָן שֶׁהִגִּיעוּ לִפְנֵי רַבִּי שִׁמְעוֹן, סִפְּרוּ לוֹ הַמַּעֲשֶׂה. אָמַר, וּמַה זֶּה בְּעַצְמוֹ, אֲפִלּוּ כָּל מִי שֶׁמַּחֲזִיק לְאִילַן (באילן) הַחַיִּים נִצּוֹל בָּעוֹלָם הַזֶּה, וַאֲפִלּוּ מִן מִיתַת הָעוֹלָם מִשְּׁאָר בְּנֵי אָדָם, כָּל שֶׁכֵּן מֵאַחֵר."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, בְּכֻלָּם מְעוֹרֶרֶת הַצְדָקָה אֶת אִילַן הַחַיִּים, וּמָקוֹם זֶה הוּא הַמָּזוֹן לַכֹּל, וּלְתַלְמִידֵי הַחֲכָמִים מַה מַּעֲשֵׂיהֶם? שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם לֹא יְכוֹלִים לְעוֹרֵר צְדָקָה עֲלֵיהֶם, שֶׁהֲרֵי הֵם אֲחוּזִים בִּצְדָקָה, וְכָל בְּנֵי הָעוֹלָם נִזּוֹנִים בִּזְכוּתָם, בָּהֶם מַמָּשׁ. וְהֵם לֹא יְכוֹלִים לְהִתְפַּרְנֵס מֵהֶם מַמָּשׁ, מִפְּנֵי שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, מִשְׁתַּדֵּל בְּאִילַן הַחַיִּים שֶׁכָּל בְּנֵי הָעוֹלָם מִתְפַּרְנְסִים מִמֶּנּוּ. נִמְצָא שֶׁהַתַּלְמִידֵי חֲכָמִים מְעוֹרְרִים מָזוֹן לָעוֹלָם וְשָׁלוֹם."],[8,"","אִם לְכָל בְּנֵי הָעוֹלָם מִתְעוֹרֵר מָזוֹן, מַדּוּעַ לָהֶם לֹא מִתְעוֹרֵר? אֶלָּא תַּלְמִיד חָכָם הוּא אִילַן הַחַיִּים מַמָּשׁ, וְאִילַן הַחַיִּים לֹא נִזּוֹן אֶלָּא מִן הָעוֹלָם הַבָּא, וְהָעוֹלָם הַבָּא לֹא נִמְצָא בָּעוֹלָם הַזֶּה, אֶלָּא לְאַחַר שֶׁעוֹלֶה לָעוֹלָם הַהוּא, אָז נִזּוֹן מִמֶּנּוּ וְנִשְׁרָשׁ שָׁרָשָׁיו עָלָיו."],[9,"","עַכְשָׁו אוֹכְלִים מִפְּרִי עֵץ הַחַיִּים. וּמַה הוּא? אוֹתוֹ מָקוֹם שֶׁנִּמְצָא אֵצֶל הָעֲנִיִּים, וְהוּא נִקְרָא (בראשית ג) פְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וְעַל זֶה אוֹכְלִים מֵהַפְּרִי הוּא בָּעוֹלָם הַזֶּה."],[10,"","וְעַל זֶה לָמַדְנוּ, הֵם נִזּוֹנִים בִּזְרוֹעַ. מַהִי הַזְּרוֹעַ? זוֹ גְבוּרָה. וְהֵם מְזֻמָּנִים לָעוֹלָם הַבָּא. שֶׁמְּזוֹן הָעוֹלָם הַבָּא אֵינוֹ בָּעוֹלָם הַזֶּה, אֶלָּא צִמְצוּם קָטָן שֶׁל הַכֹּחַ שֶׁלּוֹ שֶׁנִּמְצָא בִּמְתִיקוּת הַתּוֹרָה. וְזֶה טַעֲמוֹ עַל הַפְּרִי הַהוּא שֶׁל הָעֵץ הַתַּחְתּוֹן, וְזוֹ שִׂמְחָה שֶׁל הַתַּלְמִידֵי חֲכָמִים וּמָזוֹן הָעֶלְיוֹן שֶׁלָּהֶם."],[11,"","כֵּיוָן שֶׁיַּעַבְרוּ מֵהָעוֹלָם הַזֶּה, כַּמָּה נְחָלִים עֶלְיוֹנִים שֶׁל עוֹלָם הַבָּא מַקִּיפִים לִמְקוֹמָם, וְיִשְׁתָּרְשׁוּ בוֹ וְיַעֲלוּ לְמַעְלָה לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. מַהוּ יַעֲשֶׂה? זֶה הַיּוֹבֵל, זֶה שֶׁנִּקְרָא עוֹלָם הַבָּא. לִמְחַכֵּה לוֹ, וַדַּאי. שֶׁלֹּא רוֹצִים מָזוֹן לָעוֹלָם הַזֶּה עַד שֶׁיַּגִּיעוּ (שיתקן) לַמָּזוֹן שֶׁלָּהֶם. וּמַהוּ הַמָּזוֹן שֶׁלָּהֶם? הָעוֹלָם הַבָּא. וְעַל זֶה זַכָּאִים בַּכֹּל, שֶׁעֲלֵיהֶם כָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים וְגוֹ': (עד כאן מההשמטות). שִׁבְעָה יָמִים עֶלְיוֹנִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, וַעֲלֵיהֶם שָׁתַל וּבָנָה עוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה', וְלֹא כָתוּב בְּשֵׁשֶׁת."],[12,"","וּכְנֶגֶד אוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ שִׁבְעָה צַדִּיקֵי אֱמֶת, לְהַעֲמִידָם וּלְהָאִיר לָהֶם כָּל אֶחָד וְאֶחָד כְּנֶגֶד יוֹמוֹ, וְשָׁתַל אוֹתָם כָּל אֶחָד וְאֶחָד בְּדוֹר שֶׁרָאוּי, וְהֵם אֲבוֹת הָעוֹלָם, אַבְרָהָם יִצְחָק וְיַעֲקֹב יוֹסֵף מֹשֶׁה אַהֲרֹן דָּוִד."]]],[["וְאִינוּן אִיקְרוּן הָרִים, הַרְרֵי קֶדֶם, דְּאִינוּן תַּלְיָיִן מֵאִינוּן שִׁבְעָה יוֹמִין עִילָּאִין דַּאֲמָרָן. ו' יוֹמֵי בְּרֵאשִׁית, וְז' דְּקָיְימָא קַמַּיְיהוּ, הֲדָא הוּא דִכְתִיב, (זכריה י״ב:ח׳) וּבֵית דָּוִד כֵּאלֹהִים כְּמַלְאַךְ ה' לִפְנֵיהֶם. וְאַף עַל גַּב דְּאִיהוּ שְׁבִיעָאָה, רְבִיעָאָה אִיהוּ בְּיוֹמִין. וְיוֹסֵף אִיהוּ שְׁבִיעָאָה. אֲבָל כַּד אִתְכְּלִילַת בֵּיהּ בְּיוֹסֵף, וְיָהֵיב לֵיהּ תּוֹסֶפֶת תַּפְנוּקָא מִבֵּי מַלְכָּא, אִקְרֵי אוּף אִיהִי שְׁבִיעָאָה.","וְכָלְהוֹ אֲחִידוּ בַּה בִּשְׁכִינְתָּא, בְּרָזָא דְּשִׁבְעָה. בְּגִין דִּשְׁכִינְתָּא אִיקְרֵי בַּת שֶׁבַע. בַּת מֵאִימָּא עִילָּאָה, דְּאִיהִי כְּלָלָא דְּשֶׁבַע דַּרְגִּין דְּעִמַּהּ. וְאִיהִי דַּרְגָּא דְּצֶדֶק, עֲשִׂירָאָה דְּאִינוּן סְפִירִין, דְּאִיקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא.","וְאִיקְרֵי שְׁבִיעָאָה בִּקְרָא, (דברי הימים א כ״ט:י״א) דִּלְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד כִּי כֹל וכו', עַד הַמַּמְלָכָה. וּמַאי טַעְמָא, וְהָא רְבִיעָאָה הִיא לְיוֹמֵי. אֶלָּא בְּגִין דְּאִיהִי נְטִיעָה בַּתְרָאָה, ואִתְכְּלִילַת בִּשְׁבִיעָאָה, בְּגִין כָּךְ נָטְלָה שְׁמֵיהּ, וְכוֹלָּא חַד.","וְכָל חַד וְחַד מֵאֲבָהָן, יָדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ אַסְפַּקְלַרְיָא דִילֵיהּ. אַבְרָהָם יָדַע לֵיהּ, מִגּוֹ חֶסֶד, דְּאִיהוּ מִדַּת הַגְּדוּלָּה, מִדַּת הַחֶסֶד, יָמִינָא דְמַלְכָּא. וְעַל דָּא אָחִיד בָּהּ, וְלָא שָׁבִיק לָהּ לְעָלְמִין, וְעָבִיד טִיבוּ עִם בְּנֵי נָשָׁא, ואוֹקְמוּהָ. דְּהָא עוֹבָדוֹי סְלִיקוּ לֵיהּ בְּהַאי דַרְגָּא.","יִצְחָק יָדַע לֵיהּ בְּדַרְגָּא דִּגְבוּרָה, דְּאִקְרֵי פַּחַד יִצְחָק, וְדָחִיל לֵיהּ לְעָלְמִין. יַעֲקֹב יָדַע לֵיהּ מִגּוֹ דַּרְגָּא דְּתִפְאֶרֶת. דְּאִיהוּ כָּלִיל מֵחֶסֶד וּמִפַּחַד, וְאִקְרֵי אֱמֶת, ואָחִיד בַּהּ. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב.","יוֹסֵף יָדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא מִגּוֹ הַהִיא אַסְפַּקְלַרְיָא, דְּאִקְרֵי כֹל. וְעַל דָּא אִיקְרֵי יוֹסֵף כִּלְכֵּל, דִּכְתִיב (בראשית מ״ז:י״ב) ויְכַלְכֵּל יוֹסֵף. ואִיקְרֵי יְסוֹד עוֹלָם.","משֶׁה וְאַהֲרֹן אִינוּן תְּרֵין כְּרוּבִין, דְּאִשְׁתְּמַע קָלָא דִּלְעֵילָא מִבֵּינַיְיהוּ, וְעַל דָּא אִתְיְיהִיבַת אוֹרַיְיתָא עַל יָדַיְיהוּ. הֲדָא הוּא דִכְתִיב, וְנוֹעַדְתִּי לְךָ שָׁם וְדִבַּרְתִּי אִתְּךָ וְגוֹמֵר. וְאִינוּן תְּרֵין כְּרוּבִין דִּלְעֵילָא, אִינוּן נֵצַח וָהוֹד, וְאִינוּן תְּרֵין סַמְכִין דְּגוּפָא.","כְּגַוְונָא דָא, אִית לָהּ לְמַטְרוֹנִיתָא לְתַתָּא, תְּרֵין כְּרוּבִין תְּחוֹתָהּ, דְּיָנְקִין מִינָהּ. וְאִינוּן עִילָּאִין ודַּאי, עַל אֲרוֹן הָעֵדוּת, דְּאִיקְרֵי צֶדֶק, אֲרוֹנָא דְעֵדוּת. וּמַאן עֵדוּת, דָּא יוֹסֵף, הֲדָא הוּא דִכְתִיב, (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שָׂמוֹ. וְאִיקְרֵי תּוֹרָה שֶׁבִּכְתַב, וְהַאי אֲרוֹנָא תּוֹרָה שֶׁבְּעַל פֶּה.","תָּא חֲזֵי, כָּל אִינוּן אֲבָהָן עִילָּאִין דַּאֲחִידָן לְעֵילָא, רְמִיזָן כָּלְהוֹ בַּתּוֹרָה שֶׁבִּכְתָב, תּוֹרַת ה'. וְדָוִד דְּאִיהוּ אָחִיד בְּבָרְיָיתָא, דְּאִיהִי תּוֹרָה שֶׁבְּעַל פֶּה, רְמִיזָא בְּדִבְרֵי קַבָּלָה. וּבְגִין כָּךְ אִקְרֵי קַבָּלָה, דִּמְקַבֶּלֶת נְהִירוּ מִתּוֹרָה שֶׁבִּכְתָב, דְּאִיקְרֵי צַדִּיק, וְאִיקְרֵי יוֹסֵף, ואִיקְרֵי כֹל.","וְאִינוּן תְּרֵין כְּרוּבִין עִילָּאִין, קָיְימִין עַל הַהוּא סַהֲדוּתָא דַּאֲרוֹנָא, הֲדָא הוּא דִכְתִיב, (דברי הימים א כ״ט:י״א) וְהַנֵּצַח וְהַהוֹד, כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְדָא אִיהוּ סִיּוּמָא דִּשְׁמַיָא וּמְזַוִּוג לְהַאי אֶרֶץ.","וְהָכֵי הוּא, דְּכָל מַה שֶּׁבָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא, בָּרָא לְקִבְלֵיהּ לְתַתָּא. וְיוֹסֵף אִקְרֵי עֵדוּת, הֲדָא הוּא דִכְתִיב עֵדוּת בִּיהוֹסֵף שָׂמוֹ. וְעַל דָּא שְׁמָא דְיוֹסֵף שְׁלִים בְּכֹלָּא לְעֵילָא וְתַתָּא.","וְעַל דָּא תָּנִינָן, אָרוֹן דְּיוֹסֵף ואָרוֹן דִּשְׁכִינְתָּא, בַּהֲדֵי הֲדָדֵי הֲווֹ אָזְלִין בְּמַדְבְּרָא, וַהֲווּ כּוּלֵּי עָלְמָא אָמְרֵי מַה טִּיבָן שֶׁל שְׁנֵי אֲרוֹנוֹת אֵלּוּ. וּמְתִיבִין לוֹן, קִיֵּים זֶה מַה שֶּׁכָּתוּב בָּזֶה. קִיֵּי\"ם ודַּאי, הֲדָא הוּא דִכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, אִיהוּ קִיּוּמָא דְעָלְמָא.","אָתָא דָוִד דְּאִיהוּ שְׁבִיעָאָה, דַּאֲבָהָן אָחִיד בַּהּ, בְּהַאי בַּת שֶׁבַע, דְּאִיהִי מַמְלָכָה, וְלָא שָׁבִיק לָהּ לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ז:כ״ה-כ״ו) וְדָוִד עַבְדִּי נָשִׂיא לָהֶם לְעוֹלָם. וּכְתִיב, (תהילים פ״ט:ל״ז) כִּסְאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי. וְכָל דָּא אוֹלִיף לָן אוֹרַיְיתָא, דְּכָלְהוֹ אֲחִידָן בַּהּ בִּשְׁכִינְתָּא בְּרָזָא דְּשֶׁבַע.","תָּא חֲזֵי, אַבְרָהָם בּוּצִינָא קַדְמָאָה קַדִּישָׁא דְעָלְמָא, כַּד בָּעָא לְסַלְקָא לְדַרְגֵּיהּ, לָא יָכִיל, עַד דְּסָלֵיק ואִשְׁתְּמוֹדַע בְּאִינוּן תְּלַת דַּרְגִּין עִילָּאִין דַּעֲלֵיהּ, דְּהַהוּא חוּלָקָא דִילֵיהּ.","כֵּיוָן דְּסָלֵיק וְאִשְׁתְּמוֹדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ אִינוּן תְּלַת דַּרְגִּין, דְּעִם אִינוּן שִׁבְעָה, דְּאִיקְּרוֹן כֶּתֶר עֶלְיוֹן חָכְמָה בִּינָה, ואִינוּן שְׁלִימוּ דְּעֶשֶׂר סְפִירָן, דְּאִיקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּסָלֵיק אַחַר כַּךְ בְּאִינוּן תְּלָתָא, דְּאִינוּן עַתִּיקָא וְאַבָּא וְאִימָא, דְּנָגֵיד מִנְּהוֹן נְהִירוּ לְתַתָּא, כְּדֵין אָחִיד לְחוּלָקֵיהּ, הַהוּא דַרְגָּא דִּתְחוֹתַיְיהוּ דְּאִינוּן תְּלָתָא, דְּאִיקְרֵי חֶסֶד.","וְכָלְהוֹ אַדְבֵּיק לוֹן, מִגּוֹ אַסְפַּקְלַרְיָא דְּשָׁלְטָא בְּלֵילְיָא, דִּבְהוֹ מַמָּשׁ לָא הֲוָה בַּר נָשׁ דְּיָדַע כְּלוּם. וְעַל דָּא תָּנִינָן, בֶּן שְׁלשָׁה שָׁנִים, הִכִּיר אַבְרָהָם אֶת בּוֹרְאוֹ, בֶּן שְׁלשָׁה דַּיְיקָא.","וְתָּא חֲזֵי, רָזָא דְּהַנֵּי שְׁלשָׁה שְׁנִין, וְלָא פָּחוֹת, בְּגִין דִּשְׁכִינְתָּא אִקְרֵי בַּת שֶׁבַע, וְלָא יָכֵיל לְאִתְקְרָבָא בַּהֲדָהּ, עַד דְּסָלֵיק בְּאִינוּן תְּלַת דַּרְגִּין עִילָּאִין, דְּעִם אִינוּן ז', לְאִשְׁתְּמוֹדְעָא מִגַּוָּון, וּלְאִתְנַהֲרָא בְּכָל מַאי דְּאִיהוּ לְתַתָּא, וְג' וְז', הָא עֶשֶׂר דַּרְגִּין עִלָּאִין, רָזָא דִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא.","וְכֵיוָן דְּהֲוָה מִתְנְהֵיר בְּאִינוּן שְׁלשָׁה, בָּעָא לְסַלְקָא בְּאִינוּן שֶׁבַע, בְּרָזָא דִּכְתִיב, (בראשית כ״א:כ״ח) וַיַּצֶּב אַבְרָהָם אֶת שֶׁבַע כִּבְשׂת הַצֹּאן. וְרָזָא דָא רָמֵיז לַאֲבִימֶלֶךְ, דְּלָא יִשְׁלְטוּן עֲלֵיהוֹן בְּנוֹי, עַד דְּיִשְׁתְּלִימוּ אִינוּן שִׁבְעָה זַכָּאֵי קְשׁוֹט בְּיִשְׂרָאֵל, לָקֳבֵיל אִינוּן שִׁבְעָה דַרְגִּין דִּלְעֵילָא.","כֵּיוָן דְּיִשְׁתְּלִימוּ, יָתֵיב עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִילָּאָה. בְּקִיּוּמָא שְׁלִים. ויֵיתֵי דָוִד, דְּאִיהוּ שְׁבִיעָאָה, וְיִתְעַר לְהַהִיא בַּת שֶׁבַע דִּלְעֵילָא, דְּאִיהִי נָקְמָא נִקְמַתְהוֹן דְּיִשְׂרָאֵל, וְיִתְפְּרַע מִנְּהוֹן.","הֲדָא הוּא דִכְתִיב, (שמואל ב ח׳:א׳) וַיְהִי אַחֲרֵי כֵן וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם וַיִּקַּח דָּוִד אֶת מֶתֶג הָאַמָּה מִיַּד פְּלִשְׁתִּים. מַאי וַיְהִי אַחֲרֵי כֵן. בָּתַר דְּאִשְׁתְּלִימוּ יִשְׂרָאֵל, וַהֲווּ כְּגַוְונָא דִּלְעֵילָא, כְּדֵין וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם. דְּהָא עַד הַשְׁתָּא לָא יָכִילוּ יִשְׂרָאֵל לְמִיתְבַּר תּוֹקְפֵיהוֹן, וְהָא אִיתְעָרוּ חַבְרַיָיא בְּהַהוּא מֶתֶג הָאַמָּה, וְאוֹקְמוּהָ."],[],[[0,"","וְהֵם נִקְרָאִים הָרִים, הַרְרֵי קֶדֶם, שֶׁהֵם תְּלוּיִים מֵאוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים, וְהַשְּׁבִיעִי שֶׁעוֹמֵד לִפְנֵיהֶם, זֶהוּ שֶׁכָּתוּב (זכריהיב) וּבֵית דָּוִיד כֵּאלֹהִים כְּמַלְאַךְ ה' לִפְנֵיהֶם. וְאַף עַל גַּב שֶׁהוּא שְׁבִיעִי, ..., כְּשֶׁנִּכְלָל בּוֹ בְּיוֹסֵף וְנוֹתֵן לוֹ תַּפְנוּק מִבֵּית הַמֶּלֶךְ, נִקְרָא גַּם הוּא שְׁבִיעִי."],[1,"","וְכֻלָּם אֲחוּזִים בַּשְּׁכִינָה בְּסוֹד שֶׁל שִׁבְעָה, מִשּׁוּם שֶׁהַשְּׁכִינָה נִקְרֵאת בַּת שֶׁבַע, בַּת מֵאֵם הָעֶלְיוֹנָה, שֶׁהִיא כְּלַל שֶׁבַע דְּרָגוֹת שֶׁעִמּוֹ, וְהִיא דַּרְגָּה שֶׁל צֶדֶק הָעֲשִׂירִי, שֶׁהֵן סְפִירוֹת שֶׁנִּקְרָא בָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","וְנִקְרָא שְׁבִיעִי בַּכָּתוּב, שֶׁכָּתוּב (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּ\"ה וְהַגְּבוּרָ\"ה וְהַתִּפְאֶרֶ\"ת וְהַנֵּצַ\"ח וְהַהוֹ\"ד כִּי כֹל וְכוּ', עַד הַמַּמְלָכָה. וּמָה הַטַּעַם? וַהֲרֵי הִיא רְבִיעִית לַיָּמִים! אֶלָּא בִּגְלַל נְטִיעָה אַחֲרוֹנָה וְנִכְלֶלֶת בַּשְּׁבִיעִית, מִשּׁוּם כָּךְ לָקְחָה שְׁמוֹ, וְהַכֹּל אֶחָד."],[3,"","וְכָל אֶחָד וְאֶחָד מֵהָאָבוֹת יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ דַּרְגָּתוֹ וְאָחַז בּוֹ בְּאוֹתָהּ דַּרְגָּה. אַבְרָהָם יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁלּוֹ, שֶׁהִיא מִדַּת הַגְּדֻלָּה, מִדַּת הַחֶסֶד, שֶׁהִיא יְמִין הַמֶּלֶךְ, וְעַל כָּךְ הוּא אָחַז בָּהּ וְלֹא עָזַב אוֹתָהּ לְעוֹלָמִים, וְעָשָׂה טוֹב עִם כָּל בְּנֵי הָעוֹלָם, וּפֵרְשׁוּהָ שֶׁהֲרֵי מַעֲשָׂיו הֶעֱלוּהוּ לַדַּרְגָּה הַזֹּאת."],[4,"","יִצְחָק יָדַע אוֹתוֹ בְּדַרְגַּת הַגְּבוּרָה, שֶׁנִּקְרֵאת פַּחַד יִצְחָק, וּפָחַד מִמֶּנּוּ לְעוֹלָמִים. יַעֲקֹב יָדַע אוֹתוֹ מִתּוֹךְ דַּרְגַּת הַתִּפְאֶרֶת, שֶׁהוּא כָּלוּל מֵחֶסֶד וּמִפַּחַד, וְנִקְרָא אֱמֶת, וְאָחַז אוֹתָהּ, זֶהוּ שֶׁכָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב."],[5,"","יוֹסֵף יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁנִּקְרֵאת כֹּל, וְנִקְרָא יְסוֹד, וְעַל זֶה נִקְרָא יוֹסֵף כַּלְכֹּ\"ל, שֶׁכָּתוּב וַיְכַלְכֵּל יוֹסֵף, וְכָתוּב וְנִקְרָא יְסוֹד עוֹלָם."],[6,"","מֹשֶׁה וְאַהֲרֹן הֵם שְׁנֵי כְרוּבִים שֶׁנִּשְׁמַע קוֹל שֶׁל מַעְלָה מִבֵּינֵיהֶם, וְעַל זֶה נִתְּנָה תוֹרָה עַל יָדָם, זֶהוּ שֶׁכָּתוּב וְנוֹעַדְתִּי לְךְ שָׁם וְדִבַּרְתִּי אִתְּךְ, וְהֵם שְׁנֵי כְרוּבִים שֶׁלְּמַעְלָה, וְהֵם נֵצַ\"ח וְהוֹ\"ד, וְהֵם שְׁנֵי הָעַמּוּדִים שֶׁל הַגּוּף."],[7,"","כְּמוֹ זֶה יֵשׁ לַמַּלְכָּה לְמַטָּה שְׁנֵי כְרוּבִים תַּחְתֶּיהָ שֶׁיּוֹנְקִים מִמֶּנָּה, וְהֵם וַדַּאי עֶלְיוֹנִים, עַל אֲרוֹן הָעֵדֻת, שֶׁנִּקְרָא צֶדֶק, אֲרוֹן הָעֵדוּת. וּמִי עֵדוּת? זֶה יוֹסֵף, זֶהוּ שֶׁכָּתוּב עֵדוּת בִּיהוֹסֵף שָׂמוֹ, וְנִקְרָא תּוֹרָה שֶׁבִּכְתָב, וְאָרוֹן זֶה תּוֹרָה שֶׁבְּעַל פֶּה."],[8,"","בֹּא רְאֵה, כָּל אוֹתָם אָבוֹת עֶלְיוֹנִים שֶׁאֲחוּזִים לְמַעְלָה, כֻּלָּם רְמוּזִים בַּתּוֹרָה שֶׁבִּכְתָב. וְדָוִד שֶׁאָחוּז בָּאַחֲרוֹנָה, שֶׁהִיא תּוֹרָה שֶׁבְּעַל פֶּה, רְמוּזָה בְּדִבְרֵי קַבָּלָה, וּמִשּׁוּם כָּךְ נִקְרֵאת קַבָּלָה, שֶׁמְּקַבֶּלֶת אוֹר מִתּוֹרָה שֶׁבִּכְתָב."],[9,"","וְאוֹתָם שְׁנֵי כְרוּבִים עֶלְיוֹנִים עוֹמְדִים עַל אוֹתוֹ עֵדוּת וְאָרוֹן, זֶהוּ שֶׁכָּתוּב וְהַנֵּצַח וְהַהוֹד כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ. וְזֶהוּ סִיּוּם הַשָּׁמַיִם, וּמְזַוֵּג אֶת הָאָרֶץ הַזּוֹ."],[10,"","וְכָךָ הוּא, שֶׁכָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה - בָּרָא כְּנֶגְדּוֹ לְמַטָּה. וְיוֹסֵף נִקְרָא עֵדוּת, זֶהוּ שֶׁכָּתוּב עֵדוּת בִּיהוֹסֵף שָׂמוֹ, וְעַל זֶה שְׁמוֹ שֶׁל יוֹסֵף שָׁלֵם בַּכֹּל, לְמַעְלָה וּלְמַטָּה."],[11,"","וְעַל זֶה שָׁנִינוּ שֶׁיּוֹסֵף וְהָאָרוֹן וְהַשְּׁכִינָה הָיוּ הוֹלְכִים בַּמִּדְבָּר בְּיַחַד, וְכָל הָעוֹלָם הָיוּ אוֹמְרִים: מַה טִּיבָן שֶׁל שְׁנֵי אֲרוֹנוֹת הַלָּלוּ? וּמְשִׁיבִים לָהֶם: קִיֵּם זֶה מַה שֶּׁכָּתוּב בָּזֶה. קִיֵּם בְּוַדַּאי. זֶהוּ שֶׁכָּתוּב וְצַדִּיק יְסוֹד עוֹלָם, הוּא קִיּוּם הָעוֹלָם."],[12,"","בָּא דָוִד, שֶׁהוּא שְׁבִיעִי שֶׁל הָאָבוֹת, אָחַז בָּהּ בְּבַת שֶׁבַע הַזֹּאת, שֶׁהִיא מַמְלָכָה, וְלֹא עֲזָבָהּ לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (יחזקאל לז) וְדָוִד עַבְדִּי נָשִׂיא לָהֶם לְעוֹלָם, וְכָתוּב (תהלים פט) כִּסְאוֹ כַשֶּׁמֶשׁ נֶגְדִּי. וְכָל זֶה לִמְּדַתְנוּ הַתּוֹרָה, שֶׁכֻּלָּם אֲחוּזִים בַּשְּׁכִינָה בְּסוֹד שֶׁל שֶׁבַע."],[13,"","בֹּא וּרְאֵה, אַבְרָהָם נֵר רִאשׁוֹן קָדוֹשׁ שֶׁל הָעוֹלָם, כְּשֶׁרָצָה לְהִתְקָרֵב לְדַרְגָּתוֹ, לֹא יָכֹל, עַד שֶׁעָלָה וְנוֹדַע בְּאוֹתָן שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁעָלָיו, שֶׁהוּא חֵלֶק שֶׁלּוֹ."],[14,"","כֵּיוָן שֶׁעָלָה וְהִתְוַדַּע לוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא מִתּוֹךְ אוֹתָן שָׁלֹשׁ דְּרָגוֹת, שֶׁעִם אוֹתָן שֶׁבַע, וְשָׁלֹשׁ דְּרָגוֹת, הֵן כֶּתֶר עֶלְיוֹן חָכְמָה בִּינָה, וְהֵן שְׁלֵמוּת עֶשֶׂר סְפִירוֹת שֶׁנִּקְרָא בָּהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכֵיוָן שֶׁעָלָה אַחַר כָּךְ בְּאוֹתָן שָׁלֹשׁ, שֶׁהֵן עַתִּיק וְאַבָּא וְאִמָּא, שֶׁשּׁוֹפֵעַ מֵהֶן אוֹר לְמַטָּה, אָז אָחַז לְחֶלְקוֹ אוֹתָהּ דַּרְגָּה שֶׁתַּחַת אוֹתָן שָׁלֹשׁ, שֶׁנִּקְרָא חֶסֶד."],[15,"","שֶׁאֶת כֻּלָּן הוּא הִדְבִּיק מִתּוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה, שֶׁבָּהֶן וַדַּאי לֹא הָיָה אָדָם שֶׁיָּדַע כְּלוּם. וְעַל זֶה שָׁנִינוּ בֶּן שָׁלֹשׁ שָׁנִים הִכִּיר אַבְרָהָם אֶת בּוֹרְאוֹ, דַּוְקָא בֶּן שָׁלֹשׁ."],[16,"","וּבֹא רְאֵה סוֹד שֶׁל שָׁלֹשׁ שָׁנִים אֵלּוּ וְלֹא חָסֵר, מִשּׁוּם שֶׁשְּׁכִינָה נִקְרֵאת בַּת שֶׁבַע, וְלֹא יָכֹל לְהִתְקָרֵב אֵלֶיהָ עַד שֶׁעָלָה לְהִוָּדַע מִתּוֹכָהּ וְלִהְיוֹת מוּאָר וּלְהָאִיר לַכֹּל, מַה שֶּׁהוּא לְמַטָּה בְּאוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת עִם אוֹתָן שֶׁבַע וְשָׁלֹשׁ, הֲרֵי עֶשֶׂר דְּרָגוֹת עֶלְיוֹנוֹת סוֹד שֶׁל שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא."],[17,"","וְכֵיוָן שֶׁהָיָה נָאוֹר בְּאוֹתָן שָׁלֹשׁ, רָצָה לְהַעֲלוֹת בְּאוֹתָן שֶׁבַע בְּסוֹד הַכָּתוּב (בראשית כא) וַיַּצֵּב אַבְרָהָם אֶת שֶׁבַע כִּבְשׂת הַצֹאן. וְסוֹד זֶה רֶמֶז לַאֲבִימֶלֶךְ שֶׁלֹּא יִפָּרְעוּ מֵהֶם, עַד שֶׁיִּשְׁתַּלְּמוּ אוֹתָם שִׁבְעָה צַדִּיקֵי אֱמֶת בְּיִשְׂרָאֵל. כְּנֶגֶד אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁלְּמַעְלָה."],[18,"","כֵּיוָן שֶׁהִשְׁתַּלְּמוּ, יִהְיֶה הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ הָעוֹלָם הָעֶלְיוֹן בְּקִיּוּם שָׁלֵם, וְיָבֹא דָוִד, שֶׁהוּא שְׁבִיעִי, וִיעוֹרֵר אֶת אוֹתָהּ בַּת שֶׁבַע שֶׁלְּמַעְלָה, שֶׁהִיא נוֹקֶמֶת נִקְמוֹת יִשְׂרָאֵל, וְתִפְרַע מֵהֶם."],[19,"","זְהִוּ שֶׁכָּתוּב (שמואל ב ח) וַיְהִי אַחֲרֵי כֵן וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם וַיִּקַּח דָּוִד אֶת מֶתֶג הָאַמָּה מִיַּד פְּלִשְׁתִּים. מַה זֶּה וַיְהִי אַחֲרֵי כֵן? אַחַר שֶׁנִּשְׁתַּלְּמוּ יִשְׂרָאֵל וְהָיוּ כְּמוֹ לְמַעְלָה, אָז וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם. שֶׁהֲרֵי עַד עַכְשָׁו לֹא יָכְלוּ יִשְׂרָאֵל לִשְׁבֹּר אֶת כֹּחָם, שֶׁהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים בְּאוֹתוֹ מֶתֶג הָאַמָּה, וּפֵרְשׁוּהָ."]]],[["וְתָּא חֲזֵי, הַאי דְּרָמַז לֵיהּ אַבְרָהָם בְּכִבְשׂוֹת הַצֹּאן, וְלֹא בְּעִזִּים, וְלֹא בְּמִילֵי אַחֲרִינֵי, בְּגִין דְּאִינוּן מִסִּטְרָא דְחֶסֶד, מֵאִינוּן מְמַנָּן דְּיָנְקִין מִסִּטְרָא דְחֶסֶד, יָנְקִין לְתַתָּא אִינוּן כְּבָשִׂים, תְּחוֹת שׁוּלְטָנֵיהוֹן. ואַבְרָהָם אָחִיד לְחוּלָקֵיהּ מִדַּת הַחֶסֶד, וְכוֹלָּא בְּרָזָא דְּחָכְמְתָא.","וְעַל דָּא תָּנִינָן, מַאן דְּשָׁרֵי גוֹ עָאנָא, לָא מִסְתַּכֵּן לְעָלְמִין. וְאִי אִיהוּ שָׁרֵי גּוֹ עִזַּיָּיא, וְרָעֵי לוֹן, כַּמָּה גַרְדִּינֵי נִימוּסִין, יָתְבִין לְקִבְלֵיהּ לְאַסְטָאָה לֵיהּ, בְּגִין דְּאִינוּן מִסִּטְרָא דְּדִינָא קַשְׁיָא. אֲבָל כַּד אָתָא יִצְחָק לְמִגְזַר עִמֵּיהּ קְיָים, גָּזַר עִמֵּיהּ בְּשִׁבְעָה, דְּאִתְגַּלְּיָיא מִגּוֹ הַהִיא בֵּירָא, דִּכְתִיב (בראשית כ״ו:כ״ג) וַיִּקְרָא אוֹתָהּ שִׁבְעָה.","תָּא חֲזֵי, אַבְרָהָם קָרָא לְהַהִיא בֵּירָא דְמַיִּין, בְּאֵר שֶׁבַע. יִצְחָק קָרָא לָהּ, שִׁבְעָה. מַה בֵּין הַאי לְהַאי. אֶלָּא בְּגִין דְּיִצְחָק אָחִיד לְחוּלָקֵיהּ דַּרְגָּא דְּפַחַד, דְּאִיהוּ דִּינָא, וְעַל דָּא אוֹסֵיף בָּהּ ה'. וְה' בְּכָל אֲתַר מִדַּת הַדִּין. וְסִימָנָךְ (יחזקאל ט״ז:מ״ג) הֵא דַּרְכֵּךְ בְּרֹאשׁ נָתַתִּי. הֲדָא הוּא דִכְתִיב וַיִּקְרָא אוֹתָהּ שִׁבְעָה. דְּלָא עֲבַד בְּחוּרְפַן, כְּמָה דַּעֲבַד אֲבוּהָּ, וְכֹלָּא בְּרָזָא דְחָכְמְתָא, וְאוֹסֵיף בָּהּ ה', לְאַחֲזָאָה דְּאִיהִי חוּלָקֵיהּ.","תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּרָא לֵיהּ בְּדִינָא. כֵּיוָן דְּחָזָא דְּלָא מִתְקַיֵּים, שִׁתֵּף בֵּיהּ חֶסֶד. הֲדָא הוּא דִכְתִיב (בראשית ב׳:ד׳) בְּהִבָּרְאָם, בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים, ואוֹקְמוּהָ בְּאַבְרָהָם אִיתְקַיֵּים עָלְמָא. בְּגִין כָּךְ הַאי בֵּירָא, בֵּיתָא דְעָלְמָא, עַל שְׁמֵיהּ אִיתְקְרֵי. הֲדָא הוּא דִכְתִיב, (שם כא) עַל כֵּן קָרָא לַמָּקוֹם הַהוּא בְּאֵר שָׁבַע. אַף עַל גַּב דְּהַאי בֵּירָא אִתְדַבַּק בְּיִצְחָק, דִּכְתִיב (שם כו) וַיִּקְרָא אֹתָהּ שִׁבְעָה. שְׁמָהּ בְּאֵר שָׁבַע, סִטְרָא דְאַבְרָהָם, וְלֹא בְּאֵר שִׁבְעָה, הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְחַבְּקֵנִי.","וְתָּא חֲזֵי, ד' מֵאִינוּן שִׁבְעָה זַכָּאֵי קְשׁוֹט, כַּד בָּעוֹ לְאִתְקְרָבָא בִּשְׁכִינְתָּא, בְּרָזָא דְּשֶׁבַע, כָּלְהוֹ אִיעָרְעוּ בְּהַאי בְּאֵר, דְּלָא פָּסְקוּ מֵימוֹי לְעָלְמִין. אַבְרָהָם כָּרֵי לָהּ לְהַאי בֵּירָא, בְּגִין דְּאִיהוּ אוֹלִיף לְכָל בְּנֵי עָלְמָא, דְּיִפְלְחוּן לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּכָרֵי לָהּ, אַפֵּיק מַיִין נָבְעִין דְּלָא פָּסְקִין לְעָלְמִין.","וְכֵיוָן דְּמֵת אַבְרָהָם, מַה כְּתִיב (בראשית כ״ו:ט״ו) וְכָל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵּי אָבִיו בִּימֵי אַבְרָהָם. בְּאֵרֹת כְּתִיב, וְחַד הֲוָה, דִּכְתִיב בְּאֵר שָׁבַע, וְקָרוֹ לֵיהּ בְּאֵרוֹת, דְּמַשְׁמַע דְּסַגִּיאִין הֲווֹ. בְּגִין דְּהַאי בֵּירָא, מִתְחֲזֵי לוֹן לַאֲבָהָן בְּכָל דּוּכְתָּא דַּהֲווֹ אָזְלִין, וַהֲוָה מִתְחֲזֵי לוֹן כְּבֵירִין סַגִּיאִין.","כֵּיוָן דְּמִילְּאוּ פְּלִשְׁתִּים עַפְרָא, רָזָא דְּאַהַדְּרוּ בְּנֵי עָלְמָא לַעֲבוֹדָה זָרָה, הֲוָה עָלְמָא שָׁמֵם, דְּלֵית דְּיָדַע לְקוּדְשָׁא בְּרִיךְ הוּא. כֵּיוָן דְאָתָא יִצְחָק, מַה כְּתִיב, וַיָּשָׁב יִצְחָק וַיַּחְפֹר אֶת בְּאֵרֹת הַמַּיִם אֲשֶׁר חָפְרוּ בִּימֵי אַבְרָהָם אָבִיו. מַאי וַיָּשָׁב, אֶלָּא דַּאֲתֵיב עָלְמָא לְתִיקּוּנֵיהּ, ואוֹלֵיף לוֹן לִבְנֵי עָלְמָא דְּיֵדְעוּן לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (שם כה) וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם ויְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ. וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִ\"י, הַאי בֵּירָא מִמַּאן הוּא. מִמַּאן דְּכָל חַיִּין עִילָּאִין וְתַתָּאִין וְקִיּוּמֵיהוֹן תַּלְיָין בֵּיהּ. וְחָזֵי כֹּלָּא. הֲדָא הוּא דִכְתִיב, (דניאל ב׳:כ״ב) יָדַע מַה בַּחֲשׁוֹכָא וּנְהוֹרָא עִמֵּיהּ שְׁרֵא.","וְתָּא חֲזֵי, אִינוּן עַבְדֵּי יִצְחָק בְּגִין דְּאִינוּן מִסִּטְרָא דְדִינָא קַשְׁיָיא, כַּד חָפְרוּ לָהּ, מַה כְּתִיב, שִׂטְנָה, וְהָא אוֹקְמוּהָ, עַד דְּאָתָא אִיהוּ (בראשית כ״ו:כ״ב) וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְגו', וַיִּקְרָא שְׁמָהּ רְחוֹבוֹת ודַּאי. אֲבָל עַבְדֵּי אָבִיו, בְּגִין דְּכָלְהוֹ אַתְיָין מִסִּטְרָא דְּיָמִינָא, לָא הֲוָה שִׂטְנָא בְּעָלְמָא, וְלָא נָפֵיק דִּינָא בְּהַאי בֵּירָא, לְאַשְׂטָנָא לוֹן, כַּד לָא מַכְשְׁרֵי עוֹבָדֵיהוֹן.","וּמֵהַאי בֵּירָא, אִיהוּ פִּתְחָא לְמִינְדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. וְעַד דְּלָא סָלֵיק יִצְחָק מֵעָלְמָא, בָּרִיךְ לֵיהּ לְיַעֲקֹב, וּשְׁלָחֵיהּ לְחָרָן, לְאִזְדַּוְגָא. וְכַד אָזֵיל לְחָרָן מַה כְּתִיב (בראשית כ״ט:ב׳) וַיַּרְא וְהִנֵּה בְּאֵר בַּשָּׂדֶה, כֵּיוָן דְּחָזָא יַעֲקֹב יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ הַהוּא בֵּירָא, דְּאִקְרֵי בְּאֵר שָׁבַע. כְּדֵין אָמַר לֵיהּ לְלָבָן, אֶעֱבָדְךָ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךָ הַקְּטַנָּה דַּיְיקָא.","תָּא חֲזֵי, לָקֳבֵל אִינוּן שִׁבְעָה זַכָּאִין, פָּקֵיד קוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְיתָא, לְקָרָבָא קָרְבַּן מוּסַף, בְּשֶׁבַע זִמְנִין בְּשַׁתָּא. בְּגִין לְאוֹסָפָא לְהוֹ עִדּוּנִין וְתַפְנוּקִין מִבֵּי מַלְכָּא, דְּיִשְׂבְּעוּן אֲבָהָן בְּקַדְמִיתָא, וּבָתַר כֵּן בְּנִין. וְאִינוּן ז' זִמְנִין וְלָא יַתִּיר.","בְּשַׁבַּתָּא לָקֳבֵל צַדִּיק יְסוֹד עוֹלָם, דְּאִקְרֵי כֹל, וְאִקְרֵי שַׁבָּת, לְאוֹסָפָא לֵיהּ עִידּוּנִין מִמּוֹחָא סְתִימָאָה, וּבְרֵישׁ יַרְחָא, לָקֳבָל כְּנֶסֶת יִשְׂרָאֵל, דְּאִתְקְרִיאַת סִיהֲרָא.","וּבְט\"ו יוֹמָא לְיַרְחָא קַדְמָאָה, לָקֳבֵיל אַבְרָהָם אֲבוּהוֹן, דְּאָחִיד בְּמִדַּת הַחֶסֶד, ואִקְרֵי רִאשׁוֹן. וּבַעֲצֶרֶת דְּבַחֹדֶשׁ הַג', דְּאִתְיְיהִיבַת בֵּיהּ אוֹרַיְיתָא בְּשִׁבְעָה קוֹלוֹת, לָקֳבֵיל יַעֲקֹב, דְּאִיהוּ תְּלִיתָאי לַאֲבָהָן, וְאָחִיד בְּקוֹל קוֹל יַעֲקֹב.","וּבְרֹאשׁ הַשָּׁנָה, לָקֳבֵיל יִצְחָק, דְּאִתְיְלֵיד בֵּיהּ, וַאֲנַן מַדְכְּרִינָן בֵּיהּ עֲקֵדַת יִצְחָק, וְאִיהוּ יוֹמָא דְדִינָא, לָקֳבֵל מִדַּת הַדִּין דְּאָחִיד בַּהּ. בְּיוֹם הַכִּפּוּרִים, לָקֳבֵיל משֶׁה, דְּקַבֵּיל קוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ צְלוֹתֵיהּ, וְחָס עַל יִשְׂרָאֵל, ואַהֲדַר לֵיהּ לוּחֵי אוֹרַיְיתָא. בְּחַג הַסֻּכּוֹת, לָקֳבֵיל אַהֲרֹן, דְּבִזְכוּתֵיהּ הֲווֹ אָזְלִין שִׁבְעָה עֲנָנִין, דְּחָפָן עַל יִשְׂרָאֵל כְּסוּכּוֹת, וּבְגִין כָּךְ אִינוּן עָבְדִין סוּכָּה. וְכָל אוֹרַיְיתָא, כַּמָּה רָזִין עִילָּאִין סְתִימִין בַּהּ, וְכַד אִלֵּין שִׁבְעָה מִתּוֹסְפִין בְּבִרְכָאן, כָּל עָלְמָא בִּשְׁלִימוּ סַגִּיאָה."],[],[[0,"","וּבֹא וּרְאֵה, זֶה שֶׁרָמַז לוֹ אַבְרָהָם בְּכִבְשׂוֹת הַצֹאן וְלֹא בְעִזִּים וְלֹא בְדָבָר אַחֵר, מִשּׁוּם שֶׁהֵם מִצַּד הַחֶסֶד, שֶׁמֵּאוֹתָם מְמֻנִּים שֶׁיּוֹנְקִים מִצַּד הַחֶסֶד יוֹנְקִים לְמַטָּה אוֹתָם כְּבָשִׂים שֶׁתַּחַת שִׁלְטוֹנָם, וְאַבְרָהָם אָחַז לְחֶלְקוֹ מִדַּת הַחֶסֶד, וְהַכֹּל בְּסוֹד הַחָכְמָה. וְעַל זֶה שָׁנִינוּ, מִי שֶׁשָּׁרוּי בְּתוֹךְ צֹאן לֹא מִסְתַּכֵּן לְעוֹלָמִים. וְאִם הוּא שָׁרוּי בְּתוֹךְ עִזִּים וְרוֹעֶה אוֹתָם, כַּמָּה שׁוֹמְרֵי הַחֻקִּים יוֹשְׁבִים כְּנֶגְדּוֹ לְהַסְטוֹתוֹ, בִּגְלַל שֶׁהֵם מִצַּד שֶׁל הַדִּין הַקָּשֶׁה."],[1,"","אֲבָל כְּשֶׁבָּא יִצְחָק לִכְרֹת אִתּוֹ בְּרִית, כָּרַת אִתּוֹ בְּשִׁבְעָה שֶׁנִּגְלָה מִתּוֹךְ אוֹתוֹ בְּאֵר, שֶׁכָּתוּב (בראשית כו) וַיִּקְרָא אֹתָהּ שִׁבְעָה. בֹּא וּרְאֵה, אַבְרָהָם קָרָא לְאוֹתָהּ בְּאֵר מַיִם נוֹבְעִים בְּאֵר שֶׁבַע, וְיִצְחָק קָרָא לָהּ שִׁבְעָה. מַה בֵּין זֶה לָזֶה? אֶלָּא מִשּׁוּם שֶׁיִּצְחָק אָחַז לְחֶלְקוֹ דַּרְגָּה שֶׁל פַּחַד, שֶׁהוּא דִּין, וְעַל זֶה הוֹסִיף בָּהּ ה'. וְה' בְּכָל מָקוֹם הִיא מִדַּת הַדִּין. וְסִימָנְךְ - (יחזקאל טז) הֵא דַּרְכֵּךְ בְּרֹאשׁ נָתַתִּי. זֶהוּ שֶׁכָּתוּב וַיִּקְרָא אֹתָהּ שִׁבְעָה. שֶׁלֹּא עָשָׂה בַּכְּבָשִׂים כְּמוֹ שֶׁעָשָׂה אָבִיו, וְהַכֹּל בְּסוֹד הַחָכְמָה, וְהוֹסִיף בָּהּ ה', לְהַרְאוֹת שֶׁהִיא חֶלְקוֹ."],[2,"","בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא אוֹתוֹ בְּדִין. כֵּיוָן שֶׁרָאָה שֶׁלֹּא מִתְקַיֵּם, שִׁתֵּף בּוֹ חֶסֶד, זֶהוּ שֶׁכָּתוּב (שם ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים, וּפֵרְשׁוּהָ בְּאַבְרָהָם הִתְקַיֵּם הָעוֹלָם. בִּגְלַל כָּךְ הַבְּאֵר הַזֹּאת בֵּית הָעוֹלָם עַל שְׁמָהּ נִקְרָא, זֶהוּ שֶׁכָּתוּב עַל כֵּן קָרָא שֵׁם הָעִיר בְּאֵר שָׁבַע. אַף עַל גַּב שֶׁהַבְּאֵר הַזּוֹ נִדְבְּקָה בְיִצְחָק, שֶׁכָּתוּב וַיִּקְרָא אֹתָהּ שִׁבְעָה - שְׁמָהּ בְּאֵר שֶׁבַע צַד שֶׁל אַבְרָהָם, וְלֹא בְּאֵר שִׁבְעָה, זֶהוּ שֶׁכָּתוּב (שיר השירים ב) וִימִינוֹ תְּחַבְּקֵנִי."],[3,"","וּבֹא וּרְאֵה, אַרְבָּעָה מֵאוֹתָם שִׁבְעָה צַדִּיקֵי הָאֱמֶת, כְּשֶׁרָצוּ לְהִתְקָרֵב לַשְּׁכִינָה בְּסוֹד שֶׁל שֶׁבַע, כֻּלָּם פָּגְשׁוּ בַּבְּאֵר הַזּוֹ שֶׁלֹּא פוֹסְקִים מֵימֶיהָ לְעוֹלָמִים."],[4,"","אַבְרָהָם כָּרָה אֶת הַבְּאֵר הַזֹּאת מִשּׁוּם שֶׁהוּא לִמֵּד אֶת כָּל בְּנֵי הָעוֹלָם לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵיוָן שֶׁכָּרָה אוֹתָהּ, הוֹצִיא מַיִם נוֹבְעִים שֶׁלֹּא פוֹסְקִים לְעוֹלָמִים."],[5,"","וְכֵיוָן שֶׁמֵּת אַבְרָהָם מַה כָּתוּב? (בראשית כו) וְכָל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵי אָבִיו בִּימֵי אַבְרָהָם. כָּתוּב בְּאֵרֹת, וְרַק אַחַת הָיְתָה, שֶׁכָּתוּב בְּאֵר שָׁבַע, וְקוֹרְאִים בְּאֵרוֹת, מַשְׁמָע שֶׁרַבִּים הָיוּ, מִשּׁוּם שֶׁהַבְּאֵר הַזֹּאת נִרְאֵית לָאָבוֹת בְּכָל מָקוֹם שֶׁהָיוּ הוֹלְכִים, הָיְתָה נִרְאֵית לָהֶם גְּדוֹלִים וְכַבִּירִים."],[6,"","כֵּיוָן שֶׁמִּלְאוּהָ הַפְּלִשְׁתִּים עָפָר, סוֹד שֶׁחָזְרוּ בְּנֵי הָעוֹלָם לָעֲבוֹדָה זָרָה, וְהָעוֹלָם הָיָה שָׁמֵם, שֶׁאֵין מִי שֶׁיּוֹדֵעַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁבָּא יִצְחָק מַה כָּתוּב? (שם) וַיָּשָׁב יִצְחָק וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם אֲשֶׁר חָפְרוּ בִּימֵי אַבְרָהָם אָבִיו. מַה זֶּה וַיָּשָׁב? אֶלָּא שֶׁהֵשִׁיב אֶת הָעוֹלָם לְתִקּוּנוֹ וְלִמֵּד אֶת בְּנֵי הָעוֹלָם שֶׁיֵּדְעוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (שם כה) וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ. בְּאֵר זוֹ מִמִּי הָיְתָה? מִמִּי שֶׁכָּל חַיֵּי הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים תְּלוּיִים בּוֹ וְרוֹאֶה הַכֹּל, זֶהוּ שֶׁכָּתוּב (דניאל ב) יוֹדֵעַ מַה שֶּׁבַּחֹשֶׁךְ וְאוֹר שָׁרוּי עִמּוֹ."],[7,"","וּבֹא וּרְאֵה, אוֹתָם עַבְדֵי יִצְחָק, מִשּׁוּם שֶׁהֵם מִצַּד הַדִּין הַקָּשֶׁה, כְּשֶׁחָפְרוּ אוֹתָהּ מַה כָּתוּב? שִׁטְנָה, וַהֲרֵי פֵּרְשׁוּהָ, עַד שֶׁהוּא בָּא וַיַּחְפֹּר בְּאֵר אַחֶרֶת וַיִּקְרָא שְׁמָהּ רְחוֹבוֹת וַדַּאי. אֲבָל עַבְדֵי אָבִיו, מִשּׁוּם שֶׁכֻּלָּם בָּאִים מִצַּד הַיָּמִין, וְלֹא הָיְתָה שִׂטְנָה בָּעוֹלָם, וְלֹא יָצָא דִין מֵהַבְּאֵר הַזֹּאת לְהַסְטִין עֲלֵיהֶם כְּשֶׁמַּעֲשֵׂיהֶם לֹא הָיוּ כְשֵׁרִים."],[8,"","וּמֵהַבְּאֵר הַזֹּאת הוּא הַפֶּתַח לָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. וְעַד שֶׁלֹּא הִסְתַּלֵּק מֵהָעוֹלָם, בֵּרַךְ אֶת יַעֲקֹב וּשְׁלָחוֹ לְחָרָן לְהִזְדַּוֵּג. וּכְשֶׁהָלַךְ לְחָרָן מַה כָּתוּב? (בראשית כט) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. כֵּיוָן שֶׁרָאָה יַעֲקֹב אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אוֹתָהּ בְּאֵר שֶׁנִּקְרֵאת בְּאֵר שֶׁבַע, אָז אָמַר לְלָבָן, (שם) אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךְ הַקְּטַנָּה, דַּוְקָא הַקְּטַנָּה."],[9,"","בֹּא וּרְאֵה, כְּנֶגֶד אוֹתָם שִׁבְעָה צַדִּיקִים צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה לְהַקְרִיב קָרְבַּן מוּסָף שֶׁבַע פְּעָמִים בַּשָּׁנָה, כְּדֵי לְהוֹסִיף לָהֶם תַּפְנוּקִים וְעִדּוּנִים מִבֵּית הַמֶּלֶךְ. הָאָבוֹת יִשְׂבְּעוּ בַּתְּחִלָּה, וְאַחַר כָּךְ הַבָּנִים, וְהֵם שֶׁבַע פְּעָמִים וְלֹא יוֹתֵר."],[10,"","בְּשַׁבָּת כְּנֶגֶד צַדִּיק יְסוֹד עוֹלָם שֶׁנִּקְרָא כֹּ\"ל, וְנִקְרָא מוּסָף שַׁבָּת, לְהוֹסִיף לוֹ עִדּוּנִים מֵהַמֹּחַ הַנִּסְתָּר. וּבְרֹאשׁ חֹדֶשׁ כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת לְבָנָה."],[11,"","וּמְחֲמִשָּׁה עָשָׂר יוֹם לְחֹדֶשׁ רִאשׁוֹן כְּנֶגֶד אַבְרָהָם אֲבִיהֶם שֶׁאָחוּז בְּמִדַּת הַחֶסֶד וְנִקְרָא רִאשׁוֹן. וּבַחֹדֶשׁ הַשְּׁלִישִׁי בַּעֲצֶרֶת שֶׁנִּתְּנָה בּוֹ תּוֹרָה בְּשִׁבְעָה קוֹלוֹת, כְּנֶגֶד יַעֲקֹב שֶׁהוּא שְׁלִישִׁי לָאָבוֹת וְאָחוּז בְּקוֹל, קוֹל יַעֲקֹב."],[12,"","וּבְרֹאשׁ הַשָּׁנָה כְּנֶגֶד יִצְחָק שֶׁנּוֹלַד בּוֹ, וְאָנוּ מַזְכִּירִים בּוֹ עֲקֵדַת יִצְחָק, וְהוּא יוֹם הַדִּין כְּנֶגֶד מִדַּת הַדִּין הָאֲחוּזָה בּוֹ. בְּיוֹם הַכִּפּוּרִים כְּנֶגֶד מֹשֶׁה, שֶׁבּוֹ קִבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת תְּפִלָּתוֹ וְחָס עַל יִשְׂרָאֵל וְהֶחֱזִיר לוֹ אֶת הַתּוֹרָה. בְּחַג הַסֻּכּוֹת כְּנֶגֶד אַהֲרֹן, שֶׁבִּזְכוּתוֹ הָלְכוּ אוֹתָם שִׁבְעָה עֲנָנִים שֶׁכִּסּוּ עַל יִשְׂרָאֵל כְּמוֹ סֻכָּה, וּמִשּׁוּם זֶה עוֹשִׂים סֻכָּה, וּבְכָל הַתּוֹרָה יֵשׁ כַּמָּה סוֹדוֹת עֶלְיוֹנִים נִסְתָּרִים בָּהּ. וּכְשֶׁשִּׁבְעַת אֵלֶּה מִתּוֹסְפִים בַּבְּרָכוֹת, כָּל הָעוֹלָם בִּשְׁלֵמוּת רַבָּה. ע\"כ מההשמטות."]]],[["וְהֵנִיף אַהֲרֹן אֵת הַלְוִיִּם תְנוּפָה לִפְנֵי יְיָ. רַבִּי יְהוּדָה שָׁאִיל לְרַבִּי אַבָּא, לָמָה הָיָה הַכֹּהֵן מֵנִיף אֵת הַלְוִיִּם. אָמַר לוֹ, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְתִינוֹק. כְּשֶׁהוּא בּוֹכֶה וְכוֹעֵס, מָה עוֹשִׂין כְּדֵי לְפַיְיסוֹ. אָמַר לֵיהּ רַבִּי יְהוּדָה, מֵנִיפִין אוֹתוֹ וּמְנָעְנֵעִים אוֹתוֹ כְּדֵי לְשָׁתְקוֹ. אָמַר לֵיהּ רַבִּי אַבָּא, יְהוּדָה יְהוּדָה, מִלָּה זֹאת בָּאָה לְיָדְךָ וְלֹא חֲקַרְתָּ בָּהּ, וַהֲלֹא יִשְׁמְעוּ אָזְנְךָ מָה שֶׁפִּיךָ מְדַבֵּר.","כַּךְ הִיא מִדַּת הַגְּבוּרָה כּוֹעֶסֶת וְרוֹגֶזֶת. דִּכְתִיב, (בראשית מ״ט:ה׳) שִׁמְעוֹן וְלֵוִי אַחִים כְּלֵי חֲמָס מְכֶרוֹתֶיהֵם. וּכְתִיב (בראשית מ״ט:ז׳) אָרוּר אֲפָּם כִּי עַז וְעֵבְרָתָם כִּי קַשָׁתָה. לְפִי שֶׁהֵם מִתְגָּבְּרִים וּמִתְקַשִׁים בְּאֲפָּם וְעֵבְרָתָם לַצֵאת לַעֲשׂוֹת דִּין לְכַלוֹת וּלְהַכְרִית בְּנֵי הַעוֹלָם, אֲזָי הַכֹּהֵן שֶׁהוּא הַחֶסֶד הַעֶלְיוֹן מֵנִיף אוֹתוֹ הַצָד שֶׁל הַלְוִיִּם שֶׁהִיא מִדַּת הַגְּבוּרָה, כְּדֵי לְשָׁכֵּךְ וּלְשָׁקֵט רָגְזָה וְכַעֲסָה, כְּדֵי שֶׁיִשְׁתַּבְּרוּ הַשָׂעֲרוֹת מִכָּל שׁוּלֵיהֶן וְלֹא יִתְגָּבְּרוּ וְלֹא יִתְחֲזְקוּ. כְּעֵין דוּגְמָא זוֹ, הַכֹּהֵן שֶׁמֵנִיף אֵת הַלְוִיִּם תְנוּפָה כְּדֵי שֶׁיִשְׁקוֹט הַצָד שֶׁל גְּבוּרָה שֶׁלָהֵן כְּדֵי שֶׁלֹּא יִתְעוֹרֵר הַדִּין בָּעוֹלָם.","בָּא רַבִּי יְהוּדָה וְנָשַׁק אֵת יָדָיו. וּכְּשֶׁיִתְעוֹרְרוּ הַדִּינִין בָּעוֹלָם, כָּל הַדִּינִים הַנִמְצָאִים בְּכָל יוֹם וָיוֹם אַבְרָהָם אָבִינוּ עַלָּיו הַשָׁלוֹם הוּא דּוֹחֶה אוֹתָם לַחוּץ וְאֵינָם עוֹמְדִים לְפָנָיו, הֲדָא הוּא דִּכְתִיב, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם.","דְּאִינוּן חַד נָהָר וְגַן. נָהָר דְּנָפִיק מֵעֵדֶן וְגַן דְּאִשְׁתַּקֵי מִנֵּיהּ. הַכָא כָּל רָזָא סְתִימָא דִּמְהֵימָנוּתָא. ואוֹלִיפְנָא, הַאי מַאן דְּאִתְעָר בְּלֵילְיָא, בְּהַהִיא שַׁעֲתָא דְּעָאל קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵי צַדִּיקַיָּיא בְּגִנְתָּא. אִיצְטְרִיךְ לוֹמַר קְרָא דָא, בִּרְעוּתָא דְּלִבָּא. וּלְכַוְונָא דַּעְתֵּיהּ בֵּיהּ. וּבָתַר (תהילים קל״ט:י״ד) אוֹדְךָ עַל כִּי נוֹרָאוֹת נִפְלֵאתִי נִפְלָאִים מַעֲשֶׂיךָ וְנַפְשִׁי יוֹדַעָת מְאֹד. (ולבתר ונהר יוצא מעדן וגו') וְהַיְינוּ שְׁבָחָא דְּחַסִידֵי קַדְמָאֵי כַּד מִתְעָרֵי בְּפַלְגוּת לֵילְיָא. וּבָתַר מֵסָדְרֵי שִׁבְחַיְיהוּ וְלָעָאן בְּאוֹרַיְיתָא.","שָׁעְשׁוּעָא דְּקוּדְשָׁא בְּרִיךְ הוּא מַאי הוּא. אֶלָּא, כָּל צַדִּיקַיָּיא דְּקָיְמִין בְּדִיוּקְנָיְיהוּ מִתְלַבְּשָׁן בְּגִנְתָּא בְּכָל יוֹמָא וְיוֹמָא. כֵּיוָן דְּאִתְסָחַאן בְּטַלָּא דְּזָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחָיָיא בֵּיהּ מֵתַיָּיא, עָאלִין כּוּלְהוֹן לְגַבֵּי מָשִׁיחַ וְשַׁאֲלִין מָה דְּשָׁאַלִין, וְהָא אִתְעָרוּ חַבְרַיָּיא.","לְבָתַר מִתְכַּנְּשִׁין וּמִשְׁתַּדְלִין כּוּלְּהוּ בְּדַּעְתָּא עִילָאָה דְּכוּלְהוּ מְתִיבְתֵי דְּתַּמָּן וְעָלַיְיהוּ כַּמָה מְמָנָן. וּמִתְחַדְשֵׁי תַּמָּן כַּמָה חִדּוּשִׁין בְּאוֹרַיְיתָא. לְבָתַר נָפְקֵי כּוּלְּהוּ וְחָמָאן כַּד אָתֵי אֵלִיָהוּ לְגַבֵּי אֲבָהָן. אִיהוּ נָפִיק וְאִינְהוּ עָאלִין וְקַיְימָן קַמֵי אֲבָהָן וְחַדּוּ בְּהוּ בְּכַמָּה בְּנִין קַדִּישִׁין דְּבְּסָחֲרַנָיְיהוּ וְחַדָּאן כּוּלְּהוּ.","כַּד עַיִיל קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגוּת לֵילְיָא כּוּלְּהוּ קַיְימֵי מִתָקְנָן כְּדְקָא יֵאוֹת. וְכָל אִשְׁתַּדְלוּתַא דְּאִשְׁתַּדְלֵי כָּל הַהוּא יוֹמָא בְּחִדוּשֵׁי דְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא, תִיאוּבְתֵיהּ בְּאִינוּן צַדִּיקַיָּיא דְּחַדִישׁוּ בָּהּ מִילִין ואִשְׁתַּעֲשַׁע בְּהוּ ובְּאִינוּן מִילִין.","לְבָתַר כּוּלְּהוּ מִתְתַּקְנָן דְּכָר וְנוּקְבָּא. וְקוּדְשָׁא בְּרִיךְ הוּא בָּתַר דְּאָרָחַ וְאִשְׁתַּעֲשַׁע בְּהוּ בְּכָל אִינוּן מִילִין רָזִין דְחָכְמְתָא דִּילְהוֹן, אִתְגְּלֵי עֲלַיְיהוּ וְאִינוּן חֲמָאן בְּהַהוּא נוֹעַם יְיָ. כְּדֵין כֻּלְּהוּ חַדָּאן בְּחֶדְוָה סַגִּי, עַד דְּמִתְפַּשְּׁטֵי זִיוָא וּנְהוֹרָא דִּילְהוֹן. וּמֵהַהוּא מְשִׁיכוּ זִיוָא וּנְהוֹרָא דְּחֶדְוָה דִּילְהוֹן, עַבְדִין פֵּירִין ואִיבִּין לְעַלְמָא דָא. וְהַהוּא פֶּרִי וְאִיבָּא עֲאל תֵחוֹת גַדְפוֹי דִּשְׁכִינְתָּא, עַד זִמְנָא דְּאִיצְטְרִיךְ.","וְכֵן מִשְׁתַעֲשָּׁעַ בְּכָל צַדִּיק וְצַדִּיק (ואמר) וְאַמְרִין, זַכָּאָה אִיהוּ מַלְכָּא דִבְנִין אִלֵּין אִתְבְּרִירוּ לְחוּלָקֵיהּ וְעַדְבֵיהּ. קָלָא אִתְעָר מֵאֱמְצָעִיתָּא דִּרְקִיעָא וְקָרָא בְּקַל תַקִיף ואָמַר, (תהילים קל״ז:ז׳) זְכוֹר יְיָ לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלַיִם הָאוֹמְרִים עֲרוּ עֲרוּ עַד הַיְסוֹד בָּהּ. כְּדֵין עֲרְטִירוּ דִּילֵיהּ וְקִרְקוּרָא דִּילֵיהּ וּמִכָּל צַדִּיקַיָּיא דְּתַּמָּן אִשְׁתְּמַע בִּתְלָת מֵאָה וְתִשְׁעִין רְקִיעִין.","בְּגִין דְּלָא אִית חֶדְוָה וְשָׁעְשׁוּעָא לְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּשַׁעֲתָא דְּקַיְימֵי בְּהוּ (דקאים בהדי) צַדִּיקַיָּיא דְּתַּמָּן. וּבְגִין דָא אוֹמֵי וְאָמַר, (תהילים קל״ז:ה׳-ו׳) אִם אֶשְׁכַּחֵךְ יְרוּשָׁלַיִם תִשְׁכַּח יְמִינִי תִדְבָּק לְשׁוֹנִי לְּחִכִּי אִם לֹא אֶזְכְּרֵכִי אִם לֹא אֶעֱלֶה אֵת יְרוּשָׁלַיִם עַל רֹאשׁ שִׂמְחַתִי. בְּכָל אֲתָר דְּאִית חֶדְוָה לְקוּדְשָׁא בְּרִיךְ הוּא, קָלָא דָא נָפִיק וְקַארֵי.","כְּדֵין נָפִיק מִתַּמָּן וסָלִיק וּבָטַשׁ רְקִיעִין וְשָׁאִיג שְׁאִיגִין, עַד דְּכָל חֵילֵי שְׁמַיָא כּוּלְּהוּ בְּעִרְטוּרָא. כְּדֵין נָשְׁבָא רוּחָא וּבָטַשׁ בְּטַרְפִין דְּהַהוּא אִילָנָא רַבְרְבָא וְכָל עַנְפִּין דִּילֵיהּ בַּטְשִׁין דָא בְּדָא. וְקָלָא אִתְעָר מִגּוֹ נוֹפָא דְּאִילָנָא וְקָרֵי וְאָמַר. (תהילים ק״ה:ח׳-ט׳) זָכַר לְעוֹלָם בְּרִיתוֹ דָּבָר צִוָּה לְאֶלֶף דוֹר (דברי הימים א ט״ז:ט״ו-ט״ז) אֲשֶׁר כָּרָת אֵת אַבְרָהָם וּשְׁבוּעָתּוֹ לְיִצְחָק. כֵּיוָן דְּקָלָא דָא אִתְעָר שָׁמַע אַבְרָהָם סָבָא ואִתְעַר (כדין) כַּד אִיהוּ רַעֲוָא לְמַלְכָּא ואִתְנַחֵם בַּהֲדֵיהּ.","בְּהַהִיא שַׁעֲתָא אִתְעָרַת רוּחָא חֲדָא מִסִטְרָא דְדָרוֹם וְכָל רְעוּ וְחֶדְוָה ואַסְוָותָא אִתְעָר עַל עַלְמָא. וּכְדֵין סָלִיק צַפְרָא וְרַעֲוָא אִשְׁתְּכַּח וְנַיְיחָא לְכָל אֲסִירֵי מַלְכָּא דְּאִינוּן בְּבֵי מָרְעֲיְיהוּ. זַכָּאָה עַמָּא דְיָכְלִין לְמִנְדַּע מֵרָזִין טְמִירִין סְתִימִין דְּמַלְכָּא קַדִּישָׁא."],[],[[0,"","וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי ה'. רַבִּי יְהוּדָה שָׁאַל אֶת רַבִּי אַבָּא, לָמָּה הָיָה הַכֹּהֵן מֵנִיף אֶת הַלְוִיִּם? אָמַר לוֹ, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְתִינוֹק כְּשֶׁהוּא בּוֹכֶה וְכוֹעֵס, מָה עוֹשִׂין כְּדֵי לְפַיְּסוֹ? אָמַר לוֹ רַבִּי יְהוּדָה, מְנִיפִין אוֹתוֹ וּמְנַעְנְעִים אוֹתוֹ כְּדֵי לְשַׁתְּקוֹ. אָמַר לוֹ רַבִּי אַבָּא, יְהוּדָה יְהוּדָה, מִלָּה זֹּאת בָּאָה לְיָדְךְ וְלֹא חָקַרְתָּ בָּהּ?! וַהֲלֹא יִשְׁמְעוּ אָזְנֶיךְ מַה שֶּׁפִּיךְ מְדַבֵּר!"],[1,"","כָּךְ הִיא מִדַּת הַגְּבוּרָה, כּוֹעֶסֶת וְרוֹגֶזֶת, שֶׁכָּתוּב (בראשית מט) שִׁמְעוֹן וְלֵוִי אַחִים כְּלֵי חָמָס מְכֵרֹתֵיהֶם, וְכָתוּב אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה, לְפִי שֶׁהֵם מִתְגַּבְּרִים וּמִתְקַשִּׁים בְּאַפָּם וְעֶבְרָתָם לָצֵאת לַעֲשׂוֹת דִּין לְכַלּוֹת וּלְהַכְרִית בְּנֵי הָעוֹלָם, אֲזַי הַכֹּהֵן, שֶׁהוּא הַחֶסֶד הָעֶלְיוֹן, מֵנִיף אוֹתוֹ הַצַּד שֶׁל הַלְוִיִּם, שֶׁהוּא מִדַּת הַגְּבוּרָה, כְּדֵי לְשַׁכֵּךְ וּלְשַׁקֵּט רָגְזָהּ וְכַעֲסָהּ, כְּדֵי שֶׁיִּשְׁתַּבְּרוּ הַשְּׂעָרוֹת מִכָּל שׁוּלֵיהֶן וְלֹא יִתְגַּבְּרוּ וְלֹא יִתְחַזְּקוּ, כְּעֵין דֻּגְמָא זוֹ הַכֹּהֵן שֶׁמֵּנִיף אֶת הַלְוִיִּם תְּנוּפָה כְּדֵי שֶׁיִּשְׁקֹט הַצַּד שֶׁל הַגְּבוּרָה שֶׁלָּהֶן, כְּדֵי שֶׁלֹּא יִתְעוֹרֵר הַדִּין בָּעוֹלָם."],[2,"","בָּא רַבִּי יְהוּדָה וְנָשַׁק אֶת יָדָיו. וּכְשֶׁיִּתְעוֹרְרוּ הַדִּינִין בָּעוֹלָם, כָּל הַדִּינִים הַנִּמְצָאִים בְּכָל יוֹם וָיוֹם, אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם הוּא דּוֹחֶה אוֹתָם לַחוּץ וְאֵינָם עוֹמְדִים לְפָנָיו, זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם: ע\"כ מההשמטות."],[3,"","שֶׁהֵם אֶחָד, נָהָר וְגַן. נָהָר שֶׁיּוֹצֵא מֵעֵדֶן וְגַן שֶׁהֻשְׁקָה מִמֶּנּוּ. כָּאן כָּל הַסּוֹד הַסָּתוּם שֶׁל הָאֱמוּנָה. וְלָמַדְנוּ שֶׁמִּי שֶׁמִּתְעוֹרֵר בַּלַּיְלָה בְּאוֹתָהּ שָׁעָה שֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא יַחַד עִם הַצַּדִיקִים בַּגָּן, צָרִיךְ לוֹמַר פָּסוּק זֶה בִּרְצוֹן הַלֵּב וּלְכַוֵּן דַּעְתּוֹ בּוֹ, וְאַחַר כָּךְ אוֹדְךְ עַל כִּי נוֹרָאוֹת נִפְלֵאתִי נִפְלָאִים מַעֲשֶׂיךְ וְנַפְשִׁי יֹדַעַת מְאֹד. (ואחר כך ונהר יצא מעדן וגו'). וְזֶהוּ שֶׁבַח הַחֲסִידִים הָרִאשׁוֹנִים כְּשֶׁהִתְעוֹרְרוּ בַּחֲצוֹת הַלַּיְלָה, וְאַחַר כָּךְ מְסַדְּרִים הַשֶּׁבַח שֶׁלָּהֶם וְעוֹסְקִים בַּתּוֹרָה."],[4,"","מַהוּ שַׁעֲשׁוּעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא כָּל הַצַּדִּיקִים שֶׁעוֹמְדִים בִּדְמֻיּוֹתֵיהֶם וּמִתְלַבְּשִׁים בַּגָּן בְּכָל יוֹם וָיוֹם, כֵּיוָן שֶׁרוֹחֲצִים בַּטַּל שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת בּוֹ מֵתִים, נִכְנָסִים כֻּלָּם לַמָּשִׁיחַ וְשׁוֹאֲלִים מַה שֶּׁשּׁוֹאֲלִים, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים."],[5,"","אַחַר כָּךְ מִתְכַּנְּסִים וּמִשְׁתַּדְּלִים כֻּלָּם בְּדַעַת עֶלְיוֹנָה בְּכָל הַיְשִׁיבוֹת שֶׁשָּׁם, וַעֲלֵיהֶם כַּמָּה מְמֻנִּים, וּמִתְחַדְּשִׁים שָׁם כַּמָּה חִדּוּשִׁים בַּתּוֹרָה. אַחַר כָּךְ יוֹצְאִים כֻּלָּם וְרוֹאִים כְּשֶׁבָּא אֵלִיָּהוּ לָאָבוֹת, הוּא יוֹצֵא וְהֵם נִכְנָסִים, וְעוֹמְדִים לִפְנֵי הָאָבוֹת, וּשְׂמֵחִים בָּהֶם וּבְכַמָּה בָנִים קְדוֹשִׁים שֶׁסְּבִיבָם וּשְׂמֵחִים כֻּלָּם."],[6,"","כְּשֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה, כֻּלָּם עוֹמְדִים מְתֻקָּנִים כָּרָאוּי, וְכָל הַהִשְׁתַּדְּלוּת שֶׁהִשְׁתַּדְּלוּ כָּל אוֹתוֹ הַיּוֹם בְּחִדּוּשֵׁי תוֹרָה, תַּאֲוַת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָם צַדִּיקִים שֶׁחִדְּשׁוּ בָהּ דְּבָרִים, וּמִשְׁתַּעֲשֵׁעַ בָּהֶם וּבְאוֹתָם הַדְּבָרִים."],[7,"","אַחַר כָּךְ כֻּלָּם מְתֻקָּנִים זָכָר וּנְקֵבָה, וְאַחַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִיחַ וְהִשְׁתַּעֲשַׁע בָּהֶם בְּכָל אוֹתָם דְּבָרִים סוֹדוֹת חָכְמָתָם, מִתְגַּלֶּה עֲלֵיהֶם, וְהֵם רוֹאִים בְּאוֹתוֹ נֹעַם ה', אָז כֻּלָּם שְׂמֵחִים בְּחֶדְוָה רַבָּה עַד שֶׁמִּתְפַּשֵּׁט זִיוָם וְאוֹרָם, וּמֵאוֹתוֹ הֶמְשֵׁךְ זִיו וְאוֹר שֶׁל חֶדְוָה שֶׁלָּהֶם עוֹשִׂים פֵּרוֹת וְתוֹלָדוֹת לָעוֹלָם הַזֶּה, וְאוֹתוֹ פְּרִי וְתוֹלָדָה נִכְנָס תַּחַת כַּנְפֵי הַשְּׁכִינָה עַד זְמַן שֶׁצָּרִיךְ."],[8,"","וְכָךָ מִשְׁתַּעֲשֵׁעַ בְּכָל צַדִּיק וְצַדִּיק, (ואמר) וְאוֹמְרִים: אַשְׁרֵי הַמֶּלֶךְ שֶׁבָּנִים הַלָּלוּ נִבְרְרוּ לְחֶלְקוֹ וְגוֹרָלוֹ! קוֹל מִתְעוֹרֵר מֵאֶמְצַע הָרָקִיעַ וְקוֹרֵא בְקוֹל חָזָק וְאוֹמֵר: זְכֹר ה' לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלם הָאֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ. וְאָז רַעַשׁ הַשִּׂמְחָה שֶׁלּוֹ וְהַקִּרְקוּר שֶׁלּוֹ וּמִכָּל הַצַּדִּיקִים שֶׁשָּׁם נִשְׁמָעִים בִּשְׁלֹשׁ מֵאוֹת וְתִשְׁעִים רְקִיעִים,"],[9,"","מִשּׁוּם שֶׁאֵין חֶדְוָה וְשַׁעֲשׁוּעַ לַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בְּשָׁעָה שֶׁעוֹמְדִים בָּהֶם (שעומד יחד עם) הַצַּדִּיקִים שֶׁשָּׁם, וּמִשּׁוּם זֶה נִשְׁבַּע וְאָמַר: אִם אֶשְׁכָּחֵךְ יְרוּשָׁלם תִּשְׁכַּח יְמִינִי תִּדְבַּק לְשׁוֹנִי לְחִכִּי אִם לֹא אֶזְכְּרֵכִי אִם לֹא אעלה את ירושלים על ראש שִׂמְחָתִי. בְּכָל מָקוֹם שֶׁיֵּשׁ חֶדְוָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, קוֹל זֶה יוֹצֵא וְקוֹרֵא."],[10,"","אָז יוֹצֵא מִשָּׁם וְעוֹלֶה וּמַכֶּה רְקִיעִים וְשׁוֹאֵג שְׁאָגוֹת, עַד שֶׁכָּל חֵילוֹת הַשָּׁמַיִם כֻּלָּם בְּרַעַשׁ הַשִּׂמְחָה, וְאָז נוֹשֶׁבֶת רוּחַ וּמַכָּה בֶעָלִים שֶׁל אוֹתוֹ אִילָן גָּדוֹל, וְכָל הָעֲנָפִים שֶׁלּוֹ מַכִּים זֶה בָּזֶה, וְקוֹל מִתְעוֹרֵר מִתּוֹךְ נוֹף הָאִילָן, וְקוֹרֵא וְאוֹמֵר: זָכַר לְעוֹלָם בְּרִיתוֹ דָּבָר צִוָּה לְאֶלֶף דּוֹר אֲשֶׁר כָּרַת אֶת אַבְרָהָם וּשְׁבוּעָתוֹ לְיִצְחָק. כֵּיוָן שֶׁקּוֹל זֶה מִתְעוֹרֵר, שׁוֹמֵעַ אַבְרָהָם סָבָא וּמִתְעוֹרֵר, (אז) כַּאֲשֶׁר הוּא רָצוֹן לַמֶּלֶךְ, וּמִתְנַחֵם אִתּוֹ."],[11,"","בְּאוֹתָהּ שָׁעָה מִתְעוֹרֶרֶת רוּחַ אַחַת מִצַּד דָּרוֹם, וְכָל רָצוֹן וְחֶדְוָה וּרְפוּאָה מִתְעוֹרְרִים עַל הָעוֹלָם. וְאָז עוֹלֶה הַבֹּקֶר, וְנִמְצָא רָצוֹן וּמְנוּחָה לְכָל אֲסִירֵי הַמֶּלֶךְ שֶׁהֵם בְּבֵית חוֹלִים. אַשְׁרֵי הָעָם שֶׁיְּכוֹלִים לָדַעַת מֵהַסּוֹדוֹת הַטְּמִירִים וְהַנִּסְתָּרִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ."]]],[["אָמַר רַבִּי אַבָּא יוֹמָא חַד הֲוִינָא אֲנָא וְרַבִּי יְהוּדָה דְּמִן עַכּוֹ (אזלי) בְּמַדְבְּרָא וְעָאלְנָא בִּמְעַרְתָּא חֲדָא וְאַשְׁכַּחְנָא תַּמָּן סִפְרָא חֲדָא עַתִּיקָא דְּמִן יוֹמִין קַדְמָאִין. פַּתַחְנָא לֵיהּ ואַשְׁכַּחְנָא דְהָוָה כְּתִיב בֵּיהּ בְּרֵישׁ מִלּוֹי (ישעיהו מ״ב:ט׳) הָרִאשׁוֹנוֹת הִנֵּה בָּאוּ וְחֲדָשׁוֹת אֲנִי מַגִּיד. ואוֹקִים קְרָא בְּנִשְׁמָתֵהוֹן דְּצַדִּיקַיָּיא. מִן יוֹמָא דְּסָלִיק בְּמַחֲשָׁבָה לְמִבְרֵי עַלְמָא.","וְעַד לָא אִתְבְּרֵי עַלְמָא כָּל רוּחִין דְּצַדִּיקַיָּיא הֲווּ גְּנִיזִין בְּמַחֲשָׁבָה קָמֵיהּ כָּל חַד וְחַד בְּדִיּוּקְנֵיהּ. כֵּיוָן דְּצִיֵּיר עַלְמָא אִתְגַלְיָין כֻּלְּהוּ וְקַיִּימוּ בְּדִיוּקְנָיְיהוּ קָמֵיהּ בְּרוֹמֵי מְרוֹמִים. לְבָתַר יָהַב לוֹן בְּאוֹצָר חַד בְּגִנְתָּא דְעֵדֶן לְעֵילָּא. וְהַהוּא אוֹצָר לָא מַלְיָא לְעָלְמִין, וְתָדִיר קָרֵי הָרִאשׁוֹנוֹת הִנֵּה בָּאוּ וְחֲדָשׁוֹת אֲנִי מַגִּיד. מַאן אִינוּן אֲנִי מַגִּיד כּוּלְּהוּ בִּשְׁמָהָן וְלֵית תִיאוּבְתָּא וְכִיסוּפָא לְהַאי אוֹצָר אֶלָּא לְאַרָקָא בֵּיהּ נִשְׁמָתִין תָּדִיר. כְּמָה דְּגֵיהִנָּם לֵית תִיאוּבְתָּא וְכִיסוּפָא אֶלָּא לְקָבְּלָא נִשְׁמָתִין לְאִתְדַכָּאָה תַּמָּן וְכָל יוֹמָא קָארֵי הַב הַב. מַאי הַב הַב (אלא) אוֹקִיד אוֹקִיד.","וְהַהוּא אוֹצָר נָטִיל כָּל (אינון) נִשְׁמָתִין אִינוּן עַד זִמְנָא דְּאַלְבִּישׁ לוֹן ונָחֲתֵי לְהַאי עַלְמָא. וּמִגּוֹ חוֹבָה דְּאָדָם קַדְמָאָה דְּאַמְשִׁיךְ סִטְרָא בִּישָׁא לְעַלְמָא אִצְטְרִיכוּ לְאַלְבְּשָׁא אִינוּן נִשְׁמָתִין בִּלְבוּשָׁא דָא. דְּהָא לְבוּשָׁא אַחֲרָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבְּשָׁא לְאִינוּן נִשְׁמָתִין. (ס\"א ואמר בההוא ספרא) וְהַהוּא (והוה) אָמַר הַהוּא סִפְרָא עַד הָכָא שְׁתִיקוּ (שתוקו). וְעוֹד חֲמֵינָא מִכָּאן וּלְהָלְאָה אַתְוָון מֵחִיקַן דְּלָא אִשְׁתְּמוֹדְעָן.","וּבָתַר חֲמֵינָא לוֹן בְּחֶלְמָא ואָמְרוּ לִי שְׁתוֹק וְלָא תְגָלֵי אֶלָּא לְטִינָרָא תַקִּיפָא, וְכָךְ עֲבִידְנָא. ואַשְׁכַּחְנָא בֵּיהּ מָאנִין דִּלְבוּשָׁא אַחֲרָא זָמִין (דזמין) קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבְּשָׁא לְאִינוּן נִשְׁמָתִין לְזִימְנִין (לזמנא) דְּאָתֵי.","(אם כן) מֵתִים דְּחַיוּ עַל יְדָא דִיחֶזְקֵאל, מַאי טַעְמָא לָא עֲבָד לוֹן הַהוּא לְבוּשָׁא. אֶלָּא בְּגִין דְּלָא מָטָא זִמְנָא לְאַעֲבְּרָא בְּעָלְמָא הַהוּא אֲוִירָא דַּכְיָא דְּעָבִיד לְבוּשִׁין. וּבְגִין כָּךְ אַלְבִּישׁ לוֹן אֶלָּא כְּמָה דַהֲווּ, וְכָךְ יְהֵא לִתְחִיַּית הַמֵּתִים, בָּר דְּהַהוּא זוֹהֲמָא דְקַדְמִיתָא לָא אִשְׁתְּכַּח תַּמָּן.","כַּד נָפַק בַּר נָשׁ מֵהַאי עַלְמָא, כֻּלְּהוּ בֵּין צַדִּיקֵי בֵּין חֲסִידֵי וּתְמִימֵי וְחַיָיבֵי וְרָשִׁיעֵי. כֻּלְּהוּ עַבְרֵי בַּאֲוִירָא, לְמֶחֱמֵי אָדָם קַדְמָאָה לִבְנֵי עַלְמָא. וּמִתַּמָּן נָטִיל אוֹרְחָא הֵן לְגִנְתָא דְעֵדֶן הֵן לְגֵיהִנָּם.","כָּל אִינוּן דְּאוֹרְחַיְיהוּ לְגִּנְתָּא דְעֵדֶן, מִתְקָרְבִין לְגַבֵּי חוֹמָה דִּלְבָר מֵאִינוּן תְלַת חוֹמוֹת דְּתַּמָּן. וּכְדֵין נָפִיק חַד מְמַנָּא ואִתְעַר קַמַּיְיהוּ וְקַארֵי וְאָמַר, זַכָּאִין אַתּוּן צַדִּיקַיָּיא (בעלמין כולהו) בְּעָלְמָא. וְהַהוּא מְמַנָּא יעזרי\"אל שְׁמֵיהּ, אוֹלִיף לוֹן אוֹרְחָא ואַזְלִין קָמֵיהּ עַד תַרְעָא חֲדָא דְּגֵיהִנָּם. הַהוּא מְמוּנֶה קָארֵי בְּחֵילֵיהּ וְאָמַר, צָנוּן תְּנַנָא (תננהא) צָנוּן יָּקִידְתָא. בְּהַהִיא שַׁעְתָּא, בִּבְהִילוּ מֵצָנְנִין לָהּ וְעָאלִין כּוּלְּהוּ וְטַבְלִין וְעַבְרִין. וְכָל אִינוּן חַיָּיבִין אִתְמָסְרָן בִּידָא דְּדומ\"ה וְעָאלִין בְּגֵּיהִנָּם. וְכָל אִינוּן זַכָּאִין, לָא אִתְמָסְרָן בִּידוֹי. אֶלָּא (בידא) דְּהָא מְמוּנֶה.","וּבָתַר דְּטַבְלִין וְעַבְרִין, הַהוּא מְמוּנֶה אָזִיל קַמַּיְיהוּ עַד דְּמָטָאן לְשׁוּר דְגִנְתָּא דְעֵדֶן וְהַהוּא מְמוּנֶה קָארֵי לְפִתְחָא וְאוֹמֵר, (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְיָבֹא גּוֹי צַדִּיק שׁוֹמֵר אֱמוּנִים. כְּדֵין פַּתְחִין פִתְחָא ואַעִיל לוֹן, וְכֵן בְּכָל פִתְחָא וּפִתְחָא.","כֵּיוָן דְּעָאלִין לְגוֹ אֲתָר דְּצַדִּיקַיָּיא, צַדִּיקַיָּיא אוֹחֲרָנִין קַיְימִין וְכַמָּה חֶדְוָה עַל חֶדְוָה עַל צַדִּיקַיָּיא וְכָל בְּנֵי מְתִיבְתָּא חַדָּאן. לְסוֹף תְלָתָא יוֹמִין דְּאִתְטַמֵרָן בְּהֵיכָלִין יְדִיעָן נַפְקֵי וַאֲוִירָא נָשְׁבֵי וּמִתְצָיְּירָן כּוּלְּהוּ בְּדִיוּקְנָיְיהוּ. מִכָּאן וּלְהָלְאָה יַרְתִּין אַחְסָנַת יְרוּתָא כְּדְקָא חֲזֵי לְכָל חַד.","חַזוּתָא דְאִתְחֲזֵי בְּגִנְתָּא דְעֵדֶן מֵחֵיזוּ יְקָרָא דִּיּוּקְנָא דְּכָל דִּיוּקְנִין וְגווַֹן דְּכָל גּווָֹנִין. דְּמַלְכָּא קַדִּישָׁא לֹא אִתְגְּלִי בְּהֵיכָלָא וְלָא בְּאֲתָר חַד. אֶלָּא (אתפתח) אִתְפֶּשַׁח רְקִיעָא מְרַקְמָא עַל גַּבֵּי גִּנְתָּא לְאַרְבַּע סִטְרִין וְאִתְמָלְיָּיא מִזִּיוָא יַקִּירָא קַדִּישָׁא וְאִתְחֲזֵי תַּמָּן, ואִתְהַנָן כּוּלְּהוּ צַדִּיקַיָּיא. מַאן חָמָא חֶדְוָה וְכִסּוּפָא דְּהַהוּא נוֹעַם יְיָ.","עַד כָּאן הֲוָה לִי רֵשׁוּ לְמֶחֱמֵי בְּהַהוּא סִפְרָא. אַדְמָקִיפְנָא לְמֶחמֵי יַתִּיר בֵּיהּ, פָּרַח מִן יָדִי וְלָא חֲמֵינָא לֵיהּ. אִשְׁתָאַרְנָא עֲצִיב וּבָכֵינָא. דַמִיכְנָא תַּמָּן בְּהַהוּא מְעַרְתָּא וְחֲמֵינָא לֵיהּ (לההוא) דְהָוָה לָבִישׁ מָנָא (מצא). אָמַר לִי ר' לָמָה לָךְ לְמִבְכֵּי וְלָא תִתְעֲצֵב (ס\"א ממאן) מִמַּה דְהָוָה בְּהַהוּא סִפְרָא. פָּרַח לְגַבֵּיהּ וְנָטְלֵיה וְעַד לָא יִפּוֹק מֵהַאי עַלְמָא גָּנִיז לֵיהּ בְּהַהוּא מְעַרְתָּא דְּמָדְבְּרָא דָא, וְהַשְׁתָּא דְהָוָה מִתְגְּלֵי לְחַיָּיא הָכָא, פָּרַח בַּאֲוִירָא לְנָטְלֵיה.","מִכָּאן וּלְהָלְאָה זִיל לָךְ לְאוֹרְחָךְ, וּמֵהַהוּא יוֹמָא וְעַד הַשְׁתָּא לָא אִתְגְּלֵי לִי וְלָא זָכִינָא לְמִשְׁמָע מִמָּאן הֲוָה. וּבְכָל זִמְנָא דְּאֲנָא דָּכִירְנָא, אִשְׁתָאַרְנָא עֲצִיב. אָמַר רִבִּי אֶלְעָזָר, דִּילְמָא קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִיקָרֵיהּ דְּלָא בָּעֵי דְּיִתְגַלֵּי בְּעָלְמָא. עַד דַהֲווּ יַתְבֵי וְלָעָאן בְּמִלִּין אָחֳרָנִין עִלָּאִין וְיַקִּירִין נָהַר יְמָמָא קָמוּ ואַזְלוּ. אָמַר רַבִּי אֶלְעָזָר הַשְׁתָּא עִידָן רַעֲוָא מִקָּמֵי מַלְכָּא קַדִּישָׁא, נִימָא מִילֵי דְּאוֹרַיְיתָא וְנִתְעַסֵק בָּהּ ונִשְׁתַתֵף בִּשְׁכִינְתָּא. פָּתַח וְאָמַר, (תהילים ה׳:ד׳) יְהוָֹ\"ה בֹקֶר תִּשְׁמַע קוֹלִי בֹקֶר אֶעְרוֹךְ לְךָ וָאֲצָפֶּה. (ע\"כ). אָמַר רִבִּי אֶלְעָזָר, בִּלְעָם חַיָּיבָא, מַאן קַטִּיל לֵיהּ, וְהֵיךְ אִקְטִיל. אָמַר רַבִּי יִצְחָק וְכוּ'."],[],[[0,"","אָמַר רַבִּי אַבָּא, יוֹם אֶחָד הָיִיתִי אֲנִי וְרַבִּי יְהוּדָה שֶׁמִּן עַכּוֹ (הולכים) בַּמִּדְבָּר, וְנִכְנַסְנוּ בִמְעָרָה אַחַת, וּמָצָאנוּ שָׁם סֵפֶר עַתִּיק אֶחָד מִיָּמִים רִאשׁוֹנִים. פָּתַחְנוּ אוֹתוֹ, וּמָצָאנוּ שֶׁהָיָה כָּתוּב בּוֹ בְּרֹאשׁ דְּבָרָיו: (ישעיה מב) הָרִאשׁוֹנוֹת הִנֵּה בָאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד, וּבֵאֵר הַפָּסוּק בְּנִשְׁמוֹת הַצַּדִּיקִים. מִיּוֹם שֶׁעָלָה בְמַחֲשָׁבָה לִבְרֹא עוֹלָם."],[1,"","וְעַד שֶׁלֹּא נִבְרָא הָעוֹלָם, כָּל רוּחוֹת הַצַּדִּיקִים הָיוּ גְנוּזוֹת בְּמַחֲשָׁבָה לְפָנָיו, וְכָל אֶחָד וְאֶחָד בִּדְמוּתוֹ. כֵּיוָן שֶׁצִּיֵּר אֶת הָעוֹלָם, הִתְגַּלּוּ כֻלָּם וְעָמְדוּ בִדְמוּתָם לְפָנָיו בְּרוֹמֵי מְרוֹמִים, אַחַר כָּךְ נָתַן אוֹתָם בְּאוֹצָר אֶחָד בְּגַן עֵדֶן שֶׁלְּמַעְלָה, וְאוֹתוֹ אוֹצָר לֹא מָלֵא לְעוֹלָמִים, וְתָמִיד קוֹרֵא: הָרִאשּנוֹת הִנֵּה בָאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד. מַה הֵם אֲנִי מַגִּיד כֻּלָּם בְּשֵׁמוֹת. וְאֵין תַּאֲוָה וְכִסּוּף לָאוֹצָר הַזֶּה, אֶלָּא רַק לְהוֹרִיק בּוֹ נְשָׁמוֹת תָּמִיד. כְּמוֹ שֶׁלַּגֵּיהִנָּם אֵין תַּאֲוָה וְכִסּוּף אֶלָּא רַק לְקַבֵּל נְשָׁמוֹת לְטַהֵר שָׁם. וְכָל יוֹם קוֹרֵא: הַב הַב. מַה זֶּה הַב הַב? (אלא) שְׂרֹף שְׂרֹף."],[2,"","וְאוֹתוֹ אוֹצָר לוֹקֵחַ כָּל (אותן) הַנְּשָׁמוֹת הַלָּלוּ, עַד זְמַן שֶׁמַּלְבִּישָׁם וּמוֹרִידָם לָעוֹלָם הַזֶּה, וּמִתּוֹךְ חֵטְא אָדָם הָרִאשׁוֹן שֶׁהִמְשִׁיךְ צַד הָרָע לָעוֹלָם, הִצְטָרְכוּ לְהַלְבִּישׁ אוֹתָן נְשָׁמוֹת בִּלְבוּשׁ זֶה, שֶׁהֲרֵי לְבוּשׁ אַחֵר רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישׁ לְאוֹתָן הַנְּשָׁמוֹת. (ואמר באותו ספר) וְהַהוּא (והיה) אָמַר אוֹתוֹ סוֹפֵר: עַד כָּאן שִׁתְקוּ (שתקו). וְעוֹד רָאִיתִי מִכָּאן וָהָלְאָה אוֹתִיּוֹת מְחוּקוֹת שֶׁלֹּא יְדוּעוֹת."],[3,"","וְאַחַר כָּךְ רָאִיתִי אוֹתָן בַּחֲלוֹם, וְאָמְרוּ לִי: שְׁתֹק וְאַל תְּגַלֶּה, אֶלָּא לַסֶּלַע הַתַּקִּיף. וְכָךְ עָשִׂיתִי. וּמָצָאתִי בוֹ שֶׁכֵּלִים שֶׁל לְבוּשׁ אַחֵר עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַלְבִּישׁ אֶת אוֹתָן נְשָׁמוֹת לַעֲתִידִים (לעתיד) לָבא. (אם כן,) מֵתִים שֶׁחָיוּ עַל יְדֵי יְחֶזְקֵאל, מָה הַטַּעַם לֹא עָשָׂה לָהֶם אֶת אוֹתוֹ הַלְּבוּשׁ?"],[4,"","אֶלָּא מִשּׁוּם שֶׁלֹּא הִגִּיעַ זְמַן לְהַעֲבִיר בָּעוֹלָם אוֹתוֹ אֲוִיר טָהוֹר שֶׁעוֹשֶׂה לְבוּשִׁים, וּמִשּׁוּם זֶה לֹא הִלְבִּישָׁם אֶלָּא כְּמוֹ שֶׁהֵם הָיוּ, וְכָךְ יִהְיֶה לִתְחִיַּת הַמֵּתִים, פְּרָט שֶׁאוֹתָהּ זֻהֲמָא שֶׁל הַהַתְחָלָה לֹא נִמְצֵאת שָׁם."],[5,"","כְּשֶׁיּוֹצֵא אָדָם מֵהָעוֹלָם הַזֶּה, כֻּלָּם, בֵּין צַדִּיקִים בֵּין חֲסִידִים וּתְמִימִים וּרְשָׁעִים וְחַיָּבִים, כֻּלָּם עוֹבְרִים בְּדֶרֶךְ זוֹ לִרְאוֹת אֶת אָדָם הָרִאשׁוֹן לִבְנֵי הָעוֹלָם, וּמִשָּׁם לוֹקְחִים דֶּרֶךְ, הֵן לְגַן עֵדֶן הֵן לְגֵיהִנָּם."],[6,"","כָּל אוֹתָם שֶׁדַּרְכָם לְגַן עֵדֶן, מִתְקָרְבִים לַחוֹמָה הַחִיצוֹנִית מֵאוֹתָן שָׁלֹשׁ חוֹמוֹת שֶׁשָּׁם, וְאָז יוֹצֵא מְמֻנֶּה אֶחָד, וּמִתְעוֹרֵר לִפְנֵיהֶם וְקוֹרֵא וְאוֹמֵר: אַשְׁרֵיכֶם הַצַּדִּיקִים (בכל העולמות) בָּעוֹלָם! וְאוֹתוֹ מְמֻנֶּה, שְׁמוֹ יַעְזְרִאֵ\"ל, מְלַמֵּד אוֹתָם אֶת הַדֶּרֶךְ, וְהוֹלְכִים לְפָנָיו עַד שַׁעַר אֶחָד שֶׁל הַגֵּיהִנָּם, וְאוֹתוֹ מְמֻנֶּה קוֹרֵא בְחַיִל וְאוֹמֵר: צַנְּנוּ הֶעָשָׁן! צַנְּנוּ הַשְּׂרֵפָה! בְּאוֹתָהּ שָׁעָה מְצַנְּנִים אוֹתָהּ בִּבְהִילוּת, וְנִכְנָסִים כֻּלָּם וְטוֹבְלִים וְעוֹבְרִים, וְכָל אוֹתָם רְשָׁעִים נִמְסָרִים בְּיַד דּוּמָ\"ה וְנִכְנָסִים בַּגֵּיהִנָּם, וְכָל אוֹתָם צַדִּיקִים לֹא נִמְסָרִים בְּיָדָיו, אֶלָּא (בידי) הַמְמֻנֶּה הַזֶּה."],[7,"","וְאַחַר שֶׁטּוֹבְלִים וְעוֹבְרִים, הַמְמֻנֶּה הַזֶּה הוֹלֵךְ לִפְנֵיהֶם עַד שֶׁמַּגִּיעִים לְחוֹמַת גַּן עֵדֶן, וְאוֹתוֹ מְמֻנֶּה קוֹרֵא לַפֶּתַח וְאוֹמֵר: פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק שֹׁמֵר אֱמֻנִים (ישעיה כו). אָז פּוֹתְחִים פֶּתַח וּמַכְנִיסִים אוֹתָם, וְכָךְ בְּכָל פֶּתַח."],[8,"","כֵּיוָן שֶׁנִּכְנְסוּ לְתוֹךְ מָקוֹם שֶׁצַּדִּיקִים אֲחֵרִים עוֹמְדִים, כַּמָּה חֶדְוָה עַל חֶדְוָה עַל הַצַּדִּיקִים, וְכָל בְּנֵי הַיְשִׁיבָה שְׂמֵחִים. לְסוֹף שְׁלֹשָׁה יָמִים שֶׁמִּתְחַבְּאִים בְּהֵיכָלוֹת יְדוּעִים, יוֹצְאִים וַאֲוִירִים נוֹשְׁבִים, וּמִצְטַיְּרִים כֻּלָּם בִּדְמֻיּוֹתֵיהֶם. מִכָּאן וָהָלְאָה יוֹרְשִׁים יְרֻשָּׁה כָּרָאוּי לְכָל אֶחָד וְאֶחָד."],[9,"","מַרְאֶה שֶׁנִּרְאֶה בְּגַן עֵדֶן מִמַּרְאֶה נִכְבָּד, דְּמוּת כָּל הַדְּמֻיּוֹת, וְגָוֶן שֶׁל כָּל הַגְּוָנִים. שֶׁמֶּלֶךְ הַקָּדוֹשׁ לֹא מִתְגַּלֶּה בַּהֵיכָל וְלֹא בְמָקוֹם אֶחָד, אֶלָּא נִפְתָּח רָקִיעַ מְרֻקָּם עַל גַּב הַגָּן לְאַרְבָּעָה צְדָדִים, וּמִתְמַלֵּא מִזִּיו כָּבוֹד הַקָּדוֹשׁ וְנִרְאֶה שָׁם, וְנֶהֱנִים כָּל הַצַּדִּיקִים. מִי רָאָה חֶדְוָה וְכִסּוּף קָדוֹשׁ שֶׁל אוֹתוֹ נֹעַם ה'."],[10,"","עַד כָּאן הָיָה לִי רְשׁוּת לִרְאוֹת בְּאוֹתוֹ סֵפֶר. כְּשֶׁהִקַּפְנוּ לִרְאוֹת בּוֹ יוֹתֵר, פָּרַח מִיָּדִי וְלֹא רָאִיתִי אוֹתוֹ. נִשְׁאַרְתִּי עָצוּב וּבָכִיתִי, יָשַׁנְתִּי שָׁם בְּאוֹתָהּ מְעָרָה וְרָאִיתִי אוֹתוֹ (את אותו) שֶׁהָיָה לָבוּשׁ מַדִּים. אָמַר לִי, רַבִּי, לָמָּה לְךְ לִבְכּוֹת? וְאַל תִּתְעַצֵּב (ממי) מִמַּה שֶּׁהָיָה בְּאוֹתוֹ סֵפֶר. פָּרַח אֵלָיו וּלְקָחוֹ, וְעַד שֶׁלֹּא יָצָא מֵהָעוֹלָם הַזֶּה, גָּנַז אוֹתוֹ בְּאוֹתָהּ מְעָרָה שֶׁבַּמִּדְבָּר הַזֶּה, וְכָעֵת שֶׁהָיָה מִתְגַּלֶּה לַחַיִּים כָּאן, פָּרַח בָּאֲוִיר וּלְקָחוֹ."],[11,"","מִכָּאן וָהָלְאָה לֵךְ לְדַרְכְּךְ. וּמֵאוֹתוֹ יוֹם וְעַד עַכְשָׁו לֹא הִתְגַּלָּה לִי וְלֹא זָכִיתִי לִשְׁמֹעַ מִמִּי הָיָה, וּבְכָל זְמַן שֶׁאֲנִי נִזְכָּר, אֲנִי נִשְׁאָר עָצוּב. אָמַר רַבִּי אֶלְעָזָר, אוּלַי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדוֹ שֶׁלֹּא רוֹצֶה שֶׁיִּתְגַּלֶּה בָּעוֹלָם. עֵד שֶׁיָּשְׁבוּ וְעָסְקוּ בִּדְבָרִים אֲחֵרִים עֶלְיוֹנִים וְנִכְבָּדִים, הֵאִיר הַיּוֹם. קָמוּ וְהָלְכוּ. אָמַר רַבִּי אֶלְעָזָר, כָּעֵת עֵת רָצוֹן מִלִּפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, נֹאמַר דִּבְרֵי תוֹרָה וְנִתְעַסֵּק בָּהּ וְנִשְׁתַּתֵּף בַּשְּׁכִינָה. פָּתַח וְאָמַר, ה' בֹּקֶר תִּשְׁמַע קוֹלִי בּקֶר אֶעֱרָךְ לְךְ וַאֲצַפֶּה. אָמַר רַבִּי אֶלְעָזָר, בִּלְעָם הָרָשָׁע מִי הָרַג אוֹתוֹ, וְאֵיךְ נֶהֱרַג? אָמַר רַבִּי יִצְחָק וְכֻלֵּי: ע\"כ מההשמטות."]]],[["לֵאמֹר הִנֵּה עַם יָצָא מִמִצְרַיִם. אִי תֵימָא דְּהָא צָרִיךְ לְנַטְלָא פִּיפּוּסִין וְיוֹחַסִין דִּילְהוֹן, לָא אִיצְטְרִיךְ אֶלָּא אוֹרַח כְּלָל דִּכְתִיב הִנֵּה עַם יָצָא. מַאי טַעְמָא, מִשׁוּם דְהַכִי קָרֵי לוֹן פַּטְרוֹנָא דִּילְהוֹן כַּמָה זִמְּנִין. וְעַל דָא לָא תִטְעֵי דִּכְתִיב (שמות ה׳:א׳) שָׁלַח אֶת עַמִי בְּכָל זְמָן.","וְעוֹד כַּד נַטְלַת עֵיטָא עֲלַיְיהוּ עִם פַּרְעֹה בְּלִישְׁנָא דָא יָכַלְתְּ לְהוּ. דִּכְתִיב, (שמות א׳:ט׳) הִנֵּה עַם בְּנֵי יִשְׂרָאֵל רָב וְעָצוּם מִמֶּנּוּ. אוּף הַשְׁתָּא דִּכְתִיב, הִנֵּה עַם יָצָא ממִצְרַיִם וְלָא אַפִּיק לוֹן אַחֲרָא, אֶלָּא אִיהוּ מִגַּרְמֵיהּ נָפַק. וּבְגִין כָּךְ תֵיכוּל לְאַבְאָשָׁא לוֹן.","הִנֵּה כִּסָה אֵת עֵין הָאָרֶץ, אִית דְּאַמְרֵי סִיחוֹן וְעוֹג דְּקַטְלֵי (דקטלו) לוֹן יִשְׂרָאֵל, דַהֲווּ עֵינָא דְּאַרְעָא. אֶלָּא כַּד אַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא אַרְבֵּה עַל אַרְעָא דְּמִצְרַיִם. כְּתִיב, (שמות י׳:ט״ו) וַיְכַס אֵת עֵין כָּל הָאָרֶץ וַתֶחְשַׁךְ הָאָרֶץ. אֲמַאי, בְּגִין דְּכָל חַרְשִׁין וְקִסְמִין דְּעָלְמָא לָא יַכְלִין לְמֶעְבַּד חַרְשִׁין אֶלָּא מִלָּה חֲדָא בְּדַרְגָּא חֲדָא, בְּזִמְנָא חֲדָא. וְעַמָּא דָא אַיְיתֵי עַרוֹב מֵבּוּלְבַּל מִכַּמָּה זִינִין מֵבּוּלְבָּלִין אִלֵּין בְּאִלֵּין, עַד דְּלָא יָכְלוּ כָּל חַרְשִׁין וְקִסְמִין לְמֵיקָם. וְדָא הוּא וַיְכַס אֵת עֵין כָּל הָאָרֶץ. וְהָכָא כְּתִיב, וַיְכַס אֵת עֵין הָאָרֶץ וְהָכִי הוּא וַדַּאי.","אָמַר ר' אַבָּא בָּלָק ובִּלְעָם לָא הֲוָה בְּעָלְמָא חַרְשִׁין וְקִסְמִין כְּוָותַיְיהוּ (בלעם) חֵילֵיהּ וְתוּקְפֵיהּ הֲוָה בְּפוּמֵיהּ וְעֵינֵיהּ. בָּלָק חֵילֵיהּ וְתוּקְפֵיהּ הֲוָה בְּעוֹבָדָא דְּיָּדִין. וְדָא אִיצְטְרִיךְ לְדָא, דְּהָא כָּל זִינֵי חַרְשִׁין דְּעָלְמָא בְּפוּמָא וְעוֹבָדָא הוּא, וּבְהוּ תַלְיָין. בִּלְעָם הֲוָה לֵיהּ לִישָׁן וְלָא יְדִין, בָּלָק הֲוָה לֵיהּ יְדִין וְלָא לִישָׁן.","אַזְלוּ חַבְרַיָּיא עַד דְּמָטוּ חַד בֵּי חֲקַל וְשִׁמְשָׁא הֲוָה תַקִיף לַחֲדָא. חָמוּ הַהוּא בֵּי חֲקַל בְּשַׁפִּירוּ דְעִשְׂבִּין וּמַיִין נַפְקִין לְכָל סְטָר וְאִילָנֵי חַקְלָא סַגִּיאִין, יָתְבוּ תַּמָּן. אָמַר רַבִּי אֶלְעָזָר, כַּמָה יֵאוֹת אֲתָר דָא לְנַיְיחָא בֵּיהּ.","אַדְהֲווֹ יַתְבֵי, הַא חִוְיָא רַבְרְבָא אֲתָא בְתוּקְפָא דְשִׁמְשָׁא וְאַעֲבַר קַמַּיְיהוּ. אָמַר לֵיהּ רִבִּי אֶלְעָזָר, חִוְיָא חִוְיָא, סָטֵי לָךְ מֵאוֹרְחַךְ, דְּהָא תָב הַהוּא גַּבְרָא ואִתְנַחֵם עַל מָה דְּעָבַד, וְלָא יוֹסִיף לְמֶעְבַּד הַהוּא מִלָּה. תַּוְוהוּ חַבְרַיָּיא. אָמַר ר' אַבָּא מַאי הוּא. אָמַר לוֹן שְׁתוֹקוּ. אָמַר רִבִּי אֶלְעָזָר, חִוְיָא חִוְיָא, לְבָתַר דְּלָחִישׁוּ לָךְ מִן שְׁמַיָא, אִתְנֵחָם הַהוּא גַּבְרָא וְשַׁוִּי בִּרְעוּתֵיהּ דְּלָא יְתִיב בֵּיהּ לְעָלְמִין סָטֵי לָךְ מֵאוֹרְחַךְ. קָם חִוְיָא בְּקִיוּמֵיהּ וְלָא נָטִיל הָכָא וְהָכָא. תָב כְּמִלְקַדְמִין. אָמַר לֵיהּ, חִוְיָא חִוְיָא, יָדַעְנָא מָה דְּאַתְּ בָּעֵי, תּוּב מֵאָרְחָךְ. דְּהָא גּוֹי חַיָּיבָא אָתֵי, דְּעָבִיד בִּישׁ לְחַד יוּדָאי. וְהָא הוּא נָאִים שָׁכִיב בִּמְעַרְתָּא דִּילָךְ, זִיל וְקַטְלֵיהּ. מִיָד אַהְדַּר הַהוּא חִוְיָא וְדִּלֵּג דִלוּגִּין קַמַּיְיהוּ.","אָמַר רַבִּי אֶלְעָזָר, אִי לָא הֲוִינָא הָכָא, כַּמָה בִּישִׁין הֲוָה עֲבִיד הַאי חִוְיָא. דְּהָא כַּד בַּר נָשׁ יוּדָאי עֲבָד עוֹבָדָא דְּחוֹבָא, וְעַד לָא תָב בְּתִיוּבְתָא, לְחִישׁוּ לֵיהּ לְהַאי חִוְיָא לְקַטְלָא לֵיהּ. וְאִימְלָךְ הַהוּא בַּר נָשׁ בֵּין כַּךְ וּבֵין כַּךְ, וְאִתְנַחֵם מֵחוֹבֵיהּ. וְאָמַר דְּלָא יְתוּב לְעָלְמִין לְהַאי חַטָּאָה וְעַל דָּא אִשְׁתֵּזִיב מִן דִּינָא.","אֲמְרוּ חַבְרַיָּיא לְרַבִּי אֶלְעָזָר, בְּמָה יָדַעְתְּ. אָמַר לְהוּ, סִימָנָא יָהַב לִי אַבָּא, וַאֲנָא אִשְׁתְּמוֹדַעְנָא בֵּיהּ. אֲמְרוּ לֵיהּ, תִּינַח חִוְיָא דְּאִשְׁתְמוֹדְעַת בֵּיהּ. הַהוּא דְּאִתְנֵחַם וְתַב מֵחוֹבֵיהּ בְּמָה יָדַעְתְּ. אָמַר לְהוּ, כַּד הֲוָה אָזִיל הַהוּא חִוְיָא, קַשְׂקַשּׂוֹי הֲווּ סָלְקִין וזָנְבוֹי זָקִיף וְאִיהוּ דְּאָזִיל (אזיל) בִּבְהִילוּ. רוּחָא חֲדָא הֲוָה אָזִיל לָקֳבְלֵיה וְהָוָה קָארֵי קָמֵיהּ, תּוּב מֵאָרְחָךְ. דְּהָא תָב מֵחוֹבֵיהּ וְאִתְנְחֵם הַהוּא בַּר נָשׁ. וְהַהוּא חִוְיָא בִּישָׁא לָא הֲוָה צַיִּית עַד דְּיִתְנוּן לֵיהּ כּוֹפֶר בַּהֲדֵיהּ בְּאַתְרֵיהּ דְּהַהוּא בַּר נָשׁ דְּאִתְחַיָּיב קָטוֹלָא וְתָב. דְּכַךְ אוֹרְחוֹי דְּחִוְיָא עֵילָא וְתַתָּא, כֵּיוָן דְאִתְיְיהִיב לֵיהּ רֵשׁוּ, לָא תָב עַד דְּאַשְׁלִים הַהוּא דִּינָא בִּישָׁא דְאִתְיְיהִיב לֵיהּ רֵשׁוּ לְמֶעְבַּד, אוֹ דְּיִתְנוּן לֵיהּ בְּאַתְרֵיהּ חַיָּיבָא אַחֲרָא בְּכּוֹפְרָא. דְּהָא בְּרֵיקָנַיָּיא לָא יִפּוֹק. כֵּיוָן דְאִתְיְיהִיב לֵיהּ רֵשׁוּ.","אָמְרוּ לֵיהּ, תִּינַח כָּל דָא. הַהוּא גּוֹי דְּאַמָרַת דִּיהַבְתְּ לֵיהּ כּוֹפְרָא, בְּמָאי יָדַעְתְּ. אָמַר לוֹן, כֵּיוָן דְּמַלֵּלִית לְחִוְיָא, הַהוּא רוּחָא דְהָוָה אָזִיל לָקֳבְלֵיה וְלָחִישׁ לֵיהּ דִּיתוּב לְאוֹרְחֵיהּ דְּהָא אִתְנֵחָם הַהוּא בַּר נָשׁ. דָּלִיג הַהוּא רוּחָא עַל אוּדְנֵיהּ. (אודני ואמר לי).","תַּוְוהוּ חַבְרַיָּיא. אָמַר רַבִּי אֶלְעָזָר, נֵיהַךְ וְנֵחְמֵי, דְּהָא חִוְיָא עֲבָד מָה דְּעָבַד. קָמוּ וְקַרִיבוּ גַּבֵּי חַד טִינָרָא בְּהַהוּא בֵּי חֲקַל, אַשְׁכָּחוּ לְהַהוּא גּוֹי דְּמִית וְהַהוּא נָחָשׁ כַּרִיךְ עַל עִקְבֵיהּ וְלָא הֲוָה אַבְדִיל מִנֵּיהּ, וּבָתַר אִתְפְּרַשׁ מֵעֲקְבֵיהּ וְסָלִיק עַל גְּרוֹנֵיהּ וְאַכְרִיךְ תַּמָּן. וּמִתַּמָּן נָחִית עַל עֲקַבֵיהּ, דְּלָא הֲוָה מִתְפְּרָשׁ מִנֵּיהּ.","אַשְׁכָּחוּ לֵיהּ אַרְנָקִי חַד מַלְיָא דִּינָרִין דְּגָזִיל לְחַד יוּדָאי בְּאָרְחָא וּמְחָא לֵיהּ. נָטַל רַבִּי אֶלְעָזָר יַת אַרְנָקִי. אָמַר, בְּרִיךְ רַחֲמָנָא דְּבְּכוֹלָא עֲבִיד שְׁלִיחוּתָא. תָבוּ לְהַהוּא אֲתָר דַהֲווּ (א ז ל י).","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ישעיהו מ״ג:ד׳) מֵאֲשֶׁר יָקַרְתָּ בְּעֵינָי נִכְבָּדְתָּ וַאֲנִי אָהַבְתִּיךָ וָאֶתֵּן אָדָם תַחְתֶּיךָ וּלְאֻמִּים תַּחַת נַפְשֶׁךָ. מֵאֲשֶׁר יָקַרְתָּ, יָקָר מִּבָּעֵי לֵיהּ, וְהָכִי אִיצְטְרִיךְ. מֵאֲשֶׁר אַתָּה יָקָר בְּעֵינָי, מָהוּ יָקַרְתָּ. מִכְּלַל דְּאִיהוּ מִגַּרְמֵיהּ אִתְיָיקַר. אֶלָּא הָכִי הוּא וַדַּאי, דְּכָל בַּר נָשׁ דְּאִיהוּ בְּחִיוּבָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא בְּקַדְמִיתָא, הוּא מֵזָלְזֵלָא וְתוֹעֵבָה (תועבתא) קַמֵי קוּדְשָׁא בְּרִיךְ הוּא. וּבָתַר דְּאִימְלָךְ וְתַב מֵחוֹבֵיהּ, הַשְׁתָּא אִיהוּ אִתְיָיקַר מִגַּרְמֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא קָארֵי עָלֵיהּ ואָמַר, מֵאֲשֶׁר יָקַרְתָּ בְּעֵינָי נִכְבָּדְתָּ, אָתְּ מִגַרְמָךְ יָקַרְתָּ."],[],[[0,"","לֵאמֹר הִנֵּה עַם יָצָא מִמִּצְרַיִם. אִם תֹּאמַר שֶׁהֲרֵי צָרִיךְ לָקַחַת שֵׁמוֹת וְיוּחֲסִין שֶׁלָּהֶם - לֹא צָרִיךְ, אֶלָּא דֶּרֶךְ כְּלָל, שֶׁכָּתוּב הִנֵּה עַם יָצָא. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ קָרָא לָהֶם הַפַּטְרוֹן שֶׁלָּהֶם כַּמָּה פְעָמִים. וְעַל זֶה אַל תִּטְעֶה שֶׁכָּתוּב שַׁלַּח אֶת עַמִּי, בְּכָל זְמַן."],[1,"","וְעוֹד, כְּשֶׁלָּקַחְתָּ עֵצָה עֲלֵיהֶם עִם פַּרְעֹה, בְּלָשׁוֹן זֶה יָכֹלְתָּ לָהֶם, שֶׁכָּתוּב הִנֵּה עַם בְּנֵי יִשְׂרָאֵל רַב וְעָצוּם מִמֶּנּוּ. גַּם כָּאן, שֶׁכָּתוּב הִנֵּה עַם יָצָא מִמִּצְרַיִם. וְלֹא הוֹצִיא אוֹתָם אַחֵר, אֶלָּא הוּא מֵעַצְמוֹ יָצָא, וּמִשּׁוּם כָּךְ תּוּכַל לְהָרַע לָהֶם."],[2,"","הִנֵּה כִסָּה אֶת עֵין הָאָרֶץ. יֵשׁ אוֹמְרִים, סִיחוֹן וְעוֹג שֶׁיִּשְׂרָאֵל הָרְגוּ אוֹתָם, שֶׁהָיוּ עֵין הָאָרֶץ. אֶלָּא כְּשֶׁהֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אַרְבֶּה עַל אֶרֶץ מִצְרַיִם, כָּתוּב וַיְכַס אֶת עֵין כָּל הָאָרֶץ וַתֶּחְשַׁךְ הָאָרֶץ, לָמָּה? מִשּׁוּם שֶׁכָּל מְכַשְּׁפֵי וְקוֹסְמֵי הָעוֹלָם לֹא יָכְלוּ לַעֲשׂוֹת כְּשָׁפִים, אֶלָּא רַק דָּבָר אֶחָד בְּדַרְגָּה אַחַת בִּזְמַן אֶחָד, וְעַם זֶה הֵבִיא עָרֹב מְבֻלְבָּל מִכַּמָּה מִינִים מְבֻלְבָּלִים אֵלּוּ בְאֵלּוּ, עַד שֶׁלֹּא יָכְלוּ כָּל מְכַשְּׁפִים וְקוֹסְמִים לַעֲמֹד, וְזֶהוּ וַיְכַס אֶת עֵין כָּל הָאָרֶץ, וְכָאן כָּתוּב וַיְכַס אֶת עֵין הָאָרֶץ, וְכָךְ הוּא וַדַּאי."],[3,"","אָמַר רַבִּי אַבָּא, בָּלָק וּבִלְעָם לֹא הָיוּ בָעוֹלָם מְכַשְּׁפִים וְקוֹדְמִים כְּמוֹתָם. (בלעם), חֵילוֹ וְכֹחוֹ הָיָה בְּפִיו וְעֵינוֹ. בָּלָק, חֵילוֹ וְכֹחוֹ הָיָה בְּמַעֲשֵׂה יָדַיִם. וְזֶה צָרִיךְ אֶת זֶה, שֶׁהֲרֵי כָּל סוּגֵי הַכְּשָׁפִים שֶׁל הָעוֹלָם, בַּפֶּה וּבְמַעֲשֶׂה הוּא, וּבָהֶם תְּלוּיִים. לְבִלְעָם הָיָה לָשׁוֹן וְלֹא יָדַיִם, לְבָלָק הָיוּ יָדַיִם וְלֹא לָשׁוֹן."],[4,"","הָלְכוּ הַחֲבֵרִים עַד שֶׁהִגִּיעוּ לְשָׂדֶה אַחַת, וְהַשֶּׁמֶשׁ הָיְתָה חֲזָקָה מְאֹד. רָאוּ אֶת אוֹתוֹ בֵּית הַשָּׂדֶה בִּיפִי הָעֲשָׂבִים, וּמַיִם יוֹצְאִים לְכָל צַד וַעֲצֵי הַשָּׂדֶה רַבִּים. יָשְׁבוּ שָׁם. אָמַר רַבִּי אֶלְעָזָר, כַּמָּה נָאֶה מָקוֹם זֶה לָנוּחַ בּוֹ."],[5,"","עַד שֶׁיָּשְׁבוּ הֲרֵי נָחָשׁ גָּדוֹל בָּא בְּחֹזֶק הַשֶּׁמֶשׁ וְעָבַר לִפְנֵיהֶם. אָמַר לוֹ רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, סְטֵה לְךְ מִדַּרְכְּךְ, שֶׁהֲרֵי שָׁב אוֹתוֹ הָאִישׁ וְהִתְנַחֵם עַל מַה שֶּׁעָשָׂה וְלֹא יוֹסִיף לַעֲשׂוֹת אוֹתוֹ הַדָּבָר. תָּמְהוּ הַחֲבֵרִים. אָמַר רַבִּי אַבָּא, מַהוּ? אָמַר לָהֶם, שִׁתְקוּ. אָמַר רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, לְאַחַר שֶׁלָּחֲשׁוּ לְךְ מֵהַשָּׁמַיִם, הִתְנַחֵם אוֹתוֹ הָאִישׁ וְשָׂם בִּרְצוֹנוֹ שֶׁלֹּא יָשׁוּב בּוֹ לְעוֹלָמִים, סְטֵה לְךְ מִדַּרְכְּךְ. עָמַד הַנָּחָשׁ עַל עָמְדוֹ, וְלֹא לָקַח לְכָאן וּלְכָאן. שָׁב כְּמוֹ מִקֹּדֶם. אָמַר לוֹ, נָחָשׁ נָחָשׁ, יָדַעְתִּי מַה שֶּׁאַתָּה רוֹצֶה, שׁוּב מִדַּרְכְּךְ, שֶׁהֲרֵי גּוֹי רָשָׁע בָּא שֶׁעָשָׂה רַע לִיהוּדִי אֶחָד, וַהֲרֵי הוּא יָשֵׁן שׁוֹכֵב בַּמְּעָרָה שֶׁלְּךְ, לֵךְ וְהָרְגֵהוּ. מִיָּד חָזַר אוֹתוֹ הַנָּחָשׁ וְדִלֵּג דִּלּוּגִים לִפְנֵיהֶם."],[6,"","אָמַר רַבִּי אֶלְעָזָר, אִם לֹא הָיִיתִי פֹּה, כַּמָּה רָעוֹת הָיָה עוֹשֶׂה הַנָּחָשׁ הַזֶּה, שֶׁהֲרֵי אָדָם יְהוּדִי אֶחָד עָשָׂה מַעֲשֶׂה שֶׁל חֵטְא, וְעַד שֶׁלֹּא שָׁב בִּתְשׁוּבָה לָחֲשׁוּ לַנָּחָשׁ הַזֶּה לַהֲרֹג אוֹתוֹ, וְנִמְלַךְ אוֹתוֹ הָאִישׁ בֵּין כָּךְ וּבֵין כָּךְ, וְהִתְנַחֵם מֵחֶטְאוֹ, וְאָמַר שֶׁלֹּא יָשׁוּב לְעוֹלָמִים לְאוֹתוֹ הַחֵטְא, וְעַל כָּךְ נִצּוֹל מִן הַדִּין."],[7,"","אָמְרוּ הַחֲבֵרִים לְרַבִּי אֶלְעָזָר, בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, סִימָן נָתַן לִי אַבָּא, וַאֲנִי יוֹדֵעַ אוֹתוֹ. אָמַר לוֹ, מֵילָא הַנָּחָשׁ שֶׁיָּדַעְתָּ בּוֹ, אוֹתוֹ שֶׁהִתְנַחֵם וְשָׁב מֵחֶטְאוֹ בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, כְּשֶׁהָיָה הוֹלֵךְ אוֹתוֹ הַנָּחָשׁ, הַקַּשְׂקַשִּׂים שֶׁלּוֹ הָיוּ עוֹלִים וּזְנָבוֹ זָקוּף, וְהוּא שֶׁהוֹלֵךְ (הולך) בִּבְהִילוּת, רוּחַ אַחַת הָיְתָה הוֹלֶכֶת כְּנֶגְדּוֹ וְקוֹרֵאת לְפָנָיו: שׁוּב מִדַּרְכְּךְ, שֶׁהֲרֵי שָׁב מֵחֶטְאוֹ וְהִתְנַחֵם אוֹתוֹ הָאִישׁ. וְאוֹתוֹ הַנָּחָשׁ הָרַע לֹא הָיָה מְצַיֵּת עַד שֶׁיִּתְּנוּ לוֹ כֹּפֶר אִתּוֹ בִּמְקוֹם אוֹתוֹ אָדָם שֶׁהִתְחַיֵּב מִיתָה וְשָׁב. שֶׁכָּךְ דֶּרֶךְ הַנָּחָשׁ לְמַעְלָה וּלְמַטָּה - כֵּיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת, לֹא שָׁב עַד שֶׁהִשְׁלִים אוֹתוֹ הַדִּין הָרַע שֶׁנִּתְּנָה לוֹ רְשׁוּת לַעֲשׂוֹת, אוֹ שֶׁיִּתְּנוּ לוֹ בִּמְקוֹמוֹ רָשָׁע אַחֵר בְּכֹפֶר, שֶׁהֲרֵי בְּרֵיקָנוּת הוּא לֹא יֵצֵא, כֵּיוָן שֶׁנִּתְּנָה לוֹ רְשׁוּת."],[8,"","אָמְרוּ לוֹ, מֵילָא כָּל זֶה, אוֹתוֹ גּוֹי שֶׁאָמַרְתָּ שֶׁנָּתַתָּ לוֹ כֹּפֶר בַּמֶּה יָדַעְתָּ? אָמַר לָהֶם, כֵּיוָן שֶׁדִּבַּרְתִּי לַנָּחָשׁ, אוֹתוֹ רוּחַ שֶׁהָיְתָה כְּנֶגְדּוֹ וְלוֹחֶשֶׁת לוֹ שֶׁיָּשׁוּב לְדַרְכּוֹ, שֶׁהֲרֵי אוֹתוֹ אָדָם הִתְנַחֵם, דִּלְּגָה אוֹתָהּ רוּחַ עַל אָזְנוֹ (אזני ואמרה לי)."],[9,"","תָּמְהוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, נֵלֵךְ וְנִרְאֶה, שֶׁהֲרֵי הַנָּחָשׁ עָשָׂה מַה שֶּׁעָשָׂה. קָמוּ וְקָרְבוּ לְסֶלַע אֶחָד בְּאוֹתוֹ בֵּית שָׂדֶה, וּמָצְאוּ אוֹתוֹ הַגּוֹי מֵת וְאוֹתוֹ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ, וְלֹא הָיָה נִבְדָּל מִמֶּנּוּ. וְאַחַר כָּךְ נִפְרַד מֵעֲקֵבוֹ וְעָלָה עַל גְּרוֹנוֹ וְנִכְרַךְ שָׁם, וּמִשָּׁם הָיָה יוֹרֵד עַל עֲקֵבוֹ, שֶׁלֹּא הָיָה נִפְרָד מִמֶּנּוּ."],[10,"","מָצְאוּ לוֹ אַרְנָק אֶחָד מָלֵא דִינָרִים שֶׁגָּזַל מִיהוּדִי אֶחָד בַּדֶּרֶךְ וְהִכָּה אוֹתוֹ. לָקַח רַבִּי אֶלְעָזָר אֶת הָאַרְנָק. אָמַר, בָּרוּךְ הָרַחֲמָן שֶׁבַּכֹּל הוּא עוֹשֶׂה שְׁלִיחוּת. שָׁבוּ לְאוֹתוֹ מָקוֹם שֶׁהָיוּ (הולכים)."],[11,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, מֵאֲשֶׁר יָקַרְתָּ בְעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךְ וְאֶתֵּן אָדָם תַּחְתֶּיךְ וּלְאֻמִּים תַּחַת נַפְשֶׁךְ (ישעיה מג). מֵאֲשֶׁר יָקַרְתָּ?! יָקָר צָרִיךְ לוֹ לִכְתֹּב! וְכָךְ צָרִיךְ: מֵאֲשֶׁר אַתָּה יָקָר בְּעֵינַי. מַהוּ יָקַרְתָּ? מִכְּלָל שֶׁהוּא מֵעַצְמוֹ הִתְכַּבֵּד, אֶלָּא כָּךְ הוּא בְּוַדַּאי. שֶׁכָּל בֶּן אָדָם שֶׁהוּא בְּחִיּוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּהַתְחָלָה הוּא מְזֻלְזָל וּמְתֹעָב (תועבה) לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר שֶׁנִּמְלַךְ וְשָׁב מֵחֶטְאוֹ, עַכְשָׁו הוּא הִתְכַּבֵּד מֵעַצְמוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו וְאוֹמֵר, מֵאֲשֶׁר יָקַרְתָּ בְעֵינַי נִכְבַּדְתָּ. אַתָּה מֵעַצְמְךְ נִכְבַּדְתָּ."]]],[["בְּעֵינָי נִכְבָּדְתָּ וַאֲנִי אָהַבְתִּיךָ. דְּהָא לֵית רְחִימוּ לְקוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵי בַּר נָשׁ בְּהַאי עַלְמָא, אֶלָּא בְּמָאן דְּתָב מֵחוֹבֵיהּ. וְעַל דָּא אֲנִי אָהַבְתִּיךָ. אֲבָל מָה אַעֲבִיד דְּהָא יַהֲבִית רֵשׁוּ לְחִוְיָא לְנָזְקַא. דָא הוּא עֵיטָא, וָאֶתֵּן אָדָם תַחְתֶּיךָ. מַאי אִיהוּ אָדָם דִּיהַב קוּדְשָׁא בְּרִיךְ הוּא תְּחוֹתֵיהּ, הַהוּא אָדָם דְּאָתֵי מֵעַמָּא אַחֲרָא, דְּהַהוּא חִוְיָא מִדִּילֵיהּ יֵיכוּל, דִּכְתִיב וָאֶתֵּן אָדָם. אַל תִּקְרֵי אָדָם, אֶלָּא אֱדוֹם. וּלְאֻמִּים דָא הוּא, לְאוֹם מִלְאוֹם יֶאֱמָץ, וְדָא זַרְעָא דְעֵשָׂו דְּיָהִיב תֵחוֹת נַפְשֵׁיהּ.","אַדְהֲווֹ יַתְבֵי, הַא הַאי יוּדָאי דְּגָזַל הַהוּא גּוֹי דְּקָטַל חִוְיָא, אֲתָא בְּאוֹרְחָא לָאֵי וְעַיֵף. וּמִגּוֹ תַּקִּיפוּ דְשִׁמְשָׁא עֲאל בְּהַהוּא חֲקַל וְיָתִיב תְחוֹת אִילָנָא חַד, וְהָוָה מִתְרָעֵם לְקוּדְשָׁא בְּרִיךְ הוּא, וּמָצְדִּיק עָלֵיהּ דִּינָא, וְאָמַר. מָארֵיהּ דְּעָלְמָא, גָּלוּי ויָדוּעַ קַמָּךְ דְּאֲנָא לָא חַיִּישְׁנָא עֲלַי וְעַל גּוּפִי וְעַל מָמוֹנִי כְּלוּם, דְּהָא בְּדִינָא אִתְעֲבִיד כָּל (מה) דְּאִתְעֲבִיד. אֲבָל אַבָּא וְאִימָא סָבִין אִית לִי דְּלֵית לִי בְּמָּה אַפָרְנֵס לוֹן, וְעַל דָּא חַיִּישְׁנָא.","וְתוּ עַל כָּל דָא, צְרוֹרָא חֲדָא דְּדִינָרִין דְהָוָה בְּהַהוּא אַרְנָקִי דְּחַד מִסְכְּנָא לְמֶעְבַּד חוּפָּה לִבְרַתֵּיהּ עַנְיָיא. מָה אַעֲבִיד מָארֵי דְּעָלְמָא, עַל דָּא כַּאִיבְנָא בְּלִבָּאי יַתִּיר.","בָּכָה וְאָמַר (תהלים קי\"ט) מִשְׁפָּטֵי ה' אֶמֶת צָדְקוּ יַחְדָּיו. דִּינִין דְמָארֵי עַלְמָא, קְשׁוֹט אִינוּן. אֲמַאי אִינוּן קְשׁוֹט, בְּגִין דְּצָדְקוּ יַחְדָּיו. דְּהָא בְּשַׁעֲתָא דְּדִינָא דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְמֶעְבַּד (דינא), כַּמָה מָארֵי תְרִיסִין קַיְימִין מֵהַאי סְטָר וּמֵהָאי סְטָר וּמָצְדִיקִין אִלֵּין בְּאִלֵּין וּמַגִּיחִין אִלֵּין בְּאִלֵּין. כֵּיוָן דְּצָדְקוּ אִלֵּין בְּאִלֵּין ואִסְתָּכְּמָן כַּחֲדָא, כְּדֵין מִשְׁפָּטֵי ה' אֶמֶת. אֵימָתַי צָדְקוּ יַחְדָּיו. כַּד מַצְדִיקֵי כָּל בְּנֵי דִּינָא לְעֵילָא. וְעַל דָּא מָארֵי דְּעָלְמָא, עַל דָּא בַּכֵינָא וְלֹא עַל דִידִי.","שָׁמַע ר' אֶלְעָזָר וְחַבְרַיָּיא וְקָמוּ לְגַבֵּיהּ. חָמוּ יָתֵיהּ דְהָוָה יָתִיב תְחוֹת הַהוּא אִילָנָא וְאַתְקִיפוּ בֵּיהּ וּנְטָלוּ יָתֵיהּ לְגָּבֵּיהוֹן. אָמַר רַבִּי אֶלְעָזָר, (לא תדחל) זַכָּאָה קְשׁוֹט, דְּאִי לָאו זַכָּאָה אֲנְתְּ, לָא יַרְחִישׁ לָךְ קוּדְשָׁא בְּרִיךְ הוּא נִיסָא רַבְרְבָא כְּמָה דְּעָבַד. בְּקַדְמִיתָא טוֹל אַרְנָקִי דִּילָךְ וְתֵּיזִיל וְתֵחְמֵי מָה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינָךְ. אֲזָל בַּהֲדַיְיהוּ וְחָמָא הַהוּא גּוֹי מִית וְחִוְיָא הֲוָה עֲבִיד בֵּיהּ נוּקְמִין וְהָוָה כְּרִיךְ עַל קַדְלֵיה. אִשְׁתַּטַּח הַהוּא יוּדָאי בְּעַפְרָא ואוֹדֵי וְשַׁבַּח לְמָארֵי עַלְמָא. וְקָם ונָשִׁיק יְדוֹי דְּרִבִּי אֶלְעָזָר וְחַבְרַיָּיא. אָמַר לוֹן הַשְׁתָּא יָדַעְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ נִיסָא דָא בְּגִּינָיְיכוּ.","אֲבָל רָבַּנָן, עַל אַבָּא וְאִימָא סָבִין דְּאִית לִי בַּכֵינָא וְעַל מִסְכֵּנָא דְּיַהִיב לִי צְרוֹרָא. פָּתַח הַאָרְנָקִי וְאֲחְמֵי לוֹן צְרוֹרָא וְכֵן אֲחְמֵי לוֹן מָחָא דְּעָבַד לֵיהּ הַהוּא גּוֹי. צַלֵּי רַבִּי אֶלְעָזָר עָלֵיהּ וְאִתְּסֵי.","קְרִיבוּ לְגַבֵּיהּ דְּהַהוּא גּוֹי כְּמִלְקַדְמִין, וְחָמוּ הַהוּא חִוְיָא דְהָוָה עֲבִיד כְּדְבְּקַדְמִיתָא. אָמַר רַבִּי אֶלְעָזָר, חִוְיָא כָּל מָה דְעַבָדְתְּ יֵאוֹת עֲבַדְתְּ. וְתוּ דְּאַחְמִית חֵילָךְ וּגְבוּרְתָךְ בֵּיהּ, וְעֲבְדָתְּ בֵּיהּ נוּקְמִין סַגִּיאִין. וְהָא חֲמֵינָן תְלַת זִמְנִין ואַחְמִית כָּל מָה דְּעֲבַדְתְּ. מִכָּאן וּלְהָלְאָה זִיל ואִתְטָמָר בִּמְעַרְתָךְ, וְגָּזָרְנָא עֲלָךְ דְּלָא תַנְזִיק לְבִרְיָיתָא דְּעָלְמָא. אִתְפְּרַשׁ הַהוּא חִוְיָא וְכַפָף רֵישֵׁיהּ וְאָזַל לֵיהּ.","אָמַר רַבִּי אֶלְעָזָר לְהַהוּא יוּדָאי, טוֹל עֲדָאָה דְשָׂנְאָךְ. דְּהָא כִּיסָא דְּדַהֲבָא אִית לֵיהּ לְגַבֵּיהּ דְשָׁבָק לֵיהּ בְּרֵיהּ דְּהַהוּא גּוֹי לְאָבוֹי, וְלָא תִיטוֹל מִדִּילֵיהּ כְּלוּם. וְזִיל לְגַבֵּיהּ גַּבְרָא דְּדוּךְ פְּלַן, וְתִשְׁכַּח דְּמִיתָא אִתְתֵּיהּ. זִיל לְגַבֵּיהּ וְהַב לֵיהּ כִּיסָא דְּדִינָרִין דָא, בְּגִין דְּהַהוּא גַּבְרָא אִית לֵיהּ בְּרָא חַד ושִׁמְעוֹן שְׁמֵיהּ וְהוּא אָזִיל בִּסְחוֹרָתָא עַל יַמָּא. ואִינוּן בְּאֲרְבָּא, בְּרֵיהּ דְּהַאי גּוֹי גָּנָב לֵיהּ הַאי כִּיסָא, וְיָהַב לֵיהּ לְהַהוּא רָשָׁע. וְאֵימָא לְהַהוּא יוּדָאי דְּיַסְלִיק כִּיסָא דָא לִבְרֵיהּ, דְּלַעֲגָּל יֵיתֵי לְגַבֵּיהּ, ויוֹדֵי לְקוּדְשָׁא בְּרִיךְ הוּא דְּאַחְזַר אַבֵידַתָא לְמָארֵיהּ. וְכַךְ עֲבִיד, נָטַל כִּיסָא וְסָגִיד קָמֵיהּ דְרִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי, תַּוְוהוּ חַבְרַיָּיא.","אָמַר רַבִּי אַבָּא, בְּכָל אוֹרְחָא דָא אִיהוּ תַוְוהָא בְּכָל מָה דְחַמִינָן בָּךְ. וְהַשְׁתָּא אִיהוּ תַוְוהָא עַל תַוְוהָא, מָהוּ דֵין. אָמַר לְהוּ, מִלָּה דָא, לָאו בְּסִימָנָא אִיהִי, וְלָאו בְּחָכְמָתָא. אֶלָּא רוּחָא דִילִי אִסְתָּכַל וַאֲנָא חֲמֵינָא כְּאִילוּ בְּעֵינָא חֲמֵינָא. תַּוְוהוּ כּוּלְּהוּ חַבְרַיָּיא, אַזְלוּ כּוּלְּהוּ חַבְרַיָּיא וְהַהוּא יוּדָאי בַּהֲדַיְיהוּ. עַד דְּמָטוּ לְגַבֵּיהּ חַמוֹי. כֵּיוָן דְּמָטוּ לְתַּמָּן, אַשְׁכְּחוּהוּ לְחַמוֹי דְהָוָה יָתִיב עַל גַּבֵּי עֲרְסוֹי וְלָעֵי בְּאוֹרַיְיתָא. בָּרִיךְ בִּרְכָתָא רַבִּי אֶלְעָזָר, וּבְרִיכוּ חַבְרַיָּיא ואִיהוּ חַדֵּי בַּהֲדַיְיהוּ:","פָּתַח רַבִּי אֶלְעָזָר ואָמַר, (ירמיהו י״ז:י״ד) רְפָאֵנִי ה' ואֶרָפֵא הוֹשִׁיעֵנִי וְאִוָשֵׁעָה. כֵּיוָן דְּאָמַר רְפָאֵנִי ה', מָהוּ ואֶרָפֵא. כֵּיוָן דְּאָמַר הוֹשִׁיעֵנִי, מָהוּ ואִוָשֵׁעָה. כֵּיוָן דְּאַסְיָא מַסֵי, מַאן הוּא דְמָחֵי.","אֶלָּא (נ\"א אמר רבי יוסי חמוי), כָּל אַסְוָותָא דְּעָלְמָא בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֲבָל אִית מִנְהוֹן עַל יְדָא דִשְׁלִיחַא ואִית מִנְהוֹן דְּלָא אִתְמְסָרוּ בִּידָא דִשְׁלִיחַא. וְאִינוּן דְּאִתְמַסְרוּ בִּידָא דִשְׁלִיחַא אַסְוָותָא אִינוּן, אֲבָל לְזִמְנִין מִתְהַדְרָן. אֲבָל אִינוּן דְקוּדְשָׁא בְּרִיךְ הוּא מַסֵי, לָא מִתְהַדְרָן לְעָלְמִין, וְעַל דָּא אַסְוָותָא דִּילֵיהּ אִיהִי אַסְוָותָא דְּלֵית בָּהּ מַרְעָא כְּלָל. וּבְגִין כָּךְ, רְפָאֵנִי ה' וְאֶרָפֵא, וְדָא בְּלָא קִטְרוּגָא כְּלָל. וְהַשְׁתָּא חַבְרַיָּא, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לִי אַסְוָותָא וְעָשָׁק לִי וְעַרָב לִי."],[],[[0,"","בְעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךְ. שֶׁהֲרֵי אֵין אַהֲבָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא עִם הַבֶּן אָדָם בָּעוֹלָם הַזֶּה אֶלָּא בְּמִי שֶׁשָּׁב מֵחֶטְאוֹ, וְעַל זֶה אֲנִי אֲהַבְתִּיךְ, אֲבָל מָה אֶעֱשֶׂה שֶׁהֲרֵי נָתַתִּי רְשׁוּת לַנָּחָשׁ לְהַזִּיק? זוֹהִי הָעֵצָה - וְאֶתֵּן אָדָם תַּחְתֶּיךְ. מַהוּ אָדָם שֶׁנָּתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תַּחְתָּיו? אוֹתוֹ אָדָם שֶׁבָּא מֵעַם אַחֵר, שֶׁאוֹתוֹ נָחָשׁ יֹאכַל מִשֶּׁלּוֹ, שֶׁכָּתוּב וְאֶתֵּן אָדָם, אַל תִּקְרֵי אָדָם אֶלָּא אֱדוֹם. וּלְאֻמִּים, זֶהוּ (בראשית כה) לְאֹם מִלְאֹם יֶאֱמָץ, וְזֶה זֶרַע עֵשָׂו שֶׁנָּתַן תַּחַת נַפְשׁוֹ."],[1,"","עַד שֶׁיָּשְׁבוּ הֲרֵי הַיְּהוּדִי הַזֶּה שֶׁאוֹתוֹ הַגּוֹי גָּזַל וְהַנָּחָשׁ הֲרָגוֹ, בָּא בַדֶּרֶךְ לֵאֶה וְעָיֵף, וּמִתּוֹךְ חֹזֶק הַשֶּׁמֶשׁ נִכְנַס בְּאוֹתוֹ שָׂדֶה וְיָשַׁב תַּחַת עֵץ אֶחָד, וְהָיָה מִתְרַעֵם לַקָּדוֹשׁ-בָּרוּךְ-הוּא וּמַצְדִּיק עָלָיו אֶת הַדִּין וְאוֹמֵר: רִבּוֹן הָעוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךְ שֶׁאֵינִי חוֹשֵׁשׁ עָלַי וְעַל גּוּפִי וְעַל מָמוֹנִי כְּלוּם, שֶׁהֲרֵי בְּדִין נַעֲשָׂה כָּל (מה) שֶׁנַּעֲשָׂה, אֲבָל אָב וָאֵם זְקֵנִים יֵשׁ לִי, שֶׁאֵין לִי בַּמָּה אֲפַרְנֵס אוֹתָם, וְעַל זֶה חָשַׁשְׁתִּי."],[2,"","וְעוֹד עַל כָּל זֶה - צְרוֹר אֶחָד שֶׁל דִּינָרִים שֶׁהָיָה בְּאוֹתוֹ הָאַרְנָק, שֶׁל עָנִי אֶחָד לַעֲשׂוֹת חֻפָּה לְבִתּוֹ הָעֲנִיָּה, מָה אֶעֱשֶׂה? רִבּוֹן הָעוֹלָם, עַל זֶה כּוֹאֲבַנִי בְּלִבִּי יוֹתֵר."],[3,"","בָּכָה וְאָמַר, (תהלים יט) מִשְׁפְּטֵי ה' אֱמֶת צָדְקוּ יַחְדָּו. דִּינָיו שֶׁל רִבּוֹן הָעוֹלָם הֵם אֱמֶת. לָמָּה הֵם אֱמֶת? מִשּׁוּם שֶׁצָּדְקוּ יַחְדָּו. שֶׁהֲרֵי בִּשְׁעַת הַדִּין, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לַעֲשׂוֹת (דין), כַּמָּה בַּעֲלֵי מָגִנִּים עוֹמְדִים מִצַּד זֶה וּמִצַּד זֶה, וּמַצְדִּיקִים אֵלּוּ בְאֵלּוּ, וְנִלְחָמִים אֵלּוּ בְאֵלּוּ. כֵּיוָן שֶׁצָּדְקוּ אֵלּוּ בְאֵלּוּ וְהִסְכִּימוּ כְאֶחָד, אֲזַי מִשְׁפְּטֵי ה' אֱמֶת. אֵימָתַי צָדְקוּ יַחְדָּו? כְּשֶׁמַּצְדִּיקִים כָּל בְּנֵי הַדִּין שֶׁלְּמַעְלָה. וְעַל זֶה, רִבּוֹן הָעוֹלָם, אֲנִי בּוֹכֶה, וְלֹא עַל שֶׁלִּי!"],[4,"","שָׁמַע רַבִּי אֶלְעָזָר וְהַחֲבֵרִים, וְקָמוּ אֵלָיו. רָאוּ אוֹתוֹ שֶׁהָיָה יוֹשֵׁב תַּחַת אוֹתוֹ הָעֵץ, וְהֶחֱזִיקוּ בוֹ, וְנָטְלוּ אוֹתוֹ אֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר, (אל תפחד) צַדִּיק אֱמֶת, שֶׁאִם אֵינְךְ צַדִּיק, לֹא יַרְחִישׁ לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס גָּדוֹל כְּמוֹ שֶׁעָשָׂה. בָּרִאשׁוֹנָה טֹל אַרְנָקְךְ, וְתֵלֵךְ וְתִרְאֶה מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלָלְךְ. הָלַךָ עִמָּם, וְרָאָה אוֹתוֹ הַגּוֹי מֵת, וְהַנָּחָשׁ הָיָה עוֹשֶׂה בּוֹ נְקָמוֹת, וְהָיָה כָּרוּךְ עַל צַוָּארוֹ. הִשְׁתַּטַּח אוֹתוֹ הַיְּהוּדִי בֶּעָפָר, וְהוֹדָה וְשִׁבַּח אֶת רִבּוֹן הָעוֹלָם, וְקָם וְנָשַׁק יְדֵי רַבִּי אֶלְעָזָר וְהַחֲבֵרִים. אָמַר לָהֶם: כָּעֵת יָדַעְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִרְחִישׁ נֵס זֶה בִּגְלַלְכֶם."],[5,"","אֲבָל חֲכָמִים, עַל הָאָב וְהָאֵם הַזְּקֵנִים שֶׁיֵּשׁ לִי אֲנִי בּוֹכֶה, וְעַל הֶעָנִי שֶׁנָּתַן לִי אֶת הַצְּרוֹר. פָּתַח הָאַרְנָק וְהֶרְאָה לָהֶם אֶת הַצְּרוֹר, וְכֵן הֶרְאָה לָהֶם הַמַּכָּה שֶׁעָשָׂה לוֹ אוֹתוֹ הַגּוֹי. הִתְפַּלֵּל עָלָיו רַבִּי אֶלְעָזָר, וְנִרְפָּא."],[6,"","קָרְבוּ לְאוֹתוֹ הַגּוֹי כְּמִקֹּדֶם, וְרָאוּ אוֹתוֹ הַנָּחָשׁ שֶׁהָיָה עוֹשֶׂה בּוֹ כְּבָרִאשׁוֹנָה. אָמַר רַבִּי אֶלְעָזָר, נָחָשׁ נָחָשׁ, כָּל מַה שֶּׁעָשִׂיתָ - נָאֶה עָשִׂיתָ, וְעוֹד שֶׁהֶרְאֵיתָ כֹּחֲךְ וּגְבוּרָתְךְ בּוֹ וְעָשִׂיתָ בּוֹ נְקָמוֹת רַבּוֹת, וַהֲרֵי רָאִינוּ שָׁלֹשׁ פְּעָמִים, וְהֶרְאֵיתָ כָּל מַה שֶּׁעָשִׂיתָ. מִכָּאן וָהָלְאָה לֵךְ וְהִתְחַבֵּא בִּמְעָרָתְךְ, וְגוֹזְרַנִי עָלֶיךְ, שֶׁלֹּא תַזִּיק לִבְרִיָּה בָּעוֹלָם. נִפְרַד אוֹתוֹ הַנָּחָשׁ, וְכָפַף רֹאשׁוֹ וְהָלַךְ לוֹ."],[7,"","אָמַר רַבִּי אֶלְעָזָר לְאוֹתוֹ הַיְּהוּדִי: טֹל אֶת תַּכְשִׁיט שׂוֹנַאֲךְ, שֶׁהֲרֵי כִּיס שֶׁל זָהָב יֵשׁ לוֹ אֶצְלוֹ שֶׁהִשְׁאִיר לוֹ בְּנוֹ שֶׁל אוֹתוֹ גּוֹי לְאָבִיו, וְאַל תִּטֹּל מִשֶּׁלּוֹ כְּלוּם, וְלֵךְ לָאִישׁ שֶׁבְּמָקוֹם פְּלוֹנִי, וְתִמְצָא שֶׁמֵּתָה אִשְׁתּוֹ. לֵךְ אֵלָיו, וְתֵן לוֹ כִּיס הַדִּינָרִים הַזֶּה, מִשּׁוּם שֶׁלְּאוֹתוֹ הָאִישׁ יֵשׁ בֵּן אֶחָד, וּשְׁמוֹ שִׁמְעוֹן, וְהָיָה הוֹלֵךְ עִם סְחוֹרָה עַל הַיָּם, וְהֵם בַּסְּפִינָה, וּבְנוֹ שֶׁל הַגּוֹי הַזֶּה גָּנַב לוֹ אוֹתוֹ הַכִּיס וְנָתַן אוֹתוֹ לְאוֹתוֹ רָשָׁע. וֶאֱמֹר לְאוֹתוֹ הַיְּהוּדִי שֶׁיַּעֲלֶה כִיס זֶה לִבְנוֹ, שֶׁבִּמְהִירוּת יֵלֵךְ אֵלָיו, וְיוֹדֶה לַקָּדוֹשׁ-בָּרוּךְ- הוּא שֶׁהֶחֱזִיר אֲבֵדָה לִבְעָלָיו. וְכָךְ עָשָׂה. נָטַל הַכִּיס, וְהִשְׁתַּחֲוָה לִפְנֵי רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. תָּמְהוּ הַחֲבֵרִים."],[8,"","אָמַר רַבִּי אַבָּא, בְּכָל הַדֶּרֶךְ הַזּוֹ יֵשׁ תְּמִיהָה בְּכָל מַה שֶּׁרָאִינוּ בְּךְ, וְכָעֵת הִיא תְמִיהָה עַל תְּמִיהָה, מַה זֶּה? אָמַר לָהֶם: דָּבָר זֶה אֵינוֹ בְסִימָן הוּא וְלֹא בְחָכְמָה, אֶלָּא שֶׁרוּחִי מִסְתַּכֵּל, וַאֲנִי רָאִיתִי כְּאִלּוּ בָּעַיִן רָאִיתִי. תָּמְהוּ כָּל הַחֲבֵרִים. הָלְכוּ כָּל הַחֲבֵרִים וְאוֹתוֹ הַיְּהוּדִי עִמָּהֶם, עַד שֶׁהִגִּיעוּ לְחָמִיו. כֵּיוָן שֶׁהִגִּיעוּ לְשָׁם, מָצְאוּ אֶת חָמִיו שֶׁהָיָה יוֹשֵׁב עַל גַּבֵּי מִטָּתוֹ וְעוֹסֵק בַּתּוֹרָה. בֵּרַךְ בְּרָכָה רַבִּי אֶלְעָזָר, וּבֵרְכוּ הַחֲבֵרִים, וְהוּא שָׂמַח עִמָּם."],[9,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (ירמיה יז) רְפָאֵנִי ה' וְאֵרָפֵא הוֹשִׁיעֵנִי וְאִוָּשֵׁעָה. כֵּיוָן שֶׁאָמַר רְפָאֵנִי ה', מַהוּ וְאֵרָפֵא? כֵּיוָן שֶׁאָמַר הוֹשִׁיעֵנִי, מַהוּ וְאִוָּשֵׁעָה? כֵּיוָן שֶׁהָרוֹפֵא מְרַפֵּא, מִי הוּא שֶׁיַּכֶּה?"],[10,"","אֶלָּא (אמר רבי יוסי חמיו), כָּל רְפוּאָה שֶׁבָּעוֹלָם בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל יֵשׁ מֵהֶם עַל יְדֵי שָׁלִיחַ, וְיֵשׁ מֵהֶם שֶׁלֹּא נִמְסְרוּ בְּיַד שָׁלִיחַ. וְאוֹתָם שֶׁנִּמְסְרוּ בְּיַד שָׁלִיחַ הֵם רְפוּאָה, אֲבָל לִפְעָמִים חוֹזְרִים. אֲבָל אוֹתָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַפֵּא לֹא חוֹזְרִים לְעוֹלָמִים, וְעַל זֶה רְפוּאָתוֹ הִיא רְפוּאָה, שֶׁאֵין בָּהּ חֹלִי כְּלָל. וּמִשּׁוּם כָּךְ רְפָאֵנִי ה' וְאֵרָפֵא, וְזֶה בְּלִי קִטְרוּג כְּלָל. וְכָעֵת, חֲבֵרִים, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לִי רְפוּאָה, וְעָשַׁק לִי וְעָרַב לִי."]]],[["סָחוּ לֵיהּ כָּל הַהוּא עוֹבָדָא תָּוָוה וּבָכָה וְחַדֵּי. אָמַר, חַבְרַיָּיא נָדַרְנָא דְּאֵיהַךְ לְגַבֵּיהּ ואִתְחַבָּר בַּהֲדֵיהּ, ונוֹדֵי וּנְשָׁבָּח לְמָארֵי עַלְמָא. חַדֵּי בַּהֲדַיְיהוּ.","אָמְרוּ לֵיהּ, בְּמָאי הֲוִיתָא מִתְעַסֵּק. אָמַר לוֹן בְּפָרָשַׁת בָּלָק הֲוִינָא מִתְעַסֵּק וְחֲמֵינָא דְחָכְמְתָא דִּילֵיהּ, הֲוָה תַקִּיף וְיַתִּיר מֵחָכְמָתָא דְּבִּלְעָם. חָכְמָתָא דְּבִּלְעָם רִגְעָא חֲדָא, חָכְמָתָא דְּבָּלָק בְּכָל זִמְנָא. אֲבָל מַפְתְּחָן כֻּלְּהוּ בִּידוֹי דְּבִּלְעָם הֲוִי, דְּאִיהוּ הֲוָה שְׁלִים בְּפוּמָא. בָּלָק הֲוָה יָדַע לְמֶעְבַּד חַרְשׁוֹי, וְלָא הֲוָה יָדַע לְאַשְׁלָמָא בְּפוּמָא.","פָּתַח וְאָמַר, (ירמיהו ל׳:י׳) ואַתָּה אַל תִירָא עַבְדִּי יַעֲקֹב וְגוֹ'. הַאי קְרָא (אית לאסתכלא ביה) אוּקְמוּהָ. אֲבָל אַל תִירָא עַבְדִּי יַעֲקֹב מֵחַרְשׁוֹי דְּבִּלְעָם וְאַל תְּחַת מִקַסְמוֹי דְּבָּלָק.","תָּא חֲזֵי, הֵיךְ הֲווּ תַּרְוַיְיהוּ דָא בְּדָא בְּעֵיטָא בִּישָׁא לְקֳבֵּל יִשְׂרָאֵל. אָמַר בִּלְעָם, יַעֲקֹב בְּבֵיתָא דְלָבָן אַבָּא הֲוָה, וְנָחָשׁ נָחְשִׁין לָקֳבְּלֵיהּ, וְיָכִיל לֵיהּ. אֲנָא אֲסָדֵר נָחְשִׁין לָקֳבְּלֵיהּ. אָמַר בָּלָק, וַאֲנָא אֲסָדֵר קִסְמִין לִשְׁמָא דְּאִקְּרֵי יִשְׂרָאֵל.","בְּהַהִיא שַׁעֲתָא נָפַק רוּחָא חֲדָא מִסִטְרָא דְּיוֹסֵף מִגּוֹ עַנְפֵי אִילָנָא ונָשִׁיב בְּאִינוּן נְחָשִׁים וּבָטִיל לוֹן. וְהַיְינוּ דְּאָמַר יוֹסֵף (בראשית מ״ד:ט״ו) כִּי נָחֵשׁ יְנָחֵשׁ אִישׁ אֲשֶׁר כַּמוֹנִי. מַאי אִישׁ אֲשֶׁר כַּמוֹנִי, בְּגִינִי אִית אִישׁ דְּנְחַשִׁים יְבַטֵל לְבְּנָיְיכוּ, בְּגִינִי אִיהוּ לְעֵילָּא. וְהַיְינוּ אִישׁ אֲשֶׁר כַּמוֹנִי. אִית אִישׁ לְעֵילָּא דְּנָפַק רוּחָא אַחֲרָא מִגּוֹ אִילָנָא דִּלְתַתָּא ונָשִׁיב בְּהַהוּא קֶסֶם וּבָטִיל לוֹן.","וְהַיְינוּ קֶסֶם עַל שִׂפְתֵי מֶלֶךְ. מַאן מֶלֶךְ דָא, אִילָנָא דִּלְתַתָּא. כְּדֵין אֲתִּיב בִּלְעָם ואָמַר, כִּי לֹא נָחָשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, וְתַרְוַיְהוּ הֲווּ בִּתְרֵין סִטְרִין אִלֵּין.","כִּי אִתְּךָ אֲנִי, לָא הֲווּ יוֹמִין מִן יוֹמָא דְּאִתְבְּרֵיה עַלְמָא דְּאִיצְטְרִיךְ הָכִי לְמֶהֱוִי קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדַיְיהוּ דְּיִשְׂרָאֵל, כְּהַהוּא זִמְנָא דְּבָעָא בִּלְעָם לְשֵׁיצָאָה לְשַׂנְאֵיהוֹן דְּיִשְׂרָאֵל מֵעָלְמָא. וְעַל דָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, בִּלְעָם בָּעָא לְשֵׁיצָאָה לְכוּ מֵעָלְמָא, אֲבָל אֲנָא לָא אַעֲבִיד הָכִי. (ירמיהו ל׳:י״א) כִּי אֱעֶשֶׂה כַּלָּה בְּכָל הַגּוֹיִם אֲשֶׁר הִדַּחְתִּיךָ שָׁמָּה וְאוֹתְךָ לֹא אֱעֶשֶׂה כַלָּה. דְּאִילּוּ יֵיתוּן כָּל בְּנֵי עַלְמָא, לָא יֵיכְלוּן לְשֵיצָאָה לְכוֹן מֵעָלְמָא.","אֲתָא לָבָן בְּקַדְמִיתָא וּבְעָא לְאַעְקָרָא לֵיהּ לְיַעֲקֹב בִּלְחוֹדוֹי מֵעָלְמָא, אֲתָא קוּדְשָׁא בְּרִיךְ הוּא וַאָגִּין עָלֵיהּ. דִּכְתִיב (בראשית ל\"ג) הִשָׁמֶר לְךָ פֶּן תְּדַבֶּר עִם יַעֲקֹב מִטּוֹב עַד רַע. אֲתָא פַּרְעֹה וּבָעָא לְשֵיצָאָה לוֹן מֵעָלְמָא, אֲתָא קוּדְשָׁא בְּרִיךְ הוּא וַאָגִּין עֲלַיְיהוּ דִּכְתִיב, (שמות א׳:י״ב) וְכַאֲשֶׁר יֵעַנוּ אוֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרוֹץ. אֲתָא הָמָן וּבְעָא לְשֵׁיצָאָה לוֹן, אֲתָא קוּדְשָׁא בְּרִיךְ הוּא ואָגִּין עֲלַיְיהוּ וַאֲתִּיב כֹּלָּא עַל רֵישֵׁיהּ. וְכֵן בְּכָל דָרָא וְדָרָא קוּדְשָׁא בְּרִיךְ הוּא אַגִּין עֲלַיְיהוּ דְּיִשְׂרָאֵל תָּדִיר.","וְיִשְׂרָאֵל אַמְרֵי (איכה ג׳:כ״ב) חַסְדֵּי יְיָ כִּי לֹא תַמְנוּ כִּי לֹא כָלּוּ רַחֲמָיו. כִּי לֹא תַמוּ מִבָּעֵי לֵיהּ, אֶלָּא חַסְדֵּי יְיָ בְּכָל דָרָא וְדָרָא הֲווּ בְּסָעֲדָן, כִּי לֹא תַמְנוּ וְלָא אִשְׁתַצֵינָא. מַאי טַעְמָא, דְּלָא אִתְמֵנָעוּ רַחְמוֹי מִינָן, דִּכְתִיב כִּי לֹא כַלּוּ רַחֲמָיו.","תָּא חֲזֵי, מָה כְּתִיב בְּקַדְמִיתָא, וַיִשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֵּן בְּעוֹר. וּלְבָתַר כְּתִיב, וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן. הֲוָה לֵיהּ לְמֵימָר וַיָּבֹאוּ הַמַּלְאָכִים, מַאי טַעְמָא דְּקָא שָׁנֵי מִלָּה מִמַּאי דְּקָאָמַר בְּקַדְמִיתָא.","אֶלָּא הַהוּא רָשָׁע דְּבָּלָק חַכִּים הֲוָה בְּכָל דַּרְגִּין דִלְעֵילָּא אִינוּן דְּקַשְׁרִין קִשְׁרִין לְמֶעְבַּד בְּהוּ חַרְשִׁין וְקִסְמִין, וְכָל אִינוּן דַּרְגִּין עִילָאִין (מנייהו) מִלַיְיהוּ, דִּבְּהוּ כַּפְיָין לְדַּרְגִּין תַּתָּאִין.","אָמַר לֵיהּ, בְּכָל זִמְנָא דַּאֲנַן חַרְשִׁין וְקַסְמִין וְנָחְשִׁין אִית לָן דַּרְגִּין יְדִיעָאן וּמַלְאָכִין יְדִיעָאן דְּאִשְׁתְּמוֹדְעָן לְגַבֵּי חַרְשִׁין וְקַסְמִין. אֲבָל מִכָּאן וּלְהָלְאָה אִית לָךְ לְעַיְינָא בְּאֲתָר אַחֲרָא עִילָאָה.","כָּתַב לֵיהּ שְׁמָהָן אֲחַרָנִין בְּאִינוּן דַּרְגִּין קַדִּישִׁין, וְהָכִי אוֹרְחַיְיהוּ דְּקַסְמִין וְחַרְשִׁין, יַדְעֵי אִינוּן דַּרְגִּין דְּהַהוּא קֶסֶם שַׁרְיָיא עֲלַיְיהוּ. וְעַבְדִּין חַרְשָׁיְיהוּ וְאוּמָאן לוֹן בְּדַּרְגִּין אַחֲרָנִין עִלָּאִין מִנַיְיהוּ, וְעַבְדִּין מָה דְּעָבְדִין.","שָׁלַח לֵיהּ הָכִי, עַמָּא דָא, לָאו קִשְׁרָא דִּילְהוֹן כִּשְׁאַר עַמִּין דְּעָלְמָא, אֲבָל קִשְׁרָא דִּילְהוֹן בַּאֲתַר אַחֲרָא עִילָאָה מִתְקַשְׁרָן לְעֵילָּא מִכָּל דַּרְגִּין.","כָּתַב וְשַׁלַּח לֵיהּ פִּיפּוּסָא וּפַטְרוֹנָא דִתְרֵיסָר נְשִׁיבִין (נשיאן) דְּסַחֲרָן גַּלְגָּלֵי רְתִיכָא דְכוּרְסַיָּיא קַדִּישָׁא. אָמַר לֵיהּ, אִי תִּסְתַּכֵּל, בְּהָנֵי תִּסְתַּכֵּל. בְּגִין דְּהָנֵי תְרֵיסָר דְמִתְקַשְׁרָן בְּי\"ב שִׁבְטִין. וְאִי בְּהָנֵי תַּעְבֵּיד חַרְשִׁין, בדִּיּוּקְנָא דִּילְהוֹן לְתַתָּא דְּאִינוּן י\"ב שִׁבְטִין וְי\"ב דִגְלִין פְּרִישִׁין, נֵיכוּל לְהוּ ונָגִיח בְּהוּ קְרָבָא וְנֵעֶקַר לְהוּ מֵעָלְמָא.","וְהַיְינוּ וַיְשַׁלַּח מַלְאָכִים. ודַּאי הֲדָא הוּא דִכְתִיב, וּקְסָמִים בְּיָדָם. פִּיפּוּסִין דְּמַלְאָכִין קַדִּישִׁין הֲווּ אַתְיָין בִּידַיְיהוּ. וְאִיהוּ לָא יָדַע דְּכָל דַּרְגִּין עִלָּאִין בִּידָא דְקוּדְשָׁא בְּרִיךְ הוּא אִינוּן. מָה חָשִׁיב בָּלָק, חָשִׁיב דְעֲמָא דְּיִשְׂרָאֵל אִתְמְסָרוּ לְמַלְאָכִין כִּשְׁאָר עַמִּין דְּעָלְמָא. וְעַל דָא כָּתַב שְׁמָהָן דְּאִלֵּין מַלְאָכִין תְרֵיסָר, וְשַׁלַּח לֵיהּ. וְהַיְינוּ וַיִשְׁלַּח מַלְאָכִים."],[],[[0,"","סִפְּרוּ לוֹ כָּל אוֹתוֹ הַמַּעֲשֶׂה. תָּמַהּ וּבָכָה וְשָׂמַח. אָמַר, חֲבֵרִים, נָדַרְתִּי שֶׁאֵלֵךְ אֵלָיו וְאֶתְחַבֵּר עִמּוֹ, וְנוֹדֶה וּנְשַׁבַּח לְרִבּוֹן הָעוֹלָם. שָׂמַח עִמָּם."],[1,"","אָמְרוּ לוֹ: בַּמָּה הָיִיתָ מִתְעַסֵּק? אָמַר לָהֶם, הָיִיתִי מִתְעַסֵּק בְּפָרָשַׁת בָּלָק, וְרָאִיתִי שֶׁחָכְמָתוֹ הָיְתָה חֲזָקָה וְיוֹתֵר מֵחָכְמָתוֹ שֶׁל בִּלְעָם. חָכְמַת בִּלְעָם פַּעַם אַחַת - וְחָכְמַת בָּלָק בְּכָל זְמַן. אֲבָל כָּל הַמַּפְתְּחוֹת הָיוּ בִּידֵי בִלְעָם, מִשּׁוּם שֶׁהוּא הָיָה שָׁלֵם בַּפֶּה. בָּלָק הָיָה יוֹדֵעַ לַעֲשׂוֹת כְּשָׁפָיו, וְלֹא יָדַע לְהַשְׁלִים בַּפֶּה."],[2,"","פָּתַח וְאָמַר, (שם מו) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב כוּ'. הַפָּסוּק הַזֶּה (יש להסתכל בו) פֵּרְשׁוּהוּ. אֲבָל אַל תִּירָא עַבְדִּי יַעֲקֹב - מֵהַכְּשָׁפִים שֶׁל בִּלְעָם. וְאַל תֵּחַת - מֵהַקְּסָמִים שֶׁל בָּלָק."],[3,"","בֹּא וּרְאֵה אֵיךְ הָיוּ שְׁנֵיהֶם זֶה עִם זֶה בְּעֵצָה רָעָה כְּנֶגֶד יִשְׂרָאֵל. אָמַר בִּלְעָם: יַעֲקֹב הָיָה בְּבֵית לָבָן אַבָּא, וְנִחֵשׁ נְחָשִׁים כְּנֶגְדּוֹ וְיָכֹל לוֹ, אֲנִי אֲסַדֵּר נְחָשִׁים כְּנֶגְדּוֹ. אָמַר בָּלָק: וַאֲנִי אֲסַדֵּר קְסָמִים לַשֵּׁם שֶׁנִּקְרָא יִשְׂרָאֵל."],[4,"","בְּאוֹתָהּ שָׁעָה יָצְאָה רוּחַ אַחַת מִצִּדּוֹ שֶׁל יוֹסֵף מִתּוֹךְ עַנְפֵי הָאִילָן, וְנָשְׁבָה בְּאוֹתָם נְחָשִׁים וּבִטְּלָתָם, וְהַיְנוּ שֶׁאָמַר יוֹסֵף (בראשית מד) כִּי נַחֵשׁ יְנַחֵשׁ אִישׁ אֲשֶׁר כָּמֹנִי. מַה זֶּה אִישׁ אֲשֶׁר כָּמֹנִי? בִּשְׁבִילִי יֵשׁ אִישׁ שֶׁיְּבַטֵּל הַנְּחָשִׁים לִבְנֵיכֶם. בִּשְׁבִילִי הוּא לְמַעְלָה, וְהַיְנוּ אִישׁ אֲשֶׁר כָּמֹנִי. כָּמוֹנִי יֵשׁ אִישׁ לְמַעְלָה שֶׁמּוֹצִיא רוּחַ אַחֶרֶת מִתּוֹךָ הָעֵץ שֶׁלְּמַטָּה, וְנָשַׁב בְּאוֹתוֹ הַקֶּסֶם וּבִטֵּל אוֹתוֹ."],[5,"","וְהַיְנוּ (משליטז) קֶסֶם עַל שִׂפְתֵי מֶלֶךָ. מִי הַמֶּלֶךָ? זֶה הָעֵץ שֶׁלְּמַטָּה. אֲזַי הֵשִׁיב בִּלְעָם וְאָמַר, (במדבר כג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. וּשְׁנֵיהֶם הָיוּ מִשְּׁנֵי הַצְּדָדִים הַלָּלוּ."],[6,"","כִּי אִתְּךְ אָנִי. לֹא הָיוּ יָמִים מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם שֶׁהִצְטָרֵךָ לִהְיוֹת כָּךָ הַקָּדוֹשׁ בָּרוּךָ הוּא עִם יִשְׂרָאֵל כְּאוֹתוֹ הַזְּמַן שֶׁרָצָה בִּלְעָם לְכַלּוֹת אֶת שׂוֹנְאֵי יִשְׂרָאֵל מִן הָעוֹלָם. וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךָ הוּא: בִּלְעָם רָצָה לְהַשְׁמִידְכֶם מִן הָעוֹלָם, אֲבָל אֲנִי לֹא אֶעֱשֶׂה כָּךָ, (ירמיה מו) כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם אֲשֶׁר הִדַּחְתִּיךְ שָּׁמָּה וְאֹתְךְ לֹא אֶעֱשֶׂה כָלָה. שֶּׁאִלּוּ יָבֹאוּ כָּל עַמֵּי הָעוֹלָם, לֹא יְכוֹלִים לְהַשְׁמִידְכֶם מִן הָעוֹלָם."],[7,"","בָּא לָבָן בָּרִאשׁוֹנָה וְרָצָה לַעֲקֹר אֶת יַעֲקֹב לְבַדּוֹ מִן הָעוֹלָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עָלָיו, שֶׁכָּתוּב (בראשית לא) הִשָּׁמֶר לְךְ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב עַד רָע. בָּא פַּרְעֹה וְרָצָה לְהַשְׁמִידָם מִן הָעוֹלָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עֲלֵיהֶם, שֶׁכָּתוּב (שמות א) וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ. בָּא הָמָן וְרָצָה לְהַשְׁמִידָם - בָּא הַקָּדוֹשׁ בָּרוּךָ הוּא וְהֵגֵן עֲלֵיהֶם וְהֵשִׁיב הַכֹּל עַל רֹאשׁוֹ. וְכֵן בְּכָל דּוֹר וָדוֹר הַקָּדוֹשׁ בָּרוּךָ הוּא הֵגֵן עַל יִשְׂרָאֵל תָּמִיד."],[8,"","וְיִשְּׂרָאֵל אוֹמְרִים, (איכה ג) חַסְדֵי ה' כִּי תָמְנוּ כִּי לֹא כָלוּ רַחֲמָיו. כִּי לֹא תַמּוּ הָיָה צָרִיךָ לִכְתֹּב! אֶלָּא חַסְדֵי ה' בְּכָל דּוֹר וָדוֹר הָיוּ בְעֶזְרֵנוּ כִּי לֹא תַמְנוּ וְלֹא הֻשְׁמַדְנוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא נִמְנְעוּ רַחֲמָיו מֵעִמָּנוּ, שֶׁכָּתוּב (שם) כִּי לֹא כָלוּ רַחֲמָיו."],[9,"","בֹּא וּרְאֵה מַה כָּתוּב בָּרִאשׁוֹנָה, (במדבר כב) וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם בֶּן בְּעוֹר, וְאַחַר כָּךָ וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן. הָיָה לוֹ לוֹמַר וַיָּבאוּ הַמַּלְאָכִים, מָה הַטַּעַם שִׁנָּה הַדָּבָר מִמַּה שֶּׁאָמַר בָּרִאשׁוֹנָה?"],[10,"","אֶלָּא, אוֹתוֹ בָּלָק הָרָשָׁע הָיָה חָכָם בְּכָל הַדְּרָגוֹת שֶׁלְּמַעְלָה, אוֹתָם שֶׁקּוֹשְׁרִים קְשָׁרִים לַעֲשׂוֹת בָּהֶם כְּשָׁפִים וּקְסָמִים, וְכָל אוֹתָן דְּרָגוֹת יוֹתֵר עֶלְיוֹנוֹת (מהן) דִּבְרֵיהֶם, שֶׁבָּהֶן כּוֹפִים אֶת הַדְּרָגוֹת הַתַּחְתּוֹנוֹת."],[11,"","אָמַר לוֹ, בְּכָל פַּעַם שֶׁאָנוּ מְכַשְּׁפִים וְקוֹסְמִים וּמְנַחֲשִׁים, יֵשׁ לָנוּ דְּרָגוֹת וּמַלְאָכִים יְדוּעִים, שֶׁנּוֹדָעִים לַמְּכַשְּׁפִים וְלַקּוֹסְמִים, אֲבָל מִכָּאן וָהָלְאָה יֵשׁ לְךְ לְעַיֵּן בְּמָקוֹם אַחֵר עֶלְיוֹן."],[12,"","כָּתַב לוֹ שֵׁמוֹת אֲחֵרִים בְּאוֹתָן דְּרָגוֹת קְדוֹשׁוֹת. וְכָךְ דַּרְכֵי הַקּוֹסְמִים וְהַמְּכַשְּׁפִים, שֶׁיּוֹדְעִים אוֹתָן דְּרָגוֹת שֶׁאוֹתוֹ קֶסֶם שׁוֹרֶה בָהֶם, וְעוֹשִׂים כִּשְׁפֵיהֶם, וּמַשְׁבִּיעִים אוֹתָם בִּדְרָגוֹת אֲחֵרוֹת עֶלְיוֹנוֹת מֵהֶם, וְעוֹשִׂים מַה שֶּׁעוֹשִׂים."],[13,"","שָׁלַח לוֹ כָּךְ: הָעָם הַזֶּה, אֵין הַקֶּשֶׁר שֶׁלָּהֶם כִּשְׁאָר עַמֵּי הָעוֹלָם, אֲבָל הַקֶּשֶׁר שֶׁלָּהֶם בְּמָקוֹם אַחֵר עֶלְיוֹן נִקְשָׁרִים מֵעַל לְכָל הַדְּרָגוֹת."],[14,"","כָּתַב וְשָׁלַח לוֹ שְׁמוֹת הַהִשְׁתַּלְשְׁלוּת וְהָאֲבָהוּת שֶׁל שְׁנֵים עָשָׂר נִיצוֹצוֹת (נשיאים) שֶׁסּוֹבְבִים גַּלְגַּלֵּי הַמֶּרְכָּבָה שֶׁל הַכִּסֵּא הַקָּדוֹשׁ. אָמַר לוֹ: אִם תִּסְתַּכֵּל, בְּאֵלּוּ תִּסְתַּכֵּל, מִשּׁוּם שֶׁהַשְּׁנֵים עָשָׂר הַלָּלוּ שֶׁנִּקְשָׁרִים בִּשְׁנֵים עָשָׂר שְׁבָטִים. וְאִם בְּאֵלֶּה תַּעֲשֶׂה כְשָׁפִים, בַּדְּיוֹקָן שֶׁלָּהֶם לְמַטָּה, שֶׁהֵם שְׁנֵים עָשָׂר שְׁבָטִים וּשְׁנֵים עָשָׂר דְּגָלִים פְּרוּשִׂים, נוּכַל לָהֶם, וְנִלָּחֵם בָּהֶם בִּקְרָב, וְנַעֲקֹר אוֹתָם מִן הָעוֹלָם."],[15,"","וְהַיְנוּ וַיִּשְׁלַח מַלְאָכִים וַדַּאי. זֶהוּ שֶׁכָּתוּב וּקְסָמִים בְּיָדָם, שְׁמוֹת הַהִשְׁתַּלְשְׁלוּת שֶׁל מַלְאָכִים קְדוֹשִׁים הָיוּ מְבִיאִים בִּידֵיהֶם. וְהוּא לֹא יָדַע שֶׁכָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הֵם בִּידֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. מֶה חָשַׁב בָּלָק? חָשַׁב שֶׁעַם יִשְׂרָאֵל נִמְסְרוּ לַמַּלְאָכִים כִּשְׁאָר הָעַמִּים שֶׁל הָעוֹלָם, וְעַל כֵּן כָּתַב שֵׁמוֹת שֶׁל שְׁנֵים עָשָׂר הַמַּלְאָכִים הַלָּלוּ וְשָׁלַח לוֹ, וְהַיְנוּ וַיִּשְׁלַח מַלְאָכִים."]]],[["אָמַר לֵיהּ, תָּא חֲזֵי, כָּל דַּרְגִּין דְּאִינוּן מִתְקַשְׁרָן קִשְׁרִין לְתַבְרָא עַמָּא דָא, מִסִטְרָא דְּצָפוֹן אִינוּן. וּמִסִטְרָא דְּצָפוֹן זְמִינִין לְמִנְפַּל וְשׁוּלְטָנוּ דְחַרְשִׁין דִּילָן בְּסִטְרָא דְּצָפוֹן אִינוּן. הַשְׁתָּא נֵיכוּל לְאַגָּחָא בְּהוֹן קְרָבָא דְּהָא תְרֵיסָר אִלֵּין (דאינון) מִתְקַשְׁרָן בְּהוּ, וּמִסִטְרָא דְּצָפוֹן שַׁרְיָין לְמִמְנֵי.","וְהוֹאִיל וּמִשְׂמֹאלָא שַׁרְיָין תוּקְפָא דִּילְהוֹן, אִתְחַלָשׁ ואִתְּבַּר. בְּגִין דְכָל תוּקְפָא דִּילְהוֹן לְהַהוּא סְטָר אִיהוּ. מָהוּ דְּקָאָמַר דִּכְתִיב (דברי הימים ב ד׳:ד׳) עוֹמֵד עַל שְׁנֵים עֲשָׂר בָּקָר שְׁלֹשָׁה פּוֹנִים צָפוֹנָה, מִצָּפוֹן שָׁארֵי לְמִמְנֵי. אָמַר הַא תוּקְפָא דִּילָן מִצָּפוֹן אִיהוּ וְאִינוּן אַרְבָּעִים חָסֵר חַד, דַּרְגִּין תַּקִּיפִין מִפַּרְזְלָא וּנְחָשָׁא וּתְּחוֹתַיְיהוּ לֵית לוֹן חוּשְׁבָּנָא. וְעַל דָא נֵיכוּל לְאַגָּחָא קְרָבָא וּלְאִתְגָרַאָה בְּהוּ.","וְקוּדְשָׁא בְּרִיךְ הוּא לָא עֲבִיד הָכִי, דְּלָא שָׁבִיק לוֹן לְמַלְאָכִים וְלָא לְחֵילֵי שְׁמַיָא. אֶלָּא לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וְכָל מַלְאָכִין רַבְרְבִין וְשִׁלְטוֹנִין, פְּלַג עַל כָּל שְׁאָר עַמִּין. וְכָד אָתוּ יִשְׂרָאֵל, נָטִיל לוֹן אִיהוּ בִּלְחוֹדוֹי וְאַחֲסִין לוֹן בְתוּקְפָא בְּגוּפָא דְּאִילָנָא וְלָא שָׁבָק לוֹן בִּידָא דְּמַלְאָכִין, וְלָא בִּידָא דִמְמַנָּן וְרַבְרְבִין דְּעָלְמָא. דִּכְתִיב (דברים ל״ב:ח׳) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגוֹ'. ואִלֵּין י\"ב תְּחוּמִין מֵתַחְמָן בְּד' סִטְרֵי עַלְמָא. לְבָתַר דְבָדָר עַנְפִּין וְטַרְפִין, נָטַל לְיִשְׂרָאֵל ואַחֲסִין לוֹן בְתוּקְפָא דְּגוּפָא דְּאִילָנָא. דִּכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","אָמַר רַבִּי אֶלְעָזָר, כַּמָּהּ יֵאוֹת וְשַׁפִּיר הַאי. זַכָּאָה אוֹרְחָא דִּילָן. וְכַמָּה מִילִין עִלָּאִין קַדִּישִׁין רַוָּוחְנָא לוֹן וְחֲמֵינָא. הַהוּא יוּדָאי הֲוָה תַּמָּן לְקָמַיְיהוּ. אָמַר לוֹן, רָבַּנָן, כָּל מִילִין אִלֵּין, כַּמָה טָבָאן. וּמִילִין עִלָּאִין קַדִּישִׁין נִינְהוּ. מַאי דִּכְתִיב בַּתְרֵיהּ, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתוֹהוּ יְלֵל יְשִׁימוֹן וְגוֹ'.","אָמְרוּ לֵיהּ, אִי יָדַעְתְּ בֵּיהּ מִלָּה, אֵימָא. דְּהָא אוּקְמוּה בְּאַבְרָהָם, דְאַשְׁכַּח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא דְּפַלְחֵי עֲבוֹדָה זָרָה וְלָא הֲווּ יַדְעֵי בִּמְהֵימְנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא כּוּלְּהוּ הֲווּ טַעָאן בָּתַר עֲבוֹדָה זָרָה, וְקָם אַבְרָהָם וּפָרַח בֵּינַיְיהוּ עַנָפָא חֲדָא שְׁלִים, קֳדָם מָארֵי דְּעָלְמָא. ואַשְׁכַּח לֵיהּ תַּמָּן.","מָה עֲבָד קוּדְשָׁא בְּרִיךְ הוּא, נָטַל לֵיהּ לְהַהוּא עַנְפָא, וְאָעֲקַר לֵיהּ מִתַּמָּן ואַשְׁרֵי לֵיהּ, ואִשְׁתַּדֵּל. וְשָׁתָל לֵיהּ בְּאַרְעָא אַחֲרָא. דִּכְתִיב (בראשית י\"ב) לֵךְ לְךָ מֵאַרְצֶךָ וְגוֹ'. וְעָבִיד מִנֵּיהּ עַמָּא קַדִּישָׁא. וְדָא הִיא מְצִיאָה דְאַשְׁכַּח קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא בְּאַרְעָא, דְּלָא מְהֵימְנֵי בֵּיהּ בְקוּדְשָׁא בְּרִיךְ הוּא וְלָא יַדְעֵי מַאן אִיהוּ.","אָמַר הַהוּא יוּדָאי שַׁפִּיר הוּא, וְיֵאוֹת מִלָּה דָא. אֲבָל אִית לְשָׁאַלָא, אִי אַבְרָהָם הֲוָה דִּיּוּקְנָא דְּאִיצְטְרִיךְ. וְתוּ דְּהָא קְרָא, לָא אוֹכַח עַל אַבְרָהָם כְּלָל וְלָא אִדְכָּר לְאַבְרָהָם כְּלָל, וְלָא לְיִצְחָק, אֶלָּא לְיַעֲקֹב בִּלְחוֹדוֹי. דִּכְתִיב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב וְגוֹ', וּבַתְרֵיהּ כְּתִיב, יִמְצָאֵהוּ וְגוֹ'.","אָמַר רַבִּי אֶלְעָזָר, עִם כָּל זֶה לֹא קַשְׁיָא הָכָא. דְּהָא אַבְרָהָם אַשְׁכְּחָן דְּנָפַק מִגּוֹ פָּלְחֵי עֲבוֹדָה זָרָה. וְהָכָא אַף עַל גַּב דְיַעֲקֹב אַדְכָּר, הוּא עַל אַבְרָהָם. וְלֵית פִּירוּכָא כְּלָל בְּמִלָּה דָא. אֲבָל אִי יָדַעְתְּ מִלָּה אוֹ חִדּושָׁא אִימָא:","פָּתַח וְאָמַר הַהוּא יוּדָאי (בראשית א׳:ב׳) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְגוֹ'. מַאן אָרֶץ, הַהִיא דְאִשְׁתְמוֹדַע עִילָאָה וְתַּתָּאָה. הָיְתָה תֹהוּ, מַאי תֹהוּ. דָא קַו יָרוֹק דְאַקִיף כָּל עַלְמָא ואִיקְרֵי קַו תֹהוּ. דִּכְתִיב (ישעיה ל\"א) ונָטָה עָלֵיהּ קַו תֹהוּ ואַבְנֵי בֹּהוּ. בֹּהוּ, כְּמָה דְּתָנֵינָן, אֲבָנִין מֵפוּלָמוֹת דְמִשְׁתַקְעָן גּוֹ תְהוֹמֵי וּמִנְהוֹן נַפְקֵי מַיִין.","הַשְׁתָּא אִית לְמִנְדַע. תֹהוּ דְּאִיהוּ קַו יָרוֹק, מַאן הֲוָה (הוא) קַו יָרוֹק, אֶלָּא אַשְׁכְּחָן בְּסִפְרָא דְּאַסְיָא דְקַרְטִינָאָה וְיוֹדָאן דְקֵסָרֵי שְׁמֵיהּ, וְקָרָאן שְׁמֵיהּ אַסְיָא קַרְטִינָאָה. בְּגִין דְהוּא רָב עַל כָּל אַסְיָין וְיַקִּירָא בְּחָכְמָתָא. וְהָכִי אָמַר (אמרי) בְּלָשׁוֹן פַּרְסִי לְבַּר נָשׁ יַקִּירָא. וְהוּא אָמַר, וְהָאָרֶץ הָיְתָה תֹהוּ, מַאי תֹהוּ, אִיהִי קַו יָרוֹק דְּאַסְחַר עַלְמָא. וּמָאן אִיהוּ קְלִיפָּא דֶּאֱגוֹזָא וְדָא אִיהוּ קְלִיפָּה דִּלְבַר דְּאִיהוּ יָרוֹק.","לְגוֹ מִנֵּיהּ בֹּהוּ, וְאִינוּן אֲבָנִין מֵפוּלָמוֹת דְּמִנְּהוֹן נַפְקֵי מַיִין. מִן תֹהוּ אִתְמַשְׁכָאן עוֹר וּבָשָׂר. מִן בֹּהוּ אִתְמְשָׁכוּ גַּרְמֵי לְגוֹ מִנֵּיהּ. וְחֹשֶׁךְ, דָא מְשִׁיכוּ דְּאִתְמְשָׁךְ מִנֵּיהּ עַמָּא דְעֵשָׂו. וְאִי תֵּימָא מַאן תֹהוּ. הַרֵי (הכי) הוּא ודַּאי, דְּהָא חֹשֶׁךְ מִנֵּיהּ תַלְיָּיא. אֶלָּא אִינוּן אֲבָנִין מְפוּלָמוֹת, עָאלוּ בְּאֶמְצָעִיתָא דְמִנֵּיהּ אִתְמַשְׁכָאן גַּרְמֵי כְּמָה דְּאִתְּמַר. וְחֹשֶׁךְ מְשִׁיכוּ דָקִיק, דְּמִנֵּיהּ אִתְמְשָׁךְ עֵשָׂו.","וְרוּחַ אֱלֹהִים דָא מוֹחָא דֶּאֱגוֹזָא, דְּמִתַּמָּן אִתְמְשָׁךְ יַעֲקֹב שְׁלֵימָא, כְּגַוְונָא דֶּאֱגוֹזָא דָא. רָזָא דִּכְתִיב (יחזקאל א׳:ד׳) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, לָקֳבְלֵיהּ דְּתֹהוּ. לְגוֹ מִנֵּיהּ, עָנָן גָּדוֹל, לְקֳבְּלֵיהּ דְּבֹּהוּ. לְגוֹ מִנֵּיהּ, וְאֵשׁ מִתְלַקַּחַת, לְקֳבְּלֵיהּ דְחֹשֶׁךְ. לְגוֹ מִנֵּיהּ, ונֹגַהּ לוֹ סָבִיב, לְקֳבְּלֵיהּ דְרוּחַ אֱלֹהִים.","וּמִתוֹכָה כְּעֵין הַחַשְׁמַל, לְגוֹ מִכֹּלָּא. לְקֳבְּלֵיהּ מְרַחֶפֶת עַל פְּנֵי הַמַּיִם. דָא רוּחָא דְּאִימָא עִילָאָה, דְּקָא מְרַחֶפֶת עַל כֹּלָּא. וְיַעֲקֹב שְׁלֵימָא אִיהוּ, וְדָא מוֹחָא דֶּאֱגוֹזָא וְקוּדְשָׁא בְּרִיךְ הוּא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, ודַּאי. לְבָתָר עֲבָד קוּדְשָׁא בְּרִיךְ הוּא דְּכָל אִינוּן קְלִיפִּין יְהוֹן כּוּלְהוֹן מִשְׁתַּעְבְּדָן לֵּיהּ.","עַד הָכָא הֲוָה כְּתִיב בְּהַהוּא סִפְרָא (דאסיא) דְקַרְטִינָאָה אַסְיָא. לְבָתַר הֲוָה רָשִׁים בְּהַאי קְרָא, כָּל נְטוּרָא דְּאִיצְטְרִיךְ אַסְיָא, חַכִּים לְמֶעְבַּד לְמֵרַע דְּשָׁכִיב בְּבֵי מָרְעֵיה אֲסִירֵי דְּמַלְכָּא, לְמִפְלַח לְמָארֵי עַלְמָא."],[],[[0,"","אָמַר לוֹ: בּא וּרְאֵה, כָּל הַדְּרָגוֹת שֶׁקּוֹשְׁרוֹת קְשָׁרִים לִשְׁבֹּר אֶת הָעָם הַזֶּה, הֵן מִצַּד הַצָּפוֹן, וּמִצַּד הַצָּפוֹן עֲתִידִים לִפֹּל, וְשִׁלְטוֹן הַמְכַשְּׁפִים שֶׁלָּנוּ הֵם מִצַּד הַצָּפוֹן. עַכְשָׁו נוּכַל לְהִלָּחֵם בָּהֶם בַּקְּרָב, שֶׁהֲרֵי שְׁנֵים עָשָׂר הַלָּלוּ (שהם) קְשׁוּרִים בָּהֶם, וּמִצַּד הַצָּפוֹן מַתְחִילִים לְהִמָּנוֹת."],[1,"","וְהוֹאִיל וּמִשְּׂמֹאל מַתְחִיל, הַתֹּקֶף שֶׁלָּהֶם נֶחֱלָשׁ וְנִשְׁבָּר, מִשּׁוּם שֶׁכָּל תָּקְפָּם הוּא לְאוֹתוֹ הַצַּד. מַהוּ שֶׁאָמַר שֶׁכָּתוּב (מלכים א ז) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלֹשָׁה פֹנִים צָפוֹנָה, מִצָּפוֹן מַתְחִיל לִמְנוֹת? אָמַר, הִנֵּה הַתֹּקֶף שֶׁלָּנוּ הוּא מִצָּפוֹן, וְאוֹתָן אַרְבָּעִים חָסֵר אַחַת, דְּרָגוֹת חֲזָקוֹת מִבַּרְזֶל וּנְחֹשֶׁת, וְשֶׁתַּחְתֵּיהֶן אֵין לָהֶן חֶשְׁבּוֹן, וְעַל כֵּן נוּכַל לַעֲרֹךְ בָּהֶם קְרָב וּלְהִתְגָּרוֹת בָּהֶם."],[2,"","וְהַקָּדוֹשׁ בָּרוּךָ הוּא לֹא עָשָׂה כָּךְ, שֶׁלֹּא הִשְׁאִיר אוֹתָם לַמַּלְאָכִים וְלֹא לְצִבְאוֹת הַשָּׁמַיִם, אֶלָּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְבַדּוֹ. וְכָל הַמַּלְאָכִים הַגְּדוֹלִים וְהַשַּׁלִּיטִים חִלֵּק אוֹתָם עַל כָּל שְׁאָר הָעַמִּים. וּכְשֶׁבָּאוּ יִשְׂרָאֵל, נָטַל אוֹתָם הוּא לְבַדּוֹ, וְהִנְחִיל אוֹתָם בְּתֹקֶף בְּגוּף הָאִילָן, וְלֹא עָזַב אוֹתָם בְּיַד הַמַּלְאָכִים, וְלֹא בְּיַד מְמֻנִּים וּגְדוֹלִים שֶׁל הָעוֹלָם, שֶׁכָּתוּב (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם. וְאֵלּוּ שְׁנֵים עָשָׂר תְּחוּמִים מְתֻחָמִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, אַחַר שֶׁפִּזֵּר עֲנָפִים וְעָלִים, נָטל אֶת יִשְׂרָאֵל וְהִנְחִיל אוֹתָם בְּתקֶךְ גּוּךְ הָאִילָן, שֶׁכָּתוּב (שם) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[3,"","אָמַר רַבִּי אֶלְעָזָר, כַּמָּה יָפֶה וְנָאֶה זֶהָ. אַשְׁרֵי דַּרְכֵּנוּ, וְכַמָּה דְבָרִים עֶלְיוֹנִים קְדוֹשִׁים הִרְוַחְנוּ אוֹתָם וְרָאִיתִי. וְאוֹתוֹ יְהוּדִי הָיָה שָׁם לִפְנֵיהֶם. אָמַר לָהֶם, חֲכָמִים, כָּל הַדְּבָרִים הַלָּלוּ כַּמָּה טוֹבִים, וּדְבָרִים עֶלְיוֹנִים קְדוֹשִׁים הֵם. מַה זֶּה שֶׁכָּתוּב אַחֲרָיוִ (שם) יִמְצָאֵהוִּ בְּאֶרֶץ מִדְבָּר וּבְתהוּ יְלֵל יְשִׁמן וְגוֹ'?"],[4,"","אָמַר לוֹ, אִם יָדַעְתָּ בּוֹ דָּבָר - אֱמר, שֶׁהֲרֵי הַדָּבָר הַזֶּה פֵּרְשׁוּהוּ בְּאַבְרָהָם, שֶׁמָּצָא אוֹתוֹ הַקָּדוֹשׁ בָּרוּךָ הוּא בְּאֶרֶץ שֶׁעוֹבְדִים עֲבוֹדָה זָרָה, וְאֵין מַכִּירִים אֶת אֱמוּנַת הַקָּדוֹשׁ בָּרוּךָ הוּא, אֶלָּא כֻּלָּם הָיוּ טוֹעִים אַחַר עֲבוֹדָה זָרָה, וְקָם אַבְרָהָם, וְהִפְרִיחַ בֵּינֵיהֶם עָנָךְ אֶחָד שָׁלֵם לִפְנֵי רִבּוֹן הָעוֹלָם, וּמָצָא אוֹתוֹ שָׁם."],[5,"","מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךָ הוּא? נָטַל אֶת אוֹתוֹ הֶעָנָךְ וְעָקַר אוֹתוֹ מִשָּׁם, וְהִשְׁרָה אוֹתוֹ וְהִשְׁתַּדֵּל וְשָׁתַל אוֹתוֹ בְּאֶרֶץ אַחֶרֶת, שֶׁכָּתוּב (בראשית יב) לֶךָ לְךְ מֵאַרְצְךְ וְגוֹמֵר, וְעָשָׂה מִמֶּנּוּ עַם קָדוֹשׁ, וְזוֹ הַמְּצִיאָה שֶׁמָּצָא הַקָּדוֹשׁ בָּרוּךָ הוּא בָּעוֹלָם, בְּאֶרֶץ שֶׁלֹּא מַאֲמִינִים בַּקָּדוֹשׁ-בָּרוּךָ-הוּא וְלֹא יוֹדְעִים מִי הוּא."],[6,"","אָמַר אוֹתוֹ יְהוּדִי, יָפֶה זֶה, וְנָאֶה דָבָר זֶה, אֲבָל יֵשׁ לִשְׁאל אִם אַבְרָהָם הָיָה דְיוֹקָן שֶׁהֻצְרַךָ? וְעוֹד, שֶׁהֲרֵי הַכָּתוּב לֹא מוֹכִיחַ עַל אַבְרָהָם כְּלָל, וְלֹא הִזְכִּיר אֶת אַבְרָהָם כְּלָל, וְלֹא אֶת יִצְחָק, אֶלָּא אֶת יַעֲקֹב לְבַדּוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, וְאַחַר כָּךָ כָּתוּב יִמְצָאֵהוּ וְגוֹמֵר."],[7,"","אָמַר רַבִּי אֶלְעָזָר, עִם כָּל זֶה לֹא קָשֶׁה כָּאן, שֶׁהֲרֵי מָצָאנוּ שֶׁאַבְרָהָם יָצָא מִתּוֹךָ עוֹבְדֵי עֲבוֹדָה זָרָה, וְכָאן - אַף עַל גַּב שֶׁיַּעֲקֹב נִזְכָּר, הוּא מְדַבֵּר עַל אַבְרָהָם, וְאֵין כְּלָל קֻשְׁיָה בְּדָבָר זֶה. אֲבָל אִם יָדַעְתָּ דָּבָר אוֹ חִדּוּשׁ - אֱמֹר. ע\"כ מההשמטות."],[8,"","פָּתַח אוֹתוֹ יְהוּדִי וְאָמַר, (בראשית א) וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ וְגוֹמֵר. מִי הָאָרֶץ? אוֹתָהּ הַנּוֹדַעַת לְמַעְלָה וּמַטָּה. הָיְתָה תֹהוּ, מַה זֶּה תֹּהוּ? זֶה קַו יָרֹק שֶׁמַּקִּיף אֶת כָּל הָעוֹלָם, וְנִקְרָא קַו תֹהוּ, שֶׁכָּתוּב (ישעיה לד) וְנָטָה עָלֶיהָ קַו תֹהוּ וְאַבְנֵי בהוּ. בהוּ, כְּמוֹ שֶׁשָּׁנִינוּ, אֲבָנִים מְפֻלָּמוֹת שֶׁמְּשֻׁקָּעוֹת בְּתוֹךְ הַתְּהוֹמוֹת, וּמֵהֶן יוֹצְאִים מַיִם."],[9,"","עַכְשָׁו יֵשׁ לָדַעַת, תֹּהוּ, שֶׁהוּא קַו יָרֹק, מַהוּ קַו יָרֹק? אֶלָּא מָצָאנוּ בְּסֵפֶר הָרוֹפֵא מִקַּרְטִינָאָה, וְיוּדָן שֶׁל קֵסָרִי שְׁמוֹ, וְקוֹרְאִים אֶת שְׁמוֹ הָרוֹפֵא הַקַּרְטִינָאִי, מִשּׁוּם שֶׁהוּא גָּדוֹל עַל כָּל הָרוֹפְאִים וְנִכְבָּד בְּחָכְמָה. וְכָךְ אוֹמְרִים בְּלָשׁוֹן פַּרְסִי לְאָדָם נִכְבָּד. וְהוּא הָיָה אוֹמֵר, וְהָאָרֶץ הָיְתָה תֹהוּ, מַה זֶּה תֹּהוּ? הוּא קַו יָרֹק שֶׁמַּקִּיף כָּל הָעוֹלָם, וּמִי הוּא? קְלִפַּת הָאֱגוֹז, וְזוֹהִי הַקְּלִפָּה הַחִיצוֹנָה, שֶׁהִיא יְרֻקָּה."],[10,"","לִפְנִים מִמֶּנּוּ - בּהוּ, וְהֵן אֲבָנִים מְפֻלָּמוֹת שֶׁמֵּהֶן יוֹצְאִים מַיִם. מִתֹּהוּ נִמְשָׁךְ עוֹר וּבָשָׂר. מִן בֹּהוּ נִמְשָׁכוֹת הָעֲצָמוֹת. לִפְנִים מִמֶּנּוּ - וְחֹשֶׁךְ. זוֹ הַהַמְשָׁכָה שֶׁנִּמְשָׁךְ מִמֶּנָּה הָעָם שֶׁל עֵשָׂו. וְאִם תֹּאמַר מַה זֶּה תֹּהוּ? הֲרֵי הִיא בְּוַדַּאי שֶׁהֲרֵי הַחֹשֶׁךְ תָּלוּי מִמֶּנּוּ, אֶלָּא אוֹתָן אֲבָנִים מְפֻלָּמוֹת נִכְנְסוּ בָּאֶמְצַע, שֶׁמִּמֶּנּוּ נִמְשָׁכוֹת הָעֲצָמוֹת, כְּמוֹ שֶׁנֶּאֱמַר. וְחֹשֶׁךְ - מְשִׁיכָה דַקָּה, שֶׁמִּמֶּנָּה נִמְשָׁךְ עֵשָׂו."],[11,"","וְרוּחַ אֱלֹהִים - זֶה מֹחַ הָאֱגוֹז, שֶׁמִּשָּׁם נִמְשָׁךְ יַעֲקֹב הַשָּׁלֵם, כְּמוֹ הָאֱגוֹז הַזֶּה, סוֹד הַכָּתוּב (יחזקאל א) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, כְּנֶגֶד הַתֹּהוּ. לִפְנִים מִמֶּנּוּ - עָנָן גָּדוֹל, כְּנֶגֶד הַבּהוּ. לִפְנִים מִמֶּנּוּ - וְאֵשׁ מִתְלַקַּחַת, כְּנֶגֶד הַחֹשֶׁךְ. לִפְנִים מִמֶּנּוּ - וְנֹגַהּ לוֹ סָבִיב, כְּנֶגֶד שֶׁל וְרוּחַ אֱלֹהִים."],[12,"","וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל - לִפְנִים מֵהַכֹּל, כְּנֶגְדּוֹ מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, זוֹ רוּחַ הָאֵם הָעֶלְיוֹנָה שֶׁמְּרַחֶפֶת עַל הַכֹּל. וְיַעֲקֹב הַשָּׁלֵם הוּא, וְזֶה מֹחַ הָאֱגוֹז, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וַדַּאי. אַחַר כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אוֹתָן הַקְּלִפּוֹת, שֶׁכֻּלָּן יִהְיוּ מְשֻׁעְבָּדוֹת לוֹ."],[13,"","עַד כָּאן הָיָה כָּתוּב בְּאוֹתוֹ סֵפֶר שֶׁל הָרוֹפֵא הַקַּרְטִינָאִי. אַחַר כָּךְ הָיָה רָשׁוּם בַּכָּתוּב הַזֶּה: כָּל שְׁמִירָה שֶׁצָּרִיךְ רוֹפֵא חָכָם לַעֲשׂוֹת לְחוֹלֶה שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ אֲסִירֵי הַמֶּלֶךְ, לַעֲבֹד לְרִבּוֹן הָעוֹלָם,"]]],[["דְּכָד אָזִיל אַסְיָא חַכִּים לְגַבֵּיהּ, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁימוֹן. מַרְעִין דְּשַׁרְיָין עָלֵיהּ אַשְׁכָּח לֵיהּ בַּאֲסִירֵי דְּמַלְכָּא. אִי תֵימָא הוֹאִיל וְקוּדְשָׁא בְּרִיךְ הוּא יִפְקוֹד לְתַפְשָׁא לֵיהּ דְּלָא יִשְׁתַדָּל בַּר נָשׁ אַבַּתְרֵיהּ, לָאו הָכִי. דְּהָא דָוִד אָמַר (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דַּל וְגוֹ' וְדַּל הוּא דְּשָׁכִיב בְּבֵי מָרְעֵיה. וְאִי אַסְיָא חַכִּים הוּא, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ בִּרְכָאָן לְהַהוּא דְּיִשְׁתָּדַּל בֵּיהּ.","וְהַהוּא אַסְיָא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, בְּבֵי מָרְעֵיה שָׁכִיב. וּבְתֹהוּ יְלֵל יְשִׁימוֹן, דְּאִינוּן מַרְעִין דַחֲקִין לֵיהּ. מָאי אִיצְטְרִיךְ לֵיהּ לְמֶעְבַּד יְסוֹבֵבֶנְהוּ, יְסוֹבֵב סִיבּוּב וְיֵיתֵי עִילוֹת בְּגִין דְיִמְנָע מִנֵּיהּ אִינוּן מִלִּין דְנָזְקִין לֵיהּ, יָקִיז לֵיהּ, וְיִפּוּק מִנֵּיהּ דָּמָא בִּישָׁא. יְבוֹנְנֵהוּ, יִסְתַּכֵּל וְיָבִין, הַהוּא מַרְעָא מִמַּה הֲוִי. וְיִסְתַּכֵּל בְּגִין דְּלָא יִתְרַבֵּי עֲלוֹי וְיִמְאָךְ לֵיהּ. לְבָתָר יִצְרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, בְּגִין דִּיְהֵא נָטִיר כְּדְקָא יֵאוֹת בְּאִינוּן מַשְׁקִין, בְּאִינוּן אַסְוָותָא דְּאִצְטְרִיכוּ לֵיהּ. וְלָא יִטְעֵי מִנַיְיהוּ, דְאִלְמָלֵי יִטְעֵי אֲפִילּוּ בְּמִלָּה חֲדָא, קוּדְשָׁא בְּרִיךְ הוּא חָשִׁיב עַל אַסְיָא כְּאִילוּ שָׁפִיך דָּמָא וְקַטְלֵיהּ.","בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי דְּאַף עַל גַּב דְּהַהוּא בַּר נָשׁ אִיהוּ בֵּי אֲסִירֵי דְּמַלְכָּא, דְּיִשְׁתָּדַּל בַּר נָשׁ עָלֵיהּ וִיְסָיֵּיעַ לֵיהּ לְאַפָּקָא לֵיהּ מִבֵּי אֲסִירֵי. וְהָוָה אָמַר הָכִי, קוּדְשָׁא בְּרִיךְ הוּא דָן דִּינִי בְּנֵי עַלְמָא לְעֵילָּא, הֵן לָמוּת, הֵן לְשָׁרוּשֵׁי, הֵן לַעֲקוֹר, הֵן לַעֲנוֹשׁ נִכְסִין. מַאן דְאִתְחֲזֵי לַעֲנוֹשׁ נִכְסִין, נָפִיל בְּבֵי מָרְעֵיה וְלָא יִתְסֵי, עַד דְּעָבַר כָּל מָה דְּאִתְגַּזַר עָלֵיהּ. כֵּיוָן דְאִתְעֲנָשׁ בְּמָמוֹנֵיהּ, וְיָהִיב לֵיהּ כָּל מָה דְּאִתְגַּזַר עָלֵיהּ, אִיתְסֵי וְנָפַק מִבֵּי אֲסִירֵי. וְעַל דָא אִיצְטְרִיךְ לְאִשְתָּדְּלָא עָלֵיהּ, דְיִתֵּן עוֹנָשָׁא וְיִפּוּק.","מַאן דְאִתְחֲזֵי לְשָׁרוּשֵׁי, יִתְּפְסוּן לֵיהּ, וְיַהֲבֵי לֵיהּ בְּבֵי אֲסִירֵי. עַד דְיִשְׁתַרֵשׁ מִכֹּלָא. וּלְזִמְנִין דְיִשְׁתַרֵשׁ מִשָׁיְיפוֹי, אוֹ מֵחַד מִנַיְיהוּ, וּלְבָתַר יִפְּקוּן לֵיהּ מִבֵּי אֲסִירֵי. מַאן דְאִתְחֲזֵי לָמוּת, הָכִי הוּא, דְּאִילּוּ יִתֵּן כָּל כּוֹפְרָא וְכָל מָמוֹנָא דְּעָלְמָא לָא יִשְׁתְזִיב.","וְעַל דָּא אִיצְטְרִיךְ לְאַסְיָּיא חַכִּים לְאִשְתָדְּלָא עָלֵיהּ, אִי יָכִיל לְמֵיהַב לֵיהּ אַסְוָותָא מִן גוּפָא, יֵאוֹת. וְאִי לָאו, יִתֵּן לֵיהּ אַסְוָתָא לְנִשְׁמָתֵיהּ ויִשְׁתְדַּל עַל אַסְוָותָא דְּנִשְׁמָתָא. וְדָא הוּא אַסְיָא דְקוּדְשָׁא בְּרִיךְ הוּא יִשְׁתַדָּל עָלֵיהּ בְּהַאי עַלְמָא וּבְעָלְמָא דְאָתֵי.","אָמַר רַבִּי אֶלְעָזָר, עַד הַשְׁתָּא לָא שָׁמַעְנָא מֵאַסְיָּיא דָא וּמִסִפְרָא דָא, בָּר מזִמְנָא חֲדָא. דְּאָמַר לִי טַיָּיעָא חֲדָא דְּשָׁמַע לְאָבוֹי, דְּאַסְיָא חַד הֲוָה בְיוֹמוֹי. דְּכָד הֲוָה מִסְתַּכֵּל בְּבַר נָשׁ כַּד אִיהוּ בְּבֵי מָרְעֵיה, הֲוָה אָמַר, דָא חַי וְדָא מִית. וַהֲווּ אַמְרִין עָלֵיהּ, (דהוא הוה זכאה), דָחִיל חַטָּאָה. וְכָל מַאן דְּלָא יָכִיל לְמִדְבַּק גאצ\"ל לְמִזְבַּן] מָה דְּאִיצְטְרִיךְ, אִיהוּ הֲוָה קַנֵי לֵיהּ וְיָהִיב מדִּילֵיהּ. וַהֲווּ אַמְרִין, דְּלֵית חַכִּים בְּעָלְמָא כְּגִינֵיה. וּבִצְלוֹתֵיהּ הֲוָה עֲבִיד יַתִּיר מִמַּה דְהָוָה עֲבִיד בִּידוֹי, וְכַדּוֹמֶה לָן, דָא הֲוָה הַהוּא אַסְיָא.","אָמַר הַהוּא טַיָּיעָא, וַדַּאי סִפְרָא דִּילֵיהּ בְּיָדִי אִיהוּ, דְּקָא יְרִיתְנָא מֵאָבִי אַבָּא. וְכָל מִלּוֹי דְּהַהוּא סִפְרָא, כֻּלְּהוּ אִתְיָּיסְדָן עַל רָזִין דְּאוֹרַיְיתָא וְרָזִין סְתִימִין אַשְׁכַּחְנָא בֵּיהּ. וּמִילִין דְּאַסְוָותָא דְּאִיהוּ אָמַר דְּלָא יֵאוֹת לְמִפְעָל לוֹן, בָּר מַאן דְּאִיהוּ דָחִיל חַטָּאָה.","וְאִינוּן מִמַּה דְהָוָה עֲבִיד בִּלְעָם דְהָוָה לַחִישׁ עַל מֵרָע, וְהוּא אָמַר בְּפוּמֵיהּ, וְאִתְּסֵי מִיָד. וְכֻלְּהוּ בָּרִיר לוֹן בְּהַהוּא סִפְרָא. וְאָמַר, דָא אָסוּר וְדָא מוּתָּר לְמָאן דְדָחִיל חַטָּאָה, בְּגִין דְמָרְעִין סַגִּיאִין אָמַר, דְּתַלְיָיא אַסְוָותָא דִּילְהוֹן בִּלְחִישׁוּ דְפּוּמָא, ואִינוּן מִסִטְרָא דְנָחָשׁ, וּמִנְהוֹן מִסִטְרָא דְקֶסֶם. וְכָל אִינוּן דְאָסוּר לוֹמַר בְּפוּמָא וְאָסוּר לְמֶעְבַּד בְעוֹבָדָא, הֲוָה אָמַר. עַד דְּאַשְׁכַּחְנָא עַל מַרְעִין יְדִיעָאן דְּאִיצְטְרִיךְ לוֹמַר כָּךְ, וּלְנָדוּיֵי בְּנִדוּי וּבְשָׁמַתָּא עַל הַהוּא מֵרַע, וְאִיהוּ תַוְוהָא סַגִּי לְגַבָּן.","חַדֵּי רַבִּי אֶלְעָזָר וְחַדּוּ חַבְרַיָּיא. אָמַר רִבִּי אֶלְעָזָר אִי הַאי סִפְרָא הֲוָה לְגַבָּן, נֵחְמֵי מַאי אִיהוּ. אָמַר, אֲנָא אֶמְסַר בִּמְסִירָה עַל מְנָת לְאַחֲוָאָה (לאחזאה) לְבוֹצִינָא קַדִּישָׁא. וְתָנֵינָן, אָמַר רִבִּי אֶלְעָזָר, הַהוּא סִפְרָא הֲוָה בִּידִי תְרֵיסָר יַרְחֵי, ואַשְׁכַּחְנָא בֵּיהּ נְהוֹרִין עִלָּאִין. כַּד מָטֵינָא לְאִינוּן רָזִין דַהֲווּ מִבִּלְעָם תַּוָוהְנָא.","יוֹמָא חַד לַחִישְׁנָא בְּאֲתָר חַד, וַהֲווּ אַתְוָון סַלְקָן ונַחְתָּן. עַד דְחַמִינָן בְּחֶלְמָא וְאָמַר לִי, מָה לָךְ לְמֵיעָל בִּתְחוּמָא דְּלָאו דִּילָךְ. אִתְּעַרְנָא וְאֲבְאִישׁ קַמָּאי עַל רָזִין סְתִימִין דַהֲווּ תַּמָּן, שָׁדַרְנָא לְהַהוּא יוּדָאי וְיַהִיבְנָא לֵיהּ סִפְרָא.","וּבְּרָזִין דְּבִּלְעָם אַשְׁכַּחְנָא מֵאִינוּן שְׁמָהָן דְּמַלְאָכִים דְּשָׁדָר לֵיהּ בָּלָק, וְלָא הֲווּ מִתְסָדְרָן עַל תִיקוּנָיְיהוּ. אֲבָל כַּמָה זִינֵי אַסְוָותָא אַשְׁכַּחְנָא בֵּיהּ דְּקָא מִתְתַקְנֵי עַל תִּקּוּנֵי אוֹרַיְיתָא וְרָזִין סְתִימִין דִּילֵיהּ. וְחֲמֵינָא דְּאִינוּן בְּחַסִידוּתָא וּצְלוֹתִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְאִי תֵּימָא דְהָוָה עֲבִיד אַסְוָותָא בִּפְּסוּקֵי דְּאוֹרַיְיתָא, חַס וְשָׁלוֹם. אֶלָּא הֲוָה אָמַר רָזִין דְּאוֹרַיְיתָא, וְעַל הַהוּא רָזָא אַפִּיק רָזִין דְּאַסְוָותָא, דְּלָא חֲמֵינָא כְּהַהוּא גווָֹנָא לְעָלְמִין. אֲמֵינָא, בְּרִיךְ רַחֲמָנָא דְאַחְכִּים לִבְנֵי נָשָׁא בְּחָכְמָתָא דִלְעֵילָּא.","וּמֵאינוּן מִלִּין דְּבִּלְעָם נָסִיבְנָא. וְחֲמֵינָא בְּהוּ, דְּלָא הֲוָה בְּעָלְמָא חַכִּים בְּחַרְשִׁין כְּגִינֵיהּ. אֲמֵינָא, בְּרִיךְ רַחֲמָנָא דְבָטִיל מֵעָלְמָא חַרְשִׁין דְּלָא יִטְעוּן בְּנֵי נָשָׁא מִבָּתָר דָחַלְתָא דְקוּדְשָׁא בְּרִיךְ הוּא. ע\"כ:"],[],[[0,"","שֶׁכְּשֶׁהוֹלֵךְ רוֹפֵא חָכָם אֵלָיו, יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וּבְתֹהוּ יְלֵל יְשִׁמֹן, מַחֲלוֹת שֶׁשּׁוֹרוֹת עָלָיו, מוֹצֵא אוֹתוֹ בַּאֲסִירֵי הַמֶּלֶךְ. אִם תֹּאמַר, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְצַוֶּה לִתְפֹּס אוֹתוֹ, שֶׁלֹּא יִשְׁתַּדֵּל שׁוּם אָדָם אַחֲרָיו - לֹא כָּךְ! שֶׁהֲרֵי דָּוִד אָמַר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל וְגוֹמֵר. דַּל הוּא שֶׁשּׁוֹכֵב בְּבֵית חָלְיוֹ, וְאִם הָרוֹפֵא חָכָם, הַקָּדוֹשׁ בָּרוּךְ הוּא יִתֵּן בְּרָכוֹת לְאוֹתוֹ שֶׁמִּשְׁתַּדֵּל בּוֹ, וְאוֹתוֹ רוֹפֵא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר, שׁוֹכֵב בְּבֵית חָלְיוֹ."],[1,"","וּבְתֹהוּ יְלֵל יְשִׁמֹן, שֶׁאוֹתָם חֳלָאִים דּוֹחֲקִים אוֹתוֹ. מַה צָּרִיךְ לוֹ לַעֲשׂוֹת? יְסֹבֲבֶנְהוּ, יְסוֹבֵב סִבּוֹת וְיָבִיא עִלּוֹת כְּדֵי שֶׁיִּמְנַע מִמֶּנּוּ אוֹתָם דְּבָרִים שֶׁמַּזִּיקִים לוֹ, יַקִּיז לוֹ וְיוֹצִיא מִמֶּנּוּ דָּם רַע. יְבוֹנֲנֵהוּ, יִסְתַּכֵּל וְיָבִין אוֹתוֹ הַחֹלִי מִמָּה הָיָה, וְיִסְתַּכֵּל כְּדֵי שֶׁלֹּא יִתְרַבֶּה עָלָיו וְיַנְמִיךְ אוֹתוֹ. אַחַר כָּךְ יִצְּרֶנְהוּ כְּאִישׁוֹן עֵינוֹ, כְּדֵי שֶׁיִּהְיֶה שָׁמוּר כָּרָאוּי בְּאוֹתָם מַשְׁקִים וּבְאוֹתָן רְפוּאוֹת שֶׁצָּרִיךְ לוֹ וְלֹא יִטְעֶה מֵהֶם, שֶׁאִלְמָלֵא יִטְעֶה אֲפִלּוּ בְּדָבָר אֶחָד, הַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲשִׁיב עַל הָרוֹפֵא כְּאִלּוּ שָׁפַךְ דָּם וַהֲרָגוֹ."],[2,"","כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה שֶׁאַף עַל גַּב שֶׁאוֹתוֹ אָדָם הוּא בְּבֵית אֲסִירֵי הַמֶּלֶךְ, שֶׁיִּשְׁתַּדֵּל עָלָיו בֶּן אָדָם וִיסַיַּע לוֹ לְהוֹצִיאוֹ מִבֵּית הָאֲסוּרִים. וְהָיָה אוֹמֵר כָּךְ: הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינֵי בְּנֵי הָעוֹלָם לְמַעְלָה הֵן לָמוּת, הֵן לְשָׁרֵשׁ, הֵן לַעֲקֹר, הֵן לָתֵת עֹנֶשׁ נְכָסִים. מִי שֶׁרָאוּי לְעֹנֶשׁ נְכָסִים נוֹפֵל בְּבֵית חָלְיוֹ, וְלֹא יִתְרַפֵּא עַד שֶׁעוֹשֶׂה כָּל מַה שֶּׁנִּגְזַר עָלָיו. כֵּיוָן שֶׁנֶּעֱנָשׁ בְּמָמוֹנוֹ וְנָתַן כָּל מַה שֶּׁנִּגְזַר עָלָיו, מִתְרַפֵּא וְיוֹצֵא מִבֵּית הָאֲסוּרִים, וְעַל זֶה צָרִיךְ לְהִשְׁתַּדֵּל עָלָיו שֶׁיִּתֵּן עֹנֶשׁ וְיֵצֵא."],[3,"","מִי שֶׁרָאוּי לְשָׁרֵשׁ, יִתְפְּסוּ אוֹתוֹ וְיִתְּנוּ אוֹתוֹ בְּבֵית הָאֲסוּרִים עַד שֶׁיִּשְׁתָּרֵשׁ מֵהַכֹּל, וְלִפְעָמִים שֶׁיִּשְׁתָּרֵשׁ מֵאֵיבָרִים אוֹ מֵאֶחָד מֵהֶם, וְאַחַר כָּךְ יוֹצִיאוּהוּ מִבֵּית הָאֲסוּרִים. מִי שֶׁרָאוּי לָמוּת כָּךְ זֶה, שֶׁאִלּוּ יִתֵּן כָּל כֹּפֶר וְכָל מָמוֹן שֶׁבָּעוֹלָם לֹא יִנָּצֵל,"],[4,"","וְעַל זֶה צָרִיךְ רוֹפֵא חָכָם לְהִשְׁתַּדֵּל עָלָיו. אִם יָכוֹל לָתֵת לוֹ רְפוּאָה מִן הַגּוּף - יָפֶה, וְאִם לֹא - יִתֵּן לוֹ רְפוּאָה לְנִשְׁמָתוֹ וְיִשְׁתַּדֵּל עַל רְפוּאַת הַנְּשָׁמָה, וְזֶהוּ רוֹפֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁתַּדֵּל עָלָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[5,"","אָמַר רַבִּי אֶלְעָזָר, עַד עַכְשָׁו לֹא שָׁמַעְתִּי מֵהָרוֹפֵא הַזֶּה וּמֵהַסֵּפֶר הַזֶּה, חוּץ מִפַּעַם אַחַת שֶׁאָמַר לִי סוֹחֵר אֶחָד שֶׁשָּׁמַע מֵאָבִיו, שֶׁרוֹפֵא אֶחָד הָיָה בְיָמָיו, שֶׁכְּשֶׁהָיָה מִסְתַּכֵּל בְּאָדָם כְּשֶׁהוּא בְּבֵית חָלְיוֹ, הָיָה אוֹמֵר: זֶה יִחְיֶה, וְזֶה יָמוּת. וְהָיוּ אוֹמְרִים עָלָיו (שהוא היה צדיק) יְרֵא חֵטְא, וְכָל מִי שֶׁלֹּא יָכוֹל הָיָה לְהַשִּׂיג (לקנות) מַה שֶּׁצָּרִיךְ, הוּא הָיָה קוֹנֶה לוֹ וְנוֹתֵן מִשֶּׁלּוֹ, וְהָיוּ אוֹמְרִים שֶׁאֵין חָכָם בָּעוֹלָם כְּמוֹתוֹ, וּבִתְפִלָּתוֹ הָיָה עוֹשֶׂה יוֹתֵר מִמַּה שֶּׁהָיָה עוֹשֶׂה בְיָדָיו, וּכְדוֹמֶה לָנוּ, זֶה הָיָה אוֹתוֹ רוֹפֵא."],[6,"","אָמַר אוֹתוֹ סוֹחֵר, וַדַּאי סִפְרוֹ בְיָדִי הוּא, שֶׁיְּרַשְׁתִּיו מִסָּבִי, וְכָל דִּבְרֵי אוֹתוֹ הַסֵּפֶר הִתְיַסְּדוּ כֻלָּם עַל סוֹדוֹת הַתּוֹרָה, וְסוֹדוֹת נִסְתָּרִים מָצָאתִי בוֹ. וְדִבְרֵי רְפוּאָה שֶׁהוּא אָמַר שֶׁלֹּא רָאוּי לַעֲשׂוֹתָם, פְּרָט לְמִי שֶׁהוּא יְרֵא חֵטְא,"],[7,"","וְהֵם מִמַּה שֶּׁהָיָה עוֹשֶׂה בִלְעָם, שֶׁהָיָה לוֹחֵשׁ לְחָשִׁים עַל חוֹלֶה, וְהָיָה אוֹמֵר בְּפִיו וּמִיָּד מִתְרַפֵּא, וְכֻלָּם מְבֹרָרִים בְּאוֹתוֹ הַסֵּפֶר. וְאָמַר זֶה אָסוּר וְזֶה מֻתָּר לְמִי שֶׁיְּרֵא חֵטְא, מִשּׁוּם שֶׁחֲטָאִים רַבִּים אָמַר שֶׁרְפוּאָתָם תְּלוּיָה בְּלַחַשׁ הַפֶּה, וְהֵם מִצַּד הַנַּחַשׁ, וּמֵהֶם מִצַּד הַקֶּסֶם. וְכָל אוֹתָם שֶׁאָסוּר לוֹמַר בַּפֶּה וְאָסוּר לַעֲשׂוֹת בְּמַעֲשֶׂה הָיָה אוֹמֵר. עַד שֶׁמָּצָאתִי בְּמַחֲלוֹת יְדוּעוֹת שֶׁצָּרִיךְ לוֹמַר כָּךְ וּלְנַדּוֹת בְּנִדּוּי וּשְׁמָתָא עַל אוֹתוֹ חֹלִי, וְזוֹ תְמִיהָה גְדוֹלָה לָנוּ."],[8,"","שָׂמְחוּ רַבִּי אֶלְעָזָר וְשָׂמְחוּ הַחֲבֵרִים. אָמַר רַבִּי אֶלְעָזָר, אִם הָיָה לָנוּ סֵפֶר זֶה, נִרְאֶה מַהוּ. אָמַר, אֲנִי אֶמְסֹר בִּמְסִירָה עַל מְנָת לְהַרְאוֹת לַמְּנוֹרָה הַקְּדוֹשָׁה. וְשָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, אוֹתוֹ סֵפֶר הָיָה בְיָדִי שְׁנֵים עָשָׂר חֳדָשִׁים, וּמָצָאתִי אוֹרוֹת עֶלְיוֹנִים. כְּשֶׁהִגַּעְתִּי לְאוֹתָם סוֹדוֹת שֶׁהָיוּ מִבִּלְעָם, תָּמַהְתִּי."],[9,"","יוֹם אֶחָד לָחַשְׁתִּי בְמָקוֹם אֶחָד, וְהָיוּ הָאוֹתִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, עַד שֶׁרָאִיתִי בַחֲלוֹם וְאָמַר לִי, מַה לְּךְ לְהִכָּנֵס בִּתְחוּם שֶׁאֵינוֹ שֶׁלְּךְ? הִתְעוֹרַרְתִּי, וְהָיָה רַע לְפָנַי עַל סוֹדוֹת נִסְתָּרִים שֶׁהָיוּ שָׁם. שָׁלַחְתִּי לְאוֹתוֹ יְהוּדִי וְנָתַתִּי לוֹ הַסֵּפֶר,"],[10,"","וּבַסּוֹדוֹת שֶׁל בִּלְעָם מָצָאתִי מֵאוֹתָם שְׁמוֹת הַמַּלְאָכִים שֶׁשָּׁלַח לוֹ בָּלָק וְלֹא הָיוּ מִסְתַּדְּרִים עַל תִּקּוּנֵיהֶם. אֲבָל כַּמָּה מִינֵי רְפוּאָה מָצָאתִי בוֹ שֶׁמְּתֻקָּנִים עַל תִּקּוּנֵי הַתּוֹרָה וְסוֹדוֹת נִסְתָּרִים שֶׁלָּהּ, וְרָאִיתִי בַחֲסִידוּת וּתְפִלּוֹת לַקָּדוֹשׁ-בָּרוּךְ- הוּא. וְאִם תֹּאמַר שֶׁהָיָה עוֹשֶׂה רְפוּאָה בִּפְסוּקֵי הַתּוֹרָה - חַס וְשָׁלוֹם! אֶלָּא הָיָה אוֹמֵר סוֹדוֹת הַתּוֹרָה, וְעַל אוֹתוֹ סוֹד מוֹצִיא סוֹדוֹת רְפוּאָה שֶׁלֹּא רָאִיתִי כָאֵלֶּה לְעוֹלָמִים. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁהֶחְכִּים בְּנֵי אָדָם בְּחָכְמָה עֶלְיוֹנָה."],[11,"","וּמֵאוֹתָם דְּבָרִים שֶׁל בִּלְעָם לָקַחְתִּי, וְרָאִיתִי בָהֶם שֶׁלֹּא הָיָה בָעוֹלָם חָכָם בִּכְשָׁפִים כָּמוֹהוּ. אָמַרְתִּי, בָּרוּךְ הָרַחֲמָן שֶׁבִּטֵּל מֵהָעוֹלָם כְּשָׁפִים, כְּדֵי שֶׁלֹּא יִטְעוּ בְנֵי אָדָם מֵאַחַר יִרְאַת ה': ע\"כ מההשמטות."]]],[["(בראשית כ״ח:י״ב) וַיַּחֲלוֹם וְהִנֵּה סוּלָם, דָא צְלוֹתָא. מֻצָּב אַרְצָה, דִּמְצַלִּין בְּנֵי נָשָׁא לָהּ בְּאַרְעָא דְּאִיהִי שְׁכִינְתָּא וּמָטַאת לִשְׁמַיָּא דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְּמַר (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְרָזָא דְמִלָה (תהילים ח׳:י׳) ה' אֲדוֹנֵנוּ מָה אַדִּיר שְׁמָךְ בְּכָל הָאָרֶץ אֲשֶׁר הוֹדְךָ עַל הַשָּׁמַיִם.","וּבְּזִמְנָא דְּמוֹדָע לוֹן קוּדְשָׁא בְּרִיךְ הוּא, שְׁכִינְתָּא דְּסָלְקָא בְּהַהִיא צְלוֹתַא. מִיָּד (בראשית כ״ח:י״ב) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ, בְּהַהוּא בַּר נָשׁ. כּוּלְּהוּ פַּתְחִין גַּדְפַיְיהוּ לְקֳבֵּל שְׁכִינְתָּא (בההיא) בְּהַהוּא צְלוֹתָא. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמַעְלָה. וְהַאי אִיהוּ עוֹלִים שְׁכִינְתָּא עַל גַּדְפַיְיהוּ.","וְיוֹרְדִים בּוֹ, מַאי בּוֹ, בְקוּדְשָׁא בְּרִיךְ הוּא. וְקוּדְשָׁא בְּרִיךְ הוּא נָחִית עֲלַיְיהוּ לְקָבְּלָא שְׁכִינְתָּא, וּמִתְיָּיחֵד קוּדְשָׁא בְּרִיךְ הוּא בּוֹ (בההיא) בְּהַהוּא צְלוֹתָא. דִּשְׁכִינְתָּא אִיהִי מִצְוָה כְּלִילָא מִשֵׁם הֲוַיָּ\"ה, יהו\"ה אִיהִי חַיָּה דִּילֵיהּ, וּמִצְוָה בְּלָא מַחֲשָׁבָה לֵית לָהּ סְלִיקוּ. וּמַחֲשָׁבָה אִיהוּ אָדָם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, תִּפְאֶרֶת","מִצְוָה, מַלְכוּת כְּלִילָא מֵאַרְבַּע חֵיוָון דְּמֶרְכַּבְתָּא כְּלִילָא מֵאַרְבַּע אַתְוָון אִיהִי נוּקְבָּא דִּילֵיהּ אַנְפִּין דִּילֵיהּ, אַנְפֵּי רַחֲמֵי. בְּגִינָהּ אֲמֵינָא, (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים אַל תַעֲלֵנוּ מִזֶּה.","וּמִסִטְרָא דְצַדִיק אִתִּקְרֵי אֲחוֹרוֹי, חַיָּה כְּלִילָא ח\"י חוּלְיָין דְּאִינוּן מֵאָחוֹר דְּבַּר נָשׁ לְקֳבֵּל ח\"י נִעְנוּעִין דְּלוּלָב דְדוֹמֶה לְשִׁדְרָה דְּבֵּיהּ ח\"י חוּלְיָין. אִיהוּ אָחוֹר לְעוֹבַדָא דְּבְּרֵאשִׁית, וְקֶדֶם לְמַחֲשָׁבָה דְּאִתְּמַר בָּהּ, יִשְׂרָאֵל עָלָהּ בְּמַחֲשָׁבָה. מָה לָאו הָכִי בַּאָדָם, דְּעֵץ הַדַּעַת טוֹב וָרָע דְּאִיהוּ אָחוֹר לְמַעֲשֶׂה וְקֶדֶם לְפּוּרְעֲנוּת.","קָמוּ תַּנָּאִים וְאֱמוֹרָאִים וְאָמְרוּ, רַעְיָא מְהֵימָנָא, יִתְקַיֵּים בָּךְ הַאי קְרָא (ישעיהו ס״ב:ז׳) אַל תִּתְנוּ דֹּמִי לוֹ. דְּהָא עִלָּאִין וְתַתָּאִין מְקַנֶנִין בְּצוּלְמָא דִּידָךְ. מַשִׁירְיָין דְקוּדְשָׁא בְּרִיךְ הוּא דְּאִינוּן מִמְתִיבְתָּא עִילָאָה וּמַשִּׁירְיָין דְּמַטְרוֹנִיתָא דְּאִינוּן מִמְתִיבְתָּא תַּתָּאָה, עֲלָךְ אִתְּמַר (בראשית כ״ח:י״ב) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים וְגוֹ'. בָּךְ סָלְקִין מַשִׁירְיָין דִּשְׁכִינְתָּא בִּצְלוֹתָא דִּילָךְ, ונָחֲתִין מַשִׁירְיָין דְּקוּדְשָׁא בְּרִיךְ הוּא לְקוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי שְׁכִינְתָּא בְּכַמָּה שִׁירִין וְנִיגוּנִין בִּצְלוֹתָא. וְאַנְתְּ הוּא קְרִיבוּ דְקוּדְשָׁא בְּרִיךְ הוּא בִּצְלוֹתָא דִּילָךְ","דְּאִיהִי קָרְבְּנָא דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. (במדבר כ״ח:ב׳) בְּצַו אֵת בְּנֵי יִשְׂרָאֵל אֵת קָרְבָּנִי לַחְמִי דְּתַקִּינוּ מָארֵי מַתְנִיתִין קָרְבְּנִין בִּצְלוֹתָא מִסִטְרָא דִּיְמִינָא, דְּתַּמָּן אִישׁ חֶסֶד כֹּהֵן. וְתַּקִינוּ זְּמִירוֹת דְּאִינוּן שִׁיר דִלְוִיִּם אַבַּתְרַיְיהוּ מִסִטְרָא דִּגְבוּרָה. וְהוֹד דַרְגָּא דְּדָּוִד מַלְכָּא אִתְקַשַׁר בִּשְׂמֹאלָא. ואַהֲרֹן דְדַרְגָא דִּילֵיהּ נֶצַ\"ח אִתְקַשַׁר בְּחֶסֶד. הֲדָא הוּא דִכְתִיב (תהילים ט״ז:י״א) נְעִימוֹת בִּימִינְךָ נֶצַח.","לְבָתַר שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא, כַּלִיל בָּרְכוּ וּקְדוּשָׁה, אִיהוּ קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּבְרָכָה מִסִטְרָא דִּיְמִינָא. הֲדָא הוּא דִכְתִיב (במדבר ו׳:כ״ג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרְכוּ אֵת בְּנֵי יִשְׂרָאֵל. וּקְדוּשָׁה מִסִטְרָא דִלְוִיִּם עַמּוּדָא דְאֶמְצָעִיתָא קִשׁוּר יְמִינָא וּשְׂמָאלָא,","וְאִיהוּ קִשׁוּרָא דִּתְפִילִין דְרֵישָׁא דְּאִיהִי אִימָא עִילָאָה תְפִילִין עַל רֵישֵׁיהּ, כְּמָה דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין בִּתְפִילֵי דְמָארֵי עַלְמָא, מָה כְּתִיב בְּהוּ. ואִיהוּ קִשׁוּרָא דִתְפִלִּין דְיָד דְּאִיהִי שְׁכִינְתָּא תַּתָּאָה וְהַאי אִיהוּ דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין, הֵרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִילִין.","ש שֶׁל תְפִילִין מֹשֶׁה, כַּלִיל תְלַת עַנְפִּין דְּאַבָהָן לְעֵילָּא, דְתַקִּינוּ תְלַת צְלוֹתִין דְּאִינוּן סִימָן שמ\"ע, דְּאִיהִי שָׁחֲרִי\"ת מִנְחָ\"ה עֲרְבִי\"ת, מ\"ה דִּילָךְ צְלוֹתָא דְּשַׁבָּת דְּאִתְּמַר בֵּיהּ (בראשית א׳:כ״ח) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ'.","וְאַנְתְּ כַּלִיל מֶרְכָּבָה תַּתָּאָה דְאֲהַרֹן דָּוִד וּשְׁלֹמֹה וְאָדָם קַדְמָאָה לְעֵילָּא וּבָת זוּגֵיהּ לְתַתָּא, אֵם כָּל חַ\"י דְּאִיהוּ צַדִּיק חַי עָלְמִין. וּבְגִין דָא אַהֲרֹן אַף עַל גַּב דְּאִיהוּ יְמִינָא אוּקְמוּהָ רָבַּנָן בֵּיהּ, אַהֲרֹן שׁוּשְׁבִינָא דְמַטְרוֹנִיתָא. יַעֲקֹב אִיהוּ כַּלִיל תְלַת אֲבָהָן דְּבֵּיהּ רָכִיב אָדָם קַדְמָאָה, דְּלָאו לְמַגָּנָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, שׁוּפְרֵיהּ דְיַעֲקֹב כְּשׁוּפְרֵיהּ דְּאָדָם קַדְמָאָה.","אָמַר בּוֹצִינָא קַדִּישָׁא, רַעְיָא מְהֵימָנָא חֲזֵינָן דְּכַּפָל קוּדְשָׁא בְּרִיךְ הוּא שְׁמָךְ. ואָמַר, מֹשֶׁה מֹשֶׁה, לְאַכְלָלָא לָךְ בְּמֶרְכַּבְתָּא עִילָאָה וּבְּמֶרְכַּבְתָּא תַּתָּאָה, לְאַכְלָלָא בָּךְ אָדָם קַדְמָאָה מִסִטְרָא דְּאַבָהָן, וּלְאַכְלָלָא בָּךְ חַוָּה מִסִטְרָא דְאֲהַרֹן דָּוִד וּשְׁלֹמֹה.","לָמָה לֹא כָּפָל שֵׁם יַעֲקֹב הָכִי. אָמַר לֵיהּ בּוֹצִינָא קַדִּישָׁא בְּגִין, דְקָרָא לֵיהּ יַעֲקֹב וְיִשְׂרָאֵל. יַעֲקֹב לִישָׁנָא דְעַקֵב דְּהַיְינוּ נוּקְבָּא. דְּאִתְּמַר, עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן הָיָה מַכְהֵה גַלְגַּל חַמָּה. ואִתְקְרֵי יִשְׂרָאֵל דְּתַּמָּן רֹאשׁ דְכוּרָא, רֵישָׁא לְנוּקְבָּא דְּהַיְינוּ עָקֵב. וְהַאי אִיהוּ דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְחִוְיָא, (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנוּ עָקֵב. וְדָא גָרַם שְׁכִינְתָּא בְּגָלוּתָא דְּאִתְּמַר בָּהּ, (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת ה'.","חֲדֵי רַבִּי שִׁמְעוֹן וְחַדּוּ מָארֵי מַתְנִיתִין ואָמְרוּ, פּוּמָא דִּשְׁכִינְתָּא סִינַי, מַאן יָכִיל לְמֵיקָם (קמי) פּוּמָךְ דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ מְמַלְלִין בֵּיהּ וְשִׁתִּין רִבּוֹא דִּמְתִיבְתָּא עִילָאָה וְשִׁתִּין רִבּוֹא דִּמְתִיבְתָּא תַּתָּאָה מְמַלְלִין בֵּיהּ עַל פּוּמָךְ. וְעֲלָךְ אִתְּמַר, וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ.","דָּבָר אַחֵר וְהִנֵּה סוּלָם, פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סִינַי דָא סוּלָם ואִיהוּ קָל וְרָזָא דְמִלָה הִנֵּה ה' רוֹכֵב עַל ע\"ב קַ\"ל ע\"ב, יוֹ\"ד הֵ\"י וָי\"ו ה\"י. וְעוֹד ע\"ב י', י\"ה, יה\"ו, יְהוָֹ\"ה. קַ\"ל יוֹ\"ד, יוֹ\"ד הֵ\"א, יוֹ\"ד הֵ\"א וא\"ו, יוֹ\"ד הֵ\"א וא\"ו הֵ\"א. אַתְוָון קַדְמָאִין סָלְקִין לְע\"ב אַתְוָון, וְאִינוּן תּוֹלָדִין דִּילְהוֹן סָלְקִין קַ\"ל. ע\"ב קַ\"ל סָלְקִין מָאתָן וּתְרֵין כְּחוּשְׁבָּן ב\"ר. וְאַנְתְּ הוּא רַעְיָא מְהֵימָנָא, עֲלָךְ אִתְּמַר (תהלים ב) נַשְׁקוּ בָּר. וְאַנְתְּ רָב לְתַתָּא רַבָּן שֶׁל כָּל יִשְׂרָאֵל רַבָּן דְּמַלְאֲכֵי הַשָׁרֵת, בָּר לְעֵילָּא, בָּר לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ."],[],[[0,"","וַיַּחֲלֹם וְהִנֵּה סֻלָּם (בראשית כח) - זוֹ הַתְּפִלָּה. מֻצָּב אַרְצָה, שֶׁמִּתְפַּלְלִים בְּנֵי אָדָם אוֹתָהּ בָּאָרֶץ, שֶׁהִיא הַשְּׁכִינָה, וּמַגִּיעָה לַשָּׁמַיִם, שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְסוֹד הַדָּבָר - (תהלים ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ אֲשֶׁר תִּנָה הוֹדְךְ עַל הַשָּׁמָיִם."],[1,"","וּבִזְמַןֹ שֶׁמּוֹדִיעַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, הַשְּׁכִינָה שֶׁעוֹלָה בְּאוֹתָהּ תְּפִלָּה, מִיָּד - (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ, בְּאוֹתוֹ אָדָם. כֻּלָּם פּוֹתְחִים כַּנְפֵיהֶם לְעֻמַּת הַשְּׁכִינָה בְּאוֹתָהּ תְּפִלָּה. זֶהוּ שֶׁכָּתוּב (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמַעְלָה. וְזֶהוּ עֹלִים - שְׁכִינָה עַל כַּנְפֵיהֶם."],[2,"","וְיֹרְדִים בּוֹ, מַהוּ בּוֹ? בְּהַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַקָּדוֹשׁ בָּרוּךָ הוּא יוֹרֵד עֲלֵיהֶם לְעֻמַּת הַשְּׁכִינָה, וּמִתְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ בְּאוֹתָהּ תְּפִלָּה. שֶׁהַשְּׁכִינָה הִיא מִצְוָה כְּלוּלָה מִשֵּׁם הֲוָיָ\"ה, יְהֹוָ\"ה הִיא חַיָּה שֶׁלּוֹ, וּמִצְוָה בְּלֹא מַחֲשָׁבָה אֵין לָהּ עֲלִיָּה. וּמַחֲשָׁבָה הִיא אָדָם - שֵׁם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, תִּפְאֶרֶת,"],[3,"","מִצְוָה, הִיא מַלְכוּת כְּלוּלָה מֵאַרְבַּע חַיּוֹת שֶׁל הַמֶּרְכָּבָה כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת, הִיא נְקֵבָה שֶׁלּוֹ, פָּנִים שֶׁלּוֹ, פָּנִים שֶׁל רַחֲמִים. בִּגְלָלָהּ נֶאֱמַר, (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים אַל תַּעֲלֵנוּ מִזֶּה."],[4,"","וּמִצַד הַצַּדִּיק נִקְרָא אֲחוֹרָיו, חַיָּה כְּלוּלָה שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, שֶׁהֵן מֵאֲחוֹרָיו שֶׁל הָאָדָם לְעֻמַּת שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב שֶׁדּוֹמֶה לַשִּׁדְרָה, שֶׁבּוֹ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, שֶׁהוּא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית, וָקֶדֶם לְמַחֲשָׁבָה, שֶׁנֶּאֱמַר בָּהּ, יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה. מַה שֶּׁאֵין כֵּן בָּאָדָם, שֶׁעֵץ הַדַּעַת טוֹב וָרָע שֶׁהוּא אָחוֹר לְמַעֲשֶׂה, וָקֶדֶם לְפֻרְעָנוּת."],[5,"","קָמוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה נֶאֱמָן, יִתְקַיֵּם בְּךְ זֶה הַפָּסוּק, (ישעיה סב) אַל תִּתְּנוּ דֳמִי לוֹ. שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים מְקַנְּנִים בַּצֶּלֶם שֶׁלְּךְ. מַחֲנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם מִישִׁיבָה שֶׁל מַעְלָה, וּמַחֲנוֹת שֶׁל הַמַּלְכָּה שֶׁהֵם מִישִׁיבָה שֶׁל מַטָּה, עָלֶיךְ נֶאֱמַר (בראשית כח) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים וְגוֹ'. בְּךְ עוֹלִים מַחֲנוֹת שֶׁל הַשְּׁכִינָה בַּתְּפִלָּה שֶׁלְּךְ, וְיוֹרְדִים מַחֲנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַקָּדוֹשׁ בָּרוּךְ הוּא אֵצֶל הַשְּׁכִינָה בְּכַמָּה שִׁירִים וְנִגּוּנִים בַּתְּפִלָּה. וְאַתָּה הוּא הַקֵּרוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתְּפִלָּה שֶׁלְּךְ,"],[6,"","שֶׁהִיא קָרְבָּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ. בְּפָרָשַׁת (במדבר כח) צַו אֶת בְּנֵי יִשְׂרָאֵל, אֶת קָרְבָּנִי לַחְמִי, שֶׁתִּקְּנוּ בַּעֲלֵי הַמִּשְׁנָה קָרְבָּנוֹת בַּתְּפִלָּה מִצַּד הַיָּמִין, שֶׁשָּׁם אִישׁ חֶסֶד - כֹּהֵן. וְתִקְּנוּ אֲמִירַת הַזְּמִירוֹת שֶׁהֵם שִׁיר הַלְוִיִּם אַחֲרֵיהֶם - מִצַּד הַגְּבוּרָה. וְהוֹד, דַּרְגָּה שֶׁל דָּוִד הַמֶּלֶךְ, נִקְשָׁר בִּשְׂמֹאל. וְאַהֲרֹן, שֶׁדַּרְגָּתוֹ נֵצַ\"ח, נִקְשָׁר בְּחֶסֶד. זֶהוּ שֶׁכָּתוּב (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח."],[7,"","אַחַר כָּךְ יִחוּד בְּפָסוּק שְׁמַע יִשְׂרָאֵל, וְכוֹלֵל בְּרָכָה וּקְדֻשָּׁה, שֶׁהוּא קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּבְרָכָה מִצַּד הַיָּמִין. זֶהוּ שֶׁכָּתוּב (במדבר ו) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדֻשָּׁה מִצַּד הַלְוִיִּם, הָעַמּוּד הָאֶמְצָעִי, קִשּׁוּר יָמִין וּשְׂמֹאל, וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל רֹאשׁ שֶׁהִיא אִמָּא עֶלְיוֹנָה, תְּפִלִּין עַל רֹאשׁוֹ, כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה בִּתְפִלִּין שֶׁל אֲדוֹן הָעוֹלָם מַה כָּתוּב בָּהֶן."],[8,"","וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד, שֶׁהִיא שְׁכִינָה תַּחְתּוֹנָה, וְזֶהוּ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הֶרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְּפִלִּין."],[9,"","ש שֶׁל תְּפִלִּין מֹשֶׁה, כָּלוּל מִשְּׁלֹשָׁה עֲנָפִים שֶׁל הָאָבוֹת לְמַעְלָה, שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת שֶׁהֵן סִימַן שמ\"ע, שֶׁהִיא שַׁחֲרִי\"ת מִנְחָ\"ה עַרְבִי\"ת, מ\"ה שֶׁלְּךְ - תְּפִלַּת הַשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ (בראשית א) וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ'."],[10,"","וְאַתָּה כּוֹלֵל מֶרְכָּבָה תַּחְתּוֹנָה שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה וְאָדָם הָרִאשׁוֹן לְמַעְלָה, וּבַת זוּגוֹ לְמַטָּה, אֵם כָּל חַ\"י, שֶׁהוּא צַדִּיק חַי הָעוֹלָמִים. וּמִשּׁוּם זֶה אַהֲרֹן, אַף עַל גַּב שֶׁהוּא יָמִין, פֵּרְשׁוּהוּ חֲכָמִים בּוֹ, אַהֲרֹן שׁוֹשְׁבִין שֶׁל הַמַּלְכָּה. יַעָקֹב הוּא כָּלוּל מִשְּׁלֹשָׁה אָבוֹת, שֶׁבּוֹ רוֹכֵב אָדָם הָרִאשׁוֹן, שֶׁלֹּא לְחִנָּם פֵּרְשׁוּהוּ בַּעֲלֵי הַמִּשְׁנָה, יָפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן."],[11,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה נֶאֱמָן, רוֹאֶה אֲנִי שֶׁכָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שִׁמְךְ וְאָמַר מֹשֶׁה מֹשֶׁה, לִכְלֹל אוֹתְךְ בַּמֶּרְכָּבָה הָעֶלְיוֹנָה וּבַמֶּרְכָּבָה הַתַּחְתּוֹנָה, לִכְלֹל בְּךְ אֶת אָדָם הָרִאשׁוֹן מִצַּד הָאָבוֹת, וְלִכְלֹל בְּךְ אֶת חַוָּה מִצַּד אַהֲרֹן דָּוִד וּשְׁלֹמֹה."],[12,"","לָמָּה לֹא כָפַל שֵׁם יַעֲקֹב כָּךְ? אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, מִשּׁוּם שֶׁקָּרָא לוֹ יַעֲקֹב וְיִשְׂרָאֵל. יַעֲקֹב לְשׁוֹן עָקֵב, כְּלוֹמַר נְקֵבָה, שֶׁנֶּאֱמַר עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן הָיָה מַכְהֶה גַּלְגַּל חַמָּה. וְנִקְרָא יִשְׂרָאֵל, שֶׁשָּׁם רֹאשׁ הַזָּכָר, רֹאשׁ לַנְּקֵבָה, כְּלוֹמַר הֶעָקֵב. וְזֶהוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ, (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְשׁוּפֶנּוּ עָקֵב. וְזֶה גָּרַם שְׁכִינָה בַּגָּלוּת, שֶׁנֶּאֱמַר בָּהּ (משלי כב) עֵקֶב עֲנָוָה יִרְאַת ה'."],[13,"","שָׂמַח רַבִּי שִׁמְעוֹן, וְשָׂמְחוּ בַּעֲלֵי הַמִּשְׁנָה וְאָמְרוּ, פֶּה שֶׁל הַשְּׁכִינָה, סִינַי, מִי יָכוֹל לַעֲמֹד (לפני) פִּיךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבְּרִים בּוֹ, וְשִׁשִּׁים רִבּוֹא שֶׁל יְשִׁיבָה שֶׁל מַעְלָה וְשִׁשִּׁים רִבּוֹא שֶׁל יְשִׁיבָה שֶׁל מַטָּה מְדַבְּרִים בּוֹ עַל פִּיךְ. וְעָלֶיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ."],[14,"","דָּבָר אַחֵר וְהִנֵּה סֻלָּם - פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סִינַי זֶה סֻלָּם, וְהוּא קַל, וְסוֹד הַדָּבָר - (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָ\"ב קַ\"ל. ע\"ב - יו\"ד ה\"י וי\"ו ה\"י. וְעוֹד ע\"ב - י', י\"ה, יה\"ו, יְהֹוָ\"ה. קַ\"ל - יו\"ד, יו\"ד ה\"א, יו\"ד ה\"א וא\"ו, יו\"ד ה\"א וא\"ו ה\"א. אוֹתִיּוֹת רִאשׁוֹנוֹת עוֹלוֹת לְשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת, וְאוֹתָן תּוֹלָדוֹת שֶׁלָּהֶן עוֹלוֹת קַ\"ל. עָ\"ב קַ\"ל עוֹלִים מָאתַיִם וּשְׁנַיִם, כְּחֶשְׁבּוֹן ב\"ר. וְאַתָּה הוּא רוֹעֶה נֶאֱמָן, עָלֶיךְ נֶאֱמַר (תהלים ב) נַשְּׁקוּ בַר. וְאַתָּה רַב לְמַטָּה, רַבָּן שֶׁל כָּל יִשְׂרָאֵל, רַבָּן שֶׁל מַלְאֲכֵי הַשָּׁרֵת, בֵּן לְמַעְלָה, בֵּן לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ."]]],[["אִתְּמַר לְגַבֵּי דָּוִד (שמואל ב י\"ד) גַּם יְיָ הֶעְבִיר חֲטָאתְךָ לֹא תָּמוּת, בְּהַאי גַּם אִתְכַּפָּר דָּוִד. וְהַאי אִיהוּ שִׁיעוּרָא דְּחָלָה, מ\"ג בֵּיצִים וְתוֹסֶפֶת חוֹמֵשׁ בֵּיצָה, רָמִיז (ויקרא ה׳:ט״ז) וַחֲמִישִׁיתוֹ יוֹסֵף עַלָּיו.","זַכָּאָה צְלוֹתָא דְנָפְקָא מִפּוּמָךְ, כְּגַוְונָא דְקוּדְשָׁא בְּרִיךְ הוּא נָחִית עַל טוּרָא דְסִינָי ואִתְּמַר בֵּיהּ (דברים כ״ט:י״ד) כִּי אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ'. הָכִי בָּר (כד) אֲנְתְ תִשְׁתַדָל בְּאוֹרַיְיתָא וּצְלוֹתָא קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ עִלָּאִין וְתַתָּאִין וְכָל אִינוּן נִשְׁמָתִין דַהֲווּ וְכָל דִּעֲתִידִין לְמֶהֱוֵי וְכָל מַשִׁירְיָין דְּמַלְאָכִים ונָחִית בְּצוּלְמָא דִּילָךְ לְקָבְּלָא צְלוֹתָא דִּילָךְ ואוֹרַיְיתָא דִּילָךְ. בְּגִין דְּמַחֲשָׁבְתָא דִּילָךְ לְיַחֲדָא לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּכָל מָשִׁרְיָין דִּילֵיהּ עֵילָא וְתַתָּא","בְּאוֹרָיְיתָּךְ וּבִצְלוֹתָךְ. קוּדְשָׁא בְּרִיךְ הוּא מַחֲשָׁבָה טוֹבָה מֵצָרְפָה לְמַעֲשֶׂה. וּכְגַוְונָא דְּאִיהוּ אָמַר אָנֹכִי, וְכֻלְּהוּ אָמְרוּ (שמות כ״ד:ז׳) נַעֲשֶׂה ונִשְׁמָע, הָכִי קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד לְכָל מַשִׁירְיָין דִּילֵיהּ דְּכֻלְּהוּ שָׁתְקִין וְשָׁמְעִין לְמִלוּלָךְ, בְּגִין דִּרְעוּתָךְ בְּהוֹן לְיַחֲדָא לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּכָל מַשִּׁירְיָן דִּילֵיהּ.","וְכָל מָה דְקוּדְשָׁא בְּרִיךְ הוּא אַבְטַח לְמֶעְבַּד לָךְ כַּמָה טָבִין דְּלֵית לוֹן סוֹף, כֻּלְּהוּ אָמְרוּ נַעֲשֶׂה וְנִשְׁמָע. וּבְגִין דָא (תהילים ק״ג:כ׳-כ״א) בָּרְכוּ ה' מַלְאָכָיו גִּבּוֹרֵי כֹּחַ עוֹשֵׂי דְבָרוֹ לִשְמוֹעַ בְּקוֹל דְבָרוֹ, ואִתְתַּקַּף בָּךְ. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ וְכָל מַשִׁירְיָין דִּילֵיהּ אִסְתְּכַּמוּ לְמֶעְבַּד כָּל רְעוּתָךְ וְיַתִּיר, מָה דְּאִיהוּ כָּתוּב עַל יְדָךְ. וְלָא נָפִיל מִלָּה זְעִירָא מִכְּתִיבָת יְדָךְ דְּלָא אִתְקַיַּים. זַכָּאָה בַּר נָשׁ דְּמָארֵיהּ חָשִׁיב לֵיהּ כְּגוּפֵיהּ וְעָבִיד לֵיהּ יְקָרָא כְּדִיּוּקְנֵיהּ לְמֶהֱוִי שָׁקִיל מִילוּלִין דְּפוּמוֹי בְּאוֹרַיְיתָא וּצְלוֹתָא כְּמִלּוֹי בְּטוּרָא דְסִינָי. וְלֵית חַד דְּפָּתָח פּוּמוֹי לְקַטְרְגָא לֵיהּ אֶלָּא כֻּלְּהוּ עִלָּאִין וְתַתָּאִין בְּאַסְכָּמוּתָא חֲדָא וּבִרְעוּתָא חֲדָא:","בָּתַר הָכִי אִית לֵיהּ לְמִקְּרֵי פָּרָשַׁת בְּרֵאשִׁית, עַד וַיְהִי עֶרֶב וַיְהִי בֹּקֶר יוֹם אֶחָד. דְּאִיהִי עִלוּיָא וְתּוּשְׁבַּחְתָּא דְכוֹלָא. לְבָתָר יִתְעֲסֶק בְּפָרָשַׁת הַקֹרְבָּנוֹת לְכַפָּרָא עֲלוֹי. וְיֵימָא, צַו אֵת אַהֲרֹן, עַד תּוּקַד בּוֹ. בְּגִין דְכָל הִרְהוּרִין וּמַחֲשָׁבִין דְלֵילְיָא יִתְכַּפְּרוּ. לְבָתַר יְשַׁבַּח תּוּשְׁבַּחְתָּא דְּדָּוִד, וּבְגִין כָּךְ יֵיעוּל בַּר נָשׁ בְּתַּרְעִין דִבְּהוֹן כוּלָא וְאִיהוּ אִתְתַּקְנַת דַרְגִּין.","כֵּיוָן דְּמָטֵי לְיוֹצֵר אוֹר דְּאִיהוּ שֵׁירוּתָא דִּצְלוֹתָא דְמִיוֹשֶׁב, כְּדֵין כָּל אִינוּן דַּרְגִּין פַּתְחִין תַרְעִין וּכְדֵין (שיר השירים ג׳:ו׳) כְּתִימְרוֹת עֲשַׁן כְּתִיב. מָה תִמְרוֹת עֲשַׁן דִקְטוֹרֶת, סַלְקָא וּמִתְחַבְּרָאן דַּרְגִּין אִלֵּין בְּאִלֵּין. אוּף הָכָא אִיהִי צְלוֹתָא דְּאִיהִי כְּתִמְרוֹת עֲשַׁן דְמִתְחֲבְּרָאן וּמִתְקַשְׁרָאן אִלֵּין בְּאִלֵּין. דְּהָא אִיהוּ מְקַשֵׁר לוֹן וְאוֹמֵר, כֻּלָּם אֲהוּבִים כֻּלָּם קְדוֹשִׁים וְכוּ'.","לְבָתַר אַהֲבָה רַבָּה, לְסַלְקָא וּלְאִתְקַשְׁרָא בִּיְמִינָא וְיִחוּדָא דִּשְׁמַע. ע' רַבְרְבָא, ד' רַבְרְבָא. וְסִימָנָא ע\"ד. הַיְינוּ דִּכְתִיב (שמואל א י״ב:ה׳) עֵ\"ד ה' בָכֶם. אִשְׁתָּאֲרוּ אַתְוָון ש\"מ בְּמ' פְתוּחָה. לְפִי שְמ' פְתוּחָה מֶלֶךְ תַּתָּאָה, מ\"ם סְתוּמָה מֶלֶךְ עִילָאָה. אִשְׁתָּאֲרוּ אַתְוָון ש\"מ א\"ח, מֵהַאי סִטְרָא ש\"מ, וּמֵהָאי סִטְרָא א\"ח.","אָמַר רָב הַמְנוּנָא סָבָא כָּל מַאן דִּמְיָחֵד דָא בְּכָל יוֹמָא, חֶדְוָה זָמִין לֵיהּ מִלְעֵילָּא מֵאַתְוָון אִלֵּין. ש\"מ מֵהַאי סִטְרָא, א\"ח מֵהַאי סִטְרָא. וּמְצָרֵף אַתְוָון אִלֵּין לְמַפְרֵעַ שָׁרֵי וּבְמֵישַׁר סִיֵּים. וְסִימָן אֶשְׂמָח דִּכְתִיב (תהילים ק״ד:ל״ד) אָנֹכִי אֶשְׂמָח בְּה'. בְּה' מַמָּשׁ, וְהָכִי אִיתָא בְּסִפְרָא דְּחֲנוֹךְ.","תּוּ, אִית בֵּיהּ עַיִ\"ן רַבְרְבָא, רֶמֶז לְאִלֵּין שִׁבְעִין שְׁמָהָן רָזָא דְּאַבָהָן קַדִּישִׁין. יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה', אִלֵּין אַרְבַּע בָּתֵּי דִּתְפִילִין דְאֲחִיד לוֹן (א\"ח). ד' רַבְרְבָא דָא קֶשֶׁר שֶׁל תְפִילִין דְּאִיהִי אֲחִידַת בְּהוּ, וְהוּא רָזָא לַחַכִּימִין וְלָא אִתְמֶסָר לְגַלָּאָה.","וּתְרֵין רְצוּעִין נַפְקִין מִסִטְרָא דָא וּמִסִטְרָא דָא, רָזָא דִּתְרֵין יַרְכִין דְּהַאי א\"ח דִּנְבִיאֵי קְשׁוֹט אֲחִידָן בֵּיהּ. וְעוֹד א\"ח רֶמֶז לַפָּסוּק דְּאָמַר (שיר השירים ה׳:ב׳) פִּתְחִי לִי אֲחוֹתִי, וּלְבָתַר אֱמֶת וְיַצִיב. וַאֲמַאי וְיַצִיב, דָא תִרְגוּמוֹ. אֶלָּא דָא יַעֲקֹב וְדָא יוֹסֵף וְאִצְטְרִיךְ לְאִתְדַּבְּקָא בְּתַרְוַויְיהוּ.","וּלְבָתַר צְלוֹתָא מְעוֹמֶד. תְלַת קַדְמָאִין דְּאִינוּן מָגֵן, וּמְחַיֶּה, וְהָאֵל הַקָּדוֹשׁ. מָגֵן, אִית בֵּיהּ מ\"ב תֵיבִין, רָזָא דִּשְׁמָא קַדִּישָׁא דְמ\"ב אַתְוָון. וְאִית לְאַכְלָלָא לֵיהּ בְּלִבָּא וּלְאִתְקַשְׁרָא כְּשַׁלְהוֹבָא בְּגַּחַלְתָא בִּרְחִימוּ. וְדָא אִיהוּ בִּרְכָתָא דִּיְמִינָא.","מֵחַיֶה, אִית בֵּיהּ מ\"ט תֵיבִין בְּרָזָא דְּחַמְשִׁין תַרְעִין חָסֵר חַד. וְאִית שְׁמָּא בִּגְבוּרָה ה', וְאִיהוּ אַתָּ\"ה גִבּוֹר לְעוֹלָם אֲדֹנָ\"י. וְרָזָא דִּילֵיהּ אגל\"א ובְּרָזָא אַחֲרָא יג\"לא. וְכוֹלָא רָזָא חֲדָא מִגְבוּרָתָא דְּבִרְכָאן דִיהוּדָה, (בראשית מ״ט:י׳) אַ\"תָּה יוֹדוּךָ אַחֶיךָ, ג\"וּר אַרְיֵה יְהוּדָה, לֹ\"א יָסוּר שֵׁבֶט מִיְהוּדָה, א\"וֹסְרִי לַגֶּפֶן עִירֹה. בְּדָא אִתְעָר יְהוּדָה בִּגְבוּרָתָא קַדִּישָׁא וְדָא אִיהִי בִּרְכָתָא דִּשְׂמֹאלָא.","קְדוּשָׁה אִית בָּהּ אַרְבֵּיסָר תֵיבִין, עֶשֶׂר אָמִירָן וְד' אַתְוָון. וְדָא כַּלִיל לְכָל סִטְרִין וְאַחִיד מִסַּיְיפֵי עַלְמָא עַד סַיְיפֵי עַלְמָא. תְלַת בַּתְרָאי לָאו אִינוּן בְּחוּשְׁבָּן דָא בְּתֵּיבִין, וְאִינוּן רֶצֶה וּמוֹדִים תְרֵין עַמּוּדִים תַמְכֵי דְּאוֹרַיְיתָא. שִׂים שָׁלוֹם אִילָנָא דְחַיֵי דְּאִיהוּ שְׁלָמָא דְּבֵיתָא, שְׁלָמָא דְּכֹלָּא. וּבֵינַיְיהוּ בְּאֶמְצָעִיתָא אִינוּן בִּרְכָאָן דְּתַקִּינוּ קַדְמָאֵי וְהָכִי אוֹקְמוּהָ."],[],[[0,"","נֶאֱמַר אֵצֶל דָּוִד, (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בְּזֶה הַגַּם הִתְכַּפֵּר דָּוִד. וְזֶהוּ שִׁעוּר שֶׁל חַלָּה, שָׁלֹשׁ וְאַרְבָּעִים בֵּיצִים וְתוֹסֶפֶת חֹמֶשׁ בֵּיצָה, רָמוּז בַּנֶּאֱמַר (ויקרא ה) וַחֲמִישִׁתוֹ יוֹסֵף עָלָיו."],[1,"","אַשְׁרֵי הַתְּפִלָּה שֶׁיָּצְאָה מִפִּיךְ, כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָרַד עַל הַר סִינַי וְנֶאֱמַר בּוֹ (דברים כט) כִּי אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ'. כָּךְ בֵּן (כאשר) אַתָּה תִּשְׁתַּדֵּל בְּתוֹרָה וּתְפִלָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא יֶאֱסֹף עֶלְיוֹנִים וְתַחְתּוֹנִים וְכָל אוֹתָן נְשָׁמוֹת שֶׁהָיוּ וְכָל הָעֲתִידִים לִהְיוֹת וְכָל מַחֲנוֹת הַמַּלְאָכִים וְיָרַד בַּצֶּלֶם שֶׁלְּךְ לְקַבֵּל הַתְּפִלָּה שֶׁלְּךְ וְהַתּוֹרָה שֶׁלְּךְ. מִשּׁוּם שֶׁמַּחֲשָׁבָה שֶׁלְּךְ לְיַחֵד לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל מַחֲנוֹת שֶׁלּוֹ לְמַעְלָה וּמַטָּה"],[2,"","בְּתוֹרָתְךְ וּבִתְפִלָּתְךְ. הַקָּדוֹשׁ בָּרוּךָ הוּא, מַחֲשָׁבָה טוֹבָה מְצָרְפָהּ לְמַעֲשֶׂה. וּכְמוֹ שֶׁהוּא אָמַר אָנֹכִי, וְכֻלָּם אָמְרוּ (שמות כד) נַעֲשֶׂה וְנִשְׁמָע - כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה לְכָל הַמַּחֲנוֹת שֶׁלּוֹ שֶׁכֻּלָּם שָׁתְקוּ וְשָׁמְעוּ לְדִבּוּרְךְ, מִשּׁוּם שֶׁרְצוֹנְךְ בָּהֶם לְיַחֵד לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ."],[3,"","וְכָל מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִבְטִיחַ לַעֲשׂוֹת לְךְ כַּמָּה טוֹבוֹת שֶׁאֵין לָהֶן סוֹף, כֻּלָּם אָמְרוּ נַעֲשֶׂה וְנִשְׁמָע. וּמִשּׁוּם זֶה נֶאֱמַר, (תהלים קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ, וְהִתְחַזֵּק בְּךְ. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא ושְׁכִינָתוֹ וְכָל הַמַּחֲנוֹת שֶׁלּוֹ הִסְכִּימוּ לַעֲשׂוֹת כָּל רְצוֹנְךְ וְיוֹתֵר, מַה שֶּׁהוּא כָּתוּב עַל יָדְךְ, וְלֹא נָפַל דָּבָר קָטָן מִכְּתִיבַת יָדְךְ שֶׁלֹּא הִתְקַיֵּם. אַשְׁרֵי הָאָדָם שֶׁאֲדוֹנוֹ חוֹשֵׁב אוֹתוֹ כְּגוּפוֹ וְעוֹשֶׂה לוֹ כָּבוֹד כְּצוּרָתוֹ לִהְיוֹת לוֹקֵחַ דְּבָרִים שֶׁל פִּיו בְּתוֹרָה וּתְפִלָּה כִּדְבָרָיו בְּהַר סִינַי. וְאֵין אֶחָד שֶׁפָּתַח פִּיו לְקַטְרֵג לוֹ אֶלָּא כֻּלָּם, עֶלְיוֹנִים וְתַחְתּוֹנִים, בְּהַסְכָּמָה אַחַת וּבְרָצוֹן אֶחָד."],[4,"","אַחַר כָּךְ יֵשׁ לוֹ לִקְרֹא פָּרָשַׁת בְּרֵאשִׁית, עַד וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. שֶׁהִיא מְעֻלָּה וְשֶׁבַח שֶׁל הַכֹּל. אַחַר כָּךְ יִתְעַסֵּק בְּפָרָשַׁת הַקָּרְבָּנוֹת לְכַפֵּר עָלָיו. וְיֹאמַר, צַו אֶת אַהֲרֹן, עַד תּוּקַד בּוֹ, כְּדֵי שֶׁכָּל הִרְהוּרִים וּמַחֲשָׁבוֹת שֶׁל הַלַּיְלָה יִתְכַּפְּרוּ. אַחַר כָּךְ יְשַׁבַּח בַּתִּשְׁבָּחוֹת שֶׁל דָּוִד, וּמִשּׁוּם זֶה יִכָּנֵס אָדָם בַּשְּׁעָרִים שֶׁבָּהֶם הַכֹּל, וְהוּא מְתַקֵּן הַמַּדְרֵגוֹת."],[5,"","כֵּיוָן שֶׁהִגִּיעַ לְיוֹצֵר אוֹר, שֶׁהוּא תְּחִלַּת הַתְּפִלָּה דְּמִיֹּשֶׁב, אָז כָּל אוֹתָן הַמַּדְרֵגוֹת פּוֹתְחוֹת שְׁעָרִים, וְאָז (שיר השירים ג) כְּתִימְרוֹת עָשָׁן כָּתוּב. מַה תִּימְרוֹת עָשָׁן שֶׁל קְטֹרֶת עוֹלָה וּמִתְחַבְּרִים מַדְרֵגוֹת אֵלּוּ בְאֵלּוּ, אַף כָּאן הִיא תְפִלָּה, שֶׁהִיא כְתִימְרוֹת עָשָׁן שֶׁמִּתְחַבְּרִים וּמִתְקַשְּׁרִים אֵלּוּ בְאֵלּוּ. שֶׁהֲרֵי הוּא קוֹשֵׁר לָהֶם וְאוֹמֵר, כֻּלָּם אֲהוּבִים כֻּלָּם קְדוֹשִׁים וְכוּ'."],[6,"","אַחַר כָּךְ אַהֲבָה רַבָּה, לַעֲלוֹת וּלְהִתְקַשֵּׁר בְּיָמִין וְיִחוּד שֶׁל שְׁמַע. ע' גְּדוֹלָה, ד' גְּדוֹלָה, וְהַסִּימָן - עֵ\"ד. זֶה שֶׁכָּתוּב (שמואל א יב) עֵ\"ד ה' בָּכֶם. נִשְׁאֲרוּ אוֹתִיּוֹת ש\"מ בְּמ' פְּתוּחָה. לְפִי שֶׁמ' פְּתוּחָה מֶלֶךְ תַּחְתּוֹן, מֵ\"ם סְתוּמָה מֶלֶךְ עֶלְיוֹן. נִשְׁאֲרוּ אוֹתִיּוֹת ש\"מ א\"ח, מֵהַצַּד הַזֶּה ש\"מ, וּמֵהַצַּד הַזֶּה א\"ח."],[7,"","אָמַר רַב הַמְנוּנָא סָבָא, כָּל מִי שֶׁמְּיַחֵד זֶה בְּכָל יוֹם, שִׂמְחָה מְזֻמֶּנֶת לוֹ מִלְמַעְלָה מֵאוֹתִיּוֹת אֵלּוּ. ש\"מ מִצַּד זֶה, א\"ח מִצַּד זֶה. וּמְצָרֵף אוֹתִיּוֹת אֵלּוּ - בַּסּוֹף מַתְחִיל וּבְיֹשֶׁר סִיֵּם. וְסִימָנָךְ - אֶשְׂמַח, שֶׁכָּתוּב (תהלים קד) אָנֹכִי אֶשְׂמַח בַּה'. בַּה' מַמָּשׁ. וְכָךְ נִמְצָא בְסִפְרוֹ שֶׁל חֲנוֹךְ."],[8,"","עוֹד, יֵשׁ בּוֹ אוֹת ע' גְּדוֹלָה, רֶמֶז לְאֵלּוּ שִׁבְעִים שֵׁמוֹת, סוֹד שֶׁל הָאָבוֹת הַקְּדוֹשִׁים. יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' - אֵלּוּ אַרְבָּעָה בָתִּים שֶׁל הַתְּפִלִּין שֶׁמְּאַחֵד לָהֶם (א\"ח). ד' גְּדוֹלָה זֶה קֶשֶׁר שֶׁל תְּפִלִּין שֶׁהִיא אֲחוּזָה בָהֶם, וְהוּא סוֹד לַחֲכָמִים, וְלֹא נִמְסָר לְגַלּוֹת."],[9,"","וּשְׁתֵּי רְצוּעוֹת יוֹצְאוֹת מִצַּד זֶה וּמִצַּד זֶה - סוֹד שֶׁל שְׁתֵּי יְרֵכַיִם שֶׁל זֶה א\"ח שֶׁנְּבִיאֵי אֱמֶת אֲחוּזִים בּוֹ. וְעוֹד א\"ח, רֶמֶז לַפָּסוּק שֶׁאָמַר (שיר השירים ה) פִּתְחִי לִי אֲחֹתִי, וְאַחַר כָּךְ אֱמֶת וְיַצִּיב. וּמַדּוּעַ וְיַצִּיב זֶה תַרְגּוּמוֹ? אֶלָּא זֶה יַעֲקֹב וְזֶה יוֹסֵף, וְצָרִיךְ לְהִתְדַּבֵּק בִּשְׁנֵיהֶם."],[10,"","וְאַחַר כָּךְ תְּפִלָּה שֶׁל עֲמִידָה. שְׁלֹשָׁה רִאשׁוֹנוֹת שֶׁהֵן מָגֵן, וּמְחַיֵּה, וְהָאֵל הַקָּדוֹשׁ. מָגֵן יֵשׁ בָּהּ אַרְבָּעִים וּשְׁתַּיִם תֵּבוֹת, סוֹד שֶׁל שֵׁם הַקָּדוֹשׁ שֶׁל אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת. וְיֵשׁ לִכְלֹל לוֹ בַּלֵּב וּלְהִתְקַשֵּׁר כְּשַׁלְהֶבֶת בְּגַחֶלֶת בְּאַהֲבָה. וְזוֹ הִיא בְּרָכָה שֶׁל הַיָּמִין."],[11,"","מְחַיֵּה - יֵשׁ בָּהּ מ\"ט תֵּבוֹת, בְּסוֹד שֶׁל חֲמִשִּׁים שְׁעָרִים חָסֵר אֶחָד. וְיֵשׁ שֵׁם בִּגְבוּרָה ה', וְהוּא אַ'תָּ\"ה גִ'בּוֹר לְ'עוֹלָם אֲ'דֹנָ\"י, וְסוֹד שֶׁלּוֹ אגל\"א, וּבְסוֹד אַחֵר יגל\"א. וְהַכֹּל סוֹד אֶחָד מִגְּבוּרוֹת שֶׁל הַבְּרָכוֹת שֶׁל יְהוּדָה (בראשית מט): אַ'תָּה יוֹדוּךְ אַחֶיךְ, גּ'וּר אַרְיֵה יְהוּדָה, לֹ'א יָסוּר שֵׁבֶט מִיהוּדָה, אֹ'סְרִי לַגֶּפֶן עִירֹה. בָּזֶה מִתְעוֹרֵר יְהוּדָה בִּגְבוּרָה קְדוֹשָׁה, וְזוֹ הִיא בִּרְכַּת הַשְּׂמֹאל."],[12,"","בַּקְּדֻשָּׁה יֵשׁ אַרְבַּע עֶשְׂרֵה תֵבוֹת, עֶשֶׂר אֲמִירוֹת וְאַרְבַּע אוֹתִיּוֹת. וְזֶה כּוֹלֵל לְכָל הַצְּדָדִים וּמְאַחֵד מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם. שָׁלֹשׁ אַחֲרוֹנוֹת אֵינָן בְּחֶשְׁבּוֹן זֶה שֶׁל הַתֵּבוֹת, וְהֵן רְצֵה וּמוֹדִים, שְׁנֵי עַמּוּדִים תּוֹמְכֵי הַתּוֹרָה. שִׂים שָׁלוֹם - עֵץ הַחַיִּים שֶׁהוּא שְׁלוֹם הַבַּיִת, שָׁלוֹם שֶׁל הַכֹּל. וּבֵינֵיהֶם בְּאֶמְצָעִיתָם אֵלּוּ הַבְּרָכוֹת שֶׁתִּקְּנוּ הַקַּדְמוֹנִים, וְכָךְ בֵּאֲרוּהָ."]]],[["לְבָתַר דְּסִיֵּים צְלוֹתֵיהּ וְאוֹדֵי עַל חוֹבֵיהּ, נְפִילַת אַנְפִּין. דְהַכִי אוּקְמוּהָ דְּיַעֲבִיד כָּל מָה דְּעָבַד מֹשֶׁה רַבֵּינוּ עַלָּיו הַשָׁלוֹם (צלותין ותחנונים) תַחֲנוּנִין וּבָעוּתִין וּנְפִילַת אַנְפִּין, דִּכְתִיב (דברים ט׳:י״ח) וַאֶתְנַפָּל לִפְנֵי ה'. וְכֵיוָן דְּעָאל בְּכָל אִינוּן דַּרְגִּין עִלָּאִין וְאִתְקַשַׁר כוּלָא בְּכֻלְּהוּ, אִית לְנַחְתָא לְתַתָּא. הוֹאִיל וְנָחִית לְתַתָּא, אִיצְטְרִיךְ נְפִילַת אַנְפִּין בְּאַלְפָא בֵּיתָא.","מַאי טַעְמָא, כֵּיוָן דְּצַלֵּי צְלוֹתֵיהּ וְאוֹדֵי עַל חוֹבֵיהּ מִכָּאן וּלְהָלְאָה אַחֲזֵי גַּרְמֵיהּ דְּמָסַר נַפְשֵׁיהּ לְמָארֵיהּ בִּרְחִימוּ דִּכְתִיב (תהילים כ״ה:א׳-ב׳) אֵלֶיךָ ה' נַפְשִׁי אֶשָּׂא. וְנִיחָא לֵיהּ לְהַהוּא סִטְרָא דְּשַׁרְיָא בֵּיהּ מוֹתָא (דעביד) וְעָבִיד לֵיהּ נַיְיחָא.","וְעַל דָּא בְּאַלְפָא בֵּיתָא דָא, לֵית בָּהּ, לֹא וא\"ו וְלֹא קו\"ף וְלֹא בי\"ת, וְאִית בֵּיהּ פ' בְּאַתְרֵיהּ (ס\"א בסופיה). מַאי דְּמָסַר טַעְמָא, בְּגִין דִנְפִילָה דָא דְּמָסַר בַּר נָשׁ נַפְשֵׁיהּ לְמוֹתָא אִיצְטְרִיךְ לְכַוְּונָא רְעוּתֵיהּ וּלְמֶעֱבָּד נָחַת רוּחַ לְהַהוּא סִטְרָא דְּשַׁרְיָא בֵּיהּ מוֹתָא, כְּמָה דְּעָבִיד הַקוֹף בְּחֲרַבָה בְּהָרִים. אַחֲזֵי גַּרְמֵיהּ כְּמִית קָמֵיהּ חַיּוֹת, בְּגִין דְּדָחִיל מִנְהוֹן. וְכָד קְרִיבִין לְגַבֵּיהּ וַחֲשִׁיבֵי לְמֵיכָל וּלְקַטְלָא יָתֵיהּ, חֲמָאן יָתֵיהּ דְנָפִיל וּמִית וְחֲשִׁיבֵי דְּאִיהוּ מִית וּכְדֵין תַבָן לַאֲחוֹרָא. וְעַל דָּא אִסְתָּלָקוּ תְלַת אַתְוָון אִלֵּין, דְּלָא יָדְעֵי בְּהוּ אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי.","וְעִם כָּל דָּא בִּרְעוּתָא דְּלִבָּא שָׁוֵי גַּרְמֵיהּ וּמָסַר לֵיהּ נַפְשֵׁיהּ בִּרְחִימוּ, וְקוּדְשָׁא בְּרִיךְ הוּא חָשִׁיב עֲלוֹי כְּאִילוּ נָטִיל נִשְׁמָתֵיהּ מִנֵּיהּ. בְּגִין דְּאִית חוֹבִין דְּעָבִיד בַּר נָשׁ דְּלָא מִתְכַּפְּרָאן אֶלָּא בְּשַׁעֲתָא דְּנַפְקַת נִשְׁמָתֵיהּ מִנֵּיהּ מֵהַאי עַלְמָא. הֲדָא הוּא דִכְתִיב (ישעיהו כ״ב:י״ד) אִם יֵכוּפָּר הַעֲוֹן הַזֶּה לָכֶם עַד תְמוּתוּן. וְהַשְׁתָּא דְּאִתְחֲשִׁיךְ לֵיהּ דְנָטִיל קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתֵיהּ וְאִיהוּ יָהִיב לֵיהּ בִּרְעוּתָא, וְהַהִיא שַׁעְתָּא קַיָימָא לְכַפָּרָה עַל כָּל חוֹבוֹי וְאַשְׁלִים לְכָל סִטְרִין, וּלְהַהוּא סִטְרָא דְּאִתְּמַר.","וְעַל כָּל דָא עוֹלָה וְאִסְתַלְקָא בֵּין תְרֵין דְּרוֹעִין בְּחִבּוּקַא דִּרְחִימוּ כְּדְקָא יֵאוֹת, וְאִיהִי מְקֻטֶרֶת מוֹר וּלְבוֹנָה מִכָּל אַבְקַת רוֹכֵל.","אָמַר רַבִּי שִׁמְעוֹן, אָסִיר לֵיהּ לְבַּר נָשׁ לִטְעוֹם כְּלוּם, עַד דְּיֵכוּל מַלְכָּא עִילָאָה, וּמַאי אִיהוּ צְלוֹתָא. וּצְלוֹתָא דְּבָּר נָשׁ כְּגַוְונָא דָא, בְּקַדְמִיתָא מָזְמִין לְדִיוּקְנִין דְּחַקִיקִין בְּכוּרְסַיָּיא עַל אִינוּן בִּרְיָין דְּמִתְפַּשְּׁטֵי רוּחִין דִּילְהוֹן (ס\"א יסודא) יִחוּדָא בְּהַאי עַלְמָא מִנַיְיהוּ וְהַיְינוּ דִכְתִיב (תהילים ק״ד:כ״ד) מָה רָבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה וגו'. דְאֵיבָרִין דְּאִתְחַזוּן לְקָרְבְּנָא רוּחָא דִּילְהוֹן מִתְפָּשְׁטֵי עֲלַיְיהוּ אַרְבַּע דִּיוּקְנִין וּמְזָמְנָן עַל בִּרְיָין אִלֵּין. וְהַיְינוּ דְּקַאֲמְרִינָן וְהָאוֹפַנִּים וְחַיּוֹת הַקּוֹדֶשׁ וְכָל אִינוּן חֲיָילִין אַחֲרָנִין דְּקָא מִתְפָּשְׁטֵי מִנַיְיהוּ.","וּלְבָתַר כַּהֲנָא רַבָּא קַאָמַר חַד שֶׁמָּא קַדִּישָׁא, הַיְינוּ אַהֲבַת עוֹלָם אַהֲבְתַנוּ וְגוֹ'. וְיִחוּדָא רַבָּא מֵיַחֱדֵּי, דְּהַיְינוּ (דברים ו׳:ד׳-ה׳) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וּלְבָתַר לֵיוָאֵי קָא מִתְעָרֵי לְנִגּוּנָא דְּהַיְינוּ (דברים י״א:י״ג) וְהָיָה אִם שָׁמוֹעַ תִשְׁמֵעוּ וְגוֹ'. דָא נִגוּנַיָא דְּלֵיוָאֵי בְּגִין לְאִתְעָרָא סִטְרָא חַד. וּלְבָתַר יִשְׂרָאֵל, דָא אֱמֶת וְיַצִיב, יִשְׂרָאֵל סָבָא דְקַיְימָא עַל קָרְבְּנָא. דָא הִיא דַּרְגִּין עִלָּאִין פְּנִימָאִין וְכֹלָּא קַיָימָא עַל פָּתוֹרָא.","אֲבָל לֵית רֵשׁוּ לְחַד מִנַיְיהוּ לְאוֹשָׁטָא יְדָא וּלְמֵיכָל מִן קָרְבְּנָא עַד דְּמַלְכָּא עִילָאָה אָכִיל, וְהֵם שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת. כֵּיוָן דְּאִיהוּ אָכִיל, יָהִיב רֵשׁוּ לְאַרְבַּע דִּיוּקְנִין וּלְכָל אִינוּן סִטְרִין דְּמִתְפָּרְשָׁן מִנַיְיהוּ לְמֵיכָל.","כְּדֵין אָדָם דְּאִיהוּ דִּיּוּקְנָא דְּכָלִיל כָּל שְׁאָר, מַאִיךְ וְנָפִיל עַל אַנְפּוֹי וּמָסַר רוּחֵיהּ וְגַרְמֵיה לְגַבֵּי אָדָם דְּחַקוּק עַל אִינוּן דִּיוּקְנִין וּלְאִתְעָרָא לֵיהּ עָלֵיהּ כְּדְקָא חֲזֵי, וְהַיְינוּ אֵלֶיךָ ה' נַפְשִׁי אֶשָּׂא. תְלַת דִּיוּקְנִין אַחֲרָנִין וְכָל אִינוּן דְּמִתְפַּשְּׁטֵי מִנַיְיהוּ, תְּהִלָּה לְדָוִד וְהַיְינוּ יַבִּיעוּ יְרַנְנוּ יֹאמְרוּ יְדַבְּרוּ, כֻּלְּהוּ אַכְלֵי וְאִתְהַנוּן כָּל חַד וְחַד כְּדְּחָזֵי לֵיהּ.","מִכָּאן וּלְהָלְאָה לֵימָא בַּר נָשׁ עָאקוּ דְּלִבֵּיה (תהילים כ׳:ב׳) יַעַנְךָ ה' בְּיוֹם צָרָה עָאקוּ דְּעוּבָּרְתַא דְּיַתְבָא בְּעָאקוּ וּמִתְהַפְּכֵי כֻּלְּהוּ סְנֵיגוֹרִין עָלֵיהּ דְּבַּר נָשׁ. וְשָׁלֹשׁ פְּסִיעוֹת שֶּׁעוֹשֶׂה הַכַּוָּנָה בָּהֶם לְמִכַאֵ\"ל וְגַבְרִיאֵ\"ל רְפָאֵ\"ל שֶׁיָּצָא מִשָּׁלֹשׁ מַחֲנוֹת שְׁכִינָה וְעַל דָא כְּתִיב (תהילים קמ״ד:ט״ו) אַשְׁרֵי הַעֲם שֶׁכָּכָה לוֹ אַשְׁרֵי הַעֲם שֶׂה' אֱלֹהָיו. (כדין וגו' רס\"ה א' שורה י\"ד)","צוּלְמָא עַל בַּר נָשׁ כּוּרְסַיָּיא מֵרוּבָּעַת בְּאַרְבַּע חֵיוָון וְאָדָם לָשֶׁבֶת עַל הַכִּסֵּא. כָּל אֵבֶר וְאֵבֶר דְּהַאי צוּלְמָא אִיהוּ מַלְאַךְ דְּאִיהוּ מְמַנָּא עַל כָּל פִּקּוּדָא ופִּקּוּדָא כְּמָה דּאוּקְמוּהַ מָארֵי מַתְנִיתִין עֲשָׂה מִצְוָה אַחַת קָנָה לוֹ פְּרַקְלִיט אֶחָד.","צוּלְמָא בְּרַשִׁיעַיָּיא עֲבוֹדָה זָרָה, ד' חֵיוָון דִּילֵיהּ, עֲוֹן מַשְׁחִית אַף וְחַמָּה ד' אַנְפִּין דְּעֲבוֹדָה זָרָה נִדָּה, שִׁפְחָה, גּוֹיָה, זוֹנָה. וּבְגִין דָא (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֵת הַאָדָם בְּצַלְמוֹ, דָא מְטַטְרוֹ\"ן. מַאן אֱלֹהִים דְּבָּרָא לֵיהּ, דָא אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ סמ\"אל, דְמִנֵּיהּ אֱלֹהִים אֲחֵרִים דְּאִתְּמַר בֵּיהּ (שמות כ׳:ג׳) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנַי.","אִם זָכָה בָּרָא לֵיהּ אֱלֹהִים בְּצוּלְמָא דממטרו\"ן, עֶבֶד תְחוֹת רַבֵּיהּ. וְהַאי אִיהוּ וַיִּבְרָא אֱלֹהִים אֵת הַאָדָם בְּצַלְמוֹ, בְּהַאי דִּיּוּקְנָא. וְאִם לֹא זָכָה צֶלֶם דְּסמ\"אל. תֲנִינָא מַלְאַךְ הַמָּוֶת דְּאִיהוּ תְחוֹת רְשׁוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא לְמֵידָן בֵּיהּ בַּר נָשׁ בְּגֵּיהִנָּם, אִם לָאו הוּא צַדִּיק."],[],[[0,"","לְאַהַד שֶׁסִּיֵּם תְּפִלָּתוֹ וְהוֹדָה עַל חֲטָאָיו - נְפִילַת אַפַּיִם. שֶׁכָּךְ בֵּאֲרוּהָ, שֶׁיַּעֲשֶׂה כָּל מַה שֶּׁעָשָׂה מֹשֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, תְּפִלּוֹת וְתַחֲנוּנִים וּבַקָּשׁוֹת וּנְפִילַת אַפַּיִם, שֶׁכָּתוּב (דברים ט) וָאֶתְנַפַּל לִפְנֵי ה'. וְכֵיוָן שֶׁנִּכְנַס בְּכָל אֵלּוּ הַמַּדְרֵגוֹת הָעֶלְיוֹנוֹת וְנִקְשַׁר הַכֹּל בְּכֻלָּם, יֵשׁ לָרֶדֶת לְמַטָּה. הוֹאִיל וְיָרַד לְמַטָּה, צָרִיךְ נְפִילַת אַפַּיִם בְּאָלֶף בֵּית."],[1,"","מָה הַטַּעַם? כֵּיוָן שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ וְהוֹדָה עַל חֲטָאָיו, מִכָּאן וּלְהָלְאָה מַרְאֶה עַצְמוֹ שֶׁמּוֹסֵר נַפְשׁוֹ לְקוֹנוֹ בְּאַהֲבָה, שֶׁכָּתוּב (תהלים כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. וְנוֹחַ לוֹ לְאוֹתוֹ צַד שֶׁמְּצוּיָה בוֹ מִיתָה, עוֹשֶׂה לוֹ נַחַת."],[2,"","וְעַל זֶה בְּאַלְפָא בֵּיתָא זוֹ אֵין בָּהּ לֹא וָא\"ו וְלֹא קוֹ\"ף וְלֹא בֵּי\"ת, וְיֵשׁ בָּהּ אוֹת פ' בִּמְקוֹמָהּ (בסופה). מִי שֶׁמָּסַר טַעֲמוֹ מִשּׁוּם שֶׁנְּפִילָה זוֹ שֶׁמּוֹסֵר בֶּן אָדָם נַפְשׁוֹ לְמִיתָה, צָרִיךְ לְכַוֵּן רְצוֹנוֹ וְלַעֲשׂוֹת נַחַת רוּחַ לַצַּד הַהוּא שֶׁמְּצוּיָה בוֹ מִיתָה, כְּמוֹ שֶׁעוֹשֶׂה הַקּוֹף בֶּחָרָבָה בֶהָרִים; מַרְאֶה עַצְמוֹ כְּמוֹ מֵת בִּפְנֵי הַחַיּוֹת, מִשּׁוּם שֶׁמְּפַחֵד מֵהֶם, וְכַאֲשֶׁר מִתְקָרְבִים אֵלָיו וְחוֹשְׁבִים לֶאֱכֹל וְלַהֲרֹג אוֹתוֹ, רוֹאִים אוֹתוֹ שֶׁנּוֹפֵל וּמֵת, וְחוֹשְׁבִים שֶׁהוּא מֵת, וְאָז חוֹזְרִים לַאֲחוֹרֵיהֶם. וְעַל זֶה הִסְתַּלְּקוּ שָׁלֹשׁ אוֹתִיּוֹת אֵלּוּ שֶׁלֹּא יָדְעוּ בָהֶם אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ."],[3,"","וְעִם כָּל זֶה, בִּרְצוֹן הַלֵּב מֵשִׂים עַצְמוֹ וּמוֹסֵר לוֹ נַפְשׁוֹ בְּאַהֲבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חוֹשֵׁב עָלָיו כְּאִלּוּ נוֹטֵל נִשְׁמָתוֹ מִמֶּנּוּ. מִשּׁוּם שֶׁיֵּשׁ חֲטָאִים שֶׁעוֹשֶׂה אָדָם שֶׁלֹּא מִתְכַּפְּרִים אֶלָּא בְשָׁעָה שֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ מִזֶּה הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כב) אִם יְכֻפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמֻתוּן. וְעַתָּה שֶׁנֶּחְשַׁךְ בַּעֲדוֹ, שֶׁנָּטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת נִשְׁמָתוֹ וְהוּא נָתַן לוֹ בִרְצוֹנוֹ, וְאוֹתָהּ שָׁעָה עוֹמֶדֶת לְכַפָּרָה עַל כָּל חֲטָאָיו וְהִשְׁלִים לְכָל הַצְּדָדִים וּלְאוֹתוֹ צַד שֶׁנִּתְבָּאֵר."],[4,"","וְעִם כָּל זֶה עוֹלָה וְנִכְנֶסֶת בֵּין שְׁתֵּי זְרוֹעוֹת בְּחִבּוּק שֶׁל אַהֲבָה כְּמוֹ שֶׁצָּרִיךְ, וְהִיא מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, אָסוּר לוֹ לָאָדָם לִטְעֹם כְּלוּם עַד שֶׁיֹּאכַל הַמֶּלֶךְ הָעֶלְיוֹן, וּמַה הוּא? תְּפִלָּה. וּתְפִלָּה שֶׁל אָדָם כְּגוֹן זֶה. בָּרִאשׁוֹנָה מַזְמִין לַצּוּרוֹת שֶׁחֲקוּקוֹת בַּכִּסֵּא עַל אֵלּוּ הַבְּרִיּוֹת שֶׁמִּתְפַּשְּׁטוֹת הָרוּחוֹת שֶׁלָּהֶם (יסוד) בְּיִחוּד בְּזֶה הָעוֹלָם מֵהֶם, וְזֶה שֶׁכָּתוּב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה וְגוֹ'. שֶׁאֵיבָרִים שֶׁרְאוּיִים לְקָרְבָּן, רוּחַ שֶׁלָּהֶם מִתְפַּשֶּׁטֶת עֲלֵיהֶם אַרְבַּע צוּרוֹת וּמְזֻמֶּנֶת עַל בְּרִיּוֹת אֵלּוּ. וְזֶה שֶׁאָנוּ אוֹמְרִים וְהָאוֹפַנִּים וְחַיּוֹת הַקֹּדֶשׁ, וְכָל אוֹתָם חֲיָלוֹת אֲחֵרִים שֶׁהֵם מִתְפַּשְּׁטִים מֵהֶם."],[6,"","וּלְבַסּוֹף כֹּהֵן גָּדוֹל אוֹמֵר שֵׁם אֶחָד קָדוֹשׁ, וְזֶה אַהֲבַת עוֹלָם אֲהַבְתָּנוּ וְגוֹ'. וְיִחוּד גָּדוֹל מְיַחֲדִים, וְזֶה (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וְאַחַר כָּךְ הַלְוִיִּם הֵם מְעוֹרְרִים לְנִגּוּן, וְזֶהוּ (דברים יא) וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ וְגוֹ'. זֶה נִגּוּן הַלְוִיִּם כְּדֵי לְעוֹרֵר צַד אֶחָד. וְאַחַר יִשְׂרָאֵל, זֶה אֱמֶת וְיַצִּיב, יִשְׂרָאֵל סָבָא שֶׁעוֹמֵד עַל הַקָּרְבָּן. זוֹ הִיא מַדְרֵגוֹת עֶלְיוֹנוֹת פְּנִימִיּוֹת, וְהַכֹּל עוֹמֵד עַל הַשֻּׁלְחָן."],[7,"","אֲבָל אֵין רְשׁוּת לְאֶחָד מֵהֶם לְהוֹשִׁיט יָדוֹ וְלֶאֱכֹל מִן הַקָּרְבָּן עַד שֶׁהַמֶּלֶךְ הָעֶלְיוֹן יֹאכַל, וְהֵם שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת. כֵּיוָן שֶׁהוּא אוֹכֵל, נוֹתֵן רְשׁוּת לְאַרְבַּע צוּרוֹת וּלְכָל אֵלּוּ הַצְּדָדִים שֶׁמִּתְפַּשְּׁטִים מִמֶּנּוּ, לֶאֱכֹל."],[8,"","אָז אָדָם שֶׁהוּא צוּרָה שֶׁכּוֹלֵל כָּל הַשְּׁאָר, יוֹרֵד וְנוֹפֵל עַל פָּנָיו וּמוֹסֵר רוּחוֹ וְעַצְמוֹ לְגַבֵּי אָדָם שֶׁחָקוּק עַל אֵלּוּ הַצּוּרוֹת וּלְעוֹרֵר לוֹ עָלָיו כְּמוֹ שֶׁרָאוּי, וְזֶה אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. שָׁלֹשׁ צוּרוֹת אֲחֵרוֹת, וְכָל אֵלּוּ שֶׁמִּתְפַּשְּׁטִים מֵהֶם - תְּהִלָּה לְדָוִד, וְזֶה יַבִּיעוּ יְרַנֵּנוּ יֹאמֵרוּ יְדַבֵּרוּ - כֻּלָּם אוֹכְלִים וְנֶהֱנִים כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ."],[9,"","מִכָּאן וְאֵילָךְ יֹאמַר אָדָם צָרַת לִבּוֹ, (תהלים כ) יַעַנְךְ ה' בְּיוֹם צָרָה. צָרָה עַל הַמְעֻבֶּרֶת שֶׁיּוֹשֶׁבֶת עַל הַמַּשְׁבֵּר, וּמִתְהַפְּכִים כֻּלָּם לִהְיוֹת סָנֵגוֹרִים עַל הָאָדָם. וְשָׁלֹשׁ פְּסִיעוֹת שֶׁעוֹשֶׂה, הַכַּוָּנָה בָּהֶן לְמִיכָאֵ\"ל וְגַבְרִיאֵ\"ל רְפָאֵ\"ל שֶׁיָּצָא מִשָּׁלֹשׁ מַחֲנוֹת שְׁכִינָה, וְעַל זֶה כָּתוּב (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו. (ע\"כ מההשמטות)"],[10,"","צֶלֶם עַל אָדָם כִּסֵּא מְרֻבָּע בְּאַרְבַּע חַיּוֹת וְאָדָם לָשֶׁבֶת עַל הַכִּסֵּא. כָּל אֵיבָר וְאֵיבָר שֶׁל זֶה הַצֶּלֶם הוּא מַלְאָךְ שֶׁהוּא מְמֻנֶּה עַל כָּל מִצְוָה וּמִצְוָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, עָשָׂה מִצְוָה אַחַת - קָנָה לוֹ פְּרַקְלִיט אֶחָד."],[11,"","צֶלֶם בָּרְשָׁעִים עֲבוֹדָה זָרָה, אַרְבַּע חַיּוֹת שֶׁלּוֹ - עָוֹן מַשְׁחִית אַף וְחֵמָה, אַרְבַּע פָּנִים שֶׁל עֲבוֹדָה זָרָה - נִדָּה שִׁפְחָה גּוֹיָה זוֹנָה. וּמִשּׁוּם זֶה, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, זֶה מְטַטְרוֹ\"ן. מִי הָאֱלֹהִים שֶׁבָּרָא אוֹתוֹ? זֶה אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, סָמָאֵ\"ל, שֶׁמִּמֶּנּוּ אֱלֹהִים אֲחֵרִים, שֶׁנֶּאֱמַר בּוֹ (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי."],[12,"","אִם זָכָה - בָּרָא אוֹתוֹ אֱלֹהִים בְּצֶלֶם שֶׁל מְטַטְרוֹ\"ן, עֶבֶד תַּחַת רַבּוֹ. וְזֶהוּ וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, בְּזוֹ הַצּוּרָה. וְאִם לֹא זָכָה - צֶלֶם שֶׁל סָמָאֵ\"ל. לָמַדְנוּ, מַלְאַךְ הַמָּוֶת שֶׁהוּא תַחַת רְשׁוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לָדוּן בּוֹ אָדָם בַּגֵּיהִנָּם, אִם לֹא שֶׁהוּא צַדִּיק."]]],[["וּבְגִין דָא וַיִּיצֶר, יְצִירָה לְטַב, מְטַטְרוֹ\"ן. לְמֶעְבַּד (למהוי) לֵיהּ עוֹזֵר בְּאוֹרַיְיתָא בְּפִקּוּדִין, וְהַאי אִיהוּ אֱעֶשֶׂה לוֹ עֵזֶר. וְאִם לֹא זָכָה, יְצִירָה לְבִּישׁ, סמ\"אל. דְּאִיהוּ כְּנֶגְדּוֹ לְמֶחטֵי לֵיהּ לְמֵידָן לֵיהּ בְּגֵּיהִנָּם. וְתַרְוַיְהוּ אַזְלִין עִם בַּר נָשׁ בִתְּרֵין צוּלְמִין.","וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, דָא צוּלְמָא דְקוּדְשָׁא בְּרִיךְ הוּא, שְׁכִינְתָּא דְּאִתְּמַר בָּהּ וּמַלְכוּתוֹ בְּכָל מַשָׁלָה. וְקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי צוּלְמָא שָׁלִיט עַל תַּרְוַיְהוּ. וְהַאי צוּלְמָא תֵּיבַת נֹחַ. עוֹרֵב וּבַת זוּגוֹ לְקֳבֵּל קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ","בְּגָלוּתָא, אֲרְמִיז רָזָא דָא. וַיְשַׁלַּח אֵת הַעוֹרֵב בְּקַדְמִיתָא, דָא יֵצֶר הַרָע דְשָׁלַח לֵיהּ עִם בַּר נָשׁ בְּהַאי עַלְמָא דְאַקְדִּים, כְּגַוְונָא דְאַקְדִּים לְּיַעֲקֹב וּכְגַוְונָא דְּתְבֶן דְאַקְדִּים לַחִטָּה. אִי אַשְׁכַּח הַהוּא גּוּף מְחוּיָב בְּכַמָּה חוֹבִין, מֵלוּכְלָּךְ בְּטִנּוּפִין דְעֲבֵירוֹת. אִתְּמַר בֵּיהּ, וְלָא חָזַר עוֹרֵב בִּשְׁלִיחוּתָא דְּמָארֵיהּ. לְבָתַר וַיְשַׁלַּח אֵת הַיּוֹנָה מֵאִתּוֹ, דָא יֵצֶר הַטּוֹב:","פִּקּוּדָא לְיַבֶּם אֵשֶׁת הַאָח. וְרָזָא דָא הַא אוּקִימְנָא, דְּאִיהוּ עֲבִיד טִיבוּ וּקְשׁוֹט עִם אֲחוּהִי מֵיתָא, דְּלָא לִישְׁתְצֵי מֵהַהוּא עַלְמָא. בְּגִין דְּהַהוּא בַּר נָשׁ דְּמִית בְּלָא בְּנִין לָא אַעְבַּר כּוֹתַלָא דְפַרְזְלָא לְמֵיעָל גּוֹ פַּלְטֵרִין דְּמַלְכָּא.","בְּגִין דְּכֹתָלָא דְפַרְזְלָא קַיָימָא בֵּין הַאי עַלְמָא לְעַלְמָא אַחֲרָא, וְבַתַר הַהוּא כּוֹתַלָא קַיְימָן אֶלֶף וְשִׁיתִין רִיבּוֹא מַלְאֲכֵי חַבָּלָה, וְכֻלְּהוּ אִקְרוּן מָארֵי תְרִיסִין, מָארֵי דְּבָבוּ. סַיְיפֵי שְׁנַנָן דְּנוּרָא מֵלַהָטַן בִּידַיְיהוּ. וְגּוֹ הַהוּא כּוֹתַלָא אִית גבֵּיהּ] שִׁיתִּין אַלְפֵי הֵיכָלִין דְחַשׁוֹכָא. וְכָל הֵיכָלָא וְהֵיכָלָא אִית בֵּיהּ כַּוִין פְּתִיחָן לְגֵיהִנָּם.","וְכָל אִינוּן דְּלָא זָכוּ בְּבָּנִין בְּהַאי עַלְמָא, כַּד נַפְקִין מִינֵיהּ וְאַזְלִין לְאָעָלָא לְהַהוּא עַלְמָא אַחֲרָא וּפָגְעוּ גּוֹ הַהוּא כּוֹתַלָא. וְנָפְקִין כָּל אִינוּן מָארֵי תְרִיסִין וְטַרְדִין לוֹן, וְעָאלִין לוֹן גּוֹ אִינוּן הֵיכָלִין וְיַתְבִין תַּמָּן עַד דְיִתְפָּרְקוּן. וּבְכָל יוֹמָא וְיוֹמָא טַעֲמִין טַעְמָא דְגֵיהִנָּם, אַף עַל גַּב דְּאִיהוּ זַכָּאָה. בָּר אִי זְכוּתֵיהּ סַגִּי וּזְכוּתָא דְּאַבָהָן. וְהָנֵי אִינוּן דְאִשְׁתְדָלוּ בְּהוּ וְלָא יָכְלוּ. בְּגִין דְכָל אִינוּן דְּלָא אִתְפְּשָׁט מִנְּהוֹן דִּיּוּקְנָא דִּלְעֵילָּא בְּהַאי עַלְמָא לָא עָאלִין גּוֹ הַהוּא עַלְמָא.","וְכָל אִינוּן דְּלָא אִשְׁתָדְלוּ בְּהַאי עַלְמָא בִּבְּנִין כַּד נַפְקֵי מֵהַאי עַלְמָא קְרִיבוּ גּוֹ הַאי כּוֹתַלָא וְנָפְקִין הַנְהוּ מָארֵי תְרִיסִין וְטַרְדִין לוֹן בְּנוּרָא מְלַהֲטָא. וְגּוֹ אִינוּן הֵיכָלִין אִית הֵיכָלָא חֲדָא. וְהַהוּא הֵיכָל אִקְרֵי הֵיכָל פּוֹעֲלֵי אָוֶן, וְנָטְלִין לֵיהּ וְעָאלִין לֵיהּ בְּהַהוּא הֵיכָלָא וְתַּמָּן אִתְטְרִיד בְּכָל יוֹמָא וְדָא קָשֶׁה מֵגֵּיהִנָם. אִי אִית לֵיהּ פָרוֹקָא, יֵאוֹת. וְאִי לָאו, לָא נָפִיק מִתַּמָּן לְּעָלְמִין. וְעַל דָּא כְּתִיב (תהילים קכ״ז:ה׳) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֵת אַשְׁפָּתוֹ מֵהֶם וְגּוֹ'.","כַּד אִית לוֹן פָרוֹקָא לְאִינוּן דְּלָא זָכוּ, אִיצְטְרִיךְ לְּהַהִיא אִתְּתָא מַמָּשׁ. דְהוּא שָׁבָק תַּמָּן, בְּאֲתָר דְּנַפְשֵׁיהּ וּרְעוּתֵיהּ הֲוָה שַׁוִי תָּדִיר וְאַדְבָּק בִרְעוּתָא וְתִיאוּבְתָּא. וְכָד אִשְׁתַּמַּשׁ בְּהַהוּא אֲתָר אֲחוּהָ דְּמִיתָא, הַהוּא דַבִּיּקוּ דְתִיאוּבְתָּא דְנַפְשָׁא דְשָׁבָק בְּהַהוּא אֲתָר אִתְעָר בְּאִתְעָרוּתָא דְאִתְּתֵיהּ דְאִתְעֲרָת לְגַבֵּיהּ וְאֲחוּהָ דְּשַׁוִי רְעוּתֵיהּ בְּאַחֲוָה בְּהַהוּא אֲתָר. כְּדֵין אִתְעָרוּ דָא מִתְעָר לְהַהוּא מֵיתָא בְּאִינוּן הֵיכָלִין וְנָפַק מִתַּמָּן.","וְחַד מְמַנָּא מֵאִינוּן מָארֵי תְרִיסִין אָתֵי עִמֵּיהּ וְאִתְהַדָר בַּר נָשׁ לְהַהוּא אֲתָר וְיָשׁוּב לִימֵי עֲלוּמָיו. הַהוּא מְמַנָּא קָרֵי עָלֵיהּ, וַוי דְּנָפִיק אַגְרֵיהּ בְּטִיקוּלֵיהּ. מַאן דְהָוָה סִיב אִתְהַדָר רַבְיָא לְחַיָּכָא בֵּיהּ. וְעִם כָּל דָּא, קוּדְשָׁא בְּרִיךְ הוּא רְעוּתֵיהּ לְמֶעְבַּד עִמֵּיהּ טִיבוּ לְאִתְתַּקְנָא בְּהַאי עַלְמָא,","וְדָא אִיהוּ דְּמָארֵיהּ אִתְרְעֵי בֵּיהּ. רַבְיָא מִתְרֵיסָר שְׁנִין דְּלָא אַשְׁלִים לְעֲשְׁרִין אוֹ דְּאִיהוּ רַבְיָא דְּלָא נָסִיב, קוּדְשָׁא בְּרִיךְ הוּא אַעְקַר לֵיהּ, וְשָׁתִיל לֵיהּ לְבָתַר בְּסִטְרָא דְאָבוֹי בְּקַשְׁיוּ, וְדָא לָא אָזִיל לְהַהוּא כּוֹתַלָא. בֵּין גַּן עֵדֶן וְגֵיהִנָם אִיכָּא חַד טִינָרָא וְדָא הוּא טִינָרָא דְמַחְלוֹקֶת. אֲמַאי אִקְרֵי הָכִי, בְּגִין דְכָל בְנֵי עַלְמָא עַבְדִּין פְּלִיגָּא בְּמָארֵיהוֹן עַל הַהוּא רַבְיָא. וְקוּדְשָׁא בְּרִיךְ הוּא חָמֵי בֵּיהּ דְּלָא יִצְלָח, דְּאִי אִתְקַשֵׁי לָא אִתְנַטַּע בִּנְטִיעָא שַׁפִּיר. וְהַשְׁתָּא דְּאִיהוּ רְכִּיכָא וְיֵאוֹת לְאִתְעֲקְרָא, אִתְעַקָר וְשָׁתִיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא.","כַּד אִתְעַקָר עֲאל לְגַבֵּיהּ הַהוּא טִינָרָא וְתַּמָּן הֵיכָלִין יְדִיעָאן לְאִילֵין וַחֲיָלִין וּמַשִּׁירְיָין סַגִּיאִין קַיְימִין תַּמָּן דְמְמוּנִין עֲלַיְיהוּ. וְכֻלְּהוּ בְּחוּשְׁבָּנָא קַיְימֵי, וְקַיְימֵי תַּמָּן עַד דְאִתְפְּרִיקוּ בְּסִטְרָא דְאָבוֹי. וְאִי לָאו אֲבוֹי, זִמְנִין דְּקַיְימֵי לְחַמְשִׁין שְׁנִין וְעָבִיד בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא טִיבוּ וְאִיפְרָק בִּקְרִיבָא דְקָרִיב לֵיהּ אוֹ אֲחוּהָ. וְכַמָּה פִרוּקֵי אַזְמִין קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא בַּר נָשׁ.","גוּפָא קַדְמָאָה מָה תְּהֵא מִנֵּיהּ. שְׁאֵלְתָּא שָׁאִילּוּ קָמֵיהּ חַבְרַיָּיא, אִי יִתְקַיַּים הַהוּא גוּפָא, אִי לָאו. אִי תֵימָא דְּלָא יִתְקַיַּים, וְכִי יֵיבְדוּן עוֹבָדֵי יְדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. אִי חַיָּיבָא הֲוָה סַגִּי וְלָא אִתְחֲזֵי לְאִתְקַיְימָא, לָא שְׁאִילְנָא. דְּוַדַּאי אִתְאֲבִיד וְלָא אִתְקַיַּים. אֲבָל כַּמָה אִינוּן דְאִתְהֲדָרוּ לְהַאי עַלְמָא וְאִתְתְּקָנוּ גוּפָא מָה תְּהֵא מִנֵּיהּ.","הַהוּא גוּפָא לָא אִתְאֲבִיד, דְהָא קוּדְשָׁא בְּרִיךְ הוּא לָא יֵאַבֵּד עוֹבָדֵי יְדוֹי וּבִּרְיָין זְמִינִין לְמֶעְבַּד מִנַיְיהוּ. וְאִינוּן הֲווּ גּוּפִין דְאִתְהַדְרָן בְּלָא רוּחָא. כַּד זָמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחָיָיא מֵתַיָּיא, אִלֵּין יִתְבְּנוּן וִיקוּמוּן אַרְבְּעִין יוֹמִין בְּלָא רוּחָא. וְקוּדְשָׁא בְּרִיךְ הוּא חַס עֲלַיְיהוּ וּמְשַׁדֵר עֲלַיְיהוּ רוּחָא דְנַשִׁיב בְּגִנְתָּא דְעֵדֶן וִיקוּמוּן בְּקִיּוּמֵיהוֹן וִיהוֹן שַׁמָּשִׁין לצַדִּיקַיָּיא דְמִתְעֲסְקִין בְּאוֹרַיְיתָא. וְאִלֵּין יְמוּתוּן כְּמִלְקַדְמִין וּלְבָתַר יְקַיְמוּן לוֹן,"],[],[[0,"","וּמִשּׁוּם זֶה וַיִּיצֶר, יְצִירָה לְטוֹב, מְטַטְרוֹ\"ן, לַעֲשׂוֹת (להיות) לוֹ עוֹזֵר בַּתּוֹרָה בַּמִּצְווֹת, וְזֶהוּ אֶעֱשֶׂה לּוֹ עֵזֶר. וְאִם לֹא זָכָה, יְצִירָה לְרַע, סָמָאֵ\"ל, שֶׁהוּא כְנֶגְדּוֹ לְהַחֲטִיא אוֹתוֹ לָדוּן אוֹתוֹ בַּגֵּיהִנָּם. וּשְׁנֵיהֶם הוֹלְכִים עִם הָאָדָם בִּשְׁנֵי צְלָמִים."],[1,"","וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - זֶה הַצֶּלֶם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁכִינָה, שֶׁנֶּאֱמַר בָּהּ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט בַּצֶּלֶם הַזֶּה עַל שְׁנֵיהֶם, וְהַצֶּלֶם הַזֶּה תֵּבַת נֹחַ. עוֹרֵב וּבַת זוּגוֹ, כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בַגָּלוּת רוֹמֵז סוֹד זֶה."],[2,"","וַיְשַׁלַּח אֶת הָעֹרֵב - בָּרִאשׁוֹנָה. זֶה יֵצֶר הָרָע שֶׁשָּׁלַח לוֹ עִם הָאָדָם בָּעוֹלָם הַזֶּה שֶׁמַּקְדִּים, כְּמוֹ שֶׁהִקְדִּים לְיַעֲקֹב וּכְמוֹ שֶׁתֶּבֶן מַקְדִּים לַחִטָּה. אִם נִמְצָא הַגּוּף הַהוּא מְחֻיָּב בְּכַמָּה חוֹבוֹת, מְלֻכְלָךְ בְּטִנֹּפֶת הָעֲבֵרוֹת, נֶאֱמַר בּוֹ וְלֹא חָזַר הָעוֹרֵב בַּשְּׁלִיחוּת שֶׁל אֲדוֹנוֹ. לְבַסּוֹף - וַיְשַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ. זֶה יֵצֶר הַטּוֹב (ע\"כ מההשמטות):"],[3,"","מִצְוָה לְיַבֵּם אֵשֶׁת הָאָח. וְסוֹד זֶה הֲרֵי בֵּאַרְנוּ, שֶׁהוּא עוֹשֶׂה טוֹב וֶאֱמֶת עִם אָחִיו הַמֵּת שֶׁלֹּא יִכָּרֵת מֵהָעוֹלָם הַהוּא. מִשּׁוּם שֶׁאוֹתוֹ אָדָם שֶׁמֵּת בְּלֹא בָנִים, לֹא עָבַר כֹּתֶל שֶׁל בַּרְזֶל לְהִכָּנֵס תּוֹךְ הֵיכַל הַמֶּלֶךְ."],[4,"","מִשּׁוּם שֶׁכֹּתֶל שֶׁל בַּרְזֶל קַיָּם בֵּין הָעוֹלָם הַזֶּה לָעוֹלָם הָאַחֵר, וְאַחַר אוֹתוֹ הַכֹּתֶל עוֹמְדִים אֶלֶף וְשִׁשִּׁים רִבּוֹא מַלְאֲכֵי חַבָּלָה, וְכֻלָּם נִקְרָאִים בַּעֲלֵי מָגִנִּים, בַּעֲלֵי אֵיבָה. חֲרָבוֹת מְשֻׁנָּנוֹת שֶׁל אֵשׁ לוֹהֲטוֹת בִּידֵיהֶם. וְתוֹךָ אוֹתוֹ כֹתֶל יֵשׁ (בו) שִׁשִּׁים אֶלֶף הֵיכָלוֹת שֶׁל חֹשֶׁךְ. וְכָל הֵיכָל וְהֵיכָל יֵשׁ בּוֹ חַלּוֹנוֹת פְּתוּחִים לַגֵּיהִנָּם."],[5,"","וְכָל אֵלּוּ שֶׁלֹּא זָכוּ בְּבָנִים בָּעוֹלָם הַזֶּה, כַּאֲשֶׁר יוֹצְאִים מִמֶּנּוּ וְהוֹלְכִים לְהִכָּנֵס לְאוֹתוֹ עוֹלָם אַחֵר וּפָגְעוּ תוֹךְ אוֹתוֹ כֹתֶל, וְיוֹצְאִים כָּל אֵלּוּ בַּעֲלֵי מָגִנִּים וְטוֹרְדִים אוֹתָם, וּמַכְנִיסִים אוֹתָם תּוֹךְ אֵלּוּ הַהֵיכָלוֹת וְיוֹשְׁבִים שָׁם עַד שֶׁיִּגָּאֲלוּ. וּבְכָל יוֹם וָיוֹם טוֹעֲמִים טַעַם שֶׁל גֵּיהִנָּם, אַף עַל גַּב שֶׁהוּא זַכַּאי, חוּץ מֵאִם שֶׁזְּכוּתוֹ גְדוֹלָה וּזְכוּת אֲבוֹתָיו. וְאֵלּוּ הֵם שֶׁהִשְׁתַּדְּלוּ בָהֶם וְלֹא יָכְלוּ. מִשּׁוּם שֶׁכָּל אֵלּוּ שֶׁלֹּא הִתְפַּשְּׁטָה מֵהֶם הַצּוּרָה שֶׁל מַעְלָה בְּזֶה הָעוֹלָם, לֹא עוֹלִים תּוֹךְ הָעוֹלָם הַהוּא."],[6,"","וְכָל אֵלּוּ שֶׁלֹּא הִשְׁתַּדְּלוּ בְּזֶה הָעוֹלָם בְּבָנִים, כַּאֲשֶׁר יוֹצְאִים מִזֶּה הָעוֹלָם מִתְקָרְבִים תּוֹךְ הַכֹּתֶל הַזֶּה, וְיוֹצְאִים אוֹתָם בַּעֲלֵי מָגִנִּים וְטוֹרְדִים אוֹתָם בְּאֵשׁ לוֹהֶטֶת. וְתוֹךְ אֵלּוּ הַהֵיכָלוֹת יֵשׁ הֵיכָל אֶחָד, וְאוֹתוֹ הֵיכָל נִקְרָא הֵיכַל פּוֹעֲלֵי אָוֶן, וְלוֹקְחִים אוֹתוֹ וּמַכְנִיסִים אוֹתוֹ בְּאוֹתוֹ הֵיכָל, וְשָׁם נִטְרָד בְּכָל יוֹם וָיוֹם, וְזֶה קָשֶׁה מִגֵּיהִנָּם. אִם יֵשׁ לוֹ גוֹאֵל - טוֹב, וְאִם לֹא - לֹא יוֹצֵא מִשָּׁם לְעוֹלָמִים. וְעַל זֶה כָּתוּב (תהלים קכז) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם וְגוֹ'."],[7,"","כַּאֲשֶׁר יֵשׁ לָהֶם גּוֹאֵל לְאֵלּוּ שֶׁלֹּא זָכוּ, צָרִיךְ לְאוֹתָהּ אִשָּׁה מַמָּשׁ שֶׁהוּא עָזַב שָׁם, בְּמָקוֹם שֶׁנַּפְשׁוֹ וּרְצוֹנוֹ הָיָה שָׁם תָּמִיד וְנִדְבַּק בְּרָצוֹן וְהִשְׁתּוֹקְקוּת. וְכַאֲשֶׁר הִשְׁתַּמֵּשׁ בְּאוֹתוֹ מָקוֹם אָחִיו שֶׁל הַמֵּת, אוֹתָהּ הִתְדַבְּקוּת שֶׁל הַתְּשׁוּקָה שֶׁל הַנֶּפֶשׁ שֶׁעָזַב בְּאוֹתוֹ מָקוֹם מִתְעוֹרֶרֶת בְּהִתְעוֹרְרוּת הָאִשָּׁה שֶׁמִּתְעוֹרֶרֶת אֵלָיו וְאָחִיו שֶׁשָּׂם רְצוֹנוֹ בְאַחֲוָה בְּאוֹתוֹ מָקוֹם. אָז הִתְעוֹרְרוּת זוֹ מְעוֹרֶרֶת לְאוֹתוֹ מֵת בְּאֵלּוּ הַהֵיכָלוֹת וְיוֹצֵא מִשָּׁם."],[8,"","וּמְמֻנֶּה אֶחָד מֵאֵלּוּ בַּעֲלֵי מָגִנִּים בָּא עִמּוֹ, וְחוֹזֵר אָדָם לְאוֹתוֹ מָקוֹם וְיָשׁוּב לִימֵי עֲלוּמָיו. אוֹתוֹ מְמֻנֶּה קוֹרֵא עָלָיו: אוֹי שֶׁיָּצָא שְׂכָרוֹ בְּהֶפְסֵדוֹ. מִי שֶׁהָיָה זָקֵן, חוֹזֵק תִּינוֹק לְצַחֵק בּוֹ. וְעִם כָּל זֶה, הַקָּדוֹשׁ בָּרוּךְ הוּא רְצוֹנוֹ לַעֲשׂוֹת עִמּוֹ טוֹבָה לְתַקְּנוֹ בְּזֶה הָעוֹלָם, וְזֶהוּ שֶׁאֲדוֹנוֹ מִתְרַצֶּה בוֹ. נַעַר מִשְּׁתֵּים עֶשְׂרֵה שָׁנִים שֶׁלֹּא הִשְׁלִים לְעֶשְׂרִים אוֹ שֶׁהוּא נַעַר שֶׁלֹּא נָשׂוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר אוֹתוֹ, וְשׁוֹתֵל אוֹתוֹ לְבַסּוֹף בְּצַד אָבִיו בְּקֹשִׁי, וְזֶה לֹא הוֹלֵךְ לְאוֹתוֹ כֹתֶל."],[9,"","בֵּין גַּן עֵדֶן וְגֵיהִנָּם יֵשׁ סֶלַע אֶחָד, וְזֶה הוּא סֶלַע הַמַּחֲלֹקֶת. מַדּוּעַ נִקְרָא כָּךְ? מִשּׁוּם שֶׁכָּל בְּנֵי הָעוֹלָם עוֹשִׂים מַחֲלֹקֶת בְּרִבּוֹנָם עַל אוֹתוֹ נַעַר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה בּוֹ שֶׁלֹּא יַצְלִיחַ, שֶׁאִם יִתְקַשֶּׁה, לֹא נִנְטַע בַּנְּטִיעָה טוֹב. וְעַתָּה שֶׁהוּא רַךְ וְרָאוּי לְעָקְרוֹ, נֶעֱקָר, וְשׁוֹתֵל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[10,"","כַּאֲשֶׁר נֶעֱקָר, עוֹלֶה אֵצֶל אוֹתוֹ סֶלַע, וְשָׁם הֵיכָלוֹת יְדוּעִים לְאֵלּוּ, וַחֲיָלוֹת וּמַחֲנוֹת רַבִּים עוֹמְדִים שָׁם שֶׁמְּמֻנִּים עֲלֵיהֶם. וְכֻלָּם בְּחֶשְׁבּוֹן עוֹמְדִים, וְעוֹמְדִים שָׁם עַד שֶׁיִּגָּאֲלוּ מִצַּד שֶׁל אָבִיו. וְאִם לֹא אָבִיו, לְעִתִּים עוֹמְדִים לַחֲמִשִּׁים שָׁנָה, וְעוֹשֶׂה בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹבָה וְנִגְאָל בִּקְרוֹבוֹ שֶׁקָּרוֹב לוֹ אוֹ אָחִיו. וְכַמָּה גְאֻלּוֹת מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ אָדָם."],[11,"","הַגּוּף הָרִאשׁוֹן מַה יִּהְיֶה מִמֶּנּוּ? שְׁאֵלָה שָׁאֲלוּ לִפְנֵי הַחֲבֵרִים, אִם יִתְקַיֵּם אוֹתוֹ גוּף אִם לֹא. אִם תֹּאמַר שֶׁלֹּא יִתְקַיֵּם, וְכִי יֹאבְדוּ מַעֲשֵׂה יָדָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא?! אִם חַיָּב הָיָה הַרְבֵּה וְלֹא רָאוּי לְהִתְקַיֵּם, לֹא שָׁאַלְתִּי. שֶׁוַּדַּאי נֶאֱבָד וְלֹא יִתְקַיֵּם. אֲבָל כַּמָּה הֵם שֶׁחוֹזְרִים לְזֶה הָעוֹלָם וְנִתְקְנוּ גוּפָם, מַה יִּהְיֶה מִמֶּנּוּ?"],[12,"","הַגּוּף הַהוּא לֹא נֶאֱבָד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יְאַבֵּד מַעֲשֵׂה יָדָיו, וּבְרִיּוֹת מְזֻמָּנוֹת לַעֲשׂוֹת מִמֶּנּוּ. וְאֵלּוּ הָיוּ גוּפִים שֶׁחוֹזְרִים בְּלִי רוּחַ. כַּאֲשֶׁר עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת הַמֵּתִים, אֵלּוּ יִבָּנוּ וְיָקוּמוּ אַרְבָּעִים יוֹם בְּלִי רוּחַ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וְשׁוֹלֵחַ עֲלֵיהֶם רוּחַ שֶׁנּוֹשֶׁבֶת בְּגַן עֵדֶן, וְיָקוּמוּ עַל עָמְדָם וְיִהְיוּ שַׁמָּשִׁים לַצַּדִּיקִים שֶׁעוֹסְקִים בַּתּוֹרָה. וְאֵלּוּ יָמוּתוּ כְּמִקֹּדֶם, וְאַחַר כָּךְ יָקוּמוּ לָהֶם,"]]],[["וְעַל דָּא כְּתִיב (קהלת ד׳:ב׳) וְשַׁבַּח אֲנִי אֵת הַמֵּתִים שֶׁכְּבָר מֵתוּ, מִקַּדְמָת דְּנָא. כַּד יְקוּמוּן יִנְדְּעוּן לְמָארֵיהוֹן יְדִיעָה דְּלָא בְּרִירָא כִּשְׁאָר בְּנֵי נָשָׁא וְאִלֵּין שַׁמָּשִׁין דְעֲמָא קַדִּישָׁא. בְּסִפְרָא דִשְׁלֹמֹה עַל אִלֵּין גוּפִין כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְשֵׁנֵי אַדְמַת עֲפַר יָקִיצוּ אֵלֶּה וְגּוֹ' וְאֵלֶּה וְגּוֹ'. בֵּין זַכָּאִין בֵּין חַיָּיבִין יְקוּמוּן, וְעַל דָּא כְּתִיב בְּהוּ בְּאוֹרַח סָתִים, וְרַבִּים. וְלָא כְּתִיב מַאן אִינוּן.","וּבְגִין כָּל דָא אַף עַל גַּב דְּאַמְרִינָן דְּאִתַּבָּרוּ לָאו הָכִי. דְהָא לֵית לָן גוּפָא מֵאִלֵּין דְּלָא יְקוּמוּן מִדּוֹר הַמַּבּוּל וְדוֹר הַפָּלַגָה, וְיִתְבְּרוּן כְּמִלְקַדְמִין. דוֹר הַמַּבּוּל מָה כְּתִיב בְּהוּ כִּי הִשְׁחִית כָּל בָּשָׂר אֵת דַּרְכּוֹ, מְחַבְּלִין הַהוּא שָׁיְיפָא. בְּגִין כָּךְ אִתְעַנְשׁוּ. אוּף הָכָא כָּל אִינוּן דְּלָא זָכוּ לִבְנִין, לֵית לוֹן חוּלָקָא בְּהַהוּא עַלְמָא עַד דְמִתְתַקְנָן. וַאֲפִילּוּ לְחַמְשִׁין דָרִין אַהְדַּר לוֹן קוּדְשָׁא בְּרִיךְ הוּא כְּמָה דְּאִתְּמַר.","פִּקּוּדָא לַחֲלוֹץ אֵת יְבִמְתוֹ, הַא אִתְּמַר הוֹאִיל וְלֵית רְעוּתָא דְּהַאי אוֹ דְּהַאי, וְלָא אִתְתַּקְּנָן בְּחַבִיבוּ, אִית לַחֲלוֹץ. וְאִי תֵּימָא בְּאֲתָר דְּשַׁרְיָין חַיִּים אִית סַנְדָּל בְּשַׁפִּירוּ דְּתִקּוּנָא דְרַגְלִין, דִּכְתִיב (שיר השירים ז׳:ב׳) מָה יָפוּ פְּעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב וְגּוֹ' בְּגִין דְדָא אִיהוּ אֲתָר דְּשַׁרְיָין בֵּיהּ חַיִּים.","וּבַאֲתַר דְּשַׁרְיָא בֵּיהּ מוֹתָא לֵית סַנְדָּל כְּלָל, בְּגִין דְּאִיהוּ סִטְרָא דְּלֵית בֵּיהּ תִיקוּנָא דְרַגְלִין דְּבַּר נָשׁ. וּבְגִין כָּךְ לֵית בֵּיהּ סַנְדָּל. וְכָל אִינוּן סִטְרִין דְּמִתְפַּשְׁטִין מִנֵּיהּ, כּוּלְּהוּ מְשַׁנְיָין רַגְלִין עַד דְּאִשְׁתַּנֵי כְּרַגְלָא דְתַרְנֵגוֹלָא.","מָלְכַּת שְׁבָא כְּתִיב (מלכים א י׳:א׳) וַתָּבֹא לְנָסוֹתוֹ בְחִידוֹת, חֲדָא דְּעָבִיד לְרַגְלוֹי סָנְדְּלָא דְּסִטְרָא אוֹחֲרָא. מָה כְּתִיב (מלכים א י׳:א׳) וַיַּגֵּד לָהּ הַמֶּלֶךְ אֵת כָּל לְבָבַהּ, וְלָא כְּתִיב וַיַעֲשׂ לָהּ. גָלֵי לָהּ רָזָא וְלָא אִצְטְרִיךְ לְמֶעְבָּד לָהּ סָנְדְּלָא, דְלָאו אוֹרְחָא לְהַאי סִטְרָא בְּהַאי.","וּבְגִין כָּךְ מַאן דְּחָמֵי בְּחֶלְמֵיהּ דְּיַהֲבִין לֵיהּ סָנְדָלִין לְרַגְלוֹי, וַדַּאי חַיִּין אִתְמָסְרִין לֵיהּ. וּמָאן דְּחָמֵי דְאַעֲדָן מִנֵּיהּ סָנְדְּלָא, בְּדִינָא סִטְרָא אוֹחֲרָא יִתְמֶסָר, אִי לָא יֵתוּב. וְעַל דָּא אִית לְאַשְׁלַפָא לְהַאי וּלְמֵיהַב לֵיהּ גּוֹ עַפְרָא,","רָזָא דָא סָנְדְּלָא דְּאִיהוּ רָגִיל בֵּיהּ לָא תִשְׁלוֹף, בְּגִין דְּלָא לְאַעֲדָאָה מִנֵּיהּ. אֲבָל אִיצְטְרִיךְ סָנְדְּלָא אַחֲרָא לְמִשְׁלָף מִנֵּיהּ, וְכַמָּה אִינוּן. וְאִלֵּין מָארֵי תְרִיסִין בְּהַהוּא סִטְרָא דְמִתְכַּנְפֵי תַּמָּן לְאַנְעֲלָא הַהוּא סָנְדְּלָא לְהַהוּא סִטְרָא, וְלָא יַכְלִין.","אַהְדַּר לְגַבֵּיהּ הַהוּא מֵיתָא וְקָא טָעִין עָלֵיהּ קָמֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא לְמֵיחָס עָלֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא חַס עָלֵיהּ. וּבְגִין הַהוּא סָנְדְּלָא, אַהְדַּר לְהַהוּא אֲתָר אַרְבְּעִין יוֹמִין וְאִתְעָדֵי מֵהַהוּא מֵיתָא וְכָל אִינוּן מָארֵי תְרִיסִין דִּילֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ עוֹנָשָׁא וּפָרִיק לֵיהּ,","אֲבָל לָא עֲאל גּוֹ מַקְדְּשָׁא. וַאֲתָר מִתְתַּקְנָא לְהוּ לְבָר מִגִּנְתָא דְעֵדֶן וְתַּמָּן קַיְימִין וְאוֹדָן וּמְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא וְחָמָאן לֵיהּ מֵרָחִיק וְהַהוּא נְהִירוּ דְעִדוּנָא דְּצַדִּיקַיָּיא בְּגִנְתָּא דְעֵדֶן וְאִכְסָפוּ בְּעוֹבָדִין. זַכָּאִין אִינוּן צַדִּיקַיָּיא בְּעָלְמָא דֵין וּבְּעָלְמָא דְאָתֵי.","וְכָל אַתְוָון אִלֵּין אִינוּן (ס\"א דינין) לְסִטְרִין אַחֲרָנִין וּלְחַיָבַיָּיא, אִינוּן כְּשָׁלְשְׁלַאִין וְרוּמְחִין לְשַׁיְיפִין. תְרוּעָה שַׁלְשֶׁלֶת וּתְרֵין תְרוּעוֹת בַּעֲשָׂרָה שׁוֹפָרוֹת וְאִינוּן חַד מִן קשר\"ק, וְתִנְיָינָא מִן קר\"ק, וְאִינוּן עַמּוּדָא דְאֶמְצָעִיתָא. וְתַנְיָא צַדִּיק","כָּל חַד עַמּוּדָא דְאֶמְצָעִיתָא יִשְׂרָאֵל. שְׁלִישִׁיָה לִתְקִיעָה דְאַבְרָהָם רַחֲמִין פְּשׁוּטִים וְלִשְׁבָרִים דְּיִצְחָק דִינִין תַבְרִין דְלִבָּא, דִּשְׁבָרִים לְשׁוֹן תְּבִירוּ אִינוּן, הֲדָא הוּא דִכְתִיב (שמות כ״ג:כ״ד) שַׁבֵּר תְּשַׁבֵּר מַצֵבוֹתֵיהֶם. צַדִּיק אִיהוּ שַׁלְשֶׁלֶת תְלִיתָאָה מְמוּצָע בֵּין צְבָאוֹת דִּילֵיהּ תְרֵין שִׂפְוָון, תְקִיעָה לְפָנֶיהָ וּתְקִיעָה לְאַחֲרֶיהָ.","שְׁתֵּי חַצוֹצְרוֹת כֶּסֶף אִתְקְרִיאוּ כַּד נָטְלֵי מְרַחֲמֵי דְּאִיהוּ יְמִינָא, שְׁנָיִם כְּרוּבִים זָהָב אִתְקְרִיאוּ מִסִטְרָא דִגְבוּרָה דְּתַמָּן כְּרוּבִים, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְכֻלְּהוּ עֶשֶׂר אִתְקְשָׁרוּ בְּקֶשֶׁר אַחֵר דְּאִיהוּ סִימָן קש\"ר תקיע\"ה שברי\"ם תרוע\"ה.","לְקֳבְּלֵיהּ קֶשֶׁר שֶׁל תְפִילִין וְאוּקְמוּהָ רַבָּנָן, הֵרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִילִין וְדָא עַמּוּדָא דְאֶמְצָעִיתָא קִשׁוּרָא דִּתְלַת אֲבָהָן לְעֵילָּא, וְצַדִּיק קִשׁוּרָא דְנֶצָ\"ח הוֹ\"ד יְסוֹ\"ד. וְהַאי אִיהוּ קֶשֶׁר בְּתוֹךְ קֶשֶׁר, חוֹתָם בְּתוֹךְ חוֹתָם לְמֶהֱוֵי חַמְרָא דְּאוֹרַיְיתָא נָטִיר מִלְּגָאו,","וְהָכִי חוּלְיָא לֵית פָּחוֹת מִתְלַת כְּרִיכַן. וְדָא שְׁכִינְתָּא דְּאִיהִי בַּת יְחִידָא קִשׁוּרָא בְּשִׁין דְשַׁבָּת, אִיהוּ אוֹת דִתְפִלִּין קִשׁוּרָא בְּשִׁין דִתְפִלִּין דְּאִיהִי תְלַת עַנְפֵי דְּאַבָהָן. וְדָא יֵ\"שׁ דְּשַׁדַּ\"י אִשְׁתָּאַר דַלֶי\"ת לְמֶהוֵי אַרְבַּע בָּתֵּי דִתְפִלִּין. בְּהַאי קִשׁוּרָא אִתְקַשַׁר שֵׁ\"ד בְשַׁלְשֶׁלֶת, בְּקִשׁוּרָא דִתְפִלִּין בְּזִמְנָא דְּאִיהוּ קַשִׁיר. אִם יַצִילֵהוּ אֱלוֹהַ יִפְטוֹר גַּרְמֵיהּ מִשַׁלְשְׁלָאָהּ דְּמַלְכָּא.","בְּגִין דִּתְּרוּעָה אִיהִי בַדָּעַת וְאִיהִי עַמּוּדָא דְאֶמְצָעִיתָא, קֶשֶׁר תְלַת אֲבָהָן. אַשְׁרֵי הַעֲם יוֹדְעֵי תְרוּעָה, וְלֹא אָמַר שׁוֹמְעֵי. וּמִיַּד דְאִתְקַשַׁר שְׂמֹאלָא בִּיְמִינָא, אִתְכַּפְיָיא דִינָא וְאִתְגַבַּר רַחֲמֵי. וְקִשּׁוּרָא דְתַרְוַויְיהוּ דָּעַת. שַׁלְשֶׁלֶת קָשׁוּר בִתְקִיעָה וּשְׁבָרִים."],[],[[0,"","וְעַל זֶה כָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, מִזְּמַן קַדְמוֹן. כַּאֲשֶׁר יָקוּמוּ, יֵדְעוּ אֶת קוֹנָם יְדִיעָה שֶׁאֵינָהּ בְּרוּרָה כִּשְׁאָר בְּנֵי אָדָם, וְאֵלּוּ שַׁמָּשִׁים שֶׁל הָעָם הַקָּדוֹשׁ. בְּסִפְרוֹ שֶׁל שְׁלֹמֹה עַל אֵלּוּ הַגּוּפִים כָּתוּב, (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה וְגוֹ' וְאֵלֶּה וְגוֹ'. בֵּין צַדִּיקִים בֵּין רְשָׁעִים - יָקוּמוּ, וְעַל זֶה כָּתוּב בָּהֶם בְּאֹרַח סָתוּם - וְרַבִּים, וְלֹא כָתוּב מִי אֵלּוּ."],[1,"","וּמִשּׁוּם כָּל זֶה, אַף עַל גַּב שֶׁאָמַרְנוּ שֶׁנִּשְׁבְּרוּ - לֹא כָּךְ. שֶׁהֲרֵי אֵין לָנוּ גוּף מֵאֵלּוּ שֶׁלֹּא יָקוּמוּ מִדּוֹר הַמַּבּוּל וְדוֹר הַפְּלַגָּה, וְיִשָּׁבְרוּ כְמִקֹּדֶם. דּוֹר הַמַּבּוּל מַה כָּתוּב בָּהֶם? כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ, מַשְׁחִיתִים אוֹתוֹ אֵיבָר. מִשּׁוּם זֶה נֶעֶנְשׁוּ. אַף כָּאן, כָּל אֵלּוּ שֶׁלֹּא זָכוּ לְבָנִים, אֵין לָהֶם חֵלֶק בְּאוֹתוֹ עוֹלָם עַד שֶׁמִּתְתַּקְּנִים. וַאֲפִלּוּ לַחֲמִשִּׁים דּוֹרוֹת מַחֲזִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","מִצְוָה לַחֲלֹץ אֶת יְבִמְתּוֹ, הֲרֵי נִתְבָּאֵר הוֹאִיל וְאֵין רָצוֹן שֶׁל זֶה אוֹ שֶׁל זֶה וְלֹא נִתְקַן בַּחֲבִיבוּת, יֵשׁ לַחֲלֹץ. וְאִם תֹּאמַר, בְּמָקוֹם שֶׁמְּצוּיִים חַיִּים יֵשׁ סַנְדָּל בַּיֹּפִי שֶׁל תִּקּוּנֵי הָרַגְלַיִם, שֶׁכָּתוּב (שיר השירים ז) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב וְגוֹ', מִשּׁוּם שֶׁזֶּה הוּא מָקוֹם שֶׁמְּצוּיִים בּוֹ חַיִּים."],[3,"","וּבְמָקוֹם שֶׁמְּצוּיָה בוֹ מִיתָה אֵין סַנְדָּל כְּלָל, מִשּׁוּם שֶׁהוּא צַד שֶׁאֵין בּוֹ תִּקּוּן שֶׁל רַגְלֵי בְּנֵי אָדָם, וּמִשּׁוּם זֶה אֵין בּוֹ סַנְדָּל. וְכָל אֵלּוּ הַצְּדָדִים שֶׁמִּתְפַּשְּׁטִים מִמֶּנּוּ, כֻּלָּם מְשֻׁנֵּי רַגְלַיִם עַד שֶׁמִּשְׁתַּנֶּה כְּרַגְלֵי הַתַּרְנְגוֹל."],[4,"","בְּמַלְכַּת שְׁבָא כָּתוּב (מלכים א י) וַתָּבא לְנַסֹּתוֹ בְּחִידוֹת, אֶחָד שֶׁעָשָׂה לְרַגְלָיו סַנְדָּל שֶׁל הַצַּד הָאַחֵר. מַה כָּתוּב? (שם) וַיַּגֶּד לָהּ הַמֶּלֶךְ אֶת כָּל לְבָבָהּ (דבריה), וְלֹא כָתוּב וַיַּעַשׂ לָהּ. גִּלָּה לָהּ הַסּוֹד וְלֹא הִצְטָרֵךְ לַעֲשׂוֹת לָהּ סַנְדָּל, שֶׁאֵין דֶּרֶךְ לְאוֹתוֹ צַד בָּזֶה."],[5,"","וּמִשּׁוּם זֶה מִי שֶׁרוֹאֶה בַחֲלוֹמוֹ שֶׁנּוֹתְנִים לוֹ סַנְדָּלִים לְרַגְלָיו, וַדַּאי שֶׁחַיִּים נִמְסְרוּ לוֹ. וּמִי שֶׁרוֹאֶה שֶׁפּוֹשְׁטִים מִמֶּנּוּ סַנְדָּל, בְּדִין צַד הָאַחֵר יִמָּסֵר אִם לֹא יָשׁוּב. וְעַל זֶה יֵשׁ לִשְׁלֹף לָזֶה וְלָתֵת אוֹתוֹ תּוֹךְ עָפָר,"],[6,"","סוֹד זֶה סַנְדָּל שֶׁהוּא רָגִיל בּוֹ לֹא יִשְׁלֹף, כְּדֵי שֶׁלֹּא יָסוּר מִמֶּנּוּ. אֲבָל צָרִיךְ סַנְדָּל אַחֵר לִשְׁלֹף מִמֶּנּוּ, וְכַמָּה הֵם. אֵלּוּ בַּעֲלֵי מָגִנִּים בְּאוֹתוֹ צַד שֶׁמִּתְאַסְּפִים שָׁם לְהַנְעִיל אוֹתוֹ סַנְדָּל לְאוֹתוֹ צַד, וְלֹא יְכוֹלִים."],[7,"","חוֹזֵר אֵצֶל אוֹתוֹ מֵת וּבָא בִטְעָנוֹת עָלָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָחוּס עָלָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו. וּמִשּׁוּם אוֹתוֹ סַנְדָּל חוֹזֵר לְאוֹתוֹ מָקוֹם אַרְבָּעִים יָמִים וְסָר מֵאוֹתוֹ מֵת, וְכָל אֵלּוּ בַּעֲלֵי מָגִנִּים שֶׁלּוֹ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ עֹנֶשׁ וְגוֹאֵל אוֹתוֹ,"],[8,"","אֲבָל לֹא נִכְנָס תּוֹךְ הַמִּקְדָּשׁ. וּמָקוֹם מְתֻקָּן לָהֶם מִחוּץ לְגַן עֵדֶן, וְשָׁם עוֹמְדִים וּמוֹדִים וּמְשַׁבְּחִים לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְרוֹאִים אוֹתוֹ מֵרָחוֹק וְאֶת אוֹתוֹ הָאוֹר שֶׁל עִדּוּן הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן וּמִתְבַּיְּשִׁים בְּמַעֲשֵׂיהֶם. אַשְׁרֵיהֶם הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[9,"","וְכָל הָאוֹתִיּוֹת הָאֵלּוּ הֵן (דינים) לִצְדָדִים אֲחֵרִים וּלְחַיָּבִים, הֵן כְּשַׁלְשְׁלָאוֹת וּרְמָחִים לָאֵיבָרִים. תְּרוּעָה שַׁלְשֶׁלֶת וּשְׁתֵּי תְרוּעוֹת בַּעֲשָׂרָה שׁוֹפָרוֹת, וְהֵם אֶחָד מִן קשר\"ק, וְשֵׁנִי מִן קר\"ק, וְהֵם הָעַמּוּד הָאֶמְצָעִי. וְלָמַדְנוּ, צַדִּיק"],[10,"","כָּל אֶחָד הָעַמּוּד הָאֶמְצָעִי - יִשְׂרָאֵל. שְׁלִישִׁיָּה לַתְּקִיעָה שֶׁל אַבְרָהָם רַחֲמִים פְּשׁוּטִים, וְלַשְּׁבָרִים שֶׁל יִצְחָק דִּינִים שׁוֹבְרִים אֶת הַלֵּב, שֶׁשְּׁבָרִים לְשׁוֹן שְׁבִירָה הֵם, זֶהוּ שֶׁכָּתוּב (שמות כג) (ו) שַׁבֵּר תְּשַׁבֵּר מַצֵּבתֵיהֶם. צַדִּיק הוּא שַׁלְשֶׁלֶת שְׁלִישִׁי מְמֻצָּע בֵּין צְבָאוֹת שֶׁלּוֹ שְׁתֵּי שְׂפָתַיִם, תְּקִיעָה לְפָנֶיהָ וּתְקִיעָה לְאַחֲרֶיהָ."],[11,"","שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף נִקְרָאוֹת כַּאֲשֶׁר נוֹטְלִים מֵרַחֲמִים שֶׁהוּא יָמִין. שְׁנַיִם כְּרוּבִים זָהָב נִקְרָאִים מִצַּד הַגְּבוּרָה שֶׁשָּׁם כְּרוּבִים, וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְכָל הָעֶשֶׂר נִקְשָׁרִים בְּקֶשֶׁר אֶחָד שֶׁהוּא סִימַן קֶשֶׁ\"ר - תְּקִיעָ\"ה שְׁבָרִי\"ם תְּרוּעָ\"ה."],[12,"","כְּנֶגְדּוֹ קֶשֶׁר שֶׁל תְּפִלִּין, וּבֵאֲרוּהוּ חֲכָמִים, הֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִלִּין, וְזֶה עַמּוּד הָאֶמְצָעִי, קִשּׁוּר שֶׁל שְׁלֹשֶׁת הָאָבוֹת לְמַעְלָה, וְצַדִּיק קִשּׁוּר שֶׁל נֵצַ\"ח הוֹ\"ד יְסוֹ\"ד. וְזֶהוּ קֶשֶׁר בְּתוֹךְ קֶשֶׁר, חוֹתָם בְּתוֹךְ חוֹתָם, לִהְיוֹת הַיַּיִן שֶׁל הַתּוֹרָה שָׁמוּר מִבִּפְנִים,"],[13,"","וְכָךְ חֻלְיָה אֵין פָּחוֹת מִשָּׁלֹשׁ כְּרִיכוֹת. וְזוֹ הַשְּׁכִינָה שֶׁהִיא בַּת יְחִידָה קְשׁוּרָה בָּאוֹת שִׁי\"ן שֶׁל שַׁבָּת, הִיא אוֹת שֶׁל תְּפִלִּין קְשׁוּרָה בָּאוֹת שִׁי\"ן שֶׁל הַתְּפִלִּין, שֶׁהִיא שְׁלֹשָׁה עֲנָפִים שֶׁל הָאָבוֹת, וְזֶה אוֹתִיּוֹת יֵ\"שׁ שֶׁל שַׁדַּ\"י. נִשְׁאֲרָה אוֹת דָּלֶי\"ת לִהְיוֹת אַרְבָּעָה בָּתֵּי הַתְּפִלִּין. בְּזְהִ הַקֶּשֶׁר נִקְשָׁר שֵׁ\"ד בְּשַׁלְשֶׁלֶת בַּקֶּשֶׁר שֶׁל הַתְּפִלִּין בִּזְמַן שֶׁהוּא קָשׁוּר. אִם יַצִּילֵהוּ אֱלוֹהַּ, יִפְטֹר עַצְמוֹ מִשַּׁלְשְׁלָאוֹת הַמֶּלֶךְ,"],[14,"","מִשּׁוּם שֶׁתְּרוּעָה הִיא בַּדַּעַת וְהִיא הָעַמּוּד הָאֶמְצָעִי, קֶשֶׁר שֶׁל שְׁלֹשָׁה אָבוֹת. אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, וְלֹא אָמַר שׁוֹמְעֵי. וּמִיָּד שֶׁנִּקְשָׁר הַשְּׂמֹאל בַּיָּמִין, נִכְפֶּה הַדִּין וּמִתְגַּבְּרִים הָרַחֲמִים.וְהַקֶּשֶׁר שֶׁל שְׁנֵיהֶם - דַּעַת. שַׁלְשֶׁלֶת קְשׁוּרָה בִתְקִיעָה וּשְׁבָרִים."]]],[["וְעַל דָא פֶּסַח יְמִינָא, רֹאשׁ הַשָׁנָה שְׂמָאלָא, עַמּוּדָא דְאֶמְצָעִיתָא מַתָּן תּוֹרָה. וְאִינוּן שִׁבְעָה בְּשִׁבְעָה מוּצָקוֹת, וְאִינוּן שְׁכִינָה עִילָאָה כְּלִילָא מִשֶׁבַע סְפִירִין. שְׁכִינָה תַּתָּאָה בַּת שֶׁבַע וְאִינוּן אַרְבֵּיסָר.","עַמּוּדָא דְאֶמְצָעִיתָא כַּלִיל תַּרְוַויְיהוּ בְּיַד יְהוָֹ\"ה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְכָל שֶׁבַע מִסִטְרָא דִּשְׁכִינְתָּא. הֲדָא הוּא דִכְתִיב (תהילים קי״ט:קס״ד) שֶׁבַע בַּיוֹם הִלַּלְתִּיךָ, לְקֳבְּלַהָא עַבְדִין שֶׁבַע הַקָּפוֹת.","סוּכָּ\"ה יאהדו\"נהי, כ\"ו ה\"ס. וְקוּדְשָׁא בְּרִיךְ הוּא לוּלָב, וּשְׁכִינְתָּא אֶתְרוֹג. לוּלָב דּוֹמֶה לְגוּפָא וְאֶתְרוֹג לְלִבָּא. וּבְגוּפָא אִית חַ\"י חוּלְיָין, לוּלָב חַ\"י נִעְנוּעִין דְלוּלָב. בִּנְטִילַת לוּלָב חַ\"י נִעְנוּעִין בְּאֲנָא ה', חַ\"י נִעְנוּעִין בְּהוֹדוּ לַה', חַ\"י נִעְנוּעִין תְּחִילָה וָסוֹף ע\"ב, לְמִבְרַח בְּהוֹן ע\"ב מְמָנָן דִמְמַנָּן עַל רוּחִין בִּישִׁין וּטְלָלִין בִּישִׁין.","שִׁבְעַת יוֹמֵי דְסוּכָּה שֶׁבַע סְפִירָן. סוּכָּה אִימָא עִילָאָה דִמְסָכְּכַא עֲלַיְיהוּ. נִסוּךְ הַמַּיִם וְנִיסוּךְ הַיָּיִן מִסִטְרָא דִּיְמִינָא וּשְׂמָאלָא וְחַג שְׁמִינִי חַג עֲצֶרֶת שְׁכִינְתָּא תַּתָּאָה, בְּרַתָּא דְּמַלְכָּא וּמַטְרוֹנִיתָא.","אֵלֶה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִקְרֵאוּ אוֹתָם בְּמוֹעֲדָם, לְצִיפְרָא דִּמְצַפְצְפִין לָהּ בְּנָהָא בְּכָל יוֹמָא בְּכַמָּה צִפְצוּפִין, וְאִיהִי רְבִיעַת עֲלַיְיהוּ. בָּתַר דְאִתְרָבִּיאוּ גַדְפַיְיהוּ דִבְּנָהָא, פַּרְחוּ כֻּלְּהוּ בָּתַר אִימָא. צַיָּיד חַד הֲוָה חַכִּים, בָּעָא לְצַיְּידָא לוֹן. מָה עֲבָד צַיָּיד, נָטַל לְאִימָא דִּילְהוֹן וְקָשִׁיר לָהּ, וְאִיהִי צַוְוחַת בְּגִין בְּנָהָא, שָׁמְעוּ בְּנִין קַלָּה וְנַחְתוּ לְגַבָּהּ וְקַשִׁירוּ לוֹן. כְּגַוְונָא דָא אִימָא עִילָאָה דְּאִתְּמַר בָּהּ (דברים כ״ב:ו׳) וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים אוֹ עַל הַבֵּצִים וְאִינוּן יִשְׂרָאֵל מְצַפְצְפִין לָהּ בְּכַמָּה צִפְצוּפִין דִצְלוֹתִין וְכוּ':","תָּנוּ רַבָּנָן, כְּשֶׁחָלָה רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי. עָאלוּ קַמֵּיהּ ר' פִּנְחָס, וְר' חִיָּיא, וְר' אַבָּהוּ. אָמְרוּ לוֹ, מַאן (דהוא) קְיָימָא דְעָלְמָא, שָׁכִיב. אָמַר לוֹן, לָא בִּי דִּינָא דִּלְעֵילָא מְעַיְינִין בְּדִינָאי, דְּהָא אֲנָא חֲזָאי דְּלֵית אֲנָא מִתְיְיהִיב לְמַלְאָכָא וּלְדַיָּינָא דִלְעֵילָא. דַּאֲנָא לָאו כִּשְׁאָר בְּנֵי נָשָׁא.","אֶלָּא הַאי דִינָא דִּילִי, קוּדְשָׁא בְּרִיךְ הוּא דַּיְינֵיהּ, וְלָא בִּי דִּינֵיהּ. וְהַיְינוּ דְּאָמַר דָּוִד, בְּבָעוּתֵיהּ קַמֵּיהּ (תהילים מ״ג:א׳) שָׁפְטֵנִי אֱלֹהִים וְרִיבָה רִיבִי. וְכֵן שְׁלֹמֹה אָמַר, (מלכים א ח׳:נ״ט) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ, הוּא בִּלְחוֹדוֹי, וְלָא אַחֲרָא.","דְּהָא תְנָן (תנינן), כְּשֶׁהָאָדָם שָׁכִיב, בֵּי דִינָא דִּלְעֵילָא מִסְתַּכְּלִין בְּדִינוֹי, אִית מִנְּהוֹן דְּנָטָאן לְכַף זְכוּת, דְּאַחְזְיָין זְכוּתָא דְּבַר נָשׁ, וְאִית מִנְּהוֹן דְּנָטָאן לְכַף חוֹבָה, דְּאַחְזְיָין חוֹבָה דְּבַר נָשׁ. וְלָא נָפִיק אִינִישׁ מִן דִּינָא, כְּמָה דְּהֲוָה בָּעֵי.","אֲבָל מַאן דְּדָאִין לֵיהּ מַלְכָּא עִילָּאָה, דְּשַׁלִּיט עַל כּוֹלָא, הוּא טַב, וְלָא יָכִיל אִינִישׁ לְמֶהֱוֵי בְּהַהוּא דִינָא, בַּר טַב. מַאי טַעְמָא, דְּהָא תְנָן, מְכִילוֹי דְּמַלְכָּא עִילָּאָה, נָטֵי לִזְכוּתָא תָּדִיר, וְהוּא כּוּלֵיהּ צַד דִּמְהֵימָנוּתָא, וּבְיָדוֹ לְשָׁבְקָא לְחֶטְאִין וְחוֹבִין, הֲדָא הוּא דִכְתִיב, (תהילים ק״ל:ד׳) כִּי עִמְךָ הַסְּלִיחָה וְגו', וְלֹא עִם אַחֵר.","וּבְגִין כָּךְ בָּעֵינָא קַמֵּיהּ דְּהוּא (יהא) יָדִין דִּינָאי, וַאֲנָא אָעֵיל תְּלֵיסַר אַבָּבֵי לְעָלְמָא דְאָתֵי, דְּלָא אֲעֲבָרוּ לוֹן בַּר אֲבָהָתָא, וְלָא יְהֵא מַאן דְּיִמְחֵי בְּיָדִי, וְעוֹד דְּלָא אֶתְבַּע רְשׁוּתָא מִנְּהוֹן.","אָמַר רַבִּי שִׁמְעוֹן מִלָּה, וְחָמוּ בֵּי מַרְעֵיהּ, דְּלָא הֲוָה תַּמָּן. תְּוָוהוּ, וְלָא (הוה) יָכִיל חַד מִנְּהוֹן לְמַלָּלָא בְּפוּמֵיהּ, מִדְחִילוּ רַבָּה דַּהֲוָת עֲלֵיהוֹן. עַד דַּהֲווֹ יָתְבִין, סָלִיק לוֹן רֵיחִין דְּבוּסְמֵי סַגִּיאִין, וְכָל חַד וְחַד מִנְּהוֹן אִתְיַישַׁב, עַד דְּחָמוּ לְרַבִּי שִׁמְעוֹן, וַהֲוָה מְמַלֵּל מִלִּין, וְלָא הֲוָה חָמָאן אַחֲרָן בַּר מִינֵיהּ.","לְבָתַר עִידָן, אָמַר לוֹן רַבִּי שִׁמְעוֹן, חֲמִיתּוּן מִידֵי. אָמַר לֵיהּ ר' פִּנְחָס, לָא. אֶלָּא כּוּלָּנָא תְּוָוהִין עַל דְּלָא חָמֵינָא לָךְ בְּבֵי מַרְעָךְ זְמַן רַב. וְכַד חָמֵינָא לָךְ סָלֵיק לָן רֵיחִין דְּבוּסְמִין דְּגִנְתָּא דְּעֵדֶן, וְשָׁמַעְנָא קָלָךְ מְמַלֵּל, וְלָא יְדַעְנָא מָאן מְמַלֵּל עִמָּךְ.","אָמַר לוֹן, וְלָא שְׁמַעְתּוּן מִלָּה אוֹחֲרָנָא בַּר מִדִּידִי. אָמְרוּ לָאו. אָמַר לוֹן, לֵית אַתּוּן חַזְיָין לְמֶחמֵי סְבַר אַפִּין דְּעַתִּיק יוֹמִין.","אָמַר לוֹן, אֵימָא לְכוּ מִלָּה, תְּוַוהְנָא עַל ר' פִּנְחָס, דְּלָא חָמָא. דַּאֲנָא חָמִית לֵיהּ כְּעַן בְּהַהוּא עָלְמָא, לְתַתָּא מִינֵיהּ מֵרַבִּי אֶלְעָזָר בְּרִי.","וּכְעַן שָׁדְרוּ בְּדִילִי מִלְּעֵילָא, וְאַחְזְיָן לִי אַתְרָא דְּצַדִּיקַיָא לְעָלְמָא דְּאָתֵי, וְלָא אִתְיְישַׁר בְּלִבָּאי דּוּכְתָּאי, בַּר עִם אֲחִיָּה הַשִּׁילוֹנִי. וּבָרֵירְנָא דּוּכְתָּאי, וְאָתֵינָא, וַאֲתוּ עִמִּי תְּלַת מְאָה נִשְׁמָתִין דְּצַדִּיקַיָא, וְעֵילָא מִנְּהוֹן אָדָם הָרִאשׁוֹן, דְּהֲוָה יָתֵיב גַּבָּאי, וְהוּא הֲוָה מְמַלֵּל עִמִּי. וּבָעֵי, דְּלָא יִתְגַּלֵּי חוֹבֵיהּ לְכָל עָלְמָא. בַּר הַהוּא דְּאָמַר אוֹרַיְיתָא בְּגִינֵיהּ, וְאִתְכַּסֵּי בְּהַהוּא אִילָנָא דְּגִנְתָּא דְּעֵדֶן.","וַאֲנָא אֲמֵינָא לֵיהּ דְּהָא חַבְרַיָיא (ס\"א כבר) גִּלּוּ. אָמַר הַהוּא דְּגִלּוּ חַבְרַיָיא בֵּינַיְיהוּ טַב וְשַׁפִּיר, אֲבָל לִשְׁאָר בְּנֵי עָלְמָא לָא. מַאי טַעְמָא, דְּחָס קוּדְשָׁא בְּרִיךְ הוּא עַל יְקָרֵיהּ, וְלָא בָּעָא לְפִרְסוּמֵי חוֹבֵיהּ, אֶלָּא בְּהַהוּא אִילָנָא דַּאֲכִיל מִינֵּיהּ.","וְקוּדְשָׁא בְּרִיךְ הוּא גָּלֵי לֵיהּ (לי) בְּרָזָא דְּקוּדְשָּׁא, לַחֲבֵירַנָא, דְּלָא אִשְׁתָּעוֹ אִינוּן בַּהֲדַיְיהוּ בֵּינַיְיהוּ, וְלָא לְרַוָּוקֵי חַבְרַיָיא, וּלְאִינוּן דְּיֵיתוּן לְעָלְמָא. וְהוּא מִלָּה דְּלָא בָּעֵי כָּל אִינִישׁ, וְטָעֵי בֵּיהּ, לָאו מִשּׁוּם חוֹבָתָא דְחָב, אֶלָּא מִשּׁוּם יְקָרָא דִּשְׁמָא עִילָּאָה, דִּבְנֵי נָשָׁא לָא זְהִירִין בֵּיהּ, וּכְתִיב (שמות ג׳:ט״ו) זֶה שְׁמִי לְעוֹלָם. וְיֵיתוֹן לְמִשְׁאַל מַה דְּלָא צְרִיכֵי לוֹן."],[],[[0,"","וְעַל זֶה פֶּסַח הוּא יָמִין, רֹאשׁ הַשָּׁנָה הוּא שְׂמֹאל, הָעַמּוּד הָאֶמְצָעִי הוּא מַתַּן תּוֹרָה. וְאֵלּוּ שִׁבְעָה בְשִׁבְעָה (ושבעה) מוּצָקוֹת, וְהֵם שְׁכִינָה עֶלְיוֹנָה כְּלוּלָה מִשֶּׁבַע סְפִירוֹת. שְׁכִינָה תַחְתּוֹנָה בַּת שֶׁבַע, וְהֵם אַרְבַּע עֶשְׂרֵה."],[1,"","הָעַמּוּד הָאֶמְצָעִי כָּלוּל מִשְּׁנֵיהֶם בְּי\"ד - יְהֹוָ\"ה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְכָל שֶׁבַע מִצַּד הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (תהלים קיט) שֶׁבַע בַּיּוֹם הִלַּלְתִּיךְ. כְּנֶגְדָּהּ עוֹשִׂים שֶׁבַע הַקָּפוֹת."],[2,"","סוּכָּ\"ה יאהדונה\"י, כ\"ו ה\"ס. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לוּלָב, וְהַשְּׁכִינָה אֶתְרוֹג. לוּלָב דּוֹמֶה לַגּוּף, וְאֶתְרוֹג דּוֹמֶה לַלֵּב. וּבַגּוּף יֵשׁ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, לוּלָב שְׁמוֹנָה עָשָׂר נִעְנוּעִים שֶׁל הַלּוּלָב. וּבִנְטִילַת הַלּוּלָב שְׁמוֹנָה עָשָׂר נִעְנוּעִים בְּאָנָּא ה', שְׁמוֹנָה עָשָׂר נִעְנוּעִים בְּהוֹדוּ לַה', שְׁמוֹנָה עָשָׂר נִעְנוּעִים תְּחִלָּה וָסוֹף - ע\"ב. לְהַבְרִיחַ בָּהֶם ע\"ב מְמֻנִּים שֶׁמְּמֻנִּים עַל רוּחוֹת רָעוֹת וּטְלָלִים רָעִים."],[3,"","שִׁבְעַת יְמֵי הַסֻּכָּה - שֶׁבַע סְפִירוֹת. סֻכָּה - אִמָּא עֶלְיוֹנָה שֶׁמְּסוֹכֶכֶת עֲלֵיהֶם. נִסּוּךְ הַמַּיִם וְנִסּוּךְ הַיַּיִן - מִצַּד שֶׁל יָמִין וּשְׂמֹאל, וְחַג שְׁמִינִי חַג עֲצֶרֶת שְׁכִינָה תַחְתּוֹנָה, בַּת הַמֶּלֶךְ וְהַמַּלְכָּה."],[4,"","אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אֹתָם בְּמֹעֲדָם. לְצִפּוֹר שֶׁמְּצַפְצְפִים לָהּ בָּנֶיהָ בְּכָל יוֹם בְּכַמָּה צִפְצוּפִים, וְהִיא רוֹבֶצֶת עֲלֵיהֶם. אַחַר שֶׁנִּגְדְּלוּ כַנְפֵיהֶם שֶׁל בָּנֶיהָ, עָפוּ כֻלָּם אַחַר אִמָּם. צַיָּד אֶחָד הָיָה חָכָם, רָצָה לָצוּד אוֹתָם. מֶה עָשָׂה הַצַּיָּד? נָטַל אֶת הָאֵם שֶׁלָּהֶם וְקָשַׁר אוֹתָהּ, וְהִיא צוֹוַחַת בִּגְלַל בָּנֶיהָ. שָׁמְעוּ הַבָּנִים קוֹלָהּ וְיָרְדוּ אֶצְלָהּ וְקָשְׁרוּ אוֹתָם. כְּמוֹ זֶה הָאִמָּא הָעֶלְיוֹנָה שֶׁנֶּאֱמַר בָּהּ (דברים כב) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרֹחִים אוֹ עַל הַבֵּיצִים, וְאֵלּוּ יִשְׂרָאֵל מְצַפְצְפִים אֵלֶיהָ בְּכַמָּה צִפְצוּפִים שֶׁל תְּפִלּוֹת וְכוּ': (עד כאן מההשמטות)"],[5,"","שָׁנוּ רַבּוֹתֵינוּ, כְּשֶׁחָלָה רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, נִכְנְסוּ לְפָנָיו רַבִּי פִּנְחָס וְרַבִּי חִיָּיא וְרַבִּי אַבָּא. אָמְרוּ לוֹ, מִי (שהוא) עַמּוּדוֹ שֶׁל הָעוֹלָם, שׁוֹכֵב (מת) ?! אָמַר לָהֶם, לֹא בֵּית דִּין שֶׁל מַעְלָה מְעַיְּנִים בְּדִינִי, שֶׁהֲרֵי אֲנִי רוֹאֶה שֶׁאֵין אֲנִי נִתָּן לַמַּלְאָךְ וְלַדַּיָּן שֶׁל מַעְלָה, שֶׁאֲנִי לֹא כִשְׁאָר בְּנֵי אָדָם."],[6,"","אֶלָּא זֶה הַדִּין שֶׁלִּי, הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אוֹתוֹ וְלֹא בֵית דִּינוֹ. וְזֶה שֶׁאָמַר דָּוִד בְּבַקָּשָׁתוֹ לְפָנָיו, (תהלים מג) שָׁפְטֵנִי אֱלֹהִים וְרִיבָה רִיבִי. וְכֵן שְׁלֹמֹה אָמַר, (מלכים א ח) לַעֲשׂוֹת מִשְׁפַּט עַבְדּוֹ, הוּא לְבַדּוֹ וְלֹא אַחֵר."],[7,"","שֶׁהֲרֵי לָמַדְנוּ, כְּשֶׁאָדָם חוֹלֶה, בֵּית דִּין שֶׁל מַעְלָה מִסְתַּכְּלִים בְּדִינָיו., יֵשׁ מֵהֶם שֶׁנּוֹטִים לְכַף זְכוּת, שֶׁמַּרְאִים זְכוּתוֹ שֶׁל הָאָדָם, וְיֵשׁ מֵהֶם שֶׁנּוֹטִים לְכַף חוֹבָה, שֶׁמַּרְאִים חוֹבָתוֹ שֶׁל הָאָדָם. וְלֹא יוֹצֵא אִישׁ מִן הַדִּין כְּמוֹ שֶׁהָיָה רוֹצֶה."],[8,"","אֲבָל מִי שֶׁדָּן אוֹתוֹ הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁשּׁוֹלֵט עַל הַכֹּל - הוּא טוֹב, וְלֹא יָכוֹל אָדָם לִהְיוֹת בַּדִּין הַזֶּה חוּץ מִטּוֹב. מַה טַּעֲמוֹ? שֶׁהֲרֵי שָׁנִינוּ, מִדּוֹתָיו שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן נוֹטִים לִזְכוּת תָּמִיד, וְהוּא כֻּלּוֹ צַד שֶׁל הָאֱמוּנָה, וּבְיָדוֹ לַעֲזֹּב לַחֲטָאִים וְחוֹבוֹת. זֶהוּ שֶׁכָּתוּב (תהלים קל) עִמְּךְ הַסְּלִיחָה. לְמַעַן תִּוָּרֵא. עִמְּךְ וְלֹא עִם אַחֵר."],[9,"","וּמִשּׁוּם זֶה בִּקַּשְׁתִּי מִלְּפָנָיו שֶׁהוּא יָדוּן דִּינִי, וַאֲנִי אֶכָּנֵס בִּשְׁלֹשָׁה עָשָׂר פְּתָחִים לָעוֹלָם הַבָּא, וְעוֹד, שֶׁלֹּא עָבְרוּ אוֹתָם חוּץ מֵהָאָבוֹת, וְלֹא יִהְיֶה מִי שֶׁיִּמְחֶה בְיָדִי, שֶׁלֹּא אֶתְבַּע רְשׁוּת מֵהֶם."],[10,"","אָמַר רַבִּי שִׁמְעוֹן דָּבָר, וְרָאוּ בֵית חָלְיוֹ שֶׁלֹּא הָיָה שָׁם. תָּמְהוּ, וְלֹא יָכֹל אֶחָד מֵהֶם לְדַבֵּר בְּפִיו מֵאֵימָה גְדוֹלָה שֶׁהָיְתָה עֲלֵיהֶם. עַד שֶׁהָיוּ יוֹשְׁבִים, עָלָה לָהֶם רֵיחוֹת שֶׁל בְּשָׂמִים רַבִּים וְכָל אֶחָד הִתְיַשֵּׁב. עַד שֶׁרָאוּ לְרַבִּי שִׁמְעוֹן, וְהָיָה מְדַבֵּר דְּבָרִים, וְלֹא הָיוּ רוֹאִים אֲחֵרִים חוּץ מִמֶּנּוּ."],[11,"","לְאַחַר זְמַן אָמַר לָהֶם רַבִּי שִׁמְעוֹן, רְאִיתֶם מַשֶּׁהוּ? אָמַר לוֹ רַבִּי פִּנְחָס, לֹא. אֶלָּא כֻּלָּנוּ תְמֵהִים עַל שֶׁלֹּא רָאִינוּ אוֹתְךְ בְּבֵית חָלְיְךְ זְמַן רַב, וְכַאֲשֶׁר רָאִינוּ אוֹתְךְ, עָלָה לָנוּ רֵיחוֹת בְּשָׂמִים שֶׁל גַּן עֵדֶן, וְשָׁמַעְנוּ קוֹל אֶחָד מְדַבֵּר, וְלֹא יָדַעְנוּ מִי מְדַבֵּר עִמְּךְ."],[12,"","אָמַר לָהֶם, וְלֹא שְׁמַעְתֶּם דָּבָר אַחֵר חוּץ מִמֶּנִּי? אָמְרוּ, לֹא. אָמַר לָהֶם, אֵין אַתֶּם רְאוּיִים לִרְאוֹת סֵבֶר פָּנָיו שֶׁל עַתִּיק הַיָּמִים."],[13,"","אָמַר לָהֶם, אֹמַר לָכֶם דָּבָר, תָּמַהְתִּי עַל רַבִּי פִּנְחָס שֶׁלֹּא רָאָה, שֶׁאֲנִי רָאִיתִי אוֹתוֹ כָּעֵת בָּעוֹלָם הַבָּא, לְמַטָּה מִמֶּנּוּ מֵרַבִּי אֶלְעָזָר בְּנִי."],[14,"","וְכָעֵת שָׁלְחוּ בִּשְׁבִילִי מִלְמַעְלָה וְהֶרְאוּ לִי מָקוֹם שֶׁל הַצַּדִּיקִים לָעוֹלָם הַבָּא, וְלֹא הִתְיַשֵּׁב בְּלִבִּי מְקוֹמִי, חוּץ מֵעִם אֲחִיָּה הַשִּׁילוֹנִי. וּבָרַרְתִּי מְקוֹמִי וּבָאתִי, וּבָאוּ עִמִּי נְשָׁמוֹת שֶׁל צַדִּיקִים, וְעֶלְיוֹן מֵהֶם מִנִּשְׁמוֹת הַצַּדִּיקִים - אָדָם הָרִאשׁוֹן, שֶׁהָיָה יוֹשֵׁב אֶצְלִי וְהָיָה מְדַבֵּר עִמִּי, וּבִקֵּשׁ שֶׁלֹּא יִתְגַּלֶּה חֶטְאוֹ לְכָל הָעוֹלָם, חוּץ מֵאוֹתוֹ שֶׁאָמְרָה הַתּוֹרָה בִּגְלָלוֹ וְנִסְתָּר בְּאוֹתוֹ אִילָן שֶׁל גַּן עֵדֶן."],[15,"","וַאֲנִי אָמַרְתִּי לוֹ שֶׁהֲרֵי הַחֲבֵרִים (כבר) גִּלּוּ. אָמַר, אוֹתוֹ שֶׁגִּלּוּ הַחֲבֵרִים בֵּינֵיהֶם - טוֹב, אֲבָל שְׁאָר בְּנֵי הָעוֹלָם לֹא. מָה הַטַּעַם? שֶׁחָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כְּבוֹדוֹ וְלֹא רָצָה לְפַרְסֵם חֶטְאוֹ, אֶלָּא בְּאוֹתוֹ אִילָן שֶׁאָכַל מִמֶּנּוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה לוֹ בַּסּוֹד הַקָּדוֹשׁ לַחֲבֵרֵינוּ, חֲבֵרִים שֶׁלֹּא יְדַבְּרוּ הֵם בָּהֶם בֵּינֵיהֶם, וְלֹא לָרַוָּקִים מֵהַחֲבֵרִים וּלְאֵלּוּ שֶׁיָּבאוּ לָעוֹלָם."],[16,"","וְהוּא דָבָר שֶׁלֹּא צָרִיךְ כָּל אָדָם, וְטוֹעֶה בוֹ, לֹא מִשּׁוּם הַחֵטְא שֶׁחָטָא, אֶלָּא מִשּׁוּם כְּבוֹד הַשֵּׁם הָעֶלְיוֹן שֶׁבְּנֵי אָדָם לֹא זְהִירִים בּוֹ, וְכָתוּב (שמות ג) זֶה שְּׁמִי לְעֹלָם. וְיָבֹאוּ לִשְׁאֹל מַה שֶּׁלֹּא צָרִיךְ לָהֶם."]]],[["וְהַיְינוּ דִּכְתִיב, (שמות י״ט:כ״א) פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת וְנָפַל מִמֶּנּוּ רָב, (מאי ונפל ממנו רב). הָרַב נוֹפֵל וְנִתְפַּס בְּאוֹתוֹ עָוֹן. הַכִי גָּזַרְנָא, הַאי חַבְרָיָיא (ס\"א חברא) דְּאוֹרֵי שְׁמָא קַדִּישָׁא (לכולא), הוּא נָפִיל (ונתפס) וְאִיתָא בְּהַהוּא חוֹבָא, יַתִּיר מִנַּיְיהוּ, דִּכְתִיב וְנָפַל מִמֶּנּוּ רָב, הָרַב נוֹפֵל וְנִתְפַּס בְּאוֹתוֹ עָוֹן.","קָרֵיב לְגַבֵּיהּ רַבִּי אֶלְעָזָר בְּרֵיהּ, אָמַר לֵיהּ, אַבָּא, מָה אֲנָא הָתָם. אָמַר לֵיהּ (ס\"א זכאה חולקך ברי, זמן סגי יהא דלא תתקבר גבאי, אבל) בְּרִי דְּלָא תִּדְכַּר הַכָא אֲבָל בְּהַהוּא עָלְמָא, דּוּכְתָּא דִּידִי וְדִידָךְ בָּרֵירְנָא. זַכָּאִין אֲנָן עִם אִינוּן צַדִּיקַיָא, דְּזַמִּינִין אִינוּן לְשַׁבְּחָא לְמָארֵי עָלְמָא, דְּאִינוּן מַלְאָכִין דְּמִשְׁתַּמְּשִׁין (שמשין) דְּקַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ."],[],[[0,"","וְזֶה שֶׁכָּתוּב (שמות יט) פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת וְנָפַל מִמֶּנּוּ רָב. הָרַב נוֹפֵל וְנִתְפָּס בְּאוֹתוֹ עָוֹן. כָּךְ אֲנִי גּוֹזֵר, אֵלּוּ הַחֲבֵרִים (חבר) שֶׁמְּלַמְּדִים הַשֵּׁם הַקָּדוֹשׁ, הוּא נוֹפֵל וְנִמְצָא בְּאוֹתוֹ חֵטְא יוֹתֵר מֵהֶם, שֶׁכָּתוּב וְנָפַל מִמֶּנּוּ רָב. הָרַב נוֹפֵל וְנִתְפָּס בְּאוֹתוֹ עָוֹן."],[1,"","קָרַב אֶצְלוֹ רַבִּי אֶלְעָזָר בְּנוֹ. אָמַר לוֹ, אַבָּא, מָה אֲנִי שָׁם? אָמַר לוֹ, (אשרי חלקך בני, זמן רב יהיה שלא תקבר אצלי, אבל) בְּנִי, שֶׁלֹּא תִזָּכֵר כָּאן. אֲבָל בְּאוֹתוֹ עוֹלָם, מָקוֹם שֶׁלְּךְ וְשֶׁלִּי מְבֹרָרִים. זַכָּאִים אֲנַחְנוּ עִם אֵלּוּ הַצַּדִּיקִים שֶׁמְּזֻמָּנִים לְשַׁבֵּחַ לַאֲדוֹן הָעוֹלָם, שֶׁאֵלּוּ הַמַּלְאָכִים שֶׁמְּשַׁמְּשִׁים לְפָנָיו. זֶהוּ שֶׁכָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ."]]]]};
